const e=[{id:"ps-pc-gap-1",topic:"present-simple-vs-continuous",type:"gap-fill",difficulty:"beginner",sentence:"I usually ___ coffee in the morning, but today I'm drinking tea.",grammarRule:"Present Simple vs Present Continuous - Habit vs Now",explanation:"Use 'drink' (Present Simple) for habits/routines. Use 'drinking' (Present Continuous) for what is happening right now.",tip:"Habit/routine = Present Simple. Right now = Present Continuous.",gapFill:{gapIndex:2,correctAnswer:"drink",options:["drink","am drinking","drinks","drinking"],correctOptionIndex:0}},{id:"ps-pc-gap-2",topic:"present-simple-vs-continuous",type:"gap-fill",difficulty:"beginner",sentence:"She ___ her homework right now. She does it every evening.",grammarRule:"Present Continuous vs Present Simple",explanation:"'Is doing' (Present Continuous) — something happening right now. Compare: 'does' for habits.",tip:"Now/at this moment = Present Continuous. Every day/always = Present Simple.",gapFill:{gapIndex:1,correctAnswer:"is doing",options:["is doing","does","do","doing"],correctOptionIndex:0}},{id:"ps-pc-gap-3",topic:"present-simple-vs-continuous",type:"gap-fill",difficulty:"beginner",sentence:"They ___ in London. They have lived there for 10 years.",grammarRule:"Present Simple - Permanent Situation",explanation:"Use 'live' (Present Simple) for where someone is based/permanent situation, not 'are living'.",tip:"Where do you live? = Present Simple (permanent).",gapFill:{gapIndex:1,correctAnswer:"live",options:["live","are living","lives","living"],correctOptionIndex:0}},{id:"ps-pc-gap-4",topic:"present-simple-vs-continuous",type:"gap-fill",difficulty:"intermediate",sentence:"Look! Tom ___ on his phone instead of working.",grammarRule:"Present Continuous Question",explanation:"Use Present Continuous (is + verb-ing) for actions happening right now.",tip:"Right now / Look! / at the moment = Present Continuous.",gapFill:{gapIndex:1,correctAnswer:"is talking",options:["is talking","talks","talk","talking"],correctOptionIndex:0}},{id:"ps-pc-gap-5",topic:"present-simple-vs-continuous",type:"gap-fill",difficulty:"intermediate",sentence:"My sister ___ for a fashion company, but this month she is working on a special project.",grammarRule:"Present Simple Job vs Present Continuous Temporary Task",explanation:"'Works' (Present Simple) — her regular permanent job. Compare: 'is working' for a temporary project.",tip:"Regular job = Present Simple. Temporary task right now = Present Continuous.",gapFill:{gapIndex:1,correctAnswer:"works",options:["works","is working","work","working"],correctOptionIndex:0}},{id:"ps-pc-gap-6",topic:"present-simple-vs-continuous",type:"gap-fill",difficulty:"intermediate",sentence:"I ___ like horror films, so I never watch them.",grammarRule:"Present Simple - State Verbs",explanation:"'Like' is a state verb (feeling/opinion). We use Present Simple negative: 'don't like', never 'am not liking'.",tip:"State verbs (like, love, hate, want, need, understand, know, believe, own, see, hear) = Present Simple only.",gapFill:{gapIndex:1,correctAnswer:"don't",options:["don't","am not","won't","didn't"],correctOptionIndex:0}},{id:"ps-pc-gap-7",topic:"present-simple-vs-continuous",type:"gap-fill",difficulty:"advanced",sentence:"He usually ___ very seriously, but today he is joking and laughing with everyone.",grammarRule:"Present Simple Habit vs Present Continuous Temporary Change",explanation:"'Works' (Present Simple) — his usual habit. Compare: 'is joking' shows today is different from the norm.",tip:"Usually/normally = Present Simple. Today/right now (different from usual) = Present Continuous.",gapFill:{gapIndex:1,correctAnswer:"works",options:["works","is working","work","working"],correctOptionIndex:0}},{id:"ps-pc-error-1",topic:"present-simple-vs-continuous",type:"error-spot",difficulty:"beginner",sentence:"I living in Kyiv since I was born.",grammarRule:"Present Simple for Permanent Situation",explanation:"When talking about where you live (permanent), use Present Simple, not Present Continuous.",errorSpot:{errorWordIndex:1,wrongWord:"living",correction:"live",reason:"Where you live is permanent, so use 'live' (Present Simple), not 'living'.",correctionOptions:["live","am living","am live","lived"]}},{id:"ps-pc-error-2",topic:"present-simple-vs-continuous",type:"error-spot",difficulty:"beginner",sentence:"My father understanding English very well.",grammarRule:"State Verbs - Not Used in Continuous",explanation:"'Understand' is a state verb (expressing knowledge/ability). Never use it in Present Continuous form.",errorSpot:{errorWordIndex:2,wrongWord:"understanding",correction:"understands",reason:"'Understand' is a state verb and cannot be used in continuous form.",correctionOptions:["understands","understand","is understanding","is understand"]}},{id:"ps-pc-error-3",topic:"present-simple-vs-continuous",type:"error-spot",difficulty:"beginner",sentence:"Right now the students is listening to the teacher.",grammarRule:"Present Continuous for Current Action",explanation:"'Right now' signals Present Continuous. With plural subject 'students', use 'are', not 'is'.",errorSpot:{errorWordIndex:4,wrongWord:"is",correction:"are",reason:"'Students' is plural, so use 'are listening', not 'is listening'.",correctionOptions:["are","is","was","were"]}},{id:"ps-pc-error-4",topic:"present-simple-vs-continuous",type:"error-spot",difficulty:"intermediate",sentence:"She believing in ghosts and reads about them every day.",grammarRule:"State Verbs Don't Use Continuous",explanation:"'Believe' is a state verb. We always use 'believes' (Present Simple), never the -ing form.",errorSpot:{errorWordIndex:1,wrongWord:"believing",correction:"believes",reason:"State verbs like 'believe' are never used in -ing form. Use 'believes' (Present Simple).",correctionOptions:["believes","is believing","believed","believe"]}},{id:"ps-pc-error-5",topic:"present-simple-vs-continuous",type:"error-spot",difficulty:"intermediate",sentence:"Every day she gets up at 7 and having breakfast.",grammarRule:"Present Simple for Daily Routine",explanation:"'Every day' indicates a daily routine. Use Present Simple for both actions: 'gets up' and 'has'.",errorSpot:{errorWordIndex:8,wrongWord:"having",correction:"has",reason:"Routine actions (every day) use Present Simple 'has', not Present Continuous 'having'.",correctionOptions:["has","is having","have","had"]}},{id:"ps-pc-error-6",topic:"present-simple-vs-continuous",type:"error-spot",difficulty:"advanced",sentence:"We usually meeting on Fridays, but this week we are meeting on Thursday.",grammarRule:"Present Simple for Regular Meetings vs Present Continuous for Exception",explanation:"'Usually' signals a regular habit — use Present Simple 'meet'. 'This week' is the exception, so 'are meeting' is correct there.",errorSpot:{errorWordIndex:2,wrongWord:"meeting",correction:"meet",reason:"Regular scheduled meetings (usually, every week) use Present Simple 'meet', not 'meeting'.",correctionOptions:["meet","are meeting","met","meets"]}},{id:"ps-pc-mc-1",topic:"present-simple-vs-continuous",type:"multiple-choice",difficulty:"beginner",sentence:"Pick the correct sentence about what is happening RIGHT NOW:",grammarRule:"Present Continuous - Actions Happening Now",explanation:"Actions happening at this moment use Present Continuous (be + -ing).",multipleChoice:{question:"Which sentence is correct?",correctOption:"I am writing an email at the moment.",options:["I am writing an email at the moment.","I write an email at the moment.","I am write an email at the moment.","I writing an email at the moment."],optionExplanations:{"I am writing an email at the moment.":"Correct! 'At the moment' = Present Continuous (am + writing).","I write an email at the moment.":"Wrong. 'At the moment' needs Present Continuous, not Simple.","I am write an email at the moment.":"Wrong. Need the -ing form: am writing.","I writing an email at the moment.":"Wrong. Missing the auxiliary verb: am writing."}}},{id:"ps-pc-mc-2",topic:"present-simple-vs-continuous",type:"multiple-choice",difficulty:"beginner",sentence:"Pick the correct sentence about a DAILY HABIT:",grammarRule:"Present Simple - Habits and Routines",explanation:"Regular habits and daily routines use Present Simple.",multipleChoice:{question:"Which sentence is correct?",correctOption:"She goes to the gym three times a week.",options:["She goes to the gym three times a week.","She is going to the gym three times a week.","She going to the gym three times a week.","She are going to the gym three times a week."],optionExplanations:{"She goes to the gym three times a week.":"Correct! 'Three times a week' = Present Simple (habit).","She is going to the gym three times a week.":"Wrong. Habits use Present Simple, not Continuous.","She going to the gym three times a week.":"Wrong. Missing the auxiliary verb.","She are going to the gym three times a week.":"Wrong. With 'she', use 'is' or no auxiliary (Present Simple)."}}},{id:"ps-pc-mc-3",topic:"present-simple-vs-continuous",type:"multiple-choice",difficulty:"intermediate",sentence:"Which sentence correctly describes a PERMANENT SITUATION?",grammarRule:"Present Simple - Permanent Situations",explanation:"Permanent facts, situations, and where people live use Present Simple.",multipleChoice:{question:"Which is correct?",correctOption:"My brother lives in Canada and works as an engineer.",options:["My brother lives in Canada and works as an engineer.","My brother is living in Canada and is working as an engineer.","My brother is living in Canada and works as an engineer.","My brother living in Canada and working as an engineer."],optionExplanations:{"My brother lives in Canada and works as an engineer.":"Correct! Permanent location and job = Present Simple.","My brother is living in Canada and is working as an engineer.":"Wrong. Permanent situation needs Present Simple, not Continuous.","My brother is living in Canada and works as an engineer.":"Wrong. Mix of tenses; both should be Simple for permanent.","My brother living in Canada and working as an engineer.":"Wrong. Missing auxiliary verbs."}}},{id:"ps-pc-mc-4",topic:"present-simple-vs-continuous",type:"multiple-choice",difficulty:"intermediate",sentence:"Pick the sentence that correctly contrasts USUAL HABIT with TEMPORARY SITUATION:",grammarRule:"Present Simple vs Continuous - Usual vs Temporary",explanation:"Use Present Simple for what usually happens and Present Continuous for temporary changes.",multipleChoice:{question:"Which is correct?",correctOption:"I usually drive to work, but today I am taking the bus.",options:["I usually drive to work, but today I am taking the bus.","I usually am driving to work, but today I take the bus.","I drive to work, and today I am taking the bus.","I am usually driving to work, but today I take the bus."],optionExplanations:{"I usually drive to work, but today I am taking the bus.":"Correct! Habit (Simple) vs temporary change (Continuous).","I usually am driving to work, but today I take the bus.":"Wrong. 'Usually' = Simple, not Continuous.","I drive to work, and today I am taking the bus.":"Wrong. Missing 'usually' context for the contrast.","I am usually driving to work, but today I take the bus.":"Wrong. 'Usually' needs Simple form, not Continuous."}}},{id:"ps-pc-mc-5",topic:"present-simple-vs-continuous",type:"multiple-choice",difficulty:"intermediate",sentence:"Which sentence INCORRECTLY uses Present Continuous with a STATE VERB?",grammarRule:"State Verbs Cannot Be Continuous",explanation:"State verbs (like, love, want, need, know, believe, understand, see, hear) are never used in continuous form.",multipleChoice:{question:"Which sentence has an error?",correctOption:"She is wanting to move to Paris.",options:["She is wanting to move to Paris.","She wants to move to Paris.","He is working in an office.","They are reading a book."],optionExplanations:{"She is wanting to move to Paris.":"WRONG! 'Want' is a state verb; should be 'wants'.","She wants to move to Paris.":"Correct. Present Simple with state verb.","He is working in an office.":"Correct. Work is dynamic (can be continuous).","They are reading a book.":"Correct. Reading is dynamic (can be continuous)."}}},{id:"ps-pc-mc-6",topic:"present-simple-vs-continuous",type:"multiple-choice",difficulty:"advanced",sentence:"Which sentence correctly uses both tenses to describe TEMPORARY vs PERMANENT?",grammarRule:"Present Continuous for Temporary Change + Present Simple for Permanent",explanation:"Combine tenses: permanent situation (Simple) + temporary change (Continuous).",multipleChoice:{question:"Which is correct?",correctOption:"I live in Paris, but I am working in London this month.",options:["I live in Paris, but I am working in London this month.","I am living in Paris, but I work in London this month.","I live in Paris, but I work in London this month.","I am living in Paris, and I am working in London this month."],optionExplanations:{"I live in Paris, but I am working in London this month.":"Correct! Permanent home (Simple) + temporary work assignment (Continuous).","I am living in Paris, but I work in London this month.":"Wrong. Home is permanent (live), assignment is temporary (am working).","I live in Paris, but I work in London this month.":"Wrong. 'This month' is temporary; needs Present Continuous.","I am living in Paris, and I am working in London this month.":"Wrong. Living in Paris is permanent; should be 'live'."}}},{id:"ps-pc-reorder-1",topic:"present-simple-vs-continuous",type:"word-transform",difficulty:"beginner",sentence:"She ___ coffee every morning.",grammarRule:"Present Simple — habitual actions",explanation:"Use Present Simple for habits and routines. Third person singular (she) adds -s: 'drinks'.",tip:"Habits and routines → Present Simple: she drinks, he works, it starts.",wordTransform:{baseWord:"drink",correctAnswer:"drinks"}},{id:"ps-pc-reorder-2",topic:"present-simple-vs-continuous",type:"word-transform",difficulty:"beginner",sentence:"Look! The children ___ in the garden.",grammarRule:"Present Continuous — actions happening right now",explanation:"Use Present Continuous for actions happening at this moment. Structure: are/is/am + verb-ing.",tip:"Right now / Look / at the moment → Present Continuous: are playing, is running.",wordTransform:{baseWord:"play",correctAnswer:"are playing"}},{id:"ps-pc-reorder-3",topic:"present-simple-vs-continuous",type:"word-transform",difficulty:"intermediate",sentence:"He usually ___ the bus to school.",grammarRule:"Present Simple — frequency adverbs",explanation:"Frequency adverbs like 'usually' signal Present Simple. Third person singular adds -s: 'takes'.",tip:"Usually/always/often → Present Simple. He takes, she goes, it leaves.",wordTransform:{baseWord:"take",correctAnswer:"takes"}},{id:"ps-pc-reorder-4",topic:"present-simple-vs-continuous",type:"word-transform",difficulty:"intermediate",sentence:"We ___ dinner right now. Can I call you back?",grammarRule:"Present Continuous — temporary actions",explanation:"Use Present Continuous for what is happening at this moment. 'Right now' signals continuous.",tip:"Right now / at the moment / currently → Present Continuous: are having, is working.",wordTransform:{baseWord:"have",correctAnswer:"are having"}},{id:"ps-pc-reorder-5",topic:"present-simple-vs-continuous",type:"word-transform",difficulty:"advanced",sentence:"She ___ at a hospital. It's her permanent job.",grammarRule:"Present Simple — permanent situations",explanation:"Use Present Simple for permanent situations and facts. Third person singular adds -s.",tip:"Permanent job/situation → Present Simple: she works, he lives, it costs.",wordTransform:{baseWord:"work",correctAnswer:"works"}},{id:"ps-pc-reorder-6",topic:"present-simple-vs-continuous",type:"word-transform",difficulty:"advanced",sentence:"I can't come out. I ___ my homework.",grammarRule:"Present Continuous — current activity",explanation:"Use Present Continuous for a current activity preventing something else. Structure: am/is/are + verb-ing.",tip:"Busy right now → Present Continuous: I am doing, she is cooking, they are studying.",wordTransform:{baseWord:"do",correctAnswer:"am doing"}}],t={id:"present-simple-vs-continuous",level:"B1",name:"Present Simple vs Present Continuous",description:"Master the difference between Present Simple (habits, routines, facts) and Present Continuous (actions happening now, temporary situations). Learn when to use state verbs with Present Simple only.",lesson:"Lesson 2",icon:"🔄",cards:[{id:"ps-pc-card-1",rule:"Present Simple for habits and routines",example:"My brother ___ (go) to the gym every Tuesday and Thursday.",answer:"goes",explanation:"Use Present Simple for things we do regularly. Add -s or -es with he, she and it. Words like every day, usually and never often go with it.",examples:["We usually have lunch at one o'clock.","She never drinks coffee after six."],ua:"Звички й розклад — Present Simple: every Tuesday = «щовівторка». he/she/it + -s: goes."},{id:"ps-pc-card-2",rule:"Present Simple for facts and permanent situations",example:"The Dnipro ___ (flow) through Kyiv and into the Black Sea.",answer:"flows",explanation:"Use Present Simple for facts that are always true and for permanent situations. We do not use -ing for them.",examples:["The sun rises in the east.","My parents live in a village near Lviv."],ua:"Загальні факти — Present Simple: flows = «тече». Не «is flowing»."},{id:"ps-pc-card-3",rule:"am/is/are + -ing for actions happening now",example:"Please be quiet — the baby ___ (sleep) at the moment.",answer:"is sleeping",explanation:"Use Present Continuous for an action that is happening now. Look, listen, now and at the moment often go with it.",examples:["Listen! Someone is knocking at the door.","Sorry, I can't talk now. I'm driving."],ua:"Present Continuous: am/is/are + -ing, «зараз»: is sleeping = «спить (саме зараз)»."},{id:"ps-pc-card-4",rule:"Present Continuous for temporary situations",example:"This month I ___ (stay) with my cousin while the builders repaint my flat.",answer:"am staying",explanation:"Use Present Continuous for a situation that is temporary. It is true around now, but it will change soon.",examples:["Our team is working from home this week.","He is learning to drive at the moment."],ua:"Тимчасова ситуація («цього місяця») — am staying. Постійна ситуація — Present Simple."},{id:"ps-pc-card-5",rule:"usually (Simple) vs today / this week (Continuous)",example:"Lucy normally ___ (wear) jeans to the office, but today she's wearing a suit.",answer:"wears",explanation:"Use Present Simple for what usually happens. Use Present Continuous for what is different today or this week.",examples:["Our dog usually sleeps all day, but now he is barking at the postman.","I normally walk to work, but this week I'm cycling."],ua:"usually/normally — Present Simple, а today/this week (виняток) — Present Continuous."},{id:"ps-pc-card-6",rule:"do/does + base verb in questions and negatives",example:"Does your sister ___ (work) on Saturdays?",answer:"work",explanation:"In Present Simple questions and negatives we use do/does and the base verb. The -s goes on does, not on the main verb.",examples:["Do you take sugar in your tea?","My manager doesn't answer emails at the weekend."],ua:"У питаннях і запереченнях do/does + початкова форма: Does she work? (без -s)."},{id:"ps-pc-card-7",rule:"State verbs (know, need, want, love) are not used with -ing",example:"We ___ (need) a bigger table for the party on Saturday.",answer:"need",explanation:"State verbs describe thoughts, feelings and possession, not actions. We use Present Simple with them, even when we mean now.",examples:["I don't know her phone number.","My son loves chocolate ice cream."],ua:"Дієслова стану (know, need, want, love) не мають -ing: «нам потрібен» — need."},{id:"ps-pc-card-8",rule:"have as an action (is having) vs have = own",example:"She ___ (have) a shower, so she can't answer the phone.",answer:"is having",explanation:"Have is a state verb when it means own, so we say I have a car. When have is an action, like eat or take a shower, we can use Present Continuous.",examples:["We're having a great time in Prague this week.","My sister has two cats and a small flat."],ua:"have = «їсти, приймати душ» — може бути is having; have = «мати» — тільки have."}],rules:e},o={id:"irregular-verbs",level:"B1",name:"Irregular Verbs",description:"Practice the Past Simple and Past Participle forms of the most common irregular English verbs.",icon:"📚",cards:[{id:"irr-v-card-1",rule:"cut – cut – cut (same in all forms)",example:"My parents never let me go to concerts. Last year they finally ___ me go to one.",answer:"let",explanation:"Some irregular verbs never change: cut, put, hit, let, hurt, shut. The present, the past simple and the past participle look the same. Never add -ed.",examples:["She has cut her hair short for the summer.","I put the documents in a blue folder yesterday."],ua:"Ці дієслова не змінюються: cut — cut — cut. Не «cutted», не «putted»."},{id:"irr-v-card-2",rule:"buy – bought – bought (-ought / -aught)",example:"She teaches English at a school now. Before that, she ___ French to children in Lviv.",answer:"taught",explanation:"Many verbs end in -ought or -aught in the past: buy – bought, bring – brought, think – thought, catch – caught, teach – taught. The past simple and the past participle are the same.",examples:["He has bought a small flat near the river.","We caught the early train to Odesa on Saturday."],ua:"Закінчення -ought / -aught: teach — taught, buy — bought. Дві форми однакові."},{id:"irr-v-card-3",rule:"spend – spent – spent (-nd → -nt)",example:"I like to spend a little money on books. Last month I ___ two thousand hryvnias on them.",answer:"spent",explanation:"Some verbs change -nd to -nt: spend – spent, send – sent, lend – lent. Build – built is similar. The past simple and the past participle are the same.",examples:["She has sent her CV to five companies.","They built a small cottage by the lake in 2015."],ua:"-nd змінюється на -nt: send — sent, spend — spent; ще build — built."},{id:"irr-v-card-4",rule:"keep – kept, feel – felt, leave – left",example:"I try to keep my promises, just like my grandfather did. He ___ every promise he ever made.",answer:"kept",explanation:"Some verbs get a short vowel and end in -t: sleep – slept, keep – kept, feel – felt, leave – left. The past simple and the past participle are the same.",examples:["He felt much better after a good night's sleep.","We met at university and have been friends ever since."],ua:"Дві форми однакові: keep — kept, feel — felt, leave — left."},{id:"irr-v-card-5",rule:"swim – swam – swum (i – a – u)",example:"I swim every morning. Yesterday I swam in the lake, and today I have already ___ in the sea.",answer:"swum",explanation:"Some verbs follow the pattern i – a – u: swim – swam – swum, begin – began – begun, drink – drank – drunk. Use the second form for the past simple and the third form after have.",examples:["The film has already begun, so please be quiet.","We drank hot chocolate after the long walk."],ua:"Схема i — a — u: swim — swam — swum, begin — began — begun."},{id:"irr-v-card-6",rule:"know – knew – known (-ew / -own)",example:"I have ___ my best friend for twenty years — we met at school.",answer:"known",explanation:"Some verbs follow the pattern -ew / -own: know – knew – known, grow – grew – grown, fly – flew – flown. After have, use the form with -own.",examples:["The plane flew over the mountains in the dark.","Her children have grown so much since last summer."],ua:"Схема -ew / -own: know — knew — known, grow — grew — grown."},{id:"irr-v-card-7",rule:"drive – drove – driven (-en participle)",example:"I drove my father's car last week, but I have never ___ a lorry.",answer:"driven",explanation:"Many past participles end in -en: write – written, drive – driven, ride – ridden, take – taken, give – given, break – broken, forget – forgotten. The past simple is different.",examples:["My brother has written a book about cycling in Ukraine.","She has given me her new phone number."],ua:"Третя форма на -en: drive — driven, write — written, take — taken."},{id:"irr-v-card-8",rule:"have / has + past participle",example:"My sister is not at home — she has ___ to the gym.",answer:"gone",explanation:"After have, has and had, use the past participle, not the past simple: have eaten, has seen, has gone. Use the past simple for a finished time: I saw it yesterday.",examples:["I have never seen snow in October before.","He has already eaten, so he doesn't want a snack."],ua:"Після have / has — третя форма: I have seen, а не I have saw."},{id:"irr-v-card-9",rule:"was / were + past participle (passive)",example:"Someone kicked a ball into our garden, and the kitchen window was ___ (break).",answer:"broken",explanation:"In the passive, use was or were + past participle: was built, were stolen, was broken. For irregular verbs, learn the third form.",examples:["The old church was built in 1880.","My bag was stolen on the metro last week."],ua:"Пасив: was / were + третя форма. «Міст збудували» — The bridge was built."}],rules:[{id:"irr-v-gap-1",topic:"irregular-verbs",type:"gap-fill",difficulty:"beginner",sentence:"I ___ my finger while cutting vegetables.",grammarRule:"Irregular Verbs — Past Simple (same all forms)",explanation:"'Cut' is irregular: cut / cut / cut. All three forms are identical. We never say 'cutted'.",tip:"Same-form verbs: cut, put, hit, hurt, let, shut — no change in any tense.",gapFill:{gapIndex:1,correctAnswer:"cut",options:["cut","cutted","cuts","have cut"],correctOptionIndex:0}},{id:"irr-v-gap-2",topic:"irregular-verbs",type:"gap-fill",difficulty:"beginner",sentence:"She ___ a beautiful song at the concert last night.",grammarRule:"Irregular Verbs — Past Simple (sing/sang/sung)",explanation:"'Sing' is irregular: sing → sang (Past Simple) → sung (Past Participle). Never use 'singed'.",tip:"Group pattern a→i→u: ring/rang/rung, sing/sang/sung, drink/drank/drunk, begin/began/begun.",gapFill:{gapIndex:1,correctAnswer:"sang",options:["sang","singed","sung","sing"],correctOptionIndex:0}},{id:"irr-v-gap-3",topic:"irregular-verbs",type:"gap-fill",difficulty:"beginner",sentence:"He ___ all his money on a new gaming PC.",grammarRule:"Irregular Verbs — Past Simple (spend/spent)",explanation:"'Spend' is irregular: spend → spent (Past Simple and Past Participle). We never say 'spended'.",tip:"Pattern -nd/-nt: spend/spent, send/sent, lend/lent, build/built.",gapFill:{gapIndex:1,correctAnswer:"spent",options:["spent","spended","spends","spend"],correctOptionIndex:0}},{id:"irr-v-gap-4",topic:"irregular-verbs",type:"gap-fill",difficulty:"intermediate",sentence:"Have you ever ___ sushi before?",grammarRule:"Irregular Verbs — Past Participle (Present Perfect)",explanation:"After 'have/has' always use the Past Participle. 'Eat' → Past Participle: 'eaten'. 'Ate' is only Past Simple.",tip:"Present Perfect = have/has + Past Participle. Don't confuse 'ate' (Past Simple) with 'eaten' (Past Participle).",gapFill:{gapIndex:3,correctAnswer:"eaten",options:["eaten","ate","eated","eating"],correctOptionIndex:0}},{id:"irr-v-gap-5",topic:"irregular-verbs",type:"gap-fill",difficulty:"intermediate",sentence:"The geese ___ south at the beginning of October.",grammarRule:"Irregular Verbs — Past Simple (fly/flew/flown)",explanation:"'Fly' is irregular: fly → flew (Past Simple) → flown (Past Participle). Never say 'flied' when meaning travel through the air.",tip:"Group pattern -ew/-own: blow/blew/blown, grow/grew/grown, know/knew/known, fly/flew/flown.",gapFill:{gapIndex:2,correctAnswer:"flew",options:["flew","flied","flown","fly"],correctOptionIndex:0}},{id:"irr-v-gap-6",topic:"irregular-verbs",type:"gap-fill",difficulty:"intermediate",sentence:"She has ___ three best-selling novels in her career.",grammarRule:"Irregular Verbs — Past Participle (write/wrote/written)",explanation:"'Write' → Past Simple: 'wrote'. Past Participle: 'written'. With 'has', use 'written', not 'wrote'.",tip:"Pattern -ote/-itten: write/wrote/written, drive/drove/driven, ride/rode/ridden.",gapFill:{gapIndex:2,correctAnswer:"written",options:["written","wrote","writed","writes"],correctOptionIndex:0}},{id:"irr-v-gap-7",topic:"irregular-verbs",type:"gap-fill",difficulty:"advanced",sentence:"By the time I arrived, he had already ___ home.",grammarRule:"Irregular Verbs — Past Participle (Past Perfect)",explanation:"Past Perfect = had + Past Participle. 'Leave' → Past Participle: 'left'. Never say 'leaved'.",tip:"Feel/felt, leave/left, meet/met — same form for Past Simple and Past Participle. Use 'had left' for Past Perfect.",gapFill:{gapIndex:8,correctAnswer:"left",options:["left","leaved","leave","leaving"],correctOptionIndex:0}},{id:"irr-v-err-1",topic:"irregular-verbs",type:"error-spot",difficulty:"beginner",sentence:"Yesterday I buyed a new phone at the shop.",grammarRule:"Irregular Verbs — Past Simple (buy/bought)",explanation:"'Buy' is irregular: buy → bought. It never follows the regular -ed pattern. Say 'I bought', not 'I buyed'.",tip:"Buy/bought/bought — same group as bring/brought, catch/caught, think/thought.",errorSpot:{errorWordIndex:2,wrongWord:"buyed",correction:"bought",reason:"'Buy' is irregular. The Past Simple is 'bought', not 'buyed'.",correctionOptions:["bought","buys","buy","buying"]}},{id:"irr-v-err-2",topic:"irregular-verbs",type:"error-spot",difficulty:"beginner",sentence:"She feeled very nervous before her presentation.",grammarRule:"Irregular Verbs — Past Simple (feel/felt)",explanation:"'Feel' is irregular: feel → felt. It does not take the regular -ed ending. Say 'she felt', not 'she feeled'.",tip:"Feel/felt/felt — also: keep/kept, sleep/slept, dream/dreamt, mean/meant.",errorSpot:{errorWordIndex:1,wrongWord:"feeled",correction:"felt",reason:"'Feel' is irregular. The Past Simple is 'felt', not 'feeled'.",correctionOptions:["felt","feels","feel","feeling"]}},{id:"irr-v-err-3",topic:"irregular-verbs",type:"error-spot",difficulty:"beginner",sentence:"We catched the last bus home last night.",grammarRule:"Irregular Verbs — Past Simple (catch/caught)",explanation:"'Catch' is irregular: catch → caught. Never say 'catched'. The vowel completely changes.",tip:"Catch/caught/caught — same pattern as teach/taught/taught.",errorSpot:{errorWordIndex:1,wrongWord:"catched",correction:"caught",reason:"'Catch' is irregular. The Past Simple is 'caught', not 'catched'.",correctionOptions:["caught","catches","catch","catching"]}},{id:"irr-v-err-4",topic:"irregular-verbs",type:"error-spot",difficulty:"intermediate",sentence:"She has already taked the entrance exam twice.",grammarRule:"Irregular Verbs — Past Participle (take/took/taken)",explanation:"'Take' is irregular: take → took (Past Simple) → taken (Past Participle). After 'has', use 'taken', not 'took' or 'taked'.",tip:"Take/took/taken — Past Participle ends in -en. Same: give/gave/given, eat/ate/eaten, see/saw/seen.",errorSpot:{errorWordIndex:3,wrongWord:"taked",correction:"taken",reason:"'Take' is irregular. The Past Participle is 'taken', not 'taked'.",correctionOptions:["taken","took","takes","taking"]}},{id:"irr-v-err-5",topic:"irregular-verbs",type:"error-spot",difficulty:"intermediate",sentence:"He sended me a long message this morning.",grammarRule:"Irregular Verbs — Past Simple (send/sent)",explanation:"'Send' is irregular: send → sent. Never say 'sended'. The -nd changes to -t.",tip:"Send/sent/sent — same pattern: spend/spent, lend/lent, build/built.",errorSpot:{errorWordIndex:1,wrongWord:"sended",correction:"sent",reason:"'Send' is irregular. The Past Simple is 'sent', not 'sended'.",correctionOptions:["sent","sends","send","sending"]}},{id:"irr-v-err-6",topic:"irregular-verbs",type:"error-spot",difficulty:"advanced",sentence:"The bridge was builded in just six months.",grammarRule:"Irregular Verbs — Past Participle in Passive Voice",explanation:"'Build' is irregular: build → built. In passive voice use 'was built', not 'was builded'. Both Past Simple and Past Participle are 'built'.",tip:"Build/built/built — passive voice: 'was/were built'. Never use 'builded'.",errorSpot:{errorWordIndex:3,wrongWord:"builded",correction:"built",reason:"'Build' is irregular. The Past Participle is 'built', not 'builded'.",correctionOptions:["built","builds","build","building"]}},{id:"irr-v-mc-1",topic:"irregular-verbs",type:"multiple-choice",difficulty:"beginner",sentence:"She brought flowers to the dinner party.",grammarRule:"Irregular Verbs — Past Simple (bring/brought)",explanation:"'Bring' is irregular: bring → brought (Past Simple and Past Participle). It follows the same -ought pattern as buy/bought and think/thought.",tip:"Bring/brought/brought — a very high-frequency irregular. Never say 'bringed'.",multipleChoice:{question:"She ___ flowers to the dinner party last Saturday. Choose the correct Past Simple of 'bring':",correctOption:"brought",options:["brought","bringed","brung","bring"]}},{id:"irr-v-mc-2",topic:"irregular-verbs",type:"multiple-choice",difficulty:"beginner",sentence:"I thought about the problem all night.",grammarRule:"Irregular Verbs — Past Simple (think/thought)",explanation:"'Think' is irregular: think → thought. It belongs to the -ought group along with bring/brought, buy/bought, catch/caught.",tip:"Think/thought/thought — the whole vowel cluster changes. 'Thinked' and 'thunk' are not standard English.",multipleChoice:{question:"I ___ about the problem all night but couldn't find a solution. Choose the correct Past Simple of 'think':",correctOption:"thought",options:["thought","thinked","think","thunk"]}},{id:"irr-v-mc-3",topic:"irregular-verbs",type:"multiple-choice",difficulty:"intermediate",sentence:"Have you ever ridden a horse?",grammarRule:"Irregular Verbs — Past Participle (ride/rode/ridden)",explanation:"'Ride' is irregular: ride → rode (Past Simple) → ridden (Past Participle). With 'have/has/had', always use 'ridden'.",tip:"Ride/rode/ridden — Past Participle ends in -en. Same group: drive/drove/driven, write/wrote/written.",multipleChoice:{question:"Have you ever ___ a horse? Choose the correct Past Participle of 'ride':",correctOption:"ridden",options:["ridden","rode","rided","ridded"]}},{id:"irr-v-mc-4",topic:"irregular-verbs",type:"multiple-choice",difficulty:"intermediate",sentence:"I have seen this film three times.",grammarRule:"Irregular Verbs — Past Simple vs Past Participle (see/saw/seen)",explanation:"'See' is irregular: saw = Past Simple, seen = Past Participle. With 'have/has', always use 'seen'. Never say 'I have saw'.",tip:"Past Simple: 'I saw it yesterday.' Present Perfect: 'I have seen it before.' The key is whether 'have/has' is present.",multipleChoice:{question:"Which sentence is grammatically correct?",correctOption:"I have seen this film three times.",options:["I have seen this film three times.","I have saw this film three times.","I seen this film three times.","I have see this film three times."]}},{id:"irr-v-mc-5",topic:"irregular-verbs",type:"multiple-choice",difficulty:"intermediate",sentence:"He accidentally broke the window during the game.",grammarRule:"Irregular Verbs — Past Simple (break/broke/broken)",explanation:"'Break' → Past Simple: 'broke'. Past Participle: 'broken'. Don't confuse them — 'broke' for past actions, 'broken' with have/has/was.",tip:"Break/broke/broken — Past Simple: 'He broke it.' Past Participle: 'It was broken.' / 'He has broken it.'",multipleChoice:{question:"He accidentally ___ the window during the game. Choose the correct Past Simple of 'break':",correctOption:"broke",options:["broke","broken","breaked","brokes"]}},{id:"irr-v-mc-6",topic:"irregular-verbs",type:"multiple-choice",difficulty:"advanced",sentence:"By the time I called, she had already forgotten about our meeting.",grammarRule:"Irregular Verbs — Past Participle in Past Perfect (forget/forgot/forgotten)",explanation:"Past Perfect = had + Past Participle. 'Forget' → Past Participle: 'forgotten'. 'Forgot' is only Past Simple.",tip:"Forget/forgot/forgotten — Past Perfect: 'had forgotten'. Don't use 'had forgot' — that's a common mistake.",multipleChoice:{question:"By the time I called, she had already ___ about our meeting. Choose the correct Past Participle of 'forget':",correctOption:"forgotten",options:["forgotten","forgot","forgeted","forgetted"]}},{id:"irr-v-reorder-1",topic:"irregular-verbs",type:"word-transform",difficulty:"beginner",sentence:"She ___ a new computer last week.",grammarRule:"Irregular Verbs — Past Simple (buy/bought)",explanation:"Past Simple of 'buy' is 'bought'. Irregular verb — does not follow the regular -ed pattern.",tip:"Buy → bought. Past Simple: I bought, she bought, they bought.",wordTransform:{baseWord:"buy",correctAnswer:"bought"}},{id:"irr-v-reorder-2",topic:"irregular-verbs",type:"word-transform",difficulty:"beginner",sentence:"They ___ all evening at the cinema.",grammarRule:"Irregular Verbs — Past Simple (spend/spent)",explanation:"Past Simple of 'spend' is 'spent'. Both Past Simple and Past Participle are 'spent'.",tip:"Spend → spent. Past Simple: we spent, he spent, they spent.",wordTransform:{baseWord:"spend",correctAnswer:"spent"}},{id:"irr-v-reorder-3",topic:"irregular-verbs",type:"word-transform",difficulty:"intermediate",sentence:"Have you ever ___ this film before?",grammarRule:"Irregular Verbs — Past Participle (see/saw/seen)",explanation:"Past Participle of 'see' is 'seen'. Use it with Present Perfect: Have you ever seen...?",tip:"See → saw (Past Simple) → seen (Past Participle). 'Have you ever seen…' needs the participle.",wordTransform:{baseWord:"see",correctAnswer:"seen"}},{id:"irr-v-reorder-4",topic:"irregular-verbs",type:"word-transform",difficulty:"intermediate",sentence:"He ___ his leg during the football match.",grammarRule:"Irregular Verbs — Past Simple (break/broke/broken)",explanation:"Past Simple of 'break' is 'broke'. Irregular verb — does not follow the -ed pattern.",tip:"Break → broke (Past Simple) → broken (Past Participle). He broke it yesterday.",wordTransform:{baseWord:"break",correctAnswer:"broke"}},{id:"irr-v-reorder-5",topic:"irregular-verbs",type:"word-transform",difficulty:"intermediate",sentence:"She has ___ many letters to her friends.",grammarRule:"Irregular Verbs — Past Participle (write/wrote/written)",explanation:"Past Participle of 'write' is 'written'. Use it with Present Perfect: has written.",tip:"Write → wrote (Past Simple) → written (Past Participle). 'Has written' = Present Perfect.",wordTransform:{baseWord:"write",correctAnswer:"written"}},{id:"irr-v-reorder-6",topic:"irregular-verbs",type:"word-transform",difficulty:"advanced",sentence:"By the time we arrived, they had already ___.",grammarRule:"Irregular Verbs — Past Participle in Past Perfect (leave/left)",explanation:"Past Perfect uses 'had' + Past Participle. Past Participle of 'leave' is 'left'. 'Had left' shows an action before another past event.",tip:"Leave → left (both Past Simple and Past Participle). 'Had left' = Past Perfect.",wordTransform:{baseWord:"leave",correctAnswer:"left"}}]},n={id:"verb-patterns",level:"B1",name:"Verb Patterns",description:"Practise when to use verb + -ing (enjoy swimming) and when to use verb + to infinitive (hope to become).",lesson:"Lesson 7",icon:"🔤",cards:[{id:"vp-card-1",rule:"enjoy + -ing",example:"My parents really enjoy ___ (hike) in the mountains.",answer:"hiking",explanation:"After enjoy, use the -ing form. If you enjoy something, you are already doing it. We never say enjoy to hike.",examples:["She enjoys listening to podcasts on the train.","Do you enjoy working from home?"],ua:"«Люблять ходити в походи» — enjoy + -ing: enjoy hiking, не enjoy to hike."},{id:"vp-card-2",rule:"finish, avoid + -ing",example:"I'll call you as soon as I finish ___ (pack).",answer:"packing",explanation:"Finish and avoid are always followed by the -ing form. We say finish packing and avoid driving.",examples:["Have you finished reading the report?","I always try to avoid eating late at night."],ua:"finish і avoid — лише з -ing: finish packing («закінчити пакувати»), avoid driving («уникати їзди»)."},{id:"vp-card-3",rule:"miss, imagine, don't mind + -ing",example:"I miss ___ (cook) with my grandmother on Sundays.",answer:"cooking",explanation:"Miss, imagine and don't mind are followed by the -ing form. They talk about real or imagined experiences.",examples:["Can you imagine living on a boat?","I don't mind waiting a few minutes if the doctor is late."],ua:"miss, imagine, don't mind + -ing: «Сумую за тим, як ми готували» → I miss cooking."},{id:"vp-card-4",rule:"preposition + -ing",example:"She left the shop without ___ (buy) anything.",answer:"buying",explanation:"After a preposition, always use the -ing form. This is true for after, before, without, by and instead of.",examples:["He learned to cook by watching videos online.","Before leaving the house, check that the windows are closed."],ua:"Після прийменника лише -ing: «не купивши нічого» → without buying anything."},{id:"vp-card-5",rule:"-ing form as the subject",example:"___ (jog) every morning keeps me fit.",answer:"Jogging",explanation:"When a verb is the subject of a sentence, use the -ing form. It works like a noun: Swimming is fun.",examples:["Learning a language takes time and patience.","Smoking is not allowed in this building."],ua:"Дієслово як підмет — це -ing: «Біг щоранку» → Jogging every morning."},{id:"vp-card-6",rule:"hope, want, plan + to + verb",example:"We hope ___ (see) the northern lights in Norway next winter.",answer:"to see",explanation:"Verbs about wishes and future plans, such as hope, want and plan, are followed by to + verb. We never say hope seeing.",examples:["I want to learn Spanish before we travel to Madrid.","They plan to open a small café next year."],ua:"hope, want, plan + to: «Сподіваємося побачити» → hope to see, не hope seeing."},{id:"vp-card-7",rule:"decide, choose + to + verb",example:"After a long talk, my parents decided ___ (sell) their old flat.",answer:"to sell",explanation:"Decide and choose are followed by to + verb. They describe a decision about a future action.",examples:["She chose to study medicine at a university abroad.","We decided to take the train instead of flying."],ua:"decide, choose + to: «Вирішили продати» → decided to sell."},{id:"vp-card-8",rule:"promise, agree + to + verb",example:"He promised ___ (call) me as soon as he landed.",answer:"to call",explanation:"Promise and agree are followed by to + verb. They are about a commitment to do something in the future.",examples:["The shop agreed to refund the money.","I promise to send you the photos tonight."],ua:"promise, agree + to: «Обіцяв зателефонувати» → promised to call."},{id:"vp-card-9",rule:"need, would like + to + verb",example:"My brother needs ___ (renew) his passport before the trip.",answer:"to renew",explanation:"Need and would like are followed by to + verb. Would like is a polite way to say want.",examples:["Would you like to join us for dinner?","You need to show your ticket at the entrance."],ua:"need, would like + to: «Треба поновити» → needs to renew; «хотів би» → would like to."}],rules:[{id:"vp-gap-1",topic:"verb-patterns",type:"gap-fill",difficulty:"beginner",sentence:"She enjoys ___ tennis with her friends at the weekend.",grammarRule:"Verb + -ing form (enjoy)",explanation:"'Enjoy' is always followed by a verb in the -ing form. We say 'enjoy swimming', 'enjoy playing', never 'enjoy to play'.",tip:"Memory trick: if you enjoy something, you're already doing it — use the -ing form.",gapFill:{gapIndex:2,correctAnswer:"playing",options:["playing","to play","play","played"],correctOptionIndex:0}},{id:"vp-gap-2",topic:"verb-patterns",type:"gap-fill",difficulty:"beginner",sentence:"I hope ___ a doctor when I finish university.",grammarRule:"Verb + to infinitive (hope)",explanation:"'Hope' is followed by a to infinitive. We say 'hope to become', 'hope to find', never 'hope becoming'.",tip:"Verbs about future plans or wishes (hope, want, decide) use to + infinitive.",gapFill:{gapIndex:2,correctAnswer:"to become",options:["to become","becoming","become","became"],correctOptionIndex:0}},{id:"vp-gap-3",topic:"verb-patterns",type:"gap-fill",difficulty:"beginner",sentence:"They decided ___ a new car after their holiday.",grammarRule:"Verb + to infinitive (decide)",explanation:"'Decide' is followed by a to infinitive. We say 'decided to buy', 'decided to leave', never 'decided buying'.",tip:"Decide, choose, agree, promise — these all take to + infinitive.",gapFill:{gapIndex:2,correctAnswer:"to buy",options:["to buy","buying","buy","bought"],correctOptionIndex:0}},{id:"vp-gap-4",topic:"verb-patterns",type:"gap-fill",difficulty:"intermediate",sentence:"He finished ___ the report just before the deadline.",grammarRule:"Verb + -ing form (finish)",explanation:"'Finish' is always followed by -ing. We say 'finished writing', 'finished cooking', never 'finished to write'.",tip:"Think of finish as completing an action already in progress — so -ing feels natural.",gapFill:{gapIndex:2,correctAnswer:"writing",options:["writing","to write","write","written"],correctOptionIndex:0}},{id:"vp-gap-5",topic:"verb-patterns",type:"gap-fill",difficulty:"intermediate",sentence:"After ___ the film, we went for a walk in the park.",grammarRule:"Preposition + -ing form",explanation:"After a preposition (after, before, without, instead of), always use the -ing form. 'After seeing', never 'after to see'.",tip:"Prepositions (after, before, without, by, instead of) are always followed by -ing.",gapFill:{gapIndex:1,correctAnswer:"seeing",options:["seeing","to see","see","saw"],correctOptionIndex:0}},{id:"vp-gap-6",topic:"verb-patterns",type:"gap-fill",difficulty:"intermediate",sentence:"I can't imagine ___ in a foreign country without speaking the language.",grammarRule:"Verb + -ing form (imagine)",explanation:"'Imagine' is always followed by -ing. We say 'imagine living', 'imagine working', never 'imagine to live'.",tip:"Imagine, avoid, miss, enjoy — these verbs describe real or mental experiences, so they use -ing.",gapFill:{gapIndex:3,correctAnswer:"living",options:["living","to live","live","lived"],correctOptionIndex:0}},{id:"vp-gap-7",topic:"verb-patterns",type:"gap-fill",difficulty:"intermediate",sentence:"She promised ___ on time for the meeting.",grammarRule:"Verb + to infinitive (promise)",explanation:"'Promise' is followed by a to infinitive. We say 'promised to arrive', 'promised to help', never 'promised arriving'.",tip:"Promise is a commitment about a future action — use to + infinitive.",gapFill:{gapIndex:2,correctAnswer:"to arrive",options:["to arrive","arriving","arrive","arrived"],correctOptionIndex:0}},{id:"vp-err-1",topic:"verb-patterns",type:"error-spot",difficulty:"beginner",sentence:"I enjoy swam in the pool every morning.",grammarRule:"Verb + -ing form (enjoy)",explanation:"'Enjoy' must be followed by the -ing form, not a past tense verb. The correct form is 'enjoy swimming'.",tip:"After enjoy, always use -ing: enjoy swimming, enjoy cooking, enjoy reading.",errorSpot:{errorWordIndex:2,wrongWord:"swam",correction:"swimming",reason:"'Enjoy' is followed by -ing, not a past tense verb.",correctionOptions:["swimming","swim","to swim","swum"]}},{id:"vp-err-2",topic:"verb-patterns",type:"error-spot",difficulty:"beginner",sentence:"She hopes passing the exam next week.",grammarRule:"Verb + to infinitive (hope)",explanation:"'Hope' must be followed by a to infinitive, not -ing. The correct form is 'hopes to pass'.",tip:"Hope is about a future wish — use to + infinitive: hope to pass, hope to win.",errorSpot:{errorWordIndex:2,wrongWord:"passing",correction:"to pass",reason:"'Hope' is followed by to + infinitive, not -ing.",correctionOptions:["to pass","pass","passed","to passing"]}},{id:"vp-err-3",topic:"verb-patterns",type:"error-spot",difficulty:"intermediate",sentence:"He avoided travelled by bus to work every day.",grammarRule:"Verb + -ing form (avoid)",explanation:"'Avoid' must be followed by the -ing form, not past tense. The correct form is 'avoided travelling'.",tip:"Avoid is always followed by -ing: avoid travelling, avoid eating, avoid making.",errorSpot:{errorWordIndex:2,wrongWord:"travelled",correction:"travelling",reason:"'Avoid' is followed by -ing, not past simple.",correctionOptions:["travelling","to travel","travel","travels"]}},{id:"vp-err-4",topic:"verb-patterns",type:"error-spot",difficulty:"intermediate",sentence:"They decided going to Paris for their summer holiday.",grammarRule:"Verb + to infinitive (decide)",explanation:"'Decide' must be followed by a to infinitive, not -ing. The correct form is 'decided to go'.",tip:"Decide always takes to + infinitive: decided to go, decided to stay, decided to buy.",errorSpot:{errorWordIndex:2,wrongWord:"going",correction:"to go",reason:"'Decide' is followed by to + infinitive, not -ing.",correctionOptions:["to go","go","went","to going"]}},{id:"vp-err-5",topic:"verb-patterns",type:"error-spot",difficulty:"intermediate",sentence:"I miss see my old school friends from primary school.",grammarRule:"Verb + -ing form (miss)",explanation:"'Miss' must be followed by the -ing form. The correct form is 'miss seeing'.",tip:"Miss is followed by -ing: miss seeing, miss living, miss working.",errorSpot:{errorWordIndex:2,wrongWord:"see",correction:"seeing",reason:"'Miss' is followed by -ing, not the base form.",correctionOptions:["seeing","to see","saw","seen"]}},{id:"vp-err-6",topic:"verb-patterns",type:"error-spot",difficulty:"intermediate",sentence:"She promised finishing the project before the end of the week.",grammarRule:"Verb + to infinitive (promise)",explanation:"'Promise' must be followed by a to infinitive, not -ing. The correct form is 'promised to finish'.",tip:"Promise always takes to + infinitive: promised to finish, promised to call, promised to help.",errorSpot:{errorWordIndex:2,wrongWord:"finishing",correction:"to finish",reason:"'Promise' is followed by to + infinitive, not -ing.",correctionOptions:["to finish","finish","finished","to finishing"]}},{id:"vp-mc-1",topic:"verb-patterns",type:"multiple-choice",difficulty:"beginner",sentence:"Which verb is always followed by an -ing form?",grammarRule:"Verbs followed by -ing vs to infinitive",explanation:"'Enjoy' is always followed by -ing (enjoy swimming). 'Hope', 'want', and 'decide' are followed by to + infinitive.",tip:"Key -ing verbs: enjoy, avoid, miss, finish, imagine, don't mind, stop, spend time.",multipleChoice:{question:"Which option is correct?",correctOption:"enjoy",options:["enjoy","hope","want","decide"],optionExplanations:{enjoy:"Correct! 'Enjoy' is always followed by -ing: I enjoy swimming.",hope:"Wrong. 'Hope' takes to + infinitive: I hope to pass the exam.",want:"Wrong. 'Want' takes to + infinitive: I want to go home.",decide:"Wrong. 'Decide' takes to + infinitive: She decided to leave."}}},{id:"vp-mc-2",topic:"verb-patterns",type:"multiple-choice",difficulty:"beginner",sentence:"I would like ___ to London next summer.",grammarRule:"Verb + to infinitive (would like)",explanation:"'Would like' is followed by a to infinitive, just like 'want'. We say 'would like to travel', never 'would like travelling'.",tip:"'Would like' = polite 'want'. Both take to + infinitive.",multipleChoice:{question:"Which option correctly completes the sentence?",correctOption:"to travel",options:["to travel","travelling","travel","travelled"],optionExplanations:{"to travel":"Correct! 'Would like' is followed by to + infinitive.",travelling:"Wrong. 'Would like' takes to + infinitive, not -ing.",travel:"Wrong. You need 'to' before the verb after 'would like'.",travelled:"Wrong. 'Would like' takes to + infinitive in present meaning."}}},{id:"vp-mc-3",topic:"verb-patterns",type:"multiple-choice",difficulty:"beginner",sentence:"They agreed ___ the project together by the end of the month.",grammarRule:"Verb + to infinitive (agree)",explanation:"'Agree' is followed by a to infinitive. We say 'agreed to finish', 'agreed to help', never 'agreed finishing'.",tip:"'Agree' describes a decision or promise about the future — use to + infinitive.",multipleChoice:{question:"Which option correctly completes the sentence?",correctOption:"to finish",options:["to finish","finishing","finish","finished"],optionExplanations:{"to finish":"Correct! 'Agree' is followed by to + infinitive.",finishing:"Wrong. 'Agree' takes to + infinitive, not -ing.",finish:"Wrong. You need 'to' before the verb after 'agree'.",finished:"Wrong. 'Agree' takes to + infinitive, not past simple."}}},{id:"vp-mc-4",topic:"verb-patterns",type:"multiple-choice",difficulty:"intermediate",sentence:"I don't mind ___ early if it means avoiding the traffic.",grammarRule:"Verb + -ing form (don't mind)",explanation:"'Don't mind' is always followed by -ing. We say 'don't mind getting up', 'don't mind waiting', never 'don't mind to get up'.",tip:"'Don't mind' means it's not a problem for you — use -ing to describe the action.",multipleChoice:{question:"Which option correctly completes the sentence?",correctOption:"getting up",options:["getting up","to get up","get up","got up"],optionExplanations:{"getting up":"Correct! 'Don't mind' is always followed by -ing.","to get up":"Wrong. 'Don't mind' takes -ing, not to + infinitive.","get up":"Wrong. 'Don't mind' must be followed by -ing.","got up":"Wrong. 'Don't mind' takes -ing, not a past tense verb."}}},{id:"vp-mc-5",topic:"verb-patterns",type:"multiple-choice",difficulty:"intermediate",sentence:"She needs ___ harder if she wants to pass the exam.",grammarRule:"Verb + to infinitive (need)",explanation:"'Need' is followed by a to infinitive. We say 'needs to study', 'needs to work', never 'needs studying' (in this meaning).",tip:"Need + to infinitive describes what must be done: need to study, need to hurry.",multipleChoice:{question:"Which option correctly completes the sentence?",correctOption:"to study",options:["to study","studying","study","studied"],optionExplanations:{"to study":"Correct! 'Need' (about a person) is followed by to + infinitive.",studying:"Wrong. 'Need' (about a person) takes to + infinitive, not -ing.",study:"Wrong. You need 'to' before the verb after 'need'.",studied:"Wrong. 'Need' takes to + infinitive, not past simple."}}},{id:"vp-mc-6",topic:"verb-patterns",type:"multiple-choice",difficulty:"advanced",sentence:"___ in a foreign language can be very challenging at first.",grammarRule:"-ing form as subject of a sentence",explanation:"An -ing form can act as the subject of a sentence, just like a noun. 'Reading in a foreign language' is the subject here. We cannot use 'to read' as a subject in natural spoken English.",tip:"When a verb is the subject of a sentence, use -ing: Swimming is fun. Reading helps you learn.",multipleChoice:{question:"Which option correctly completes the sentence?",correctOption:"Reading",options:["Reading","To read","Read","Reads"],optionExplanations:{Reading:"Correct! The -ing form can act as the subject of a sentence.","To read":"This can work in formal written English, but -ing is more natural here.",Read:"Wrong. The base form cannot be the subject of a sentence.",Reads:"Wrong. A conjugated verb cannot be the subject of a sentence."}}},{id:"vp-reorder-1",topic:"verb-patterns",type:"word-transform",difficulty:"beginner",sentence:"I love ___ in the sea.",grammarRule:"Verb + -ing form (love)",explanation:"'Love' is followed by the -ing form: 'love swimming'. Add -ing to the base verb.",tip:"Love, like, hate, enjoy — all followed by -ing: love swimming, enjoy reading.",wordTransform:{baseWord:"swim",correctAnswer:"swimming"}},{id:"vp-reorder-2",topic:"verb-patterns",type:"word-transform",difficulty:"beginner",sentence:"She decided ___ a new car.",grammarRule:"Verb + to infinitive (decide)",explanation:"'Decide' is followed by to + infinitive: 'decided to buy'. Use the full infinitive form.",tip:"Decide, choose, agree, promise — always followed by to + infinitive.",wordTransform:{baseWord:"buy",correctAnswer:"to buy"}},{id:"vp-reorder-3",topic:"verb-patterns",type:"word-transform",difficulty:"beginner",sentence:"They avoid ___ by bus.",grammarRule:"Verb + -ing form (avoid)",explanation:"'Avoid' is always followed by -ing: 'avoid travelling'. Never use to + infinitive after avoid.",tip:"Avoid + -ing: avoid travelling, avoid eating, avoid making mistakes.",wordTransform:{baseWord:"travel",correctAnswer:"travelling",alternativeAnswers:["traveling"]}},{id:"vp-reorder-4",topic:"verb-patterns",type:"word-transform",difficulty:"intermediate",sentence:"He hopes ___ a doctor one day.",grammarRule:"Verb + to infinitive (hope)",explanation:"'Hope' is followed by to + infinitive: 'hopes to become'. Use the full infinitive form.",tip:"Hope describes a wish — always followed by to + infinitive: hope to become, hope to find.",wordTransform:{baseWord:"become",correctAnswer:"to become"}},{id:"vp-reorder-5",topic:"verb-patterns",type:"word-transform",difficulty:"intermediate",sentence:"I enjoy ___ in the park on weekends.",grammarRule:"-ing form after enjoy",explanation:"'Enjoy' is always followed by the -ing form, not the infinitive: 'enjoy walking'.",tip:"Enjoy + -ing: enjoy walking, enjoy cooking, enjoy watching. Never enjoy + to.",wordTransform:{baseWord:"walk",correctAnswer:"walking"}},{id:"vp-reorder-6",topic:"verb-patterns",type:"word-transform",difficulty:"intermediate",sentence:"I promised ___ on time.",grammarRule:"Verb + to infinitive (promise)",explanation:"'Promise' is followed by to + infinitive: 'promised to arrive'. Use the full infinitive.",tip:"Promise always takes to + infinitive: promise to call, promise to arrive, promise to help.",wordTransform:{baseWord:"arrive",correctAnswer:"to arrive"}}]},i={id:"narrative-tenses",level:"B1",name:"Narrative Tenses",description:"Practise Past Simple, Past Continuous, and Past Perfect — the three tenses used to tell stories in English.",icon:"📖",cards:[{id:"nt-card-1",rule:"Past Simple for finished events in order",example:"Last Friday we ___ (arrive) at the hotel at nine and went straight to bed.",answer:"arrived",explanation:"Use Past Simple for finished actions in the past. When we tell events one after another, each verb is Past Simple.",examples:["She opened the window, took a deep breath and started to work.","Our flight landed at noon, and we took a taxi to the city centre."],ua:"Завершені дії в минулому, одна за одною: приїхали, пішли спати. Правильні дієслова мають -ed."},{id:"nt-card-2",rule:"did / didn't + base verb",example:"We didn't ___ (go) out last night because it was raining.",answer:"go",explanation:"After did or didn't, the main verb goes back to the base form. The past is already shown by did.",examples:["I didn't sleep well last night because of the noise.","Did you enjoy the concert on Saturday?"],ua:"Після did/didn't дієслово в початковій формі: didn't go, а не «didn't went»."},{id:"nt-card-3",rule:"was/were + -ing for what was in progress",example:"At nine o'clock last night, my parents ___ (watch) the news on TV.",answer:"were watching",explanation:"Use Past Continuous to say what was happening at a certain moment in the past. The action was not finished at that moment.",examples:["At eight o'clock this morning, I was waiting for the bus in the rain.","At midnight, the neighbours were still talking on the balcony."],ua:"Past Continuous — «що відбувалося в той момент»: о дев'ятій вони дивилися — were watching."},{id:"nt-card-4",rule:"was + -ing, when + Past Simple (interrupted action)",example:"We ___ (drive) to the airport when the car broke down.",answer:"were driving",explanation:"A long action in progress uses Past Continuous. A short event that interrupted it uses Past Simple, often after when.",examples:["I was crossing the street when I saw an old friend.","She was paying at the till when her card stopped working."],ua:"Довга дія — were driving, коротка подія, що її перервала, — Past Simple: «їхали, коли зламалася»."},{id:"nt-card-5",rule:"while + Past Continuous (two actions at the same time)",example:"While the mechanic ___ (check) the engine, I was reading in the waiting room.",answer:"was checking",explanation:"Use while with Past Continuous for actions that went on at the same time. Both actions were in progress together.",examples:["While we were having lunch, the children were playing in the garden.","My colleague was typing a report while I was answering emails."],ua:"while + Past Continuous: дві дії тривали одночасно — «поки механік перевіряв, я читала»."},{id:"nt-card-6",rule:"had + past participle for the earlier past action",example:"When I opened the fridge, someone ___ (already/eat) all the cheese.",answer:"had already eaten",explanation:"Past Perfect shows that one past action happened before another past action. The earlier action is had + past participle.",examples:["By the time we found the café, it had already closed.","When she called him, he had already left the office."],ua:"Past Perfect (had + V3) — дія, що сталася раніше за іншу минулу: «відкрив, а сир уже з'їли»."},{id:"nt-card-7",rule:"found out / discovered + Past Perfect",example:"I called the hotel and found out that they ___ (lose) my booking the day before.",answer:"had lost",explanation:"After verbs like find out, discover and realise, use Past Perfect for the thing that happened earlier. First it happened, later you learned about it.",examples:["We found out that our neighbours had moved to Poland the year before.","He discovered that someone had borrowed his car without asking."],ua:"found out / discovered + had + V3: дізналися пізніше, а подія сталася раніше (the day before)."},{id:"nt-card-8",rule:"had never + past participle (before that moment)",example:"We were surprised, because we ___ (never/see) snow before that day.",answer:"had never seen",explanation:"Use had never + past participle for an experience you did not have before a certain moment in the past. It is the past version of have never.",examples:["I had never flown before that trip, so I was very nervous.","She had never met his parents until that weekend."],ua:"had never + V3: «ніколи раніше не бачили» — досвід до певного моменту в минулому."}],rules:[{id:"nt-gap-1",topic:"narrative-tenses",type:"gap-fill",difficulty:"beginner",sentence:"I ___ university in 2015 and started my first job.",grammarRule:"Past Simple — completed action in the past",explanation:"We use Past Simple for completed actions in the past, especially with a specific time (in 2015). 'Left' is the Past Simple form of 'leave'.",tip:"Past Simple answers the question: What happened? When did it happen?",gapFill:{gapIndex:1,correctAnswer:"left",options:["left","leave","was leaving","had left"],correctOptionIndex:0}},{id:"nt-gap-2",topic:"narrative-tenses",type:"gap-fill",difficulty:"beginner",sentence:"She ___ a book when the phone rang.",grammarRule:"Past Continuous — action interrupted by Past Simple",explanation:"The longer background action (reading) uses Past Continuous. The short interrupting action (rang) uses Past Simple. Structure: was/were + -ing.",tip:"When = interruption. The action in 'when' clause uses Past Simple; the longer action uses Past Continuous.",gapFill:{gapIndex:1,correctAnswer:"was reading",options:["was reading","read","reads","had read"],correctOptionIndex:0}},{id:"nt-gap-3",topic:"narrative-tenses",type:"gap-fill",difficulty:"beginner",sentence:"They ___ dinner when we arrived at the restaurant.",grammarRule:"Past Continuous — background action in progress",explanation:"Past Continuous describes what was already happening (eating dinner) when another event occurred (we arrived). Structure: were + -ing.",tip:"Past Continuous = the scene that was already set when the story moment happened.",gapFill:{gapIndex:1,correctAnswer:"were having",options:["were having","had","have had","had had"],correctOptionIndex:0}},{id:"nt-gap-4",topic:"narrative-tenses",type:"gap-fill",difficulty:"intermediate",sentence:"By the time we arrived, the film ___ already started.",grammarRule:"Past Perfect — action completed before another past action",explanation:"'Had' + past participle (had started) = Past Perfect. The film starting happened BEFORE we arrived. We use Past Perfect to make the order clear.",tip:"'By the time' is a classic signal for Past Perfect — the earlier action is always Past Perfect.",gapFill:{gapIndex:7,correctAnswer:"had",options:["had","was","have","did"],correctOptionIndex:0}},{id:"nt-gap-5",topic:"narrative-tenses",type:"gap-fill",difficulty:"intermediate",sentence:"I realised I ___ my keys at home when I reached the door.",grammarRule:"Past Perfect — earlier past action with thinking verbs",explanation:"After thinking verbs (realise, discover, find out, remember), we often use Past Perfect to show that the earlier action happened before the moment of realisation. 'Had left' = left before the moment I realised.",tip:"Realise, discover, find out, remember + Past Perfect = a common narrative pattern.",gapFill:{gapIndex:3,correctAnswer:"had left",options:["had left","left","was leaving","have left"],correctOptionIndex:0}},{id:"nt-gap-6",topic:"narrative-tenses",type:"gap-fill",difficulty:"intermediate",sentence:"While she ___ in the garden, it started to rain.",grammarRule:"Past Continuous — simultaneous background action (while)",explanation:"'While' introduces a background action in progress (was working). The main event that interrupted it (it started to rain) uses Past Simple.",tip:"While + Past Continuous sets the scene. The interrupting event uses Past Simple.",gapFill:{gapIndex:2,correctAnswer:"was working",options:["was working","worked","had worked","works"],correctOptionIndex:0}},{id:"nt-gap-7",topic:"narrative-tenses",type:"gap-fill",difficulty:"advanced",sentence:"He ___ in Dublin for five years before he moved to Cork.",grammarRule:"Past Perfect — duration before a past event",explanation:"Past Perfect is used here to show that living in Dublin came BEFORE moving to Cork. 'Had lived' makes the sequence of events clear.",tip:"Before/after + two past actions = use Past Perfect for the earlier one to make the order clear.",gapFill:{gapIndex:1,correctAnswer:"had lived",options:["had lived","lived","was living","has lived"],correctOptionIndex:0}},{id:"nt-err-1",topic:"narrative-tenses",type:"error-spot",difficulty:"beginner",sentence:"The phone ringed while I was reading a book.",grammarRule:"Past Simple — irregular verb (ring/rang)",explanation:"'Ring' is an irregular verb. The Past Simple form is 'rang', not 'ringed'. 'Ringed' does not exist in standard English.",tip:"Irregular verbs: ring → rang → rung. Never add -ed to irregular verbs.",errorSpot:{errorWordIndex:2,wrongWord:"ringed",correction:"rang",reason:"'Ring' is irregular — Past Simple is 'rang', not 'ringed'.",correctionOptions:["rang","rung","ringed","ringing"]}},{id:"nt-err-2",topic:"narrative-tenses",type:"error-spot",difficulty:"beginner",sentence:"They was playing football when it started to rain.",grammarRule:"Past Continuous — subject-verb agreement (they/were)",explanation:"Past Continuous with 'they' must use 'were', not 'was'. 'Was' is only used with I/he/she/it.",tip:"Past Continuous: I/he/she/it + was; you/we/they + were.",errorSpot:{errorWordIndex:1,wrongWord:"was",correction:"were",reason:"'They' requires 'were', not 'was', in Past Continuous.",correctionOptions:["were","was","are","had been"]}},{id:"nt-err-3",topic:"narrative-tenses",type:"error-spot",difficulty:"beginner",sentence:"He didn't knew the way to Sam's house.",grammarRule:"Past Simple negative — did + base form",explanation:"After 'didn't', always use the base form of the verb. 'Knew' is past tense, but after 'did/didn't' we go back to the base form: 'didn't know'.",tip:"Did/didn't + BASE form — never use past tense after did/didn't.",errorSpot:{errorWordIndex:2,wrongWord:"knew",correction:"know",reason:"After 'didn't', use the base form — not the past tense form.",correctionOptions:["know","knew","known","knowing"]}},{id:"nt-err-4",topic:"narrative-tenses",type:"error-spot",difficulty:"intermediate",sentence:"She had went to Paris before she visited London.",grammarRule:"Past Perfect — had + past participle",explanation:"Past Perfect is formed with 'had' + past participle. The past participle of 'go' is 'gone', not 'went'. 'Went' is only Past Simple.",tip:"go → went (Past Simple) → gone (Past Participle). Past Perfect: had gone.",errorSpot:{errorWordIndex:2,wrongWord:"went",correction:"gone",reason:"Past Perfect = had + past participle. 'Gone' is the past participle of 'go', not 'went'.",correctionOptions:["gone","went","go","going"]}},{id:"nt-err-5",topic:"narrative-tenses",type:"error-spot",difficulty:"intermediate",sentence:"When I got to work, I realised I forgot my laptop at home.",grammarRule:"Past Perfect after thinking verbs (realise)",explanation:"After 'realised', we need Past Perfect ('had forgotten') to show that forgetting the laptop happened BEFORE the moment of realising. Using Past Simple ('forgot') makes the sequence unclear.",tip:"Realise/discover/find out + Past Perfect = the earlier action was already done when you noticed.",errorSpot:{errorWordIndex:8,wrongWord:"forgot",correction:"had forgotten",reason:"The forgetting happened before the realising — use Past Perfect: 'had forgotten'.",correctionOptions:["had forgotten","forgot","have forgotten","was forgetting"]}},{id:"nt-err-6",topic:"narrative-tenses",type:"error-spot",difficulty:"advanced",sentence:"They have visited Paris the year before they moved to London.",grammarRule:"Past Perfect vs Present Perfect",explanation:"When both events are in the past, use Past Perfect ('had visited'), not Present Perfect ('have visited'). Present Perfect connects the past to now — it cannot be used with a specific past time reference like 'the year before they moved'.",tip:"If both events are finished and in the past, use Past Perfect — never Present Perfect.",errorSpot:{errorWordIndex:1,wrongWord:"have",correction:"had",reason:"Both events are in the past — use Past Perfect (had visited), not Present Perfect (have visited).",correctionOptions:["had","have","has","were"]}},{id:"nt-mc-1",topic:"narrative-tenses",type:"multiple-choice",difficulty:"beginner",sentence:"I ___ to music when the internet crashed.",grammarRule:"Past Continuous — interrupted background action",explanation:"The background action in progress (listening to music) uses Past Continuous. The sudden interrupting event (crashed) uses Past Simple.",tip:"Crash, ring, knock, arrive — these sudden events interrupt a Past Continuous action.",multipleChoice:{question:"Which option correctly completes the sentence?",correctOption:"was listening",options:["was listening","listened","had listened","listen"],optionExplanations:{"was listening":"Correct! Past Continuous shows the background action that was interrupted.",listened:"Wrong. 'Listened' (Past Simple) would mean both actions are equal main events.","had listened":"Wrong. Past Perfect is for an earlier action, not a simultaneous background one.",listen:"Wrong. 'Listen' is present tense — we need a past form here."}}},{id:"nt-mc-2",topic:"narrative-tenses",type:"multiple-choice",difficulty:"beginner",sentence:"He ___ the restaurant at 7pm and ordered a steak.",grammarRule:"Past Simple — sequence of completed actions",explanation:"We use Past Simple for a sequence of completed past actions. Both actions (arrived, ordered) happened one after the other and are finished.",tip:"A sequence of story events: he arrived → he ordered → he ate. Each uses Past Simple.",multipleChoice:{question:"Which option correctly completes the sentence?",correctOption:"arrived at",options:["arrived at","was arriving at","had arrived at","arrives at"],optionExplanations:{"arrived at":"Correct! Past Simple for a completed action in a sequence.","was arriving at":"Wrong. Past Continuous describes a background action, not a sequence of events.","had arrived at":"Wrong. Past Perfect is for an action completed before another past action.","arrives at":"Wrong. 'Arrives' is present tense — we need the past here."}}},{id:"nt-mc-3",topic:"narrative-tenses",type:"multiple-choice",difficulty:"intermediate",sentence:"By the time she got to the station, the train ___.",grammarRule:"Past Perfect — action completed before another past action",explanation:"'By the time' shows that the train leaving happened BEFORE she got to the station. The earlier action uses Past Perfect.",tip:"'By the time' + Past Simple → Past Perfect in the other clause.",multipleChoice:{question:"Which option correctly completes the sentence?",correctOption:"had already left",options:["had already left","already left","was already leaving","has already left"],optionExplanations:{"had already left":"Correct! Past Perfect shows the train left before she arrived.","already left":"Wrong. Past Simple doesn't make the sequence clear enough here.","was already leaving":"Wrong. Past Continuous suggests it was in progress, not already gone.","has already left":"Wrong. Present Perfect cannot be used for a finished past situation."}}},{id:"nt-mc-4",topic:"narrative-tenses",type:"multiple-choice",difficulty:"intermediate",sentence:"They ___ their coffee as the waiter closed the café.",grammarRule:"Past Continuous — two simultaneous actions (as/while)",explanation:"'As' and 'while' are used to describe two actions happening at the same time. Both actions use Past Continuous to show they were in progress together.",tip:"As/while + two actions happening together = Past Continuous + Past Continuous.",multipleChoice:{question:"Which option correctly completes the sentence?",correctOption:"were finishing",options:["were finishing","finished","had finished","finish"],optionExplanations:{"were finishing":"Correct! Past Continuous for an action in progress at the same time as another.",finished:"Wrong. 'Finished' (Past Simple) suggests a sequence, not simultaneous actions.","had finished":"Wrong. Past Perfect means the action was already over — but here it was still happening.",finish:"Wrong. 'Finish' is present tense — we need a past form here."}}},{id:"nt-mc-5",topic:"narrative-tenses",type:"multiple-choice",difficulty:"intermediate",sentence:"I didn't have any money because I ___ my wallet.",grammarRule:"Past Perfect — cause happened before the effect",explanation:"The cause (losing the wallet) happened BEFORE the effect (not having money). We use Past Perfect for the earlier action: 'had lost'.",tip:"When one past event caused another — the cause uses Past Perfect.",multipleChoice:{question:"Which option correctly completes the sentence?",correctOption:"had lost",options:["had lost","lost","was losing","have lost"],optionExplanations:{"had lost":"Correct! The wallet was lost BEFORE the moment of not having money.",lost:"This is possible when the sequence is already clear, but Past Perfect is more precise here.","was losing":"Wrong. Past Continuous suggests the losing was in progress, not completed.","have lost":"Wrong. Present Perfect cannot be used in a fully past narrative."}}},{id:"nt-mc-6",topic:"narrative-tenses",type:"multiple-choice",difficulty:"advanced",sentence:"How ___ Harry at university?",grammarRule:"Past Simple — question form (did + base form)",explanation:"Past Simple questions use 'did' + subject + base form. We say 'How did you meet Harry?' — never 'How did you met Harry?'.",tip:"Past Simple question: Did + subject + BASE FORM. The main verb stays in base form.",multipleChoice:{question:"Which option correctly completes the question?",correctOption:"did you meet",options:["did you meet","did you met","were you meeting","had you met"],optionExplanations:{"did you meet":"Correct! Past Simple question: did + subject + base form.","did you met":"Wrong. After 'did', always use the base form — never the past tense form.","were you meeting":"Wrong. Past Continuous question form, but doesn't fit this context.","had you met":"Wrong. Past Perfect question would need a specific earlier past context."}}},{id:"nt-reorder-1",topic:"narrative-tenses",type:"word-transform",difficulty:"beginner",sentence:"She ___ a book when the phone rang.",grammarRule:"Past Continuous — interrupted background action",explanation:"Past Continuous describes what was in progress when the interruption happened. Structure: was/were + verb-ing.",tip:"Background action in progress + 'when' + interruption: was reading when the phone rang.",wordTransform:{baseWord:"read",correctAnswer:"was reading"}},{id:"nt-reorder-2",topic:"narrative-tenses",type:"word-transform",difficulty:"beginner",sentence:"While I ___ home, I met an old friend.",grammarRule:"Past Continuous — background action with 'while'",explanation:"'While' introduces the longer background action in Past Continuous. The meeting (Past Simple) happened during the walk.",tip:"While + Past Continuous (ongoing action) + Past Simple (event that happened during it).",wordTransform:{baseWord:"walk",correctAnswer:"was walking"}},{id:"nt-reorder-3",topic:"narrative-tenses",type:"word-transform",difficulty:"intermediate",sentence:"When I arrived, the film had already ___.",grammarRule:"Past Perfect — completed before another past event",explanation:"Past Perfect shows the film started before I arrived. Past Participle of 'start' is 'started' (regular verb).",tip:"The earlier action → Past Perfect: had already started, had already left, had already finished.",wordTransform:{baseWord:"start",correctAnswer:"started"}},{id:"nt-reorder-4",topic:"narrative-tenses",type:"word-transform",difficulty:"intermediate",sentence:"She had already ___ before he arrived.",grammarRule:"Past Perfect — completed before another past event",explanation:"Past Perfect: had + past participle. 'Eaten' is the past participle of 'eat'. It shows the meal was finished before his arrival.",tip:"Eat → ate (Past Simple) → eaten (Past Participle). 'Had eaten' = Past Perfect.",wordTransform:{baseWord:"eat",correctAnswer:"eaten"}},{id:"nt-reorder-5",topic:"narrative-tenses",type:"word-transform",difficulty:"intermediate",sentence:"I ___ TV when the lights went out.",grammarRule:"Past Continuous — activity in progress when interrupted",explanation:"Past Continuous shows what was happening when the interruption occurred. 'Was watching' = in progress.",tip:"Was/were + verb-ing = action in progress. 'When' introduces the interrupting event.",wordTransform:{baseWord:"watch",correctAnswer:"was watching"}},{id:"nt-reorder-6",topic:"narrative-tenses",type:"word-transform",difficulty:"advanced",sentence:"By the time we arrived, they had already ___.",grammarRule:"Past Perfect — earlier completed action",explanation:"'By the time we arrived' means before our arrival. Past Perfect (had left) shows the earlier completed action.",tip:"By the time... + Past Perfect: had already left, had already eaten, had already gone.",wordTransform:{baseWord:"leave",correctAnswer:"left"}}]},a={id:"modifiers",level:"B1",name:"Modifiers",description:"Practise modifiers like quite, fairly, relatively, and a bit/a lot more — used to say how much or how little something is true.",lesson:"Lesson 10",icon:"📏",cards:[{id:"mod-card-1",rule:"quite + adjective",example:"The hotel was ___ (quite / very) nice: not bad, but not great either.",answer:"quite",explanation:"Quite makes an adjective weaker than very. Something is true, but not strongly: quite interesting means interesting, but not very interesting.",examples:["The hotel was quite small, but the rooms were clean.","My new neighbours seem quite friendly."],ua:"quite ≈ «досить» (слабше, ніж very): quite small — «досить маленький»."},{id:"mod-card-2",rule:"quite a / an + adjective + noun",example:"She is quite ___ interesting person — she has lived in six countries.",answer:"an",explanation:"Only quite can go before a or an: quite a long day, quite an easy test. We cannot say fairly a long day or pretty an easy test.",examples:["It was quite a long journey, but we enjoyed it.","He is quite an experienced driver."],ua:"Перед a / an ставимо тільки quite: quite an easy test, а не fairly an easy test."},{id:"mod-card-3",rule:"quite a lot of + noun + to + verb",example:"She has quite a lot of money ___ spend on holidays.",answer:"to",explanation:"Quite a lot of means a large amount. After the noun, use to + infinitive, not -ing: quite a lot of money to spend, quite a lot of work to do.",examples:["We have quite a lot of work to finish before Friday.","There is quite a lot of food to carry."],ua:"Після іменника — to + дієслово: quite a lot of work to do — «досить багато роботи»."},{id:"mod-card-4",rule:"fairly / relatively / reasonably + adjective",example:"For a hotel in the city centre, it was ___ (relative) cheap.",answer:"relatively",explanation:"Fairly, relatively and reasonably also mean moderately. Use them before an adjective in its normal form, not before an -er form: fairly cheap, not fairly cheaper.",examples:["The new library is relatively quiet, even at lunchtime.","The flat is in a reasonably good area."],ua:"fairly / relatively / reasonably ≈ «досить», «відносно». Далі — звичайна форма: fairly cheap."},{id:"mod-card-5",rule:"pretty + adjective",example:"Your English is pretty ___ (good / well). Where did you learn it?",answer:"good",explanation:"Before an adjective, pretty means quite or fairly. It is informal. Use an adjective after pretty, not an adverb: pretty good, not pretty well.",examples:["The coffee here is pretty good, and it's cheap.","My train was pretty full this morning."],ua:"pretty тут не «гарний», а «досить»: pretty good — «досить добре»."},{id:"mod-card-6",rule:"a bit more / a bit less",example:"My husband earns 30,000 hryvnias a month and I earn 29,000, so I earn a bit ___ than he does.",answer:"less",explanation:"A bit more and a bit less show a small difference. After a bit more, use the normal adjective: a bit more careful, not a bit more carefuller.",examples:["I'd like to sleep a bit more at the weekend.","Could you be a bit more careful with my laptop?"],ua:"a bit more / less — «трохи більше / менше». Після more — звичайна форма: a bit more careful."},{id:"mod-card-7",rule:"a lot more / a lot less",example:"Marta's old flat was tiny. Her new flat has three bedrooms, so she has a ___ more space now.",answer:"lot",explanation:"A lot more and a lot less show a big difference. Use a bit for a small change and a lot for a large change.",examples:["The new phone is a lot more expensive than my old one.","She now works a lot more than she used to."],ua:"a lot more / less — «набагато більше / менше», a bit — «трохи»."},{id:"mod-card-8",rule:"less + uncountable, fewer + countable",example:"A smaller team means ___ people to share the work.",answer:"fewer",explanation:"Use less with uncountable nouns (money, time, traffic) and fewer with countable nouns (people, meetings, cars). A lot less and a lot fewer follow the same rule.",examples:["There is less traffic in the city on Sundays.","We had fewer customers than usual this week."],ua:"Fewer — те, що можна порахувати (people), less — те, що не можна (money, time)."},{id:"mod-card-9",rule:"hard (= with effort) and hardly (= almost not)",example:"He studies ___ (hard / hardly) every evening, so he got the best mark in the group.",answer:"hard",explanation:"Hard means with a lot of effort: work hard, try hard. Hardly means almost not: I hardly know him. The two words have very different meanings.",examples:["My grandmother worked hard all her life.","I hardly know my new neighbours."],ua:"hard — «наполегливо»; hardly — «ледве, майже не». Значення різні!"},{id:"mod-card-10",rule:"good (adjective) and well (adverb)",example:"We have lived next door for ten years, so we know each other very ___.",answer:"well",explanation:"Good describes a noun: a good cook. Well describes how we do something: he cooks well. After a verb, use well, not good.",examples:["My brother speaks English well after two years abroad.","She is a good listener."],ua:"good — прикметник («хороший»), well — прислівник («добре»): «Вона добре готує» — She cooks well."}],rules:[{id:"mod-gap-1",topic:"modifiers",type:"gap-fill",difficulty:"beginner",sentence:"That's ___ interesting — I wouldn't say it was very exciting though.",grammarRule:"quite — less strong than very",explanation:"'Quite' means less strong than 'very'. We use it when something is true to a moderate degree. 'That's quite interesting' = it's interesting, but not very interesting.",tip:"Quite = moderately true. Very = strongly true. Quite is always weaker than very.",gapFill:{gapIndex:1,correctAnswer:"quite",options:["quite","very","extremely","absolutely"],correctOptionIndex:0}},{id:"mod-gap-2",topic:"modifiers",type:"gap-fill",difficulty:"beginner",sentence:"It's ___ difficult to find a good job in this city at the moment.",grammarRule:"quite + adjective",explanation:"'Quite' + adjective describes something that is true to a moderate degree. 'Quite difficult' = difficult, but not extremely difficult.",tip:"quite + adjective: quite difficult, quite expensive, quite interesting.",gapFill:{gapIndex:1,correctAnswer:"quite",options:["quite","a bit","a lot","much"],correctOptionIndex:0}},{id:"mod-gap-3",topic:"modifiers",type:"gap-fill",difficulty:"beginner",sentence:"This area is ___ cheap to live in compared to the city centre.",grammarRule:"relatively + adjective",explanation:"'Relatively' means in comparison to other things. 'Relatively cheap' = cheap when you compare it to other options. It has a similar meaning to 'quite' and 'fairly'.",tip:"Relatively, fairly, quite, pretty — all mean 'to a moderate degree'. Use them before adjectives.",gapFill:{gapIndex:3,correctAnswer:"relatively",options:["relatively","absolutely","extremely","very"],correctOptionIndex:0}},{id:"mod-gap-4",topic:"modifiers",type:"gap-fill",difficulty:"intermediate",sentence:"She's ___ an easy-going person — that's why everyone gets along with her.",grammarRule:"quite a/an + adjective + noun",explanation:"Only 'quite' can go before 'a/an'. We say 'quite a difficult language', 'quite an easy-going person'. We cannot use fairly, relatively, or pretty in this structure.",tip:"quite a/an + adjective + noun. No other modifier (fairly, relatively, pretty) works in this structure.",gapFill:{gapIndex:1,correctAnswer:"quite",options:["quite","fairly","relatively","pretty"],correctOptionIndex:0}},{id:"mod-gap-5",topic:"modifiers",type:"gap-fill",difficulty:"intermediate",sentence:"He is ___ happy with his new lifestyle since moving to the countryside.",grammarRule:"fairly + adjective",explanation:"'Fairly' means to a moderate degree — similar to 'quite'. 'Fairly happy' = happy, but not very happy. It is used only before adjectives, not before 'a/an'.",tip:"Fairly, relatively, pretty, reasonably are all interchangeable with quite before adjectives.",gapFill:{gapIndex:3,correctAnswer:"fairly",options:["fairly","absolutely","completely","extremely"],correctOptionIndex:0}},{id:"mod-gap-6",topic:"modifiers",type:"gap-fill",difficulty:"intermediate",sentence:"I'd like to travel ___ more before I settle down and start a family.",grammarRule:"a bit more — small degree",explanation:"'A bit more' means a small amount more. 'I'd like to travel a bit more' = I want to travel slightly more than I do now. 'A bit' is used for small changes.",tip:"a bit more/less = small degree. a lot more/less = large degree.",gapFill:{gapIndex:4,correctAnswer:"a bit",options:["a bit","a lot","quite","fairly"],correctOptionIndex:0}},{id:"mod-gap-7",topic:"modifiers",type:"gap-fill",difficulty:"intermediate",sentence:"She'd like to spend ___ less on eating out and save more money each month.",grammarRule:"a lot less — large degree",explanation:"'A lot less' means a large amount less. It suggests a significant reduction. Compare: 'a bit less' (small change) vs 'a lot less' (big change).",tip:"a lot more/less = significantly more/less. Use when the change is large.",gapFill:{gapIndex:4,correctAnswer:"a lot",options:["a lot","a bit","quite","fairly"],correctOptionIndex:0}},{id:"mod-err-1",topic:"modifiers",type:"error-spot",difficulty:"beginner",sentence:"She'd like to be a bit more healthier than she is now.",grammarRule:"a bit more + adjective (base form)",explanation:"'A bit more' is already a comparative structure, so the adjective must stay in its base form. We say 'a bit more healthy', never 'a bit more healthier' — that's a double comparative.",tip:"a bit more + BASE adjective: a bit more healthy, a bit more careful. Never use -er after 'more'.",errorSpot:{errorWordIndex:7,wrongWord:"healthier",correction:"healthy",reason:"'A bit more' already makes it comparative — don't add -er as well.",correctionOptions:["healthy","healthier","healthiest","health"]}},{id:"mod-err-2",topic:"modifiers",type:"error-spot",difficulty:"beginner",sentence:"He is fairly happier with his new lifestyle since moving abroad.",grammarRule:"fairly + adjective (base form)",explanation:"'Fairly' is a modifier used before the base form of an adjective. 'Happier' is comparative — you cannot combine a modifier like 'fairly' with a comparative adjective.",tip:"fairly/quite/relatively + BASE adjective. Never use them before -er comparative forms.",errorSpot:{errorWordIndex:3,wrongWord:"happier",correction:"happy",reason:"'Fairly' goes before the base form of an adjective, not a comparative form.",correctionOptions:["happy","happier","happiest","happiness"]}},{id:"mod-err-3",topic:"modifiers",type:"error-spot",difficulty:"intermediate",sentence:"My life is pretty well at the moment, I have no complaints.",grammarRule:"pretty + adjective (not adverb)",explanation:"'Pretty' as a modifier goes before an adjective, not an adverb. 'Well' is an adverb — the adjective form is 'good'. We say 'My life is pretty good', not 'pretty well'.",tip:"pretty/quite/fairly + adjective. 'Well' is an adverb — use 'good' (adjective) after modifiers.",errorSpot:{errorWordIndex:4,wrongWord:"well",correction:"good",reason:"Modifiers like 'pretty' go before adjectives, not adverbs. 'Well' is an adverb — use 'good'.",correctionOptions:["good","well","better","great"]}},{id:"mod-err-4",topic:"modifiers",type:"error-spot",difficulty:"intermediate",sentence:"It's quite hardly to find a parking space in the city centre.",grammarRule:"quite + adjective (not adverb)",explanation:"'Hardly' is an adverb meaning 'almost not'. The adjective here should be 'hard' (= difficult). We say 'quite hard to find', not 'quite hardly to find'.",tip:"Hard (adjective) = difficult. Hardly (adverb) = almost not. They have completely different meanings.",errorSpot:{errorWordIndex:2,wrongWord:"hardly",correction:"hard",reason:"'Hardly' means 'almost not' — the adjective needed here is 'hard' (= difficult).",correctionOptions:["hard","hardly","harder","hardest"]}},{id:"mod-err-5",topic:"modifiers",type:"error-spot",difficulty:"intermediate",sentence:"That's quite a lot of money spending on a single meal out.",grammarRule:"quite a lot of money + to infinitive",explanation:"After 'money' we use a to infinitive (to spend), not an -ing form (spending). The -ing form is not grammatically correct here as a purpose/comment structure.",tip:"quite a lot of money to spend, to save, to waste — use to + infinitive after noun phrases like this.",errorSpot:{errorWordIndex:6,wrongWord:"spending",correction:"to spend",reason:"After 'money' use to + infinitive, not -ing: 'a lot of money to spend'.",correctionOptions:["to spend","spending","spent","spend"]}},{id:"mod-err-6",topic:"modifiers",type:"error-spot",difficulty:"advanced",sentence:"She'd like to spend a lot fewer on eating out each month.",grammarRule:"a lot less (uncountable) vs a lot fewer (countable)",explanation:"'Spend' refers to money, which is uncountable. We use 'less' with uncountable nouns and 'fewer' with countable nouns. The correct form is 'a lot less', not 'a lot fewer'.",tip:"fewer = countable nouns (fewer friends, fewer meals). less = uncountable (less money, less time).",errorSpot:{errorWordIndex:6,wrongWord:"fewer",correction:"less",reason:"Money is uncountable — use 'less', not 'fewer'.",correctionOptions:["less","fewer","little","least"]}},{id:"mod-mc-1",topic:"modifiers",type:"multiple-choice",difficulty:"beginner",sentence:"That's ___ an expensive hobby — most people can't afford it.",grammarRule:"quite a/an — only 'quite' before a/an",explanation:"Only 'quite' can be placed before 'a/an' in the structure quite a/an + adjective + noun. We cannot say 'fairly an expensive hobby' or 'pretty an expensive hobby'.",tip:"quite a/an + adjective + noun is a fixed structure. No other modifier works here.",multipleChoice:{question:"Which option correctly completes the sentence?",correctOption:"quite",options:["quite","fairly","relatively","pretty"],optionExplanations:{quite:"Correct! Only 'quite' can go before 'a/an': quite an expensive hobby.",fairly:"Wrong. 'Fairly' cannot go before 'a/an' — only 'quite' works in this structure.",relatively:"Wrong. 'Relatively' cannot go before 'a/an' — only 'quite' works here.",pretty:"Wrong. 'Pretty' cannot go before 'a/an' — only 'quite' works in this structure."}}},{id:"mod-mc-2",topic:"modifiers",type:"multiple-choice",difficulty:"beginner",sentence:"The film was good, but I wouldn't say it was amazing — it was ___ entertaining.",grammarRule:"quite — moderate degree, less strong than very",explanation:"'Quite' is the right modifier here because it expresses a moderate degree — something that is true but not strongly so. The context ('good, but not amazing') confirms a moderate strength is needed.",tip:"Quite = moderate. Very/extremely = strong. When something is good but not amazing, use quite.",multipleChoice:{question:"Which option correctly completes the sentence?",correctOption:"quite",options:["quite","extremely","absolutely","incredibly"],optionExplanations:{quite:"Correct! 'Quite' expresses a moderate degree — matching the 'good but not amazing' context.",extremely:"Wrong. 'Extremely' is too strong — the context says it wasn't amazing.",absolutely:"Wrong. 'Absolutely' is used with extreme adjectives (absolutely fantastic), not moderate ones.",incredibly:"Wrong. 'Incredibly' is too strong for this context."}}},{id:"mod-mc-3",topic:"modifiers",type:"multiple-choice",difficulty:"intermediate",sentence:"I'd like to exercise ___ more — maybe just an extra 20 minutes a day.",grammarRule:"a bit more — small degree",explanation:"'A bit more' expresses a small increase. The context ('just an extra 20 minutes') confirms the change is small. 'A lot more' would suggest a much bigger increase.",tip:"Context clues like 'just', 'slightly', 'a little' suggest 'a bit'. Words like 'much', 'significantly' suggest 'a lot'.",multipleChoice:{question:"Which option correctly completes the sentence?",correctOption:"a bit",options:["a bit","a lot","quite","fairly"],optionExplanations:{"a bit":"Correct! 'A bit more' = a small increase, matching 'just an extra 20 minutes'.","a lot":"Wrong. 'A lot more' suggests a big increase — but the context says 'just an extra 20 minutes'.",quite:"Wrong. 'Quite more' is not a standard English expression.",fairly:"Wrong. 'Fairly more' is not correct — use 'fairly' before adjectives, not before 'more'."}}},{id:"mod-mc-4",topic:"modifiers",type:"multiple-choice",difficulty:"intermediate",sentence:"The new office is ___ easy to get to — there are two bus routes and a metro stop.",grammarRule:"fairly/relatively/quite/pretty + adjective",explanation:"All four modifiers (fairly, relatively, quite, pretty) can be used before an adjective to express a moderate degree. Here 'fairly' or 'relatively' fit best as they suggest it's reasonably easy but not extremely so.",tip:"Fairly, relatively, quite, and pretty are largely interchangeable before adjectives. All mean 'moderately'.",multipleChoice:{question:"Which option correctly completes the sentence?",correctOption:"fairly",options:["fairly","absolutely","terribly","barely"],optionExplanations:{fairly:"Correct! 'Fairly easy' = moderately easy — the context supports a positive, moderate description.",absolutely:"Wrong. 'Absolutely easy' is not natural — 'absolutely' is used with extreme adjectives.",terribly:"Wrong. 'Terribly easy' sounds very informal and doesn't match the neutral tone here.",barely:"Wrong. 'Barely easy' means almost not easy — the opposite of what the context describes."}}},{id:"mod-mc-5",topic:"modifiers",type:"multiple-choice",difficulty:"intermediate",sentence:"He'd like to earn ___ more so he can save up for a house.",grammarRule:"a lot more — large degree",explanation:"'A lot more' expresses a large increase. Saving for a house requires a significant change in earnings, so 'a lot more' is appropriate. 'A bit more' would suggest only a small increase.",tip:"Saving for a house, paying off a mortgage — these are large goals. Use 'a lot more', not 'a bit more'.",multipleChoice:{question:"Which option correctly completes the sentence?",correctOption:"a lot",options:["a lot","a bit","quite","pretty"],optionExplanations:{"a lot":"Correct! 'A lot more' = a significant increase, which fits saving for a house.","a bit":"Possible, but 'a bit more' implies a small increase — unlikely to be enough to save for a house.",quite:"Wrong. 'Quite more' is not a standard English expression.",pretty:"Wrong. 'Pretty more' is not correct — use 'pretty' before adjectives only."}}},{id:"mod-mc-6",topic:"modifiers",type:"multiple-choice",difficulty:"advanced",sentence:"That's ___ a difficult language to learn — even advanced students find it challenging.",grammarRule:"quite a/an + adjective + noun",explanation:"Only 'quite' can precede 'a/an' in this structure. The sentence 'quite a difficult language' = it is significantly difficult. This use of 'quite' before 'a/an' actually has a stronger meaning than 'quite' before a plain adjective.",tip:"Quite a/an + noun phrase can sometimes mean 'remarkably' — stronger than quite + adjective alone.",multipleChoice:{question:"Which option correctly completes the sentence?",correctOption:"quite",options:["quite","rather","fairly","pretty"],optionExplanations:{quite:"Correct! Only 'quite' goes before 'a/an' in this structure: quite a difficult language.",rather:"Wrong here — 'rather a difficult language' is possible in British English but unusual; 'quite' is the standard taught form.",fairly:"Wrong. 'Fairly a difficult language' is not grammatically possible.",pretty:"Wrong. 'Pretty a difficult language' is not grammatically possible."}}},{id:"mod-reorder-1",topic:"modifiers",type:"word-transform",difficulty:"beginner",sentence:"She explains things very ___.",grammarRule:"Adjective → adverb: add -ly",explanation:"To modify a verb, use an adverb. Add -ly to the adjective 'clear' to make the adverb 'clearly'.",tip:"Adjective + -ly = adverb: clear → clearly, slow → slowly, quiet → quietly.",wordTransform:{baseWord:"clear",correctAnswer:"clearly"}},{id:"mod-reorder-2",topic:"modifiers",type:"word-transform",difficulty:"beginner",sentence:"He is ___ happy with his new job.",grammarRule:"fairly + adjective — moderate degree",explanation:"'Fairly happy' means moderately happy. 'Fairly' comes before the adjective.",tip:"Fairly goes before the adjective: fairly easy, fairly cheap, fairly good.",wordTransform:{baseWord:"fair",correctAnswer:"fairly"}},{id:"mod-reorder-3",topic:"modifiers",type:"word-transform",difficulty:"intermediate",sentence:"The test was ___ easy.",grammarRule:"surprisingly + adjective",explanation:"'Surprisingly easy' means easier than expected. Add -ly to 'surprising' to form the adverb.",tip:"Surprising → surprisingly. Use -ly adverbs before adjectives to express unexpected degree.",wordTransform:{baseWord:"surprising",correctAnswer:"surprisingly"}},{id:"mod-reorder-4",topic:"modifiers",type:"word-transform",difficulty:"intermediate",sentence:"This area is ___ expensive to live in.",grammarRule:"relatively + adjective",explanation:"'Relatively expensive' means expensive compared to other places. Add -ly to 'relative' to form the adverb.",tip:"Relative → relatively. Comes before the adjective: relatively cheap, relatively easy.",wordTransform:{baseWord:"relative",correctAnswer:"relatively"}},{id:"mod-reorder-5",topic:"modifiers",type:"word-transform",difficulty:"intermediate",sentence:"He plays the piano ___.",grammarRule:"good (adjective) vs well (adverb)",explanation:"'Well' is the adverb form of 'good'. Use 'well' to describe how an action is done: plays well, speaks well.",tip:"Good (adjective) → well (adverb). 'He plays well' (not 'plays good').",wordTransform:{baseWord:"good",correctAnswer:"well"}},{id:"mod-reorder-6",topic:"modifiers",type:"word-transform",difficulty:"advanced",sentence:"She works ___ — often until midnight.",grammarRule:"hard (adverb) vs hardly (= almost not)",explanation:"'Hard' is both an adjective and adverb meaning 'with effort'. 'Hardly' means 'almost not' — a completely different meaning.",tip:"She works hard (= with effort). She hardly works (= almost not at all). These mean opposite things!",wordTransform:{baseWord:"hard/hardly",correctAnswer:"hard"}}]},r={id:"past-simple-present-perfect",level:"B1",name:"Past Simple & Present Perfect",description:"Practise when to use the Present Perfect (I've been) and when to use the Past Simple (I went) — one of the most important distinctions in English.",icon:"⏳",cards:[{id:"ps-pp-card-1",rule:"have/has + past participle",example:"Dan ___ (already/send) the invoice, so you don't need to do it.",answer:"has already sent",explanation:"Present Perfect is have/has + past participle. Use has with he, she and it, and have with I, you, we and they. Already goes between has and the participle.",examples:["I have already booked our table for tonight.","The students have already finished the first test."],ua:"have/has + третя форма дієслова: he/she/it — has. already = «вже»."},{id:"ps-pp-card-2",rule:"ever / never + Present Perfect (life experience)",example:"I ___ (never/try) Georgian food, but I'd love to.",answer:"have never tried",explanation:"Use Present Perfect with ever and never to talk about your life up to now. We do not say when it happened.",examples:["Have you ever driven a truck?","My parents have never been to the sea."],ua:"ever = «коли-небудь», never = «ніколи». «Ти коли-небудь…?» — Have you ever…?"},{id:"ps-pp-card-3",rule:"Past Simple with a finished time (ago, yesterday, in 2019)",example:"We ___ (move) to this flat three years ago.",answer:"moved",explanation:"When we say exactly when something happened, we use Past Simple. We do not use Present Perfect with words like ago, yesterday, last year or in 2019.",examples:["I met my husband in 2012.","The shop closed two weeks ago."],ua:"ago, yesterday, in 2019 — точний минулий час: лише Past Simple (moved), не «have moved»."},{id:"ps-pp-card-4",rule:"Present Perfect for a past action with a result now",example:"Look! Somebody ___ (break) the car window!",answer:"has broken",explanation:"Use Present Perfect when a past action has a result that we can see or feel now. The result is important, not the time.",examples:["I can't log in because I have forgotten my password.","She has cut her finger, so she can't play the guitar today."],ua:"Наслідок видно зараз — has/have + V3: «розбили» (і вікно розбите) — has broken."},{id:"ps-pp-card-5",rule:"Present Perfect with today, this week, this year",example:"I ___ (write) four reports this week, and it's only Wednesday.",answer:"have written",explanation:"Use Present Perfect for a time period that is not finished yet. This week, today and this year are still going on. Compare: last week is finished, so we use Past Simple.",examples:["We have had two fire drills this year.","Has the postman come today?"],ua:"this week, today — період ще триває: have written, а не «wrote»."},{id:"ps-pp-card-6",rule:"for + period, since + point in time",example:"We've lived in this flat ___ six years, and we still love it.",answer:"for",explanation:"Use Present Perfect for a situation that started in the past and is still true now. Use for with a length of time and since with the starting point.",examples:["My brother has worked in Warsaw for six years.","We have had this car since 2018."],ua:"for + проміжок («шість років»), since + момент («з ранку»): ситуація триває й досі."},{id:"ps-pp-card-7",rule:"Present Perfect to start, Past Simple for details",example:"We've visited Lisbon twice. Last time, we ___ (stay) in a small hotel near the river.",answer:"stayed",explanation:"We often start with Present Perfect to talk about an experience. When we give details about one time, we switch to Past Simple.",examples:["I've read that novel. I borrowed it from my sister last month.","She has been to Italy. She went to Rome in 2019."],ua:"Спершу Present Perfect про досвід, потім Past Simple для деталей: last time — stayed."},{id:"ps-pp-card-8",rule:"yet in questions and negatives",example:"I haven't booked the tickets ___, so I'll do it tonight.",answer:"yet",explanation:"Use yet with Present Perfect in questions and negative sentences. It means 'until now' and goes at the end of the sentence.",examples:["Has the delivery arrived yet?","We haven't decided where to go on holiday yet."],ua:"yet у питаннях і запереченнях = «ще (не)», стоїть у кінці: haven't booked … yet."}],rules:[{id:"ps-pp-gap-1",topic:"past-simple-present-perfect",type:"gap-fill",difficulty:"beginner",sentence:"I ___ to Paris twice in my life — it's a beautiful city.",grammarRule:"Present Perfect — general experience (no specific time)",explanation:"We use Present Perfect for general life experiences when the time is not specified. 'I've been to Paris' tells us about the experience, not when it happened.",tip:"No time mentioned? Use Present Perfect. Specific time (last year, in 2019)? Use Past Simple.",gapFill:{gapIndex:1,correctAnswer:"have been",options:["have been","went","was","had been"],correctOptionIndex:0}},{id:"ps-pp-gap-2",topic:"past-simple-present-perfect",type:"gap-fill",difficulty:"beginner",sentence:"She ___ to Sweden in 2019 to attend an international conference.",grammarRule:"Past Simple — specific time in the past",explanation:"'In 2019' is a specific finished time in the past. Whenever we mention a specific past time (in 2019, last year, yesterday, this morning), we use Past Simple.",tip:"Specific time signals → Past Simple: in 2019, last year, yesterday, two days ago.",gapFill:{gapIndex:1,correctAnswer:"went",options:["went","has gone","has been","had gone"],correctOptionIndex:0}},{id:"ps-pp-gap-3",topic:"past-simple-present-perfect",type:"gap-fill",difficulty:"beginner",sentence:"Have you ___ been to New York? I'd love to visit one day.",grammarRule:"Present Perfect with ever — asking about life experience",explanation:"We use 'ever' with Present Perfect to ask about life experiences up to now. 'Have you ever been?' = at any point in your life, have you visited?",tip:"Ever and never are typical Present Perfect words. Have you EVER...? I've NEVER...",gapFill:{gapIndex:2,correctAnswer:"ever",options:["ever","never","already","just"],correctOptionIndex:0}},{id:"ps-pp-gap-4",topic:"past-simple-present-perfect",type:"gap-fill",difficulty:"intermediate",sentence:"I can't play tennis today because I ___ my leg during training.",grammarRule:"Present Perfect — past action relevant to the present",explanation:"We use Present Perfect when a past action has a result or consequence in the present. Hurting the leg happened in the past, but the result (can't play today) is happening now.",tip:"PP for present relevance: I've lost my keys (= I can't get in now). I've hurt my leg (= I can't play now).",gapFill:{gapIndex:8,correctAnswer:"have hurt",options:["have hurt","hurt","was hurting","had hurt"],correctOptionIndex:0}},{id:"ps-pp-gap-5",topic:"past-simple-present-perfect",type:"gap-fill",difficulty:"intermediate",sentence:"I ___ five kilometres today, but I might run a bit more this evening.",grammarRule:"Present Perfect — unfinished period of time",explanation:"We use Present Perfect when the time period is not finished. 'Today' is still ongoing, so we use Present Perfect. If the day were over, we'd use Past Simple.",tip:"Today, this week, this year = unfinished → Present Perfect. Yesterday, last week = finished → Past Simple.",gapFill:{gapIndex:1,correctAnswer:"have run",options:["have run","ran","was running","had run"],correctOptionIndex:0}},{id:"ps-pp-gap-6",topic:"past-simple-present-perfect",type:"gap-fill",difficulty:"intermediate",sentence:"He ___ here before, so everything in the building is new to him.",grammarRule:"Present Perfect negative — no specific time",explanation:"'Hasn't worked here before' describes a general experience up to now. There is no specific time mentioned, so we use Present Perfect. The result is visible in the present (everything is new to him).",tip:"Before, ever, never with no specific time → Present Perfect.",gapFill:{gapIndex:1,correctAnswer:"hasn't worked",options:["hasn't worked","didn't work","wasn't working","hadn't worked"],correctOptionIndex:0}},{id:"ps-pp-gap-7",topic:"past-simple-present-perfect",type:"gap-fill",difficulty:"intermediate",sentence:"A: Have you been to Colombia? B: Yes, I ___ there in 2021 with my family.",grammarRule:"Past Simple after Present Perfect opener — adding specific details",explanation:"Conversations about experiences often begin with Present Perfect. Once a specific time is mentioned (in 2021), we switch to Past Simple to add detail.",tip:"PP opens the topic → PS adds the specific story. 'Have you been?' 'Yes, I went in 2021.'",gapFill:{gapIndex:9,correctAnswer:"went",options:["went","have been","was","had gone"],correctOptionIndex:0}},{id:"ps-pp-err-1",topic:"past-simple-present-perfect",type:"error-spot",difficulty:"beginner",sentence:"I have went to Paris twice in my life.",grammarRule:"Present Perfect — have/has + past participle",explanation:"Present Perfect = have/has + past participle. 'Went' is Past Simple, not a past participle. The past participle of 'go' when talking about visiting a place is 'been'.",tip:"go → went (Past Simple) → been (Past Participle for 'have been to' = visited).",errorSpot:{errorWordIndex:2,wrongWord:"went",correction:"been",reason:"After 'have', use the past participle. 'Went' is Past Simple — the correct form is 'been'.",correctionOptions:["been","went","go","gone"]}},{id:"ps-pp-err-2",topic:"past-simple-present-perfect",type:"error-spot",difficulty:"beginner",sentence:"I has been to Poland a few times.",grammarRule:"Present Perfect — subject-verb agreement (I + have)",explanation:"'I' takes 'have', not 'has'. 'Has' is used with he/she/it. This is a common agreement mistake with Present Perfect.",tip:"I/you/we/they + have. He/she/it + has. 'I has' is always wrong.",errorSpot:{errorWordIndex:1,wrongWord:"has",correction:"have",reason:"'I' takes 'have', not 'has'. Has is only used with he/she/it.",correctionOptions:["have","has","had","am"]}},{id:"ps-pp-err-3",topic:"past-simple-present-perfect",type:"error-spot",difficulty:"beginner",sentence:"Did you ever been to New York?",grammarRule:"Present Perfect question — Have/Has + subject + past participle",explanation:"Questions with 'ever' about life experiences use Present Perfect: Have you ever been? We cannot use 'Did' with 'ever been' — 'Did' requires the base form ('go'), not the past participle ('been').",tip:"Ever in questions → Have you ever...? Never use Did + ever + past participle.",errorSpot:{errorWordIndex:0,wrongWord:"Did",correction:"Have",reason:"Questions with 'ever' use Present Perfect: Have you ever...? Not Did you ever been.",correctionOptions:["Have","Did","Do","Had"]}},{id:"ps-pp-err-4",topic:"past-simple-present-perfect",type:"error-spot",difficulty:"intermediate",sentence:"He haven't worked here before.",grammarRule:"Present Perfect negative — subject-verb agreement (he + hasn't)",explanation:"'He' takes 'hasn't' (has + not), not 'haven't' (have + not). 'Haven't' is used with I/you/we/they.",tip:"He/she/it + hasn't. I/you/we/they + haven't. Match the auxiliary to the subject.",errorSpot:{errorWordIndex:1,wrongWord:"haven't",correction:"hasn't",reason:"'He' takes 'hasn't', not 'haven't'. Haven't is for I/you/we/they.",correctionOptions:["hasn't","haven't","didn't","wasn't"]}},{id:"ps-pp-err-5",topic:"past-simple-present-perfect",type:"error-spot",difficulty:"intermediate",sentence:"She has took the exam three times this year.",grammarRule:"Present Perfect — have/has + past participle",explanation:"'Took' is Past Simple, not a past participle. The past participle of 'take' is 'taken'. Present Perfect always requires the past participle after have/has.",tip:"take → took (Past Simple) → taken (Past Participle). Always use the past participle after have/has.",errorSpot:{errorWordIndex:2,wrongWord:"took",correction:"taken",reason:"After 'has', use the past participle. 'Took' is Past Simple — the correct form is 'taken'.",correctionOptions:["taken","took","take","taking"]}},{id:"ps-pp-err-6",topic:"past-simple-present-perfect",type:"error-spot",difficulty:"advanced",sentence:"I never saw that film before.",grammarRule:"Present Perfect with never — general experience",explanation:"'Never' with a life experience requires Present Perfect, not Past Simple. 'I've never seen that film' = at no point in my life have I seen it. Using Past Simple with 'never' is incorrect in standard English.",tip:"Never with life experiences → Present Perfect: I've never been, I've never tried, I've never seen.",errorSpot:{errorWordIndex:2,wrongWord:"saw",correction:"have seen",reason:"'Never' with a life experience requires Present Perfect: 'I've never seen', not 'I never saw'.",correctionOptions:["have seen","saw","seen","had seen"]}},{id:"ps-pp-mc-1",topic:"past-simple-present-perfect",type:"multiple-choice",difficulty:"beginner",sentence:"I ___ to New York twice — it's an incredible city.",grammarRule:"Present Perfect — general experience",explanation:"No specific time is mentioned — just the number of times. This is a general life experience, so we use Present Perfect: 've been.",tip:"Experience with no time = Present Perfect. 'Twice', 'a few times', 'before' = PP signals.",multipleChoice:{question:"Which option correctly completes the sentence?",correctOption:"'ve been",options:["'ve been","went","was","had been"],optionExplanations:{"'ve been":"Correct! No specific time — general experience → Present Perfect.",went:"Wrong. 'Went' (Past Simple) needs a specific time: I went in 2020.",was:"Wrong. 'Was' is Past Simple of 'be' and doesn't work here.","had been":"Wrong. Past Perfect is for an action before another past action."}}},{id:"ps-pp-mc-2",topic:"past-simple-present-perfect",type:"multiple-choice",difficulty:"beginner",sentence:"I ___ a hamburger yesterday for the first time in months.",grammarRule:"Past Simple — specific time (yesterday)",explanation:"'Yesterday' is a specific finished time in the past. Whenever we use specific past time expressions, we must use Past Simple.",tip:"Yesterday, last week, in 2019, two years ago, this morning (if day is over) → Past Simple.",multipleChoice:{question:"Which option correctly completes the sentence?",correctOption:"ate",options:["ate","have eaten","was eating","had eaten"],optionExplanations:{ate:"Correct! 'Yesterday' is a specific past time → Past Simple.","have eaten":"Wrong. Present Perfect cannot be used with a specific finished time like 'yesterday'.","was eating":"Wrong. Past Continuous describes a background action, not a completed event.","had eaten":"Wrong. Past Perfect is used before another past action, not with 'yesterday' alone."}}},{id:"ps-pp-mc-3",topic:"past-simple-present-perfect",type:"multiple-choice",difficulty:"intermediate",sentence:"I can't find my keys anywhere — I think I ___ them at the café.",grammarRule:"Present Perfect — past action relevant to the present",explanation:"The past action (leaving the keys) has a current consequence (can't find them now). This present relevance is expressed with Present Perfect.",tip:"Can't do something NOW because of a past action → Present Perfect for the past action.",multipleChoice:{question:"Which option correctly completes the sentence?",correctOption:"'ve left",options:["'ve left","left","was leaving","had left"],optionExplanations:{"'ve left":"Correct! The past action is relevant now (I can't find them) → Present Perfect.",left:"Possible in informal speech, but Present Perfect is more precise for present relevance.","was leaving":"Wrong. Past Continuous describes an ongoing background action, not a completed one.","had left":"Wrong. Past Perfect is for an action before another past action — here the result is in the present."}}},{id:"ps-pp-mc-4",topic:"past-simple-present-perfect",type:"multiple-choice",difficulty:"intermediate",sentence:"I ___ three cups of coffee this morning — I feel a bit jittery.",grammarRule:"Present Perfect — unfinished period (this morning)",explanation:"'This morning' refers to a period that is still going on (the morning hasn't ended). We use Present Perfect for unfinished time periods.",tip:"This morning (still morning), today, this week, this year = unfinished → Present Perfect.",multipleChoice:{question:"Which option correctly completes the sentence?",correctOption:"'ve had",options:["'ve had","had","was having","have been having"],optionExplanations:{"'ve had":"Correct! 'This morning' is an unfinished period → Present Perfect.",had:"Wrong in this context — 'had' (Past Simple) would suggest the morning is over.","was having":"Wrong. Past Continuous describes an ongoing background action, not completed cups of coffee.","have been having":"Wrong. Present Perfect Continuous can work here but 've had is more natural for counting."}}},{id:"ps-pp-mc-5",topic:"past-simple-present-perfect",type:"multiple-choice",difficulty:"intermediate",sentence:"A: Have you tried sushi? B: Yes! I ___ it for the first time in Tokyo in 2022.",grammarRule:"Past Simple — adding specific detail after Present Perfect opener",explanation:"The conversation starts with Present Perfect ('Have you tried?'). Once we add a specific time ('in Tokyo in 2022'), we switch to Past Simple to tell the story.",tip:"PP asks about the experience. PS tells the specific story with details and time.",multipleChoice:{question:"Which option correctly completes B's reply?",correctOption:"tried",options:["tried","have tried","was trying","had tried"],optionExplanations:{tried:"Correct! Specific time 'in Tokyo in 2022' → Past Simple to tell the story.","have tried":"Wrong. Once you add a specific time, switch to Past Simple.","was trying":"Wrong. Past Continuous describes a background action, not a completed first experience.","had tried":"Wrong. Past Perfect is for an action before another past action, not for this context."}}},{id:"ps-pp-mc-6",topic:"past-simple-present-perfect",type:"multiple-choice",difficulty:"advanced",sentence:"I ___ that restaurant — you should definitely try it.",grammarRule:"Present Perfect — recommendation based on experience",explanation:"When making a recommendation based on a personal experience, Present Perfect is used because the focus is on the experience and its present relevance (you should try it), not on when it happened.",tip:"Recommendations from experience: 'I've been there', 'I've read it', 'I've tried it' → Present Perfect.",multipleChoice:{question:"Which option correctly completes the sentence?",correctOption:"'ve been to",options:["'ve been to","went to","was at","had visited"],optionExplanations:{"'ve been to":"Correct! Recommendation based on experience with present relevance → Present Perfect.","went to":"Possible, but less natural — 'went to' feels like it needs a time ('last week').","was at":"Wrong. 'Was at' is Past Simple and doesn't carry the recommendation/relevance meaning.","had visited":"Wrong. Past Perfect implies a context of another past event, which doesn't fit here."}}},{id:"ps-pp-reorder-1",topic:"past-simple-present-perfect",type:"word-transform",difficulty:"beginner",sentence:"I ___ that film last week. It was brilliant.",grammarRule:"Past Simple — specific finished time",explanation:"'Last week' is a specific finished time, so we use Past Simple. Past Simple of 'see' is 'saw'.",tip:"Last week/year, yesterday, in 2019 → Past Simple. See → saw (irregular).",wordTransform:{baseWord:"see",correctAnswer:"saw"}},{id:"ps-pp-reorder-2",topic:"past-simple-present-perfect",type:"word-transform",difficulty:"beginner",sentence:"Have you ever ___ to Japan?",grammarRule:"Present Perfect — life experience question",explanation:"'Have you ever been...?' asks about life experience. 'Been' is the past participle of 'be' used with Present Perfect.",tip:"Have you ever been to...? = asking about life experience. Be → been (past participle).",wordTransform:{baseWord:"be",correctAnswer:"been"}},{id:"ps-pp-reorder-3",topic:"past-simple-present-perfect",type:"word-transform",difficulty:"intermediate",sentence:"She ___ in Paris since 2018.",grammarRule:"Present Perfect — unfinished duration with 'since'",explanation:"'Since 2018' = from 2018 until now → Present Perfect. Third person singular: 'has lived'.",tip:"Since + year → Present Perfect: has lived, has worked, has known.",wordTransform:{baseWord:"live",correctAnswer:"has lived"}},{id:"ps-pp-reorder-4",topic:"past-simple-present-perfect",type:"word-transform",difficulty:"intermediate",sentence:"I have already ___ my homework.",grammarRule:"Present Perfect — 'already' signals completion",explanation:"'Already' with Present Perfect shows something is done. 'Finished' is the past participle of 'finish' (regular verb).",tip:"Already + Present Perfect: have already finished, has already arrived, have already eaten.",wordTransform:{baseWord:"finish",correctAnswer:"finished"}},{id:"ps-pp-reorder-5",topic:"past-simple-present-perfect",type:"word-transform",difficulty:"intermediate",sentence:"He ___ to London last summer.",grammarRule:"Past Simple — specific past time",explanation:"'Last summer' is a specific finished time → Past Simple. Past Simple of 'go' is 'went'.",tip:"Go → went (irregular). Last summer/year/week + Past Simple.",wordTransform:{baseWord:"go",correctAnswer:"went"}},{id:"ps-pp-reorder-6",topic:"past-simple-present-perfect",type:"word-transform",difficulty:"intermediate",sentence:"Have you ever ___ sushi?",grammarRule:"Present Perfect — life experience with 'ever'",explanation:"'Have you ever tried...?' asks about life experience. 'Tried' is the past participle of 'try' (regular: try → tried).",tip:"Have you ever + past participle? Try → tried (regular verb, y → ied).",wordTransform:{baseWord:"try",correctAnswer:"tried"}}]},s={id:"apologise-and-give-reasons",level:"B1",name:"Apologise & Give Reasons",description:"Practise the phrases used to apologise, give reasons, accept responsibility, and promise action in English.",icon:"🙏",cards:[{id:"apol-card-1",rule:"Sorry to + base verb",example:"Sorry ___ interrupt, but your taxi is here.",answer:"to",explanation:"Use sorry to + base verb when you apologise for something you are doing right now. Do not use -ing after sorry to.",examples:["Sorry to bother you, but is this seat free?","Sorry to call you so late in the evening."],ua:"Sorry to + дієслово: «Вибачте, що турбую» — Sorry to bother you."},{id:"apol-card-2",rule:"sorry for / apologise for + -ing",example:"I'm really sorry for ___ (miss) your birthday party last night.",answer:"missing",explanation:"After a preposition such as for, use the -ing form. Say apologise for not replying or sorry for forgetting, never 'for to forget'.",examples:["I apologise for not replying sooner.","We are very sorry for causing so much trouble."],ua:"Після for — форма на -ing: «Вибач, що забув» — sorry for forgetting."},{id:"apol-card-3",rule:"make a mistake (not do a mistake)",example:"It's easy to ___ a mistake when you are in a hurry.",answer:"make",explanation:"We make mistakes, errors and decisions. We do tasks and activities, for example do homework. Never say do a mistake.",examples:["I'm sorry, I made a mistake with the price.","Everyone makes mistakes when they are tired."],ua:"Українською «зробити помилку», а англійською — тільки make a mistake, не do."},{id:"apol-card-4",rule:"It was my / our fault",example:"My colleague and I forgot to lock the office. It was ___ fault, not the cleaner's.",answer:"our",explanation:"Say it was my fault or it was our fault to accept responsibility. Fault is uncountable here, so it has no plural: never 'our faults'.",examples:["It was my fault. I didn't check the time.","Don't blame Anna. It was our fault, not hers."],ua:"«Це моя вина» — It was my fault. Fault тут без -s: не «our faults»."},{id:"apol-card-5",rule:"was / got + past participle (reasons)",example:"Sorry I was late yesterday. The road ___ (close) because of an accident.",answer:"was closed",explanation:"To give a reason, use was/were or got + past participle. It shows that something outside your control happened.",examples:["Our train was delayed because of a signal failure.","The 7:30 bus got cancelled, so I had to walk."],ua:"Причину пояснюємо пасивом: «Потяг затримався» — The train was delayed."},{id:"apol-card-6",rule:"I got lost / I got the time wrong",example:"I thought our appointment was at three, but it was at two. I got the time ___.",answer:"wrong",explanation:"Use got + adjective to explain a mistake or a problem: I got lost, I got the time wrong, I got stuck.",examples:["I got lost in the old town and my phone had no signal.","Sorry, I got the address wrong and went to the old office."],ua:"Пояснюємо: «я заблукав» — I got lost, «я переплутав час» — I got the time wrong."},{id:"apol-card-7",rule:"There was a problem with ...",example:"Sorry I didn't reply. There was a problem ___ my email password, and I couldn't log in.",answer:"with",explanation:"Use there was a problem/delay/issue with + noun to say that something went wrong without blaming anyone. It sounds polite and professional.",examples:["There was a delay with the delivery, but it arrived today.","There was a problem with the lift, so we used the stairs."],ua:"Без звинувачення: «Була проблема з...» — There was a problem with..."},{id:"apol-card-8",rule:"Don't worry about it / Never mind",example:"A: Sorry, I spilled coffee on your desk. B: Don't worry ___ it — I'll wipe it up.",answer:"about",explanation:"To accept an apology, say Don't worry, No problem, That's fine or Never mind. Don't worry about it is a friendly and very common reply.",examples:["No problem, we have plenty of time.","Never mind, it's only a small mistake."],ua:"Прийняти вибачення: «Нічого страшного» — Don't worry about it / No problem."},{id:"apol-card-9",rule:"I'll call you back / as soon as possible",example:"I'm in a meeting right now, but I'll call you ___ at four o'clock.",answer:"back",explanation:"To promise action, use I'll + verb. Call you back means return someone's call: the pronoun goes between call and back. As soon as possible is a fixed phrase.",examples:["I'll call you back as soon as I leave the office.","I'll send you the file as soon as possible."],ua:"Обіцянка: «Передзвоню» — I'll call you back. Займенник стоїть між call і back."},{id:"apol-card-10",rule:"should have + past participle",example:"I should ___ booked the tickets earlier, but I forgot. I'm so sorry.",answer:"have",explanation:"Use should have + past participle to say you regret something you did not do. It is a polite way to take responsibility.",examples:["I should have told you about the change.","We should have left earlier to avoid the traffic."],ua:"Жаль, що не зробив: «Треба було попередити» — I should have warned you."}],rules:[{id:"apol-gap-1",topic:"apologise-and-give-reasons",type:"gap-fill",difficulty:"beginner",sentence:"Sorry I'm ___ and the traffic was absolutely terrible today.",grammarRule:"Apologising — Sorry I'm late",explanation:"'Sorry I'm late' is the standard phrase to apologise for arriving after the expected time. It is short, natural, and commonly used in both formal and informal situations.",tip:"Sorry I'm late / Sorry to keep you waiting / I'm really sorry — all are natural ways to apologise.",gapFill:{gapIndex:2,correctAnswer:"late",options:["late","sorry","here","ready"],correctOptionIndex:0}},{id:"apol-gap-2",topic:"apologise-and-give-reasons",type:"gap-fill",difficulty:"beginner",sentence:"I'm sorry I'm late. My train was ___ by over an hour.",grammarRule:"Giving a reason — My (train) was delayed",explanation:"'Was delayed' explains why you are late. It uses passive voice (the train was delayed by something outside your control). This is a common and natural way to give a reason.",tip:"My train/bus was delayed. My flight got cancelled. The traffic was terrible — all give reasons.",gapFill:{gapIndex:7,correctAnswer:"delayed",options:["delayed","cancelled","lost","missed"],correctOptionIndex:0}},{id:"apol-gap-3",topic:"apologise-and-give-reasons",type:"gap-fill",difficulty:"beginner",sentence:"I got the ___ wrong and came on Thursday instead of Friday.",grammarRule:"Giving a reason — I got the (date/time) wrong",explanation:"'I got the date wrong' means you had the wrong information about the date. This phrase is used to explain a mix-up or misunderstanding about when something was happening.",tip:"I got the date/time/address/name wrong — all follow the same pattern to explain a mistake.",gapFill:{gapIndex:3,correctAnswer:"date",options:["date","meeting","train","person"],correctOptionIndex:0}},{id:"apol-gap-4",topic:"apologise-and-give-reasons",type:"gap-fill",difficulty:"beginner",sentence:"I'll be there as soon as ___. Please don't start without me.",grammarRule:"Taking action — I'll be there as soon as possible",explanation:"'As soon as possible' is a fixed phrase meaning 'at the earliest moment'. It shows you are taking action to fix the problem quickly. Often shortened to ASAP.",tip:"'As soon as possible' is a fixed phrase — memorise it as a whole unit.",gapFill:{gapIndex:6,correctAnswer:"possible",options:["possible","I want","quickly","fast"],correctOptionIndex:0}},{id:"apol-gap-5",topic:"apologise-and-give-reasons",type:"gap-fill",difficulty:"intermediate",sentence:"My flight got ___ so I had to book a completely new ticket for the next day.",grammarRule:"Giving a reason — My (flight) got cancelled",explanation:"'Got cancelled' means the flight was cancelled (by the airline). 'Got cancelled' is more natural in spoken English than 'was cancelled', though both are correct.",tip:"My train/flight got cancelled — 'got' + past participle is common in spoken English for things that happened to you.",gapFill:{gapIndex:3,correctAnswer:"cancelled",options:["cancelled","delayed","missed","changed"],correctOptionIndex:0}},{id:"apol-gap-6",topic:"apologise-and-give-reasons",type:"gap-fill",difficulty:"intermediate",sentence:"There was a ___ with your reservation and your room wasn't ready on arrival.",grammarRule:"Giving a reason — There was a (problem/delay) with...",explanation:"'There was a problem with...' is used to explain that something went wrong, without necessarily saying whose fault it was. It is polite and professional.",tip:"There was a problem/delay/issue with... — use this when something went wrong with a system or service.",gapFill:{gapIndex:3,correctAnswer:"problem",options:["problem","fault","mistake","reason"],correctOptionIndex:0}},{id:"apol-gap-7",topic:"apologise-and-give-reasons",type:"gap-fill",difficulty:"intermediate",sentence:"It was ___ fault — I should have double-checked the meeting time.",grammarRule:"Accepting responsibility — It was my fault",explanation:"'It was my fault' is a direct and honest way to accept responsibility. It is stronger than just apologising — it clearly states who is to blame.",tip:"It was my/our fault. I made a mistake. — both accept responsibility directly and clearly.",gapFill:{gapIndex:2,correctAnswer:"my",options:["my","me","mine","myself"],correctOptionIndex:0}},{id:"apol-err-1",topic:"apologise-and-give-reasons",type:"error-spot",difficulty:"beginner",sentence:"Sorry to keeping you waiting — I got stuck in traffic.",grammarRule:"Sorry to + base form (not -ing)",explanation:"'Sorry to keep you waiting' is the correct fixed phrase. After 'sorry to', we use the base form of the verb, not the -ing form. 'Sorry to keeping' is not grammatically correct.",tip:"Sorry to + BASE FORM: Sorry to keep you waiting, Sorry to bother you, Sorry to interrupt.",errorSpot:{errorWordIndex:2,wrongWord:"keeping",correction:"keep",reason:"After 'sorry to', use the base form — not the -ing form.",correctionOptions:["keep","keeping","kept","have kept"]}},{id:"apol-err-2",topic:"apologise-and-give-reasons",type:"error-spot",difficulty:"beginner",sentence:"I did a mistake and sent the wrong file to the client.",grammarRule:"Accept responsibility — make a mistake (not do)",explanation:"The correct collocation is 'make a mistake', not 'do a mistake'. In English, 'make' is used with mistakes, errors, and decisions. 'Do' is used with tasks and activities.",tip:"Make a mistake / make an error — never 'do a mistake'. Make = create something (including errors).",errorSpot:{errorWordIndex:1,wrongWord:"did",correction:"made",reason:"The correct collocation is 'make a mistake', not 'do a mistake'.",correctionOptions:["made","did","have","got"]}},{id:"apol-err-3",topic:"apologise-and-give-reasons",type:"error-spot",difficulty:"intermediate",sentence:"The journey was terribly and I arrived two hours late.",grammarRule:"The (traffic/journey) was terrible — adjective, not adverb",explanation:"After 'was', we need an adjective ('terrible'), not an adverb ('terribly'). The subject 'journey' is described by an adjective. 'Terribly' is an adverb used to modify verbs or other adjectives, not after 'was'.",tip:"The traffic/journey was TERRIBLE (adjective). Not 'terribly' — that's an adverb.",errorSpot:{errorWordIndex:3,wrongWord:"terribly",correction:"terrible",reason:"After 'was', use an adjective (terrible), not an adverb (terribly).",correctionOptions:["terrible","terribly","terrified","terrific"]}},{id:"apol-err-4",topic:"apologise-and-give-reasons",type:"error-spot",difficulty:"intermediate",sentence:"I'll call you backs later today once I have more information.",grammarRule:"Taking action — I'll call you back",explanation:"'Call you back' is a fixed phrasal verb meaning to return someone's phone call. 'Back' does not change form — it is an adverb in this phrase, not a noun, so it cannot be pluralised.",tip:"I'll call you back / I'll get back to you — fixed phrases. Never 'call you backs'.",errorSpot:{errorWordIndex:3,wrongWord:"backs",correction:"back",reason:"'Back' in 'call you back' is an adverb — it cannot be made plural.",correctionOptions:["back","backs","backward","behind"]}},{id:"apol-err-5",topic:"apologise-and-give-reasons",type:"error-spot",difficulty:"intermediate",sentence:"It was our faults and we should have checked the schedule more carefully.",grammarRule:"Accept responsibility — It was my/our fault (uncountable)",explanation:"'Fault' in this context is uncountable and does not take a plural form. We say 'It was my fault' or 'It was our fault', never 'my faults' or 'our faults'.",tip:"It was my/our fault — 'fault' here is uncountable. No plural form.",errorSpot:{errorWordIndex:3,wrongWord:"faults",correction:"fault",reason:"'Fault' in 'It was our fault' is uncountable — no plural form.",correctionOptions:["fault","faults","mistake","problem"]}},{id:"apol-err-6",topic:"apologise-and-give-reasons",type:"error-spot",difficulty:"advanced",sentence:"I apologise for been late to the presentation this morning.",grammarRule:"I apologise for + -ing form",explanation:"'Apologise for' is followed by a gerund (-ing form). 'Been' is a past participle, not a gerund. The correct form is 'being', which is the -ing form of 'be'.",tip:"Apologise for + -ing: apologise for being late, apologise for missing, apologise for causing.",errorSpot:{errorWordIndex:3,wrongWord:"been",correction:"being",reason:"After 'apologise for', use the -ing form. 'Been' is past participle — 'being' is the gerund.",correctionOptions:["being","been","be","to be"]}},{id:"apol-mc-1",topic:"apologise-and-give-reasons",type:"multiple-choice",difficulty:"beginner",sentence:"A: I'm really sorry I missed the meeting. B: ___ — it happens to everyone.",grammarRule:"Accepting an apology — Don't worry",explanation:"'Don't worry' is a natural, friendly way to accept an apology and reassure someone. It tells the person that the situation is not serious.",tip:"Don't worry / No problem / It's fine / Never mind — all accept an apology and reassure the speaker.",multipleChoice:{question:"Which option correctly completes B's reply?",correctOption:"Don't worry",options:["Don't worry","Thank you","I'm sorry","That's wrong"],optionExplanations:{"Don't worry":"Correct! 'Don't worry' accepts the apology and reassures the person.","Thank you":"Wrong. 'Thank you' is a response to thanks, not an apology.","I'm sorry":"Wrong. 'I'm sorry' is an apology — here we need a response to an apology.","That's wrong":"Wrong. This does not accept an apology — it suggests disagreement."}}},{id:"apol-mc-2",topic:"apologise-and-give-reasons",type:"multiple-choice",difficulty:"beginner",sentence:"A: Sorry about that — I sent the wrong file. B: ___, just send me the correct one.",grammarRule:"Accepting an apology — No problem",explanation:"'No problem' dismisses the apology and focuses on the solution. It is casual and reassuring, commonly used in both spoken and written English.",tip:"No problem / Don't worry / It's fine / That's OK — all tell the person not to worry.",multipleChoice:{question:"Which option correctly completes B's reply?",correctOption:"No problem",options:["No problem","No thank you","That's bad","I disagree"],optionExplanations:{"No problem":"Correct! 'No problem' accepts the apology and moves on to the solution.","No thank you":"Wrong. 'No thank you' refuses an offer — it is not used to accept an apology.","That's bad":"Wrong. This would make the person feel worse, not better.","I disagree":"Wrong. This is used to express disagreement, not to accept an apology."}}},{id:"apol-mc-3",topic:"apologise-and-give-reasons",type:"multiple-choice",difficulty:"intermediate",sentence:"I'll ___ once I get out of the meeting — probably around 4pm.",grammarRule:"Taking action — I'll call you back",explanation:"'Call you back' is the correct word order for this phrasal verb. The object pronoun ('you') goes between the verb ('call') and the particle ('back').",tip:"Call you back — the pronoun always goes between 'call' and 'back'. Never 'call back you'.",multipleChoice:{question:"Which option correctly completes the sentence?",correctOption:"call you back",options:["call you back","call back you","you call back","back call you"],optionExplanations:{"call you back":"Correct! Pronoun goes between the verb and particle: call + you + back.","call back you":"Wrong. With pronoun objects, the particle cannot come before the pronoun.","you call back":"Wrong. This is an inversion — not correct in this context.","back call you":"Wrong. This word order does not exist in English."}}},{id:"apol-mc-4",topic:"apologise-and-give-reasons",type:"multiple-choice",difficulty:"intermediate",sentence:"The ___ was terrible, so I took the train instead of driving.",grammarRule:"Giving a reason — The (traffic/journey) was terrible",explanation:"The phrase 'The traffic was terrible' is used to explain a delay caused by bad road conditions. 'Traffic' fits perfectly here because the speaker decided to take the train instead of driving.",tip:"The traffic/journey was terrible — use this to explain a delay caused by travel conditions.",multipleChoice:{question:"Which option correctly completes the sentence?",correctOption:"traffic",options:["traffic","apology","mistake","problem"],optionExplanations:{traffic:"Correct! 'The traffic was terrible' explains why driving wasn't possible.",apology:"Wrong. An apology cannot be terrible in this context — we need a travel reason.",mistake:"Wrong. 'The mistake was terrible' doesn't explain why someone took the train.",problem:"Wrong. 'There was a problem' is a different structure — 'The problem was terrible' doesn't fit."}}},{id:"apol-mc-5",topic:"apologise-and-give-reasons",type:"multiple-choice",difficulty:"intermediate",sentence:"I'm so sorry — I completely ___ and went to the wrong office.",grammarRule:"Giving a reason — I got lost",explanation:"'I got lost' means you lost your way and couldn't find the right place. It is a natural, common phrase to explain why you were late or went to the wrong place.",tip:"I got lost = I couldn't find my way. A fixed phrase — always 'got lost', not 'was lost' (in this meaning).",multipleChoice:{question:"Which option correctly completes the sentence?",correctOption:"got lost",options:["got lost","got late","made lost","was losing"],optionExplanations:{"got lost":"Correct! 'I got lost' is the natural phrase for losing your way.","got late":"Wrong. 'Got late' is not a standard English phrase — use 'was late' or 'arrived late'.","made lost":"Wrong. 'Make lost' is not an English collocation.","was losing":"Wrong. 'Was losing' is continuous — it doesn't describe arriving at the wrong place."}}},{id:"apol-mc-6",topic:"apologise-and-give-reasons",type:"multiple-choice",difficulty:"advanced",sentence:"A: I'm so sorry about the mix-up with your order. B: ___ — let's just sort it out now.",grammarRule:"Accepting an apology — Never mind",explanation:"'Never mind' is used to tell someone not to worry about something that has already happened. It accepts the apology and moves the conversation forward. It is slightly more formal than 'Don't worry'.",tip:"Never mind / Don't worry / No problem / That's OK — all accept an apology. 'Never mind' often implies 'let's move on'.",multipleChoice:{question:"Which option correctly completes B's reply?",correctOption:"Never mind",options:["Never mind","Never ever","Don't ever","No worry"],optionExplanations:{"Never mind":"Correct! 'Never mind' accepts the apology and suggests moving forward.","Never ever":"Wrong. 'Never ever' is an emphatic form of 'never' — it doesn't accept an apology.","Don't ever":"Wrong. 'Don't ever' is a warning or prohibition, not an apology acceptance.","No worry":"Wrong. The correct phrase is 'No worries' (informal) or 'Don't worry' — 'No worry' is not standard."}}},{id:"apol-reorder-1",topic:"apologise-and-give-reasons",type:"word-transform",difficulty:"beginner",sentence:"I'm really sorry for ___ late.",grammarRule:"Gerund after preposition: sorry for + -ing",explanation:"After a preposition ('for'), we use the -ing form (gerund). 'Sorry for being late' = I apologise for my lateness.",tip:"Preposition + -ing: sorry for being, thank you for coming, responsible for missing.",wordTransform:{baseWord:"be",correctAnswer:"being"}},{id:"apol-reorder-2",topic:"apologise-and-give-reasons",type:"word-transform",difficulty:"beginner",sentence:"Please accept my ___.",grammarRule:"Noun plural: apology → apologies",explanation:"'Apologies' is the plural of 'apology'. It is the formal noun used in polite requests for forgiveness.",tip:"Apology → apologies (nouns ending in -y: change y to i + -es). Formal: please accept my apologies.",wordTransform:{baseWord:"apology",correctAnswer:"apologies"}},{id:"apol-reorder-3",topic:"apologise-and-give-reasons",type:"word-transform",difficulty:"beginner",sentence:"The train ___ by 20 minutes.",grammarRule:"Passive voice for giving reasons: was/were + past participle",explanation:"Use passive voice to explain what happened: 'was delayed' (by something outside your control). Delay → delayed (regular).",tip:"Giving reasons with passive: the train was delayed, my flight got cancelled, the road was closed.",wordTransform:{baseWord:"delay",correctAnswer:"was delayed"}},{id:"apol-reorder-4",topic:"apologise-and-give-reasons",type:"word-transform",difficulty:"intermediate",sentence:"I should have ___ you earlier. I'm sorry.",grammarRule:"Should have + past participle — missed obligation",explanation:"'Should have called' expresses regret about a past action that didn't happen. Structure: should have + past participle.",tip:"Should have + past participle = regret: should have called, should have told, should have come.",wordTransform:{baseWord:"call",correctAnswer:"called"}},{id:"apol-reorder-5",topic:"apologise-and-give-reasons",type:"word-transform",difficulty:"intermediate",sentence:"Sorry to ___ you waiting.",grammarRule:"Sorry to + base verb",explanation:"'Sorry to keep you waiting' is a fixed polite phrase. After 'sorry to', use the base form of the verb.",tip:"Sorry to + base verb: sorry to keep, sorry to bother, sorry to interrupt.",wordTransform:{baseWord:"keep",correctAnswer:"keep"}},{id:"apol-reorder-6",topic:"apologise-and-give-reasons",type:"word-transform",difficulty:"intermediate",sentence:"I ___ a big mistake and I take full responsibility.",grammarRule:"Past Simple — accepting responsibility (make/made)",explanation:"'Made' is the Past Simple of 'make'. 'Make a mistake' is a fixed collocation — never 'do a mistake'.",tip:"Make → made. Collocations: make a mistake, make an error, make a decision.",wordTransform:{baseWord:"make",correctAnswer:"made"}}]},l={id:"prepositions-of-time",level:"B1",name:"Prepositions of Time",description:"Practise using before, after, during, until, between, in, at, and on with time expressions.",icon:"⏰",cards:[{id:"pot-card-1",rule:"at + clock time",example:"The train to Lviv leaves ___ 6.45 every morning.",answer:"at",explanation:"Use at with clock times. We say at 6.45, at 9 a.m. and at five o'clock.",examples:["The bank opens at half past nine.","Please call me at 5 o'clock."],ua:"at + година: at 6.45 = «о 6.45»."},{id:"pot-card-2",rule:"on + day or date",example:"My dentist appointment is ___ Thursday, 14 March.",answer:"on",explanation:"Use on with days and dates. We say on Friday, on 3 May and on Monday morning.",examples:["We usually clean the house on Saturdays.","Her birthday is on 21 June."],ua:"on + день/дата: on Thursday = «у четвер», on 14 March = «14 березня»."},{id:"pot-card-3",rule:"in + month, year, season",example:"My grandparents got married ___ 1978.",answer:"in",explanation:"Use in with longer periods: months, years, seasons and decades. We say in 1978, in July and in winter.",examples:["It often snows here in January.","I'll take my driving test in spring."],ua:"in + місяць, рік, пора року: in 1978 = «у 1978 році», in winter = «взимку»."},{id:"pot-card-4",rule:"at night, at the weekend",example:"Foxes come into our garden ___ night.",answer:"at",explanation:"Some fixed expressions use at: at night and at the weekend. In American English people say on the weekend.",examples:["I don't like walking alone at night.","Are you free at the weekend?"],ua:"at night = «вночі», at the weekend = «на вихідних» (британська англійська)."},{id:"pot-card-5",rule:"in + period of time (from now)",example:"Hurry up, the film starts ___ twenty minutes!",answer:"in",explanation:"In + a period of time means 'after that time from now'. We use it for future events.",examples:["My exam starts in a week.","I'll finish this report in an hour."],ua:"in + проміжок часу в майбутньому = «через»: in twenty minutes — «через двадцять хвилин»."},{id:"pot-card-6",rule:"before / after + event or time",example:"She took a shower ___ her run, because she was covered in mud.",answer:"after",explanation:"Before means earlier than something. After means later than something. Both can be followed by a time or an event.",examples:["Please arrive before nine o'clock.","Let's go for a walk after dinner."],ua:"before = «до, перед», after = «після». Далі йде час або подія: after her run."},{id:"pot-card-7",rule:"during + noun",example:"The lights went out three times ___ the storm.",answer:"during",explanation:"During + a noun means 'at some point in' an event or period. With a verb we use while instead: while it was raining.",examples:["Please don't use your phone during the lesson.","I woke up twice during the night."],ua:"during + іменник = «під час»: during the storm. З дією — while + підмет + дієслово."},{id:"pot-card-8",rule:"until = up to a point, then it stops",example:"The museum is closed ___ next Monday, and then it reopens.",answer:"until",explanation:"Until shows the end point of a situation. It continues up to that moment and then it stops.",examples:["We stayed in Prague until Sunday evening.","Please wait here until I call your name."],ua:"until = «до (певного моменту)»: closed until Monday — «зачинено до понеділка»."},{id:"pot-card-9",rule:"since + point in time, for + period",example:"She has been in hospital ___ Monday morning, but she's feeling better.",answer:"since",explanation:"Use since with the moment when something started. Use for with a length of time. Both go with Present Perfect for situations that are still true.",examples:["I have lived in Kyiv since 2015.","He has worked here for six years."],ua:"since + момент = «з», for + період = «протягом»: since Monday, for six years."},{id:"pot-card-10",rule:"between ... and ...",example:"The museum café is quiet ___ two and four in the afternoon.",answer:"between",explanation:"Between ... and ... gives the start and the end of a time. We say between two and four, not between two to four.",examples:["The delivery will arrive between ten and twelve.","Call me between five and six."],ua:"between ... and = «між ... та»: between two and four — «між другою та четвертою»."}],rules:[{id:"pot-gap-1",topic:"prepositions-of-time",type:"gap-fill",difficulty:"beginner",sentence:"We need to be there ___ 7 p.m.",grammarRule:"Use 'before' to talk about something happening earlier than a specific time.",explanation:"'Before 7 p.m.' means we must arrive earlier than 7 p.m.",tip:"before/after + specific time or event",gapFill:{gapIndex:5,correctAnswer:"before",options:["before","until","during","at"],correctOptionIndex:0}},{id:"pot-gap-2",topic:"prepositions-of-time",type:"gap-fill",difficulty:"beginner",sentence:"___ breakfast, she left for school.",grammarRule:"Use 'after' to talk about something happening later than a specific event.",explanation:"'After breakfast' means she had breakfast first, then left for school.",tip:"after + event",gapFill:{gapIndex:0,correctAnswer:"After",options:["After","Before","During","Until"],correctOptionIndex:0}},{id:"pot-gap-3",topic:"prepositions-of-time",type:"gap-fill",difficulty:"beginner",sentence:"We talked about it ___ lunch.",grammarRule:"Use 'during' to talk about something that happens within a period of time.",explanation:"'During lunch' means the conversation happened while they were eating lunch.",tip:"during + period/event",gapFill:{gapIndex:4,correctAnswer:"during",options:["during","in","while","at"],correctOptionIndex:0}},{id:"pot-gap-4",topic:"prepositions-of-time",type:"gap-fill",difficulty:"intermediate",sentence:"She worked there ___ 2004.",grammarRule:"Use 'until/till' to talk about something which happens up to a certain time and then stops.",explanation:"'Until 2004' means she worked there and stopped in 2004.",tip:"until/till + end point",gapFill:{gapIndex:3,correctAnswer:"until",options:["until","since","before","during"],correctOptionIndex:0}},{id:"pot-gap-5",topic:"prepositions-of-time",type:"gap-fill",difficulty:"intermediate",sentence:"They lived in New York ___ 2005 and 2008.",grammarRule:"Use 'between' to talk about a time that starts at a certain point and finishes at a certain point.",explanation:"'Between 2005 and 2008' gives a start and end year for their time in New York.",tip:"between + time + and + time",gapFill:{gapIndex:5,correctAnswer:"between",options:["between","from","during","until"],correctOptionIndex:0}},{id:"pot-gap-6",topic:"prepositions-of-time",type:"gap-fill",difficulty:"beginner",sentence:"We're going on holiday ___ August.",grammarRule:"Use 'in' with months, years, decades, centuries, and seasons.",explanation:"August is a month, so we use 'in'.",tip:"in + month/year/season",gapFill:{gapIndex:4,correctAnswer:"in",options:["in","at","on","during"],correctOptionIndex:0}},{id:"pot-gap-7",topic:"prepositions-of-time",type:"gap-fill",difficulty:"beginner",sentence:"The film starts ___ 8.30 p.m.",grammarRule:"Use 'at' with specific clock times.",explanation:"8.30 p.m. is a specific clock time, so we use 'at'.",tip:"at + specific time",gapFill:{gapIndex:3,correctAnswer:"at",options:["at","in","on","by"],correctOptionIndex:0}},{id:"pot-err-1",topic:"prepositions-of-time",type:"error-spot",difficulty:"intermediate",sentence:"She worked there since 2004.",grammarRule:"Use 'until' to show when something stopped. 'Since' means it continues to now.",explanation:"'Since 2004' would mean she is still working there. 'Until 2004' means she stopped in 2004.",tip:"until = up to a point and then stops",errorSpot:{errorWordIndex:3,wrongWord:"since",correction:"until",reason:"'Since' implies the action continues to the present. 'Until' shows the action stopped at that point.",correctionOptions:["until","before","after","by"]}},{id:"pot-err-2",topic:"prepositions-of-time",type:"error-spot",difficulty:"beginner",sentence:"We need to be there on 5 o'clock.",grammarRule:"Use 'at' with specific clock times, not 'on'.",explanation:"'On' is used with days and dates. For clock times, use 'at'.",tip:"at + clock time",errorSpot:{errorWordIndex:5,wrongWord:"on",correction:"at",reason:"'On' is used with days/dates. Clock times use 'at': at 5 o'clock.",correctionOptions:["at","in","by","before"]}},{id:"pot-err-3",topic:"prepositions-of-time",type:"error-spot",difficulty:"beginner",sentence:"We're going on holiday on August.",grammarRule:"Use 'in' with months, not 'on'.",explanation:"'On' is for specific days/dates. Months use 'in': in August.",tip:"in + month",errorSpot:{errorWordIndex:4,wrongWord:"on",correction:"in",reason:"We use 'on' with days and dates, but 'in' with months: in August.",correctionOptions:["in","at","during","by"]}},{id:"pot-err-4",topic:"prepositions-of-time",type:"error-spot",difficulty:"intermediate",sentence:"They lived in New York from 2005 and 2008.",grammarRule:"Use 'between...and' to show a time range with a clear start and end.",explanation:"'From' needs 'to': from 2005 to 2008. The correct structure here is 'between 2005 and 2008'.",tip:"between + time + and + time",errorSpot:{errorWordIndex:5,wrongWord:"from",correction:"between",reason:"The correct structure is 'between 2005 and 2008'. 'From' would need 'to': from 2005 to 2008.",correctionOptions:["between","during","until","before"]}},{id:"pot-err-5",topic:"prepositions-of-time",type:"error-spot",difficulty:"intermediate",sentence:"I'll see you on ten minutes.",grammarRule:"Use 'in' + period of time to show when something will happen in the future.",explanation:"'In ten minutes' means after ten minutes have passed. 'On' is not used with time periods.",tip:"in + period of time (future)",errorSpot:{errorWordIndex:3,wrongWord:"on",correction:"in",reason:"Use 'in' + a period of time to show a future event: in ten minutes, in three hours.",correctionOptions:["in","after","at","within"]}},{id:"pot-err-6",topic:"prepositions-of-time",type:"error-spot",difficulty:"intermediate",sentence:"Let's go there in the weekend.",grammarRule:"Use 'at' with 'weekend' and 'night'.",explanation:"'At the weekend' and 'at night' are fixed expressions. 'In' is not used here.",tip:"at the weekend / at night",errorSpot:{errorWordIndex:3,wrongWord:"in",correction:"at",reason:"'At the weekend' and 'at night' are fixed expressions. Use 'at', not 'in'.",correctionOptions:["at","on","during","over"]}},{id:"pot-mc-1",topic:"prepositions-of-time",type:"multiple-choice",difficulty:"beginner",sentence:"The conference finishes ___ three hours.",grammarRule:"Use 'in' + a period of time to show when something will happen.",explanation:"'In three hours' means after three hours have passed. Used for future events.",tip:"in + period = it will happen after that time",multipleChoice:{question:"Which preposition correctly completes: 'The conference finishes ___ three hours.'?",correctOption:"in",options:["in","after","at","within"],optionExplanations:["Correct! 'In three hours' shows when it will end (future time period).","'After three hours' is understandable but 'in' is the standard choice here.","'At' is used with specific clock times, not with periods like 'three hours'.","'Within' is possible but 'in' is the natural, standard choice."]}},{id:"pot-mc-2",topic:"prepositions-of-time",type:"multiple-choice",difficulty:"beginner",sentence:"She worked there ___ 2004. (Then she changed jobs.)",grammarRule:"'Until/till' describes a duration that ends at a specific point.",explanation:"'Until 2004' means she worked there and stopped in 2004. The sentence shows the action ended.",tip:"until = up to that point, then stops",multipleChoice:{question:"Which preposition means 'up to a certain time and then stops'?",correctOption:"until",options:["until","during","between","after"],optionExplanations:["Correct! 'Until' shows the end point of an action: until 2004, until midnight.","'During' means within a period, not up to an end point.","'Between' describes a range between two points, not a single end point.","'After' means following a time, not up to a time."]}},{id:"pot-mc-3",topic:"prepositions-of-time",type:"multiple-choice",difficulty:"beginner",sentence:"We use prepositions of time to specify exactly when something happens.",grammarRule:"Use 'in' with years, decades, centuries, and seasons.",explanation:"Years use 'in': in 2020, in the 1990s. Days use 'on'. Clock times use 'at'.",tip:"in + year/decade/season",multipleChoice:{question:"Which sentence is CORRECT?",correctOption:"In 2020 I changed my career.",options:["In 2020 I changed my career.","At 2020 I changed my career.","On 2020 I changed my career.","By 2020 I changed my career."],optionExplanations:["Correct! 'In' is used with years.","'At' is used with clock times and fixed expressions, not years.","'On' is used with days and dates, not years.","'By 2020' means before or at the end of 2020 — a different meaning."]}},{id:"pot-mc-4",topic:"prepositions-of-time",type:"multiple-choice",difficulty:"intermediate",sentence:"They're leaving ___ 3 p.m. and 4 p.m.",grammarRule:"Use 'between' to talk about a time that starts and finishes at certain points.",explanation:"'Between 3 p.m. and 4 p.m.' specifies a window of time with a start and end.",tip:"between + time + and + time",multipleChoice:{question:"Which preposition correctly fills: 'They're leaving ___ 3 p.m. and 4 p.m.'?",correctOption:"between",options:["between","from","during","within"],optionExplanations:["Correct! 'Between...and' shows a time range with two specific points.","'From' would need 'to': from 3 p.m. to 4 p.m.","'During' is used with periods or events (during the meeting), not clock time ranges.","'Within' could work in some contexts but is not the standard choice here."]}},{id:"pot-mc-5",topic:"prepositions-of-time",type:"multiple-choice",difficulty:"intermediate",sentence:"We talked about the project ___ the meeting.",grammarRule:"Use 'during' to describe something happening within a period or event.",explanation:"'During the meeting' means the conversation happened within the time of the meeting.",tip:"during + event/period (noun)",multipleChoice:{question:"Which preposition best completes: 'We talked about the project ___ the meeting.'?",correctOption:"during",options:["during","while","in","at"],optionExplanations:["Correct! 'During' + noun (the meeting) describes something happening within that event.","'While' is a conjunction, not a preposition — it needs a clause: 'while we were in the meeting'.","'In' is used with periods of time (in the afternoon), not specific events like meetings.","'At' is used with specific times or fixed expressions, not events."]}},{id:"pot-mc-6",topic:"prepositions-of-time",type:"multiple-choice",difficulty:"intermediate",sentence:"Let's go there at the weekend.",grammarRule:"Use 'at' with 'weekend' and 'night'.",explanation:"'At the weekend' and 'at night' are fixed expressions in British English.",tip:"at the weekend / at night",multipleChoice:{question:"Which sentence is CORRECT (British English)?",correctOption:"Let's go there at the weekend.",options:["Let's go there at the weekend.","Let's go there in the weekend.","Let's go there on the weekend.","Let's go there during the weekend."],optionExplanations:["Correct! In British English, 'at the weekend' is the standard expression.","'In the weekend' is incorrect. 'In' is used with months, years, and seasons.","'On the weekend' is used in American English but not standard in British English.","'During the weekend' is grammatically possible but not the standard fixed expression."]}},{id:"pot-reorder-1",topic:"prepositions-of-time",type:"word-transform",difficulty:"beginner",sentence:"She arrived ___ the meeting started.",grammarRule:"Use 'before' + event to describe what happens first.",explanation:"'Before the meeting started' tells us she arrived first. Use 'before' to show sequence.",tip:"before + event: before the meeting, before lunch, before he left.",wordTransform:{baseWord:"before/after",correctAnswer:"before"}},{id:"pot-reorder-2",topic:"prepositions-of-time",type:"word-transform",difficulty:"beginner",sentence:"The lesson is ___ Monday morning.",grammarRule:"Use 'on' with days of the week.",explanation:"Use 'on' with specific days and dates: on Monday, on Tuesday, on 5th March.",tip:"on + day: on Monday, on Friday. in + month: in August. at + time: at 7 p.m.",wordTransform:{baseWord:"at/on/in",correctAnswer:"on"}},{id:"pot-reorder-3",topic:"prepositions-of-time",type:"word-transform",difficulty:"intermediate",sentence:"The conference finishes ___ three hours.",grammarRule:"Use 'in' + period of time to indicate when something will happen.",explanation:"'In three hours' means after three hours have passed from now. Use 'in' for future time periods.",tip:"in + period of time = after that time: in an hour, in three days, in two weeks.",wordTransform:{baseWord:"at/in/for",correctAnswer:"in"}},{id:"pot-reorder-4",topic:"prepositions-of-time",type:"word-transform",difficulty:"beginner",sentence:"We're going on holiday ___ August.",grammarRule:"Use 'in' with months.",explanation:"Use 'in' with months and seasons: in August, in winter, in the summer.",tip:"in + month/season: in August, in winter. Never 'on August' or 'at August'.",wordTransform:{baseWord:"at/on/in",correctAnswer:"in"}},{id:"pot-reorder-5",topic:"prepositions-of-time",type:"word-transform",difficulty:"intermediate",sentence:"She worked at the hospital ___ 2010.",grammarRule:"Use 'until' to show the end point of a continuing action.",explanation:"'Until 2010' means she kept working there and stopped in 2010. Use 'until' for the end point of a continuous action.",tip:"until + end point: until 2010, until midnight, until she left.",wordTransform:{baseWord:"since/until",correctAnswer:"until"}},{id:"pot-reorder-6",topic:"prepositions-of-time",type:"word-transform",difficulty:"advanced",sentence:"I've been learning English ___ three years.",grammarRule:"Use 'for' with periods of time.",explanation:"'For three years' means over a period of three years. Use 'for' with a duration of time.",tip:"for + period: for three years, for two hours, for a week. since + point: since 2018.",wordTransform:{baseWord:"for/since",correctAnswer:"for"}}]},h={id:"question-forms",level:"B1",name:"Question Forms",description:"Practise word order in questions, subject vs. object questions, questions with prepositions, and yes/no questions.",icon:"❓",cards:[{id:"qf-card-1",rule:"question word + do/does + subject + verb",example:"How often ___ your sister visit you nowadays?",answer:"does",explanation:"In present simple questions, put do or does after the question word. Use does with he, she and it, and do with I, you, we and they. The main verb stays in the base form.",examples:["Where do your cousins live?","What does your brother do on Sundays?"],ua:"В українській допоміжного слова немає, а в англійській потрібне do/does: How often does she visit?"},{id:"qf-card-2",rule:"did + subject + base verb",example:"Why ___ you leave the party so early last night?",answer:"did",explanation:"Use did to ask about the past, with every subject. After did, the main verb is in the base form, not the past form.",examples:["How did you get home after the concert?","What did your boss say about the new schedule?"],ua:"Минулий час у питанні: did + початкова форма. Не «did you left», а «did you leave»."},{id:"qf-card-3",rule:"am/is/are + subject + -ing",example:"What ___ you cooking for dinner tonight?",answer:"are",explanation:"Use am, is or are before the subject to ask about actions happening now or planned. The main verb ends in -ing.",examples:["Where is your sister staying in Rome?","Is Marco coming to the party on Friday?"],ua:"Не «do you cooking»: перед дієсловом з -ing завжди потрібне be: What are you cooking?"},{id:"qf-card-4",rule:"have/has + subject + past participle",example:"How many countries ___ you visited so far?",answer:"have",explanation:"Use have or has before the subject to ask about experience or about what has happened until now. Use has with he, she and it. The main verb is a past participle.",examples:["Has your brother finished his homework yet?","Have you ever been to Scotland?"],ua:"Present perfect: have/has на початку, потім підмет і третя форма дієслова: Have you visited?"},{id:"qf-card-5",rule:"yes/no questions: auxiliary first",example:"___ your colleagues eat lunch together these days?",answer:"Do",explanation:"A yes/no question has no question word. Put the auxiliary first, then the subject, then the main verb. We answer with Yes or No.",examples:["Does your office have free parking for staff?","Did you sleep well last night?"],ua:"Питання без питального слова («Ти любиш каву?») починається з do/does/did: Do you like coffee?"},{id:"qf-card-6",rule:"subject questions: no do/does/did",example:"Which team ___ (win) the match last Saturday?",answer:"won",explanation:"When who, what or which is the subject, we do not use do, does or did. The word order is the same as in a statement.",examples:["Who lives next door to you?","What happened to your phone?"],ua:"Якщо who/what — підмет, допоміжне не потрібне: Who called you?, а не «Who did call you?»"},{id:"qf-card-7",rule:"who/what as object: + auxiliary + subject",example:"Who ___ your manager ask for help when she is busy?",answer:"does",explanation:"When who or what is the object, we need an auxiliary: question word + do/does/did + subject + verb. Compare: Who called you? (who = subject) and Who did you call? (who = object).",examples:["Who did Anna meet in town on Saturday?","Which colour does your sister prefer?"],ua:"Who did you call? = «кому ти дзвонив?», Who called you? = «хто тобі дзвонив?» — різний порядок слів."},{id:"qf-card-8",rule:"keep the preposition at the end",example:"Who did you go to the concert ___?",answer:"with",explanation:"In everyday questions, the preposition stays with the verb at the end of the question. Starting with the preposition (With whom...?) sounds very formal.",examples:["What are you waiting for?","Which hotel did they stay at?"],ua:"Українською «З ким ти ходив?» — прийменник спереду, англійською в кінці: Who did you go with?"}],rules:[{id:"qf-gap-1",topic:"question-forms",type:"gap-fill",difficulty:"beginner",sentence:"Where ___ you live?",grammarRule:"Word order in questions: question word + auxiliary verb + subject + main verb.",explanation:"In present simple questions, we use 'do/does' as the auxiliary. With 'you', we use 'do'.",tip:"question word + auxiliary (do/does/did/are/have) + subject + verb",gapFill:{gapIndex:1,correctAnswer:"do",options:["do","are","did","have"],correctOptionIndex:0}},{id:"qf-gap-2",topic:"question-forms",type:"gap-fill",difficulty:"beginner",sentence:"What ___ he want?",grammarRule:"Use 'did' as the auxiliary in past simple questions.",explanation:"'What did he want?' uses 'did' for past simple. After 'did', the main verb stays in the base form.",tip:"past simple question: did + subject + base form",gapFill:{gapIndex:1,correctAnswer:"did",options:["did","does","has","was"],correctOptionIndex:0}},{id:"qf-gap-3",topic:"question-forms",type:"gap-fill",difficulty:"beginner",sentence:"When ___ they coming?",grammarRule:"Use 'are' as the auxiliary in present continuous questions.",explanation:"'When are they coming?' is a present continuous question. 'Are' is the auxiliary.",tip:"present continuous question: are/is + subject + -ing",gapFill:{gapIndex:1,correctAnswer:"are",options:["are","do","did","were"],correctOptionIndex:0}},{id:"qf-gap-4",topic:"question-forms",type:"gap-fill",difficulty:"intermediate",sentence:"Who ___ you invite to the party?",grammarRule:"Object questions use an auxiliary verb. Subject questions do not.",explanation:"We are asking about the object (who you invited), so we use the auxiliary 'did'.",tip:"object question: question word + auxiliary + subject + verb",gapFill:{gapIndex:1,correctAnswer:"did",options:["did","do","have","were"],correctOptionIndex:0}},{id:"qf-gap-5",topic:"question-forms",type:"gap-fill",difficulty:"intermediate",sentence:"What did they ___ about?",grammarRule:"With verb + preposition phrases, keep the preposition at the end of the question.",explanation:"'Talk about' is a verb + preposition phrase. The preposition 'about' stays at the end.",tip:"verb + preposition: keep preposition at the end",gapFill:{gapIndex:3,correctAnswer:"talk",options:["talk","spoke","discussing","chat"],correctOptionIndex:0}},{id:"qf-gap-6",topic:"question-forms",type:"gap-fill",difficulty:"beginner",sentence:"___ he work in London?",grammarRule:"Yes/no questions start with the auxiliary verb. Use 'does' for third person singular.",explanation:"'Does he work...?' is a yes/no question. It starts with 'Does' (auxiliary for he/she/it).",tip:"yes/no question: auxiliary + subject + base verb",gapFill:{gapIndex:0,correctAnswer:"Does",options:["Does","Do","Is","Has"],correctOptionIndex:0}},{id:"qf-gap-7",topic:"question-forms",type:"gap-fill",difficulty:"intermediate",sentence:"Who ___ a drink?",grammarRule:"Subject questions don't use an auxiliary verb — the question word is the subject.",explanation:"'Who wants a drink?' is a subject question. 'Who' is the subject, so no auxiliary is needed.",tip:"subject question: question word + verb (no auxiliary)",gapFill:{gapIndex:1,correctAnswer:"wants",options:["wants","does want","is wanting","did want"],correctOptionIndex:0}},{id:"qf-err-1",topic:"question-forms",type:"error-spot",difficulty:"intermediate",sentence:"What did he wrote about?",grammarRule:"After the auxiliary 'did', use the base form of the verb.",explanation:"'Did' is the auxiliary, so the main verb must be the base form: 'write', not 'wrote'.",tip:"did + base form (NOT past simple)",errorSpot:{errorWordIndex:3,wrongWord:"wrote",correction:"write",reason:"After 'did', always use the base form of the verb: 'What did he write?' not 'wrote'.",correctionOptions:["write","written","writes","writing"]}},{id:"qf-err-2",topic:"question-forms",type:"error-spot",difficulty:"beginner",sentence:"Where does she lives?",grammarRule:"After the auxiliary 'does', use the base form of the verb.",explanation:"'Does' is the auxiliary, so the main verb must be the base form: 'live', not 'lives'.",tip:"does + base form (no -s ending)",errorSpot:{errorWordIndex:3,wrongWord:"lives?",correction:"live?",reason:"After 'does', always use the base form: 'Where does she live?' not 'lives'.",correctionOptions:["live?","lived?","living?","to live?"]}},{id:"qf-err-3",topic:"question-forms",type:"error-spot",difficulty:"intermediate",sentence:"What did you listened to?",grammarRule:"After the auxiliary 'did', use the base form of the verb.",explanation:"'Listened' is past simple. After 'did', the base form 'listen' is required.",tip:"did + base form (NOT past simple)",errorSpot:{errorWordIndex:3,wrongWord:"listened",correction:"listen",reason:"After 'did', use the base form: 'What did you listen to?' not 'listened'.",correctionOptions:["listen","listening","listens","to listen"]}},{id:"qf-err-4",topic:"question-forms",type:"error-spot",difficulty:"beginner",sentence:"Do they watching the game?",grammarRule:"Use 'are' (not 'do') as the auxiliary in present continuous questions.",explanation:"'Watching' is the -ing form, which requires 'are' as the auxiliary, not 'do'.",tip:"present continuous question: are + subject + -ing",errorSpot:{errorWordIndex:0,wrongWord:"Do",correction:"Are",reason:"Present continuous uses 'be' as the auxiliary: 'Are they watching?' not 'Do they watching?'.",correctionOptions:["Are","Did","Have","Were"]}},{id:"qf-err-5",topic:"question-forms",type:"error-spot",difficulty:"intermediate",sentence:"Who are you look for?",grammarRule:"With 'are', the main verb must be in the -ing form.",explanation:"'Are you looking' is the correct present continuous form. 'Look' should be 'looking'.",tip:"are + subject + -ing form",errorSpot:{errorWordIndex:3,wrongWord:"look",correction:"looking",reason:"After 'are', use the -ing form: 'Who are you looking for?' not 'look'.",correctionOptions:["looking","looked","looks","to look"]}},{id:"qf-err-6",topic:"question-forms",type:"error-spot",difficulty:"intermediate",sentence:"Have they arrive?",grammarRule:"In present perfect questions, use 'have/has' + past participle.",explanation:"'Have' is the auxiliary for present perfect, which requires the past participle: 'arrived'.",tip:"have/has + past participle",errorSpot:{errorWordIndex:2,wrongWord:"arrive?",correction:"arrived?",reason:"Present perfect uses 'have' + past participle: 'Have they arrived?' not 'arrive'.",correctionOptions:["arrived?","arriving?","arrives?","to arrive?"]}},{id:"qf-mc-1",topic:"question-forms",type:"multiple-choice",difficulty:"intermediate",sentence:"Who wrote it? / What did he write?",grammarRule:"Subject questions don't use an auxiliary verb. Object questions do.",explanation:"'Who wrote it?' is a subject question — 'who' is the subject. 'What did he write?' is an object question — 'what' is the object.",tip:"subject question = no auxiliary; object question = auxiliary needed",multipleChoice:{question:"Which is a SUBJECT question?",correctOption:"Who wrote it?",options:["Who wrote it?","Who did you invite?","What did he write?","Did you know?"],optionExplanations:["Correct! 'Who' is the subject here — no auxiliary is used.","This is an object question — 'who' is the object of 'invite'. 'Did' is the auxiliary.","This is an object question — 'what' is the object of 'write'. 'Did' is the auxiliary.","This is a yes/no question, not a subject question."]}},{id:"qf-mc-2",topic:"question-forms",type:"multiple-choice",difficulty:"beginner",sentence:"What did you talk about? / Who are you looking for?",grammarRule:"With verb + preposition phrases, the preposition comes at the end of the question.",explanation:"We keep 'talk about' and 'look for' together. The preposition goes at the end: 'What did you talk about?'",tip:"preposition at the end of the question",multipleChoice:{question:"Where does the preposition usually go in a question with a verb + preposition?",correctOption:"At the end of the question",options:["At the end of the question","Before the subject","After the question word","Before the auxiliary verb"],optionExplanations:["Correct! The preposition comes at the end: 'What did you talk about?' not 'About what did you talk?'","Placing it before the subject sounds very formal and unnatural in modern English.","Placing it right after the question word would separate the verb and its preposition.","The preposition belongs with its verb, not near the auxiliary."]}},{id:"qf-mc-3",topic:"question-forms",type:"multiple-choice",difficulty:"beginner",sentence:"Did you enjoy the film?",grammarRule:"Yes/no questions start with the auxiliary verb: auxiliary + subject + main verb.",explanation:"'Did you enjoy the film?' is a yes/no question. The auxiliary 'did' comes first, then the subject 'you', then the base form 'enjoy'.",tip:"yes/no question: auxiliary first, then subject",multipleChoice:{question:"Which sentence has CORRECT word order for a yes/no question?",correctOption:"Did you enjoy the film?",options:["Did you enjoy the film?","You did enjoy the film?","Did enjoy you the film?","Enjoyed you the film?"],optionExplanations:["Correct! Auxiliary (Did) + subject (you) + base verb (enjoy) is the correct order.","The auxiliary must come before the subject, not after it.","The subject must come between the auxiliary and the main verb.","We cannot invert subject and verb without an auxiliary in modern English."]}},{id:"qf-mc-4",topic:"question-forms",type:"multiple-choice",difficulty:"beginner",sentence:"Have they arrived?",grammarRule:"Yes/no questions don't use a question word. The answer is Yes or No.",explanation:"'Have they arrived?' can be answered with 'Yes, they have' or 'No, they haven't'. There is no question word.",tip:"yes/no question = no question word (who/what/where/when/why/how)",multipleChoice:{question:"Which question is a YES/NO question?",correctOption:"Have they arrived?",options:["Have they arrived?","When have they arrived?","Who arrived?","What happened?"],optionExplanations:["Correct! This question has no question word — the answer is simply Yes or No.","This uses the question word 'When', so it is a Wh- question, not a yes/no question.","This uses the question word 'Who', so it is a subject question.","This uses the question word 'What', so it is a subject question."]}},{id:"qf-mc-5",topic:"question-forms",type:"multiple-choice",difficulty:"intermediate",sentence:"Who invited you to the party? John invited me.",grammarRule:"In subject questions, the question word replaces the subject. No auxiliary is needed.",explanation:"We're asking about the person who did the inviting (the subject). 'Who' replaces the subject 'John', and no auxiliary is needed.",tip:"subject question: no auxiliary — question word IS the subject",multipleChoice:{question:"In a subject question, we ___.",correctOption:"don't use an auxiliary verb",options:["don't use an auxiliary verb","always use 'do' as the auxiliary","put the subject before the verb","use 'who' at the end of the sentence"],optionExplanations:["Correct! Subject questions use the same word order as statements: 'Who invited you?' not 'Who did invite you?'","We never use 'do' in subject questions. Compare: 'Who did you invite?' (object) vs. 'Who invited you?' (subject).","In a subject question, the question word (who/what) IS the subject — it comes first.","'Who' always comes at the beginning of the question, not the end."]}},{id:"qf-mc-6",topic:"question-forms",type:"multiple-choice",difficulty:"intermediate",sentence:"What did you talk about?",grammarRule:"Keep the verb and its preposition together in questions.",explanation:"'Talk about' is a phrasal verb. The preposition 'about' stays at the end: 'What did you talk about?'",tip:"never separate verb + preposition in questions",multipleChoice:{question:"Which question correctly asks about a verb + preposition phrase?",correctOption:"What did you talk about?",options:["What did you talk about?","About what did you talk?","What about did you talk?","What did you about talk?"],optionExplanations:["Correct! The preposition 'about' comes at the end, after the main verb.","This is very formal and not natural in everyday English.","The preposition must stay with its verb, not go after the question word.","The preposition must follow the verb, not be placed between auxiliary and main verb."]}},{id:"qf-reorder-1",topic:"question-forms",type:"word-transform",difficulty:"beginner",sentence:"Where ___ you live?",grammarRule:"Present Simple questions: Do/Does + subject + verb",explanation:"Questions with 'you' use 'do'. Word order: question word + do/does + subject + verb.",tip:"Do + I/you/we/they. Does + he/she/it. Question: Where do you live?",wordTransform:{baseWord:"do/does",correctAnswer:"do"}},{id:"qf-reorder-2",topic:"question-forms",type:"word-transform",difficulty:"beginner",sentence:"___ she work in London?",grammarRule:"Yes/no questions: auxiliary + subject + base verb",explanation:"Yes/no questions start with the auxiliary. Third person singular (she) uses 'Does'.",tip:"Does + he/she/it + base verb? Do + I/you/we/they + base verb?",wordTransform:{baseWord:"Do/Does",correctAnswer:"Does"}},{id:"qf-reorder-3",topic:"question-forms",type:"word-transform",difficulty:"intermediate",sentence:"What time ___ the film start?",grammarRule:"Does + singular subject + base verb?",explanation:"'The film' is third person singular → use 'does'. Question: What time + does + subject + verb?",tip:"Singular subject (the film, he, she) → does. Plural subject (they, films) → do.",wordTransform:{baseWord:"do/does",correctAnswer:"does"}},{id:"qf-reorder-4",topic:"question-forms",type:"word-transform",difficulty:"beginner",sentence:"Where ___ they go last night?",grammarRule:"Past Simple questions: Did + subject + base verb",explanation:"Past Simple questions use 'did' for all subjects. The main verb stays in base form: 'go' (not 'went').",tip:"Did + subject + base verb: did they go, did she come, did he see.",wordTransform:{baseWord:"did/were",correctAnswer:"did"}},{id:"qf-reorder-5",topic:"question-forms",type:"word-transform",difficulty:"intermediate",sentence:"How long ___ you been learning English?",grammarRule:"Present Perfect questions: Have/Has + subject + past participle",explanation:"Present Perfect questions about duration use 'have' or 'has'. With 'you', use 'have'.",tip:"Have + I/you/we/they. Has + he/she/it. How long have you been...?",wordTransform:{baseWord:"have/has",correctAnswer:"have"}},{id:"qf-reorder-6",topic:"question-forms",type:"word-transform",difficulty:"intermediate",sentence:"___ your teacher give you homework every day?",grammarRule:"Yes/no question with 3rd person singular",explanation:"'Your teacher' is third person singular → use 'Does'. The main verb 'give' stays in base form.",tip:"Does + 3rd person singular subject + base verb? Does she/he/it + verb?",wordTransform:{baseWord:"Do/Does",correctAnswer:"Does"}}]},d={id:"starting-ending-conversations",level:"B1",name:"Starting & Ending Conversations",lesson:"Lesson 9",description:"Practice phrases for starting, maintaining, and ending conversations in English",icon:"💬",cards:[{id:"conv-card-1",rule:"any in questions and negatives",example:"I'm sorry, we haven't got ___ tickets left. Tonight's show is sold out.",answer:"any",explanation:"Use any in questions and negative sentences. Use some in positive sentences.",examples:["Are there any good restaurants around here?","Do you have any plans for the weekend?"],ua:"«Чи є якісь...?» і «немає жодних...» — any; some вживаємо у ствердженнях."},{id:"conv-card-2",rule:"at + event or place",example:"Will you be ___ Anna's wedding on Saturday?",answer:"at",explanation:"We use at for events and places where people meet: at a party, at a concert, at a conference. We do not use on for events.",examples:["We were at a concert when you called.","She usually sees her friends at the gym."],ua:"Українською «на концерті, на весіллі», англійською at: at a concert, at a wedding, не on."},{id:"conv-card-3",rule:"How long have you + past participle",example:"How long have you ___ your neighbours?",answer:"known",explanation:"To ask about a situation that started in the past and is still true now, use How long + have/has + subject + past participle. Do not use the past simple here.",examples:["How long has your sister lived in Canada?","How long have you been waiting for the bus?"],ua:"Тут теперішній час: «Як давно ти їх знаєш?» → How long have you known them?"},{id:"conv-card-4",rule:"by the way",example:"Thanks for the lift home. And, ___ the way, I love your new car.",answer:"by",explanation:"By the way is a fixed phrase. We use it to add a new thought or a casual extra piece of information to the conversation.",examples:["By the way, do you know a good dentist nearby?","Dan, by the way, is coming to dinner too."],ua:"«До речі» англійською by the way, а не on the way, яке означає «по дорозі»."},{id:"conv-card-5",rule:"tag questions: positive + negative tag",example:"The concert was fantastic, ___ it?",answer:"wasn't",explanation:"A tag question is a short question at the end of a sentence. After a positive statement, use a negative tag with the same auxiliary verb. It invites the other person to agree with you.",examples:["You like jazz, don't you?","Your sister lives in Poland, doesn't she?"],ua:"Як «правда?» чи «так?»: після ствердження ставимо заперечний хвіст: You like jazz, don't you?"},{id:"conv-card-6",rule:"plans: Are you + -ing",example:"What ___ you doing after work tomorrow?",answer:"are",explanation:"To ask about someone's plans, use the present continuous: am, is or are + subject + -ing. It is a friendly way to start a conversation.",examples:["Are you going anywhere this summer?","Is Maria coming to the party on Saturday?"],ua:"Плани: «Що ти робиш завтра?» — present continuous: What are you doing tomorrow?"},{id:"conv-card-7",rule:"How was/were + noun?",example:"How ___ your exams last week?",answer:"were",explanation:"To ask about a past event, use How was or How were. Use was with a singular noun and were with a plural noun.",examples:["How was your flight from Warsaw?","How were the shops in the city centre?"],ua:"«Як пройшли твої іспити?» — минулий час be: How were your exams? (was/were)."},{id:"conv-card-8",rule:"giving permission: Go ahead / Be my guest / Not at all",example:`"Do you mind if I open the window?" "___ at all, it's quite warm in here."`,answer:"Not",explanation:`Not at all means "I don't mind". We use it to answer Do you mind if I...? Go ahead and Be my guest also give permission, but they sound more like "please do".`,examples:['"May I borrow your pen?" "Be my guest."','"Can I take this chair?" "Go ahead, nobody is using it."'],ua:"Not at all на «Do you mind...?» означає «зовсім ні». Go ahead / Be my guest — «прошу, робіть»."},{id:"conv-card-9",rule:"And you? (returning a question)",example:"I work in a bank near here. And ___?",answer:"you",explanation:"After you answer a question, you can return it with And you?, What about you? or How about you? This keeps the conversation going.",examples:[`"I'm a bit tired today. What about you?"`,'"I usually take the bus. How about you?"'],ua:"Повернути питання: «А ти?» → And you? Так само What about you? або How about you?"},{id:"conv-card-10",rule:"fixed farewell phrases",example:"It was lovely to see you again. Let's keep ___ touch!",answer:"in",explanation:"We end conversations with fixed phrases, so learn them as whole chunks: see you later, have a good time, keep in touch, take care. Do not change the words or the prepositions.",examples:["Take care of yourself, and have a safe trip home!","See you on Monday, and have a lovely weekend!"],ua:"Прощання — готові фрази: keep in touch («підтримуймо зв'язок»), take care («бережи себе»)."}],rules:[{id:"conv-gap-1",topic:"starting-ending-conversations",type:"gap-fill",difficulty:"beginner",sentence:"Excuse me, is there ___ wifi near here?",grammarRule:"Quantifiers in questions",explanation:"'Any' is used in questions and negative sentences when asking about availability. 'Some' is for positive statements.",tip:"Use 'any' in questions: 'Is there any...?'",gapFill:{gapIndex:4,correctAnswer:"any",options:["a","any","some","free"],correctOptionIndex:1}},{id:"conv-gap-2",topic:"starting-ending-conversations",type:"gap-fill",difficulty:"beginner",sentence:"Is this your ___ time at this event?",grammarRule:"Fixed conversation phrases",explanation:"'First time' is a fixed phrase used to ask if someone has never been to a place or event before.",tip:"The full phrase is 'Is this your first time here/at...?'",gapFill:{gapIndex:3,correctAnswer:"first",options:["last","only","first","next"],correctOptionIndex:2}},{id:"conv-gap-3",topic:"starting-ending-conversations",type:"gap-fill",difficulty:"intermediate",sentence:"How long have you ___ this job?",grammarRule:"Present perfect with 'how long'",explanation:"Use 'have + past participle' with 'How long' to ask about duration. 'Had' is the past participle of 'have'.",tip:"'How long have you had...?' — asking about something you still have.",gapFill:{gapIndex:4,correctAnswer:"had",options:["done","had","made","worked"],correctOptionIndex:1}},{id:"conv-gap-4",topic:"starting-ending-conversations",type:"gap-fill",difficulty:"beginner",sentence:"I'm Sarah, ___ the way.",grammarRule:"Fixed conversation phrases",explanation:"'By the way' is a fixed phrase used to introduce yourself or add extra information casually in conversation.",tip:"'By the way' signals a casual, informal addition to a conversation.",gapFill:{gapIndex:2,correctAnswer:"by",options:["on","in","by","for"],correctOptionIndex:2}},{id:"conv-gap-5",topic:"starting-ending-conversations",type:"gap-fill",difficulty:"intermediate",sentence:"It's a lovely evening, ___ it?",grammarRule:"Tag questions",explanation:"Tag questions after positive statements use a negative tag. 'It's lovely' → 'isn't it?'",tip:"Positive statement + negative tag: 'It's nice, isn't it?'",gapFill:{gapIndex:4,correctAnswer:"isn't",options:["is","doesn't","isn't","wasn't"],correctOptionIndex:2}},{id:"conv-gap-6",topic:"starting-ending-conversations",type:"gap-fill",difficulty:"beginner",sentence:"I've ___ to go, I'm afraid.",grammarRule:"Fixed farewell phrases",explanation:"'I've got to go' is a common informal phrase meaning 'I must leave now'. 'I'm afraid' softens the statement.",tip:"'Have got to' = 'have to' in informal British English.",gapFill:{gapIndex:1,correctAnswer:"got",options:["get","getting","got","gone"],correctOptionIndex:2}},{id:"conv-gap-7",topic:"starting-ending-conversations",type:"gap-fill",difficulty:"beginner",sentence:"Have ___ at the festival!",grammarRule:"Fixed farewell phrases",explanation:"'Have fun' is a fixed farewell phrase. You cannot say 'Have well' or 'Have nice' without an article.",tip:"'Have fun!' and 'Have a good time!' are both correct farewells.",gapFill:{gapIndex:1,correctAnswer:"fun",options:["well","fun","nice","good"],correctOptionIndex:1}},{id:"conv-err-1",topic:"starting-ending-conversations",type:"error-spot",difficulty:"intermediate",sentence:"Is this your first time on this event?",grammarRule:"Prepositions with events",explanation:"We use 'at' with events and places: 'at this event', 'at a party', 'at a festival'. 'On' is used for surfaces and days.",tip:"Use 'at' for events: 'at a concert', 'at a meeting', 'at this event'.",errorSpot:{errorWordIndex:5,wrongWord:"on",correction:"at",reason:"We use 'at' with events and places: 'at this event', 'at a party', 'at a festival'.",correctionOptions:["in","at","for","of"]}},{id:"conv-err-2",topic:"starting-ending-conversations",type:"error-spot",difficulty:"intermediate",sentence:"It's a lovely day, is it?",grammarRule:"Tag questions",explanation:"After a positive statement, the tag question must be negative: 'It's lovely, isn't it?'",tip:"Positive statement → negative tag. 'It is...' → '...isn't it?'",errorSpot:{errorWordIndex:4,wrongWord:"is",correction:"isn't",reason:"After a positive statement, the tag question must be negative: 'It's lovely, isn't it?'",correctionOptions:["was","isn't","doesn't","hasn't"]}},{id:"conv-err-3",topic:"starting-ending-conversations",type:"error-spot",difficulty:"intermediate",sentence:"Are you do anything nice at the weekend?",grammarRule:"Present continuous",explanation:"After 'Are you', we need the -ing form (present continuous): 'Are you doing anything nice?'",tip:"'Are you + -ing': 'Are you doing, going, working...'",errorSpot:{errorWordIndex:2,wrongWord:"do",correction:"doing",reason:"After 'Are you', we need the -ing continuous form: 'Are you doing anything nice?'",correctionOptions:["done","doing","did","does"]}},{id:"conv-err-4",topic:"starting-ending-conversations",type:"error-spot",difficulty:"beginner",sentence:"See you lately",grammarRule:"Fixed farewell phrases",explanation:"'See you later' is a fixed farewell expression. 'Lately' means 'recently' — the opposite of what is needed here.",tip:"Fixed farewell: 'See you later.' Never 'See you lately.'",errorSpot:{errorWordIndex:2,wrongWord:"lately",correction:"later",reason:"'See you later' is a fixed phrase. 'Lately' means 'recently', which is the opposite meaning.",correctionOptions:["soon","later","again","next"]}},{id:"conv-err-5",topic:"starting-ending-conversations",type:"error-spot",difficulty:"beginner",sentence:"That's me bus, I've got to go",grammarRule:"Possessive adjectives",explanation:"'My' is a possessive adjective (my bus, my bag). 'Me' is an object pronoun and cannot modify a noun.",tip:"Possessive adjectives: my, your, his, her, its, our, their.",errorSpot:{errorWordIndex:1,wrongWord:"me",correction:"my",reason:"'My' is the possessive form. 'Me' is an object pronoun — it cannot describe ownership.",correctionOptions:["the","my","this","a"]}},{id:"conv-err-6",topic:"starting-ending-conversations",type:"error-spot",difficulty:"intermediate",sentence:"Did you listen about the earthquake?",grammarRule:"Verb + preposition collocations",explanation:"'Hear about' means to receive information about something. 'Listen to' means to pay careful attention to a sound.",tip:"'Did you hear about...?' is the natural phrase for sharing news.",errorSpot:{errorWordIndex:2,wrongWord:"listen",correction:"hear",reason:"'Hear about' = to receive news of something. 'Listen' requires 'to': 'listen to music'.",correctionOptions:["know","hear","learn","talk"]}},{id:"conv-mc-1",topic:"starting-ending-conversations",type:"multiple-choice",difficulty:"beginner",sentence:"Which response shows you are happy for someone to proceed with something?",grammarRule:"Responses giving permission",explanation:"'Go ahead' means 'yes, you may proceed'. It is used to give someone permission to do something.",tip:"'Go ahead', 'Be my guest', and 'Not at all' all give permission, but in slightly different contexts.",multipleChoice:{question:"Which option is correct?",correctOption:"Go ahead.",options:["I've got to go.","Go ahead.","By the way.","How long have you?"],optionExplanations:["This means you are leaving, not giving permission.","Correct — 'Go ahead' means 'yes, you may do it'.","This is used to add information to a conversation, not to give permission.","This is an incomplete question, not a response."]}},{id:"conv-mc-2",topic:"starting-ending-conversations",type:"multiple-choice",difficulty:"beginner",sentence:"Someone has answered your question. You want to ask the same question back. Which phrase do you use?",grammarRule:"Keeping a conversation going",explanation:"'And you?' is used to return a question to the other person after they have answered yours.",tip:"'And you?', 'What about you?', and 'How about you?' all work the same way.",multipleChoice:{question:"Which phrase is correct?",correctOption:"And you?",options:["Be my guest.","Not at all.","See you later.","And you?"],optionExplanations:["This gives someone permission to do something.","This means 'I do not mind at all' — a permission phrase.","This is a farewell phrase used when leaving.","Correct — 'And you?' returns the same question back to the other person."]}},{id:"conv-mc-3",topic:"starting-ending-conversations",type:"multiple-choice",difficulty:"beginner",sentence:"Which phrase is used to politely give someone permission to do something?",grammarRule:"Giving permission politely",explanation:"'Be my guest' is a polite, slightly formal way to say 'please go ahead — you are welcome to do it'.",tip:"'Be my guest' sounds more generous and formal than just 'go ahead'.",multipleChoice:{question:"Which option is correct?",correctOption:"Be my guest.",options:["How was your weekend?","Be my guest.","I've got to go.","Did you hear about it?"],optionExplanations:["This is a conversation starter about someone's recent activities.","Correct — 'Be my guest' means 'please, go ahead — you are welcome to'.","This is a farewell phrase used when you need to leave.","This is a conversation starter used to bring up news."]}},{id:"conv-mc-4",topic:"starting-ending-conversations",type:"multiple-choice",difficulty:"intermediate",sentence:"Which is the correct tag to complete: 'It's a lovely morning, ___'?",grammarRule:"Tag questions",explanation:"After a positive statement using 'is', the negative tag is 'isn't it?'. The tag uses the same auxiliary verb in negative form.",tip:"Positive statement → negative tag. 'It is...' → 'isn't it?'",multipleChoice:{question:"Which option is correct?",correctOption:"isn't it?",options:["is it?","isn't it?","doesn't it?","wasn't it?"],optionExplanations:["Wrong — after a positive statement we need a negative tag.","Correct — positive statement + negative tag: 'It's lovely, isn't it?'","Wrong — 'doesn't' is used with present simple verbs (e.g. 'She works here, doesn't she?'), not 'to be'.","Wrong — 'wasn't' is past tense, but 'It's' is present."]}},{id:"conv-mc-5",topic:"starting-ending-conversations",type:"multiple-choice",difficulty:"beginner",sentence:"You have just met someone at an event and want to introduce yourself informally. Which phrase fits?",grammarRule:"Informal introductions",explanation:"'I'm [name], by the way' is a natural, casual way to introduce yourself during a conversation.",tip:"'By the way' is used to add something casually — including your own name.",multipleChoice:{question:"Which phrase is correct?",correctOption:"I'm Emma, by the way.",options:["That's my bus, by the way.","Have fun, by the way.","Go ahead, by the way.","I'm Emma, by the way."],optionExplanations:["This is a farewell used when you need to leave — not an introduction.","This is a farewell phrase — not an introduction.","This gives permission — not an introduction.","Correct — 'I'm [name], by the way' is a natural informal self-introduction."]}},{id:"conv-mc-6",topic:"starting-ending-conversations",type:"multiple-choice",difficulty:"beginner",sentence:"Which phrase is used to start a conversation by bringing up recent news or events?",grammarRule:"Conversation starters with news",explanation:"'Did you hear about...?' is used to bring up something newsworthy that you both might know about.",tip:"Use 'Did you hear about...?' or 'Did you watch...?' to start a conversation about shared topics.",multipleChoice:{question:"Which option is correct?",correctOption:"Did you hear about the match?",options:["See you later.","Did you hear about the match?","Not at all.","Have fun."],optionExplanations:["This is a farewell phrase.","Correct — 'Did you hear about...?' is a classic opener to share or discuss news.","This means 'I do not mind' — a permission response, not a conversation starter.","This is a farewell phrase."]}},{id:"conv-reorder-1",topic:"starting-ending-conversations",type:"word-transform",difficulty:"beginner",sentence:"How long ___ you been working here?",grammarRule:"Present Perfect question — duration",explanation:"'How long have you been...?' asks how much time has passed. Use 'have' with 'you'.",tip:"How long + have/has + subject + been + verb-ing? How long have you been working?",wordTransform:{baseWord:"have/has",correctAnswer:"have"}},{id:"conv-reorder-2",topic:"starting-ending-conversations",type:"word-transform",difficulty:"beginner",sentence:"___ you hear about the new coffee shop?",grammarRule:"Past Simple question — asking about news",explanation:"'Did you hear about...?' asks if someone received information in the past. Use 'Did' for past simple questions.",tip:"Did you hear about...? = past simple question. Use 'did' for all subjects.",wordTransform:{baseWord:"Did/Have",correctAnswer:"Did"}},{id:"conv-reorder-3",topic:"starting-ending-conversations",type:"word-transform",difficulty:"beginner",sentence:"How ___ your weekend?",grammarRule:"Past Simple with 'be': How was/were...?",explanation:"'How was your weekend?' uses the past simple of 'be'. 'Weekend' is singular → 'was'.",tip:"How was your + singular noun? How were your + plural noun?",wordTransform:{baseWord:"was/were",correctAnswer:"was"}},{id:"conv-reorder-4",topic:"starting-ending-conversations",type:"word-transform",difficulty:"intermediate",sentence:"___ you doing anything special tonight?",grammarRule:"Present Continuous question — asking about plans",explanation:"'Are you doing...?' is a Present Continuous question used to ask about plans. Use 'Are' with 'you'.",tip:"Are you + -ing? Are you doing/going/coming? Use Present Continuous for future plans.",wordTransform:{baseWord:"Are/Were",correctAnswer:"Are"}},{id:"conv-reorder-5",topic:"starting-ending-conversations",type:"word-transform",difficulty:"intermediate",sentence:"I'm afraid I ___ to go now.",grammarRule:"'have to' for obligation — leaving a conversation",explanation:"'I have to go' expresses obligation or necessity. 'I'm afraid I have to go' is a polite farewell.",tip:"Have to = must/need to. I have to go, I have to leave, I have to run.",wordTransform:{baseWord:"have/had",correctAnswer:"have"}},{id:"conv-reorder-6",topic:"starting-ending-conversations",type:"word-transform",difficulty:"intermediate",sentence:"It was lovely ___ you.",grammarRule:"Adjective + -ing form as object",explanation:"'Lovely meeting you' = the act of meeting was lovely. After 'lovely/nice/great', use the -ing form.",tip:"It was lovely/nice/great + meeting/seeing/talking to + object.",wordTransform:{baseWord:"meet",correctAnswer:"meeting"}},{id:"conv-match-1",topic:"starting-ending-conversations",type:"sentence-match",difficulty:"beginner",sentence:"Match each conversation opener to its correct ending.",grammarRule:"Conversation openers",explanation:"These are fixed phrases used to start a conversation. Each beginning has only one natural, correct ending.",tip:"Pay attention to grammar and the type of question each beginning sets up.",sentenceMatch:{pairs:[{beginning:"It's a lovely day,",ending:"isn't it?"},{beginning:"Did you hear about",ending:"the accident?"},{beginning:"Are you doing anything nice",ending:"at the weekend?"},{beginning:"How long have you",ending:"worked here?"}]}},{id:"conv-match-2",topic:"starting-ending-conversations",type:"sentence-match",difficulty:"beginner",sentence:"Match each farewell phrase to its correct ending.",grammarRule:"Farewell and closing phrases",explanation:"These are fixed farewell expressions used to end a conversation. Each phrase has one standard, correct completion.",tip:"'See you later', 'Have a good time', 'Great talking to you' and 'I'm [name], by the way' are all fixed phrases.",sentenceMatch:{pairs:[{beginning:"See you",ending:"later."},{beginning:"Have a good",ending:"time!"},{beginning:"Great talking",ending:"to you."},{beginning:"I'm David,",ending:"by the way."}]}}]},c=[{id:"aof-gap-1",topic:"adverbs-of-frequency",type:"gap-fill",difficulty:"beginner",sentence:"She ___ arrives at the office before 9 a.m.",grammarRule:"Adverb of Frequency — Before the Main Verb",explanation:"Adverbs of frequency go BEFORE the main verb (except 'to be'). 'Always' sits between the subject 'She' and the verb 'arrives'.",tip:"Subject + adverb + main verb: She always arrives, He never eats, They usually walk.",gapFill:{gapIndex:1,correctAnswer:"always",options:["always","is always","always is","be always"],correctOptionIndex:0}},{id:"aof-gap-2",topic:"adverbs-of-frequency",type:"gap-fill",difficulty:"beginner",sentence:"Our classroom is ___ very noisy before lessons start.",grammarRule:"Adverb of Frequency — After 'To Be'",explanation:"When the main verb is 'to be', the adverb comes AFTER it. Structure: Subject + be + adverb.",tip:"After 'to be': She is always ready, He is never late, They are usually tired.",gapFill:{gapIndex:3,correctAnswer:"usually",options:["usually","usually is","is usually","usually be"],correctOptionIndex:0}},{id:"aof-gap-3",topic:"adverbs-of-frequency",type:"gap-fill",difficulty:"beginner",sentence:"I go swimming ___ a week to stay fit.",grammarRule:"Definite Frequency — Twice",explanation:"For 'two times', always use 'twice'. 'Two times a week' is non-standard in everyday English.",tip:"One time = once. Two times = twice. Three or more = three times, four times, etc.",gapFill:{gapIndex:3,correctAnswer:"twice",options:["twice","two times","two","second"],correctOptionIndex:0}},{id:"aof-gap-4",topic:"adverbs-of-frequency",type:"gap-fill",difficulty:"intermediate",sentence:"You should ___ read the instructions before using the machine.",grammarRule:"Adverb of Frequency — With Auxiliary Verbs",explanation:"With modal auxiliaries (should, must, can, will, etc.), the adverb goes BETWEEN the auxiliary and the main verb.",tip:"Subject + auxiliary + adverb + main verb: You should always check, She can sometimes help.",gapFill:{gapIndex:2,correctAnswer:"always",options:["always","is always","always is","be always"],correctOptionIndex:0}},{id:"aof-gap-5",topic:"adverbs-of-frequency",type:"gap-fill",difficulty:"intermediate",sentence:"The team meets ___ a month to review progress.",grammarRule:"Definite Frequency — Once",explanation:"For 'one time', use 'once'. Say 'once a month', not 'one time a month'.",tip:"One time = once. Use 'once a week/month/year' for regular activities.",gapFill:{gapIndex:3,correctAnswer:"once",options:["once","one time","one","first"],correctOptionIndex:0}},{id:"aof-gap-6",topic:"adverbs-of-frequency",type:"gap-fill",difficulty:"advanced",sentence:"He ___ complains about anything, even when things go wrong.",grammarRule:"Hardly Ever — Used with Positive Verbs",explanation:"'Hardly ever' is already negative in meaning, so it must be used with a POSITIVE verb form. Never add 'don't/doesn't'.",tip:"Negative adverbs (never, hardly ever, seldom) + positive verb: He never complains, She hardly ever misses.",gapFill:{gapIndex:1,correctAnswer:"hardly ever",options:["hardly ever","doesn't hardly ever","hardly ever doesn't","hardly"],correctOptionIndex:0}},{id:"aof-error-1",topic:"adverbs-of-frequency",type:"error-spot",difficulty:"beginner",sentence:"Is she usually cook dinner for the family?",grammarRule:"Frequency Adverbs in Yes/No Questions — Do/Does",explanation:"For action verbs with he/she/it, use 'Does' in questions, not 'Is'. 'Is' is only used with the verb 'to be'.",errorSpot:{errorWordIndex:0,wrongWord:"Is",correction:"Does",reason:"'Cook' is an action verb, so use 'Does' for he/she/it questions: 'Does she usually cook?' not 'Is she usually cook?'",correctionOptions:["Does","Is","Are","Do"]}},{id:"aof-error-2",topic:"adverbs-of-frequency",type:"error-spot",difficulty:"beginner",sentence:"He always arrive early to the morning meeting.",grammarRule:"Subject-Verb Agreement with Frequency Adverbs",explanation:"Frequency adverbs don't change the verb agreement rule. Third-person singular (he/she/it) still needs -s on the verb.",errorSpot:{errorWordIndex:2,wrongWord:"arrive",correction:"arrives",reason:"'He' = third person singular → needs 'arrives'. Frequency adverbs don't affect subject-verb agreement.",correctionOptions:["arrives","arrive","is arriving","arrived"]}},{id:"aof-error-3",topic:"adverbs-of-frequency",type:"error-spot",difficulty:"beginner",sentence:"She calls her mother twice the week.",grammarRule:"Definite Frequency — Indefinite Article 'A'",explanation:"Frequency expressions use the indefinite article 'a', not 'the'. Say 'twice a week', 'once a month', 'three times a year'.",errorSpot:{errorWordIndex:5,wrongWord:"the",correction:"a",reason:"Use 'a' (not 'the') in frequency expressions: twice a week, once a month, three times a year.",correctionOptions:["a","the","per","in"]}},{id:"aof-error-4",topic:"adverbs-of-frequency",type:"error-spot",difficulty:"intermediate",sentence:"He is seldomly on time for appointments.",grammarRule:"Adverb Form — Seldom",explanation:"'Seldom' is already an adverb. Adding '-ly' creates a non-existent word. Use 'seldom', not 'seldomly'.",errorSpot:{errorWordIndex:2,wrongWord:"seldomly",correction:"seldom",reason:"'Seldom' is an adverb on its own — no '-ly' needed. It also goes AFTER 'is' (to be).",correctionOptions:["seldom","seldomly","often","usually"]}},{id:"aof-error-5",topic:"adverbs-of-frequency",type:"error-spot",difficulty:"intermediate",sentence:"My brother rarely watch TV in the evenings.",grammarRule:"Subject-Verb Agreement — Rarely",explanation:"The adverb 'rarely' doesn't change the agreement rule. 'My brother' = he → third person singular → needs 'watches'.",errorSpot:{errorWordIndex:3,wrongWord:"watch",correction:"watches",reason:"'My brother' = he → third person singular → 'watches'. The adverb 'rarely' doesn't affect this.",correctionOptions:["watches","watch","is watching","watched"]}},{id:"aof-error-6",topic:"adverbs-of-frequency",type:"error-spot",difficulty:"advanced",sentence:"The doctor told me to take this pill three times of day.",grammarRule:"Definite Frequency — 'Times A Day'",explanation:"The structure is 'number + times + a + time period'. Use 'a day', not 'of day'.",errorSpot:{errorWordIndex:10,wrongWord:"of",correction:"a",reason:"Use 'a' before the time period: three times a day, four times a week, twice a year.",correctionOptions:["a","of","in","per"]}},{id:"aof-mc-1",topic:"adverbs-of-frequency",type:"multiple-choice",difficulty:"beginner",sentence:"Choose the sentence with the correct adverb position:",grammarRule:"Adverb of Frequency — Before the Main Verb",explanation:"Adverbs of frequency go BEFORE the main verb. 'Usually' must come between the subject 'She' and the verb 'works'.",tip:"Subject + adverb + main verb: She usually works, He often travels, They always eat.",multipleChoice:{question:"Which sentence is correct?",correctOption:"She usually works from home on Fridays.",options:["She usually works from home on Fridays.","She works usually from home on Fridays.","She works from home usually on Fridays.","She works from home on usually Fridays."],optionExplanations:{"She usually works from home on Fridays.":"Correct! Adverb 'usually' goes before the main verb 'works'.","She works usually from home on Fridays.":"Wrong. 'Usually' must come BEFORE the main verb, not after it.","She works from home usually on Fridays.":"Wrong. Adverbs of frequency don't go between the place and time expressions.","She works from home on usually Fridays.":"Wrong. The adverb goes before the main verb, not before the time expression."}}},{id:"aof-mc-2",topic:"adverbs-of-frequency",type:"multiple-choice",difficulty:"beginner",sentence:"Choose the sentence with the correct position of 'always':",grammarRule:"Adverb of Frequency — After 'To Be'",explanation:"When the verb is 'to be' (am/is/are), the adverb comes AFTER it. Structure: Subject + be + adverb + rest.",tip:"After 'to be': My boss is always organised, She is never late, We are usually tired.",multipleChoice:{question:"Which sentence is correct?",correctOption:"My boss is always very organised.",options:["My boss is always very organised.","My boss always is very organised.","Always my boss is very organised.","My boss very organised is always."],optionExplanations:{"My boss is always very organised.":"Correct! 'Always' comes AFTER the verb 'is'.","My boss always is very organised.":"Wrong. With 'to be', the adverb must come AFTER 'is', not before it.","Always my boss is very organised.":"Wrong. 'Always' cannot go at the beginning of a sentence.","My boss very organised is always.":"Wrong. The word order is completely incorrect."}}},{id:"aof-mc-3",topic:"adverbs-of-frequency",type:"multiple-choice",difficulty:"intermediate",sentence:"Which adverb CAN be placed at the beginning of a sentence for emphasis?",grammarRule:"Adverb Position — Beginning of Sentence",explanation:"Some adverbs can go at the start for emphasis: usually, normally, often, frequently, sometimes, occasionally. Others CANNOT start a sentence: always, seldom, rarely, hardly ever, never.",tip:"Can start a sentence: sometimes, usually, often, occasionally. Cannot: always, never, seldom, rarely.",multipleChoice:{question:"Which word can correctly start a sentence?",correctOption:"Sometimes",options:["Sometimes","Never","Always","Seldom"],optionExplanations:{Sometimes:"Correct! 'Sometimes' can go at the beginning: 'Sometimes I skip lunch.'",Never:"Wrong. 'Never' cannot go at the start of a statement.",Always:"Wrong. 'Always' cannot go at the start of a statement.",Seldom:"Wrong. 'Seldom' cannot go at the start of a statement."}}},{id:"aof-mc-4",topic:"adverbs-of-frequency",type:"multiple-choice",difficulty:"intermediate",sentence:"Choose the sentence that correctly uses 'hardly ever':",grammarRule:"Hardly Ever — With Positive Verbs",explanation:"'Hardly ever' is already negative in meaning, so it must be used with a POSITIVE verb. Never combine it with 'don't/doesn't'.",tip:"Hardly ever + positive verb: She hardly ever misses class. Never: She hardly ever doesn't miss class.",multipleChoice:{question:"Which sentence is correct?",correctOption:"She hardly ever misses a lesson.",options:["She hardly ever misses a lesson.","She hardly ever doesn't miss a lesson.","She doesn't hardly ever miss a lesson.","She is hardly ever miss a lesson."],optionExplanations:{"She hardly ever misses a lesson.":"Correct! 'Hardly ever' + positive verb 'misses'.","She hardly ever doesn't miss a lesson.":"Wrong. 'Hardly ever' + negative verb = double negative.","She doesn't hardly ever miss a lesson.":"Wrong. Double negative — 'hardly ever' already carries a negative meaning.","She is hardly ever miss a lesson.":"Wrong. After 'is' you need an adjective, not a base verb."}}},{id:"aof-mc-5",topic:"adverbs-of-frequency",type:"multiple-choice",difficulty:"intermediate",sentence:"Choose the correct 'How often' question:",grammarRule:"How Often — Question Form",explanation:"'How often' is used to ask about frequency. Structure: How often + do/does + subject + base verb?",tip:"How often do you...? How often does she...? How often are you...? (with 'to be')",multipleChoice:{question:"Which question is correctly formed?",correctOption:"How often do you exercise?",options:["How often do you exercise?","How often you do exercise?","How often are you exercise?","How often does you exercise?"],optionExplanations:{"How often do you exercise?":"Correct! Structure: How often + do + you + base verb.","How often you do exercise?":"Wrong. The auxiliary 'do' must come before the subject: 'do you'.","How often are you exercise?":"Wrong. Use 'do' (not 'are') with action verbs like 'exercise'.","How often does you exercise?":"Wrong. 'Does' is for he/she/it. With 'you', use 'do'."}}},{id:"aof-mc-6",topic:"adverbs-of-frequency",type:"multiple-choice",difficulty:"intermediate",sentence:"Choose the sentence with the correct adverb position with a modal verb:",grammarRule:"Adverb of Frequency — With Auxiliary Verbs",explanation:"With modal auxiliaries (should, can, must, will, etc.), the adverb goes BETWEEN the modal and the main verb.",tip:"Modal + adverb + main verb: You should always check. She can sometimes help. They must never lie.",multipleChoice:{question:"Which sentence is correct?",correctOption:"You should always check your work before submitting.",options:["You should always check your work before submitting.","You always should check your work before submitting.","You should check always your work before submitting.","Always you should check your work before submitting."],optionExplanations:{"You should always check your work before submitting.":"Correct! Adverb between modal 'should' and main verb 'check'.","You always should check your work before submitting.":"Wrong. The adverb goes AFTER the modal, not before it.","You should check always your work before submitting.":"Wrong. The adverb goes BEFORE the main verb, not after it.","Always you should check your work before submitting.":"Wrong. 'Always' cannot go at the start of a sentence."}}},{id:"aof-mc-7",topic:"adverbs-of-frequency",type:"multiple-choice",difficulty:"advanced",sentence:"Choose the correct Yes/No question with a frequency adverb:",grammarRule:"Frequency Adverbs in Yes/No Questions",explanation:"In Yes/No questions, the adverb goes after the subject: Does/Do + subject + adverb + main verb?",tip:"Questions: Does she usually cook? Do you often travel? Are you always late? (with 'to be')",multipleChoice:{question:"Which question is correct?",correctOption:"Does she usually cook dinner?",options:["Does she usually cook dinner?","Does usually she cook dinner?","Does she cook usually dinner?","Usually does she cook dinner?"],optionExplanations:{"Does she usually cook dinner?":"Correct! Structure: Does + she (subject) + usually (adverb) + cook (verb).","Does usually she cook dinner?":"Wrong. 'Usually' must come after the subject 'she', not before it.","Does she cook usually dinner?":"Wrong. 'Usually' must come before the main verb 'cook', not after it.","Usually does she cook dinner?":"Wrong. 'Usually' can start a statement, but not a question beginning with 'Does'."}}},{id:"aof-reorder-1",topic:"adverbs-of-frequency",type:"word-transform",difficulty:"beginner",sentence:"She ___ has a salad for lunch.",grammarRule:"Adverb Form — Usual → Usually",explanation:"Add '-ly' to 'usual' to form the adverb 'usually' (90%). Adverbs of frequency go before the main verb.",tip:"Adjective → adverb: usual → usually, normal → normally, general → generally.",wordTransform:{baseWord:"usual",correctAnswer:"usually"}},{id:"aof-reorder-2",topic:"adverbs-of-frequency",type:"word-transform",difficulty:"beginner",sentence:"He ___ travels abroad for work.",grammarRule:"Adverb Form — Frequent → Frequently",explanation:"Add '-ly' to 'frequent' to form 'frequently' (70%). It means the same as 'often'.",tip:"Frequent → frequently. About 70% of the time — several times a week.",wordTransform:{baseWord:"frequent",correctAnswer:"frequently"}},{id:"aof-reorder-3",topic:"adverbs-of-frequency",type:"word-transform",difficulty:"intermediate",sentence:"She ___ loses her temper, even under pressure.",grammarRule:"Adverb Form — Rare → Rarely",explanation:"Add '-ly' to 'rare' to form 'rarely' (5%). It means the same as 'hardly ever'.",tip:"Rare → rarely. About 5% of the time — almost never. Use with a positive verb.",wordTransform:{baseWord:"rare",correctAnswer:"rarely"}},{id:"aof-reorder-4",topic:"adverbs-of-frequency",type:"word-transform",difficulty:"intermediate",sentence:"We ___ eat out at a restaurant on weekends.",grammarRule:"Adverb Form — Occasional → Occasionally",explanation:"Add '-ly' to 'occasional' to form 'occasionally' (30%). It means 'sometimes, but not often'.",tip:"Occasional → occasionally. About 30% of the time — now and then.",wordTransform:{baseWord:"occasional",correctAnswer:"occasionally"}},{id:"aof-reorder-5",topic:"adverbs-of-frequency",type:"word-transform",difficulty:"intermediate",sentence:"He ___ wakes up before 7 a.m.",grammarRule:"Adverb Form — General → Generally",explanation:"Add '-ly' to 'general' to form 'generally' (80%). It means 'in most cases' — similar to 'normally'.",tip:"General → generally. About 80% of the time — as a rule, in most situations.",wordTransform:{baseWord:"general",correctAnswer:"generally"}},{id:"aof-reorder-6",topic:"adverbs-of-frequency",type:"word-transform",difficulty:"advanced",sentence:"She ___ finishes work at 6 p.m., but today she stayed until 8.",grammarRule:"Adverb Form — Normal → Normally",explanation:"Add '-ly' to 'normal' to form 'normally' (80%). It signals the usual routine, often used to contrast with an exception.",tip:"Normal → normally. Great for contrasts: 'She normally does X, but today...'",wordTransform:{baseWord:"normal",correctAnswer:"normally"}}],p={id:"adverbs-of-frequency",level:"B1",name:"Adverbs of Frequency",description:"Master adverbs of frequency (always, usually, often, sometimes, never) and their position in sentences. Learn once/twice, definite frequency phrases like 'three times a week', and how to avoid double negatives.",lesson:"Lesson 3",icon:"🔁",cards:[{id:"aof-card-1",rule:"adverb + main verb",example:"Tom has a coffee after lunch every day, without exception. He ___ has a coffee after lunch.",answer:"always",explanation:"Adverbs of frequency usually go before the main verb. Put them between the subject and the verb: I never smoke, she often travels.",examples:["We sometimes eat at the market on Saturdays.","My manager rarely replies to emails after six."],ua:"Прислівник частоти — перед дієсловом: «Я завжди п'ю чай» — I always drink tea."},{id:"aof-card-2",rule:"he / she / it + adverb + verb-s",example:"I always walk to work, and my brother always ___ to work too.",answer:"walks",explanation:"Frequency adverbs do not change the verb. With he, she and it the main verb still takes -s: she usually leaves, he never calls.",examples:["Our teacher usually comes five minutes early.","The shop rarely closes before eight o'clock."],ua:"Прислівник не змінює правила: he / she / it + дієслово з -s. «Вона завжди сміється» — She always laughs."},{id:"aof-card-3",rule:"be + adverb of frequency",example:"The train is on time every single day of the year. It is ___ late.",answer:"never",explanation:"With the verb be (am, is, are, was, were), the adverb comes after it: we are usually busy, they are never late.",examples:["My neighbours are usually very quiet at night.","I am often tired after a long shift."],ua:"З be прислівник стоїть після нього: «Вона завжди вдома» — She is always at home."},{id:"aof-card-4",rule:"modal / auxiliary + adverb + main verb",example:"On this building site you must ___ wear a helmet, without exception.",answer:"always",explanation:"With can, must, should, will or have, the adverb goes after the auxiliary and before the main verb: you can sometimes park here, I have never been to Rome.",examples:["She can sometimes work from home on Fridays.","I have never tried Japanese food."],ua:"Після can, must, have — перед смисловим дієсловом: I have never tried — «я ніколи не пробував»."},{id:"aof-card-5",rule:"hardly ever / rarely / seldom + positive verb",example:"We see my uncle about once every five years. We hardly ___ see him.",answer:"ever",explanation:"Hardly ever, rarely and seldom already mean almost never. Use them with a positive verb. Never add don't or doesn't.",examples:["Our manager rarely works at weekends.","I hardly ever eat dessert in the evening."],ua:"Українською: «майже ніколи не їм». Англійською без don't: I hardly ever eat."},{id:"aof-card-6",rule:"once / twice / three times a week",example:"I water the plants on Monday, Wednesday and Friday, so I water them ___ a week.",answer:"three times",explanation:"Say once for one and twice for two. After that, use number + times: three times, four times. Use a (not the) before the period: once a week, twice a year.",examples:["She goes to her Spanish class once a week.","My brother visits our parents twice a year."],ua:"Раз — once, два — twice, далі three times. «Двічі на тиждень» — twice a week."},{id:"aof-card-7",rule:"How often + do / does + subject + verb?",example:"A: ___ do you go to the dentist? B: Every six months.",answer:"How often",explanation:"Use How often to ask about frequency. After it, use the normal question form: how often + do/does + subject + verb. With be: how often are you...?",examples:["How often does your train run in the evening?","How often are you late for work?"],ua:"How often...? — «Як часто...?» Відповідь: every day, twice a week, never."},{id:"aof-card-8",rule:"Do / Does + subject + adverb + verb",example:"___ your sister often visit you at weekends?",answer:"Does",explanation:"In questions the adverb goes after the subject and before the main verb. Use Do or Does with action verbs. With be, the adverb also comes after the subject: Are you always this busy?",examples:["Do you often work late on Fridays?","Are your neighbours always this noisy?"],ua:"У питанні прислівник — після підмета: Do you often travel? — «Ти часто подорожуєш?»"},{id:"aof-card-9",rule:"never + positive verb (no don't)",example:"I'm allergic to nuts, so I ___ (never / don't never) eat them.",answer:"never",explanation:"Never already makes the sentence negative, so the verb stays positive: I never eat, not I don't never eat.",examples:["My father never drinks coffee after six.","We never watch TV during dinner."],ua:"Українською «я ніколи не їм», англійською одне заперечення: I never eat, а не «I don't never eat»."}],rules:c},u=[{id:"sdv-gap-1",topic:"stative-dynamic-verbs",type:"gap-fill",difficulty:"beginner",sentence:"She ___ a beautiful voice.",grammarRule:"Stative Verb 'Have' — Possession / Characteristic",explanation:"'Have' used to express possession or a characteristic is stative — use Present Simple, never Present Continuous.",tip:"Have (own/possess) = stative → has/have. Have (experience) = dynamic → is having/are having.",gapFill:{gapIndex:1,correctAnswer:"has",options:["has","is having","having","have"],correctOptionIndex:0}},{id:"sdv-gap-2",topic:"stative-dynamic-verbs",type:"gap-fill",difficulty:"beginner",sentence:"He ___ the project will be successful.",grammarRule:"Stative Verb 'Think' — Belief / Opinion",explanation:"'Think' used to express a belief or opinion is stative — use Present Simple. 'I think' = I believe.",tip:"Think (believe) = stative → thinks/think. Think (consider/process) = dynamic → is thinking.",gapFill:{gapIndex:1,correctAnswer:"thinks",options:["thinks","is thinking","thinking","think"],correctOptionIndex:0}},{id:"sdv-gap-3",topic:"stative-dynamic-verbs",type:"gap-fill",difficulty:"intermediate",sentence:"We ___ a great time at the party right now!",grammarRule:"Dynamic Verb 'Have' — Experiencing",explanation:"'Have' used to mean 'experience' or 'enjoy' is dynamic — use Present Continuous. 'Having a great time' = experiencing/enjoying.",tip:"Have a good time / have a meeting / have lunch → dynamic → use is/am/are having.",gapFill:{gapIndex:1,correctAnswer:"are having",options:["are having","have","has","having"],correctOptionIndex:0}},{id:"sdv-gap-4",topic:"stative-dynamic-verbs",type:"gap-fill",difficulty:"intermediate",sentence:"I ___ my dentist tomorrow afternoon.",grammarRule:"Dynamic Verb 'See' — Meeting / Visiting",explanation:"'See' used to mean 'meet' or 'visit' is dynamic — use Present Continuous. 'I'm seeing' = I have an appointment.",tip:"See (understand) = stative → I see. See (visit/meet) = dynamic → I'm seeing.",gapFill:{gapIndex:1,correctAnswer:"am seeing",options:["am seeing","see","sees","seeing"],correctOptionIndex:0}},{id:"sdv-gap-5",topic:"stative-dynamic-verbs",type:"gap-fill",difficulty:"intermediate",sentence:"She ___ very rude to everyone lately.",grammarRule:"Dynamic Verb 'Be' — Temporary Behaviour",explanation:"'Be' used to describe temporary behaviour uses Present Continuous: 'is being'. It means she is acting rudely now — it may not last.",tip:"Be (permanent quality) = stative → She is kind. Be (temporary behaviour) = dynamic → She is being rude.",gapFill:{gapIndex:1,correctAnswer:"is being",options:["is being","is","being","be"],correctOptionIndex:0}},{id:"sdv-gap-6",topic:"stative-dynamic-verbs",type:"gap-fill",difficulty:"advanced",sentence:"I ___ about changing my job at the moment.",grammarRule:"Dynamic Verb 'Think' — Considering / Processing",explanation:"'Think' used to mean 'consider' or 'reflect on' is dynamic — use Present Continuous.",tip:"Think (believe) = I think it's true. Think (consider) = I'm thinking about it.",gapFill:{gapIndex:1,correctAnswer:"am thinking",options:["am thinking","think","thinks","thinking"],correctOptionIndex:0}},{id:"sdv-error-1",topic:"stative-dynamic-verbs",type:"error-spot",difficulty:"beginner",sentence:"She knowing French and Italian.",grammarRule:"Stative Verb 'Know' — Never in Continuous",explanation:"'Know' is a stative verb — it describes a state of mind (having knowledge). Stative verbs cannot be used in the -ing form.",errorSpot:{errorWordIndex:1,wrongWord:"knowing",correction:"knows",reason:"'Know' is stative and cannot use the -ing form. Use Present Simple: 'She knows French and Italian.'",correctionOptions:["knows","knowing","is knowing","known"]}},{id:"sdv-error-2",topic:"stative-dynamic-verbs",type:"error-spot",difficulty:"beginner",sentence:"The coffee tasting bitter this morning.",grammarRule:"Stative Verb 'Taste' — Sensory Property",explanation:"'Taste' used to describe a flavour (sensory property) is stative. Use Present Simple: 'tastes'.",errorSpot:{errorWordIndex:2,wrongWord:"tasting",correction:"tastes",reason:"'Taste' (= has a flavour) is stative — no -ing form. Use 'tastes': 'The coffee tastes bitter.'",correctionOptions:["tastes","tasting","is tasting","tasted"]}},{id:"sdv-error-3",topic:"stative-dynamic-verbs",type:"error-spot",difficulty:"beginner",sentence:"I believing this is a good idea.",grammarRule:"Stative Verb 'Believe' — Opinion",explanation:"'Believe' is a stative verb expressing an opinion or judgement. It cannot be used in the -ing form.",errorSpot:{errorWordIndex:1,wrongWord:"believing",correction:"believe",reason:"'Believe' is stative — always use Present Simple: 'I believe', never 'I am believing'.",correctionOptions:["believe","believing","am believing","believed"]}},{id:"sdv-error-4",topic:"stative-dynamic-verbs",type:"error-spot",difficulty:"intermediate",sentence:"He resembling his father very much.",grammarRule:"Stative Verb 'Resemble' — Appearance",explanation:"'Resemble' describes how someone looks compared to another person — it is always stative. Use Present Simple.",errorSpot:{errorWordIndex:1,wrongWord:"resembling",correction:"resembles",reason:"'Resemble' is always stative — no continuous form exists. Use 'resembles': 'He resembles his father very much.'",correctionOptions:["resembles","resembling","is resembling","resembled"]}},{id:"sdv-error-5",topic:"stative-dynamic-verbs",type:"error-spot",difficulty:"intermediate",sentence:"This bag belonging to Maria.",grammarRule:"Stative Verb 'Belong' — Ownership",explanation:"'Belong' describes ownership and is always stative. It cannot be used in the -ing form.",errorSpot:{errorWordIndex:2,wrongWord:"belonging",correction:"belongs",reason:"'Belong' is stative — always Present Simple: 'This bag belongs to Maria.'",correctionOptions:["belongs","belonging","is belonging","belonged"]}},{id:"sdv-error-6",topic:"stative-dynamic-verbs",type:"error-spot",difficulty:"advanced",sentence:"He being 30 years old.",grammarRule:"Stative Verb 'Be' — Permanent Characteristic",explanation:"'Be' describes a permanent characteristic (age, origin, appearance) — use Present Simple 'is/am/are', not 'being'.",errorSpot:{errorWordIndex:1,wrongWord:"being",correction:"is",reason:"Permanent qualities use 'is': 'He is 30 years old.' Use 'is being' ONLY for temporary behaviour: 'He is being rude.'",correctionOptions:["is","being","has","was"]}},{id:"sdv-mc-1",topic:"stative-dynamic-verbs",type:"multiple-choice",difficulty:"beginner",sentence:"Choose the sentence that uses 'know' correctly:",grammarRule:"Stative Verb 'Know' — Always Simple",explanation:"'Know' is always stative — it cannot be used in continuous form in any context.",tip:"Know, believe, understand, remember — always stative, always Present Simple.",multipleChoice:{question:"Which sentence is correct?",correctOption:"She knows three languages.",options:["She knows three languages.","She is knowing three languages.","She knowing three languages.","She is know three languages."],optionExplanations:{"She knows three languages.":"Correct! 'Know' is stative — always use Present Simple.","She is knowing three languages.":"Wrong. 'Know' is stative and can never be used in continuous form.","She knowing three languages.":"Wrong. Missing auxiliary verb AND wrong form — 'know' cannot be -ing.","She is know three languages.":"Wrong. 'Know' must be in the simple form, not with 'is': 'She knows'."}}},{id:"sdv-mc-2",topic:"stative-dynamic-verbs",type:"multiple-choice",difficulty:"beginner",sentence:"Choose the sentence where 'have' is used as a STATIVE verb:",grammarRule:"Stative Verb 'Have' — Possession",explanation:"'Have' is stative when it means 'possess' or 'own'. It's dynamic (continuous) when it means 'experience': having a bath, having fun.",tip:"Have (own) = stative → has/have. Have (experience/enjoy) = dynamic → is having.",multipleChoice:{question:"Which sentence uses 'have' with a stative (possession) meaning?",correctOption:"She has a house in the countryside.",options:["She has a house in the countryside.","She is having lunch with a client.","They are having a great time.","He is having a shower."],optionExplanations:{"She has a house in the countryside.":"Correct! 'Has a house' = possesses/owns → stative → Present Simple.","She is having lunch with a client.":"Wrong. 'Having lunch' is dynamic (an activity/experience) → Present Continuous is correct here.","They are having a great time.":"Wrong. 'Having a great time' = experiencing → dynamic → Continuous is correct here.","He is having a shower.":"Wrong. 'Having a shower' is an activity → dynamic → Continuous is correct here."}}},{id:"sdv-mc-3",topic:"stative-dynamic-verbs",type:"multiple-choice",difficulty:"intermediate",sentence:"Choose the sentence where 'see' is used as a DYNAMIC verb:",grammarRule:"Stative vs Dynamic — 'See'",explanation:"When 'see' means 'meet' or 'visit', it is dynamic — use Present Continuous. When it means 'perceive' or 'understand', it is stative — use Present Simple.",tip:"See (understand/perceive) = stative: 'I see.' See (visit/meet by arrangement) = dynamic: 'I'm seeing my lawyer tonight.'",multipleChoice:{question:"In which sentence does 'see' describe an action or arrangement?",correctOption:"I'm seeing the doctor at 10 a.m. tomorrow.",options:["I'm seeing the doctor at 10 a.m. tomorrow.","I see what you mean now.","I can see the mountains from here.","Do you see anyone you recognise?"],optionExplanations:{"I'm seeing the doctor at 10 a.m. tomorrow.":"Correct! 'I'm seeing' = I have an appointment — the dynamic use of 'see'.","I see what you mean now.":"Wrong. 'I see' here = I understand — this is the stative use.","I can see the mountains from here.":"Wrong. 'Can see' = visual perception — this is the stative use.","Do you see anyone you recognise?":"Wrong. 'See' here = visual perception — this is the stative use."}}},{id:"sdv-mc-4",topic:"stative-dynamic-verbs",type:"multiple-choice",difficulty:"intermediate",sentence:"She is being very generous today.",grammarRule:"Dynamic Verb 'Be' — Temporary Behaviour",explanation:"'Is being' + adjective describes temporary behaviour — how someone is acting right now. It suggests this is unusual or different from normal.",tip:"She is kind = permanent quality. She is being kind = temporary behaviour (unusual or noteworthy).",multipleChoice:{question:"What does this tell us about her generosity?",correctOption:"She is acting generously now — it might not be her usual behaviour.",options:["She is acting generously now — it might not be her usual behaviour.","She is always a very generous person.","She is gradually becoming more generous.","She was generous in the past but is not now."],optionExplanations:{"She is acting generously now — it might not be her usual behaviour.":"Correct! 'Is being' = temporary behaviour — it suggests this is noteworthy or unusual.","She is always a very generous person.":"Wrong. A permanent quality uses 'is': 'She is generous.'","She is gradually becoming more generous.":"Wrong. 'Becoming' would be needed for this meaning.","She was generous in the past but is not now.":"Wrong. 'Is being' is present tense — it refers to current behaviour."}}},{id:"sdv-mc-5",topic:"stative-dynamic-verbs",type:"multiple-choice",difficulty:"intermediate",sentence:"Find the sentence that uses 'taste' INCORRECTLY:",grammarRule:"Stative vs Dynamic 'Taste'",explanation:"'Taste' = has a flavour → stative → Present Simple ('tastes'). 'Taste' = try/sample → dynamic → Present Continuous ('is tasting').",tip:"The soup tastes good (= has flavour). He is tasting the soup (= trying it actively).",multipleChoice:{question:"Which sentence has an error?",correctOption:"This pizza is tasting amazing.",options:["This pizza is tasting amazing.","This pizza tastes amazing.","He is tasting the soup to check the salt.","Can you taste the garlic in this dish?"],optionExplanations:{"This pizza is tasting amazing.":"WRONG! 'Amazing' describes the pizza's flavour — that's stative. Use 'tastes': 'This pizza tastes amazing.'","This pizza tastes amazing.":"Correct. 'Tastes' (= has a flavour) is stative → Present Simple.","He is tasting the soup to check the salt.":"Correct. 'Is tasting' (= trying/sampling) is dynamic → Present Continuous.","Can you taste the garlic in this dish?":"Correct. Asking about sensory perception — stative meaning is fine in question form."}}},{id:"sdv-mc-6",topic:"stative-dynamic-verbs",type:"multiple-choice",difficulty:"intermediate",sentence:"Choose the sentence where 'think' expresses an ACTIVE thought process:",grammarRule:"Stative vs Dynamic 'Think'",explanation:"'Think' = believe/have an opinion → stative → Simple. 'Think' = actively consider → dynamic → Continuous.",tip:"I think it's wrong (= I believe). I'm thinking about it (= I'm considering/processing).",multipleChoice:{question:"Which sentence uses 'think' as an active process (not just an opinion)?",correctOption:"I'm thinking about your proposal right now.",options:["I'm thinking about your proposal right now.","I think she's telling the truth.","He thinks the meeting was a waste of time.","Do you think it will snow tomorrow?"],optionExplanations:{"I'm thinking about your proposal right now.":"Correct! 'Am thinking' = actively considering/processing → dynamic use of 'think'.","I think she's telling the truth.":"Wrong. 'I think' = I believe/have an opinion → stative use.","He thinks the meeting was a waste of time.":"Wrong. 'Thinks' = he has an opinion → stative use.","Do you think it will snow tomorrow?":"Wrong. 'Do you think' = do you believe → stative use."}}},{id:"sdv-mc-7",topic:"stative-dynamic-verbs",type:"multiple-choice",difficulty:"advanced",sentence:"Choose the sentence where 'look' is used as a STATIVE verb (= appears):",grammarRule:"Stative vs Dynamic 'Look'",explanation:"'Look' = appear/seem → stative → Simple. 'Look' = direct one's eyes at → dynamic → Continuous.",tip:"You look great (= you appear). She is looking at the photo (= she is examining it).",multipleChoice:{question:"In which sentence does 'look' mean 'appear' (stative)?",correctOption:"You look tired. Are you okay?",options:["You look tired. Are you okay?","She is looking at some old photographs.","Why are you looking at me like that?","He is looking for his glasses."],optionExplanations:{"You look tired. Are you okay?":"Correct! 'Look' = appear/seem → stative → Present Simple 'look'.","She is looking at some old photographs.":"Wrong. 'Looking at' = examining/directing eyes → dynamic → Present Continuous is correct.","Why are you looking at me like that?":"Wrong. 'Looking at me' = directing eyes at someone → dynamic → Continuous is correct.","He is looking for his glasses.":"Wrong. 'Looking for' = searching → dynamic → Continuous is correct."}}},{id:"sdv-reorder-1",topic:"stative-dynamic-verbs",type:"word-transform",difficulty:"beginner",sentence:"She ___ the answer to every question.",grammarRule:"Stative Verb 'Know' — Present Simple",explanation:"'Know' is stative — it expresses a state of mind (having knowledge). Use Present Simple with -s for third person singular.",tip:"Know is always stative: she knows, he knows, I know — never 'is knowing'.",wordTransform:{baseWord:"know",correctAnswer:"knows"}},{id:"sdv-reorder-2",topic:"stative-dynamic-verbs",type:"word-transform",difficulty:"beginner",sentence:"This coat ___ to my sister.",grammarRule:"Stative Verb 'Belong' — Ownership",explanation:"'Belong' is always stative (ownership). Use Present Simple — add -s for third person singular.",tip:"Belong, own, possess — always stative: the house belongs to them, it owns nothing.",wordTransform:{baseWord:"belong",correctAnswer:"belongs"}},{id:"sdv-reorder-3",topic:"stative-dynamic-verbs",type:"word-transform",difficulty:"intermediate",sentence:"He ___ three cars and a motorbike.",grammarRule:"Stative Verb 'Have' — Possession",explanation:"'Have' = possess/own is stative. Use Present Simple 'has' for third person singular — never 'is having'.",tip:"He has a car (= he owns it) → stative. Compare: He is having lunch (= experiencing an activity) → dynamic.",wordTransform:{baseWord:"have",correctAnswer:"has"}},{id:"sdv-reorder-4",topic:"stative-dynamic-verbs",type:"word-transform",difficulty:"intermediate",sentence:"They ___ a very important meeting right now.",grammarRule:"Dynamic Verb 'Have' — Activity / Experience",explanation:"'Have' = participate in an activity or experience is dynamic. Use Present Continuous 'are having'.",tip:"They are having a meeting / a great time / lunch → dynamic 'have' → always use Present Continuous.",wordTransform:{baseWord:"have",correctAnswer:"are having"}},{id:"sdv-reorder-5",topic:"stative-dynamic-verbs",type:"word-transform",difficulty:"intermediate",sentence:"She ___ about moving to a new city.",grammarRule:"Dynamic Verb 'Think' — Considering",explanation:"'Think' = actively consider or reflect is dynamic. Use Present Continuous 'is thinking'.",tip:"She is thinking about it (= considering). She thinks it's true (= believes). The context tells you which!",wordTransform:{baseWord:"think",correctAnswer:"is thinking"}},{id:"sdv-reorder-6",topic:"stative-dynamic-verbs",type:"word-transform",difficulty:"advanced",sentence:"Stop it! You ___ very selfish right now.",grammarRule:"Dynamic Verb 'Be' — Temporary Behaviour",explanation:"'Be' + adjective in continuous form describes temporary behaviour — how someone is acting right now. It's different from their usual character.",tip:"You are selfish (permanent quality). You are being selfish (= acting selfishly right now — temporary).",wordTransform:{baseWord:"be",correctAnswer:"are being"}}],m={id:"stative-dynamic-verbs",level:"B1",name:"Stative vs Dynamic Verbs",description:"Learn the difference between stative verbs (think, know, have, see, taste, smell, belong) and their dynamic forms. Understand how the same verb can have different meanings — and different grammar — depending on context.",lesson:"Lesson 4",icon:"🧠",cards:[{id:"sdv-card-1",rule:"know, believe, understand: no continuous",example:"My brother ___ (understand) Italian, but he can't speak it.",answer:"understands",explanation:"Stative verbs describe states, not actions: know, believe, understand, remember, want, love. We use them in the present simple, not the continuous. We say I know, never I am knowing.",examples:["I don't remember his name, but I recognise his face.","These shoes cost a lot, but I really love them."],ua:"Це стани, а не дії: «я знаю» — I know. Форми I am knowing не існує."},{id:"sdv-card-2",rule:"belong, own, resemble: no continuous",example:"My aunt ___ (own) a small bakery in Lviv.",answer:"owns",explanation:"Belong, own and resemble describe ownership and appearance. They are stative, so we use the present simple. We say it belongs to me, not it is belonging to me.",examples:["That red car belongs to our neighbours.","My sister resembles our mother, especially her smile."],ua:"own, belong, resemble — стани: Present Simple. «Ця сумка належить Марії» — belongs, не is belonging."},{id:"sdv-card-3",rule:"have = own (stative)",example:"Do your grandparents ___ (have) a house by the sea?",answer:"have",explanation:"When have means own or possess, it is stative. We use the present simple: I have, she has. We do not say I am having a house.",examples:["Our office has three meeting rooms.","Do you have a car?"],ua:"have у значенні «мати, володіти» — стан: She has a car. Не is having a car."},{id:"sdv-card-4",rule:"have = experience (is having)",example:"Can I call you back later? I ___ (have) a shower.",answer:"am having",explanation:"When have means do or experience something, such as a meal, a shower or a party, it is a dynamic verb. We can use the continuous form: I'm having, she is having.",examples:["She is having a coffee break at the moment.","They are having a party on Saturday night."],ua:"have + дія (обід, душ, вечірка) — це дія, тому is having: I'm having lunch."},{id:"sdv-card-5",rule:"think = opinion (simple)",example:"Most of my friends ___ (think) this restaurant is too expensive.",answer:"think",explanation:"When think means believe or have an opinion, it is stative. We use the present simple: I think, she thinks. We do not say I am thinking it is expensive.",examples:["Do you think it will rain tomorrow?","My boss thinks we need a new system."],ua:"think = «вважати, гадати» — стан: I think it's good. Не I'm thinking it's good."},{id:"sdv-card-6",rule:"think = consider (is thinking)",example:"Don't disturb Tom. He ___ (think) hard about a difficult problem.",answer:"is thinking",explanation:"When think means consider or use your mind for a while, it is an action. We can use the continuous: I'm thinking about it. Usually it is followed by about or of.",examples:["I'm thinking of taking a short break from work.","What are you thinking about at the moment?"],ua:"think = «обмірковувати» — дія: I'm thinking about it («я це обмірковую»)."},{id:"sdv-card-7",rule:"see: understand (simple) vs meet (continuous)",example:"Oh, I ___ (see) what you mean. Thanks for explaining!",answer:"see",explanation:"See means understand or notice with your eyes, and then it is stative: I see, can you see? When see means meet by arrangement, it is an action: I'm seeing my accountant on Thursday.",examples:["Can you see the mountains from your window?","I'm seeing my accountant on Thursday morning."],ua:"see = «розуміти, бачити» — стан: I see. see = «зустрічатися» — дія: I'm seeing a friend."},{id:"sdv-card-8",rule:"be vs being",example:"Mark is usually very calm, but today he ___ (be) really impatient with us.",answer:"is being",explanation:"Be + adjective describes a permanent quality: she is kind. Being + adjective describes behaviour at one moment, often unusual: she is being kind today.",examples:["Our teacher is very generous.","Why are you being so quiet today? Is something wrong?"],ua:"is being + прикметник — поведінка саме зараз: He is being rude («він поводиться грубо»)."},{id:"sdv-card-9",rule:"look, taste, smell, sound: simple",example:"This soup ___ (smell) delicious. What did you put in it?",answer:"smells",explanation:"Look, taste, smell and sound describe an impression, so they are stative: it smells good. When we do the action on purpose, they are dynamic: the chef is tasting the sauce.",examples:["That dress looks beautiful on you.","The chef is tasting the sauce before serving it."],ua:"taste/smell/look/sound описують враження: «Суп смачно пахне» — smells, не is smelling."}],rules:u},g=[{id:"pp-gap-1",topic:"possessive-pronouns",type:"gap-fill",difficulty:"beginner",sentence:"This isn't your umbrella. I think it's ___.",grammarRule:"Possessive Pronoun 'Mine'",explanation:"'Mine' replaces 'my' + noun ('my umbrella'). A possessive pronoun stands alone — no noun follows it.",tip:"mine = my + noun. Never put a noun straight after mine.",gapFill:{gapIndex:7,correctAnswer:"mine",options:["mine","my","me","I"],correctOptionIndex:0}},{id:"pp-gap-2",topic:"possessive-pronouns",type:"gap-fill",difficulty:"beginner",sentence:"We left our bags in the car, but Tom and Ana left ___ at the hotel.",grammarRule:"Possessive Pronoun 'Theirs'",explanation:"'Theirs' replaces 'their' + noun ('their bags'). It refers to something belonging to two or more other people.",tip:"theirs = their + noun, used alone to avoid repeating the noun.",gapFill:{gapIndex:12,correctAnswer:"theirs",options:["theirs","their","them","they"],correctOptionIndex:0}},{id:"pp-gap-3",topic:"possessive-pronouns",type:"gap-fill",difficulty:"intermediate",sentence:"I can't find my charger. Can I borrow ___?",grammarRule:"Possessive Pronoun 'Hers'",explanation:"'Hers' replaces 'her' + noun ('her charger'). There is no apostrophe — 'her's' doesn't exist.",tip:"hers = her + noun. Compare: her charger → hers.",gapFill:{gapIndex:8,correctAnswer:"hers",options:["hers","her","she","herself"],correctOptionIndex:0}},{id:"pp-gap-4",topic:"possessive-pronouns",type:"gap-fill",difficulty:"intermediate",sentence:"My sister and I share a flat. ___ is on the third floor.",grammarRule:"Possessive Pronoun 'Ours'",explanation:"'Ours' replaces 'our' + noun ('our flat'). It shows something belongs to the speaker and at least one other person.",tip:"ours = our + noun, used without repeating the noun.",gapFill:{gapIndex:7,correctAnswer:"ours",options:["ours","our","us","we"],correctOptionIndex:0}},{id:"pp-gap-5",topic:"possessive-pronouns",type:"gap-fill",difficulty:"intermediate",sentence:"I found two umbrellas at the office. Is one of them ___?",grammarRule:"Possessive Pronoun 'Yours'",explanation:"'Yours' replaces 'your' + noun ('your umbrella'). It works for one person or several people.",tip:"yours = your + noun. Never say 'yours umbrella'.",gapFill:{gapIndex:11,correctAnswer:"yours",options:["yours","your","you","you're"],correctOptionIndex:0}},{id:"pp-gap-6",topic:"possessive-pronouns",type:"gap-fill",difficulty:"advanced",sentence:"He says this isn't his jacket, but I'm sure it's ___.",grammarRule:"Possessive Pronoun 'His'",explanation:"'His' is unusual: the same word is both the possessive adjective ('his jacket') and the possessive pronoun ('it's his'). The spelling never changes.",tip:"his never changes form — his jacket (adjective) and it's his (pronoun) look identical.",gapFill:{gapIndex:10,correctAnswer:"his",options:["his","him","he's","he"],correctOptionIndex:0}},{id:"pp-error-1",topic:"possessive-pronouns",type:"error-spot",difficulty:"beginner",sentence:"This bag isn't yours, it's my.",grammarRule:"My vs Mine — No Noun After a Pronoun",explanation:"With no noun after it, we need the possessive pronoun 'mine', not the possessive adjective 'my'. 'My' always needs a noun straight after it.",errorSpot:{errorWordIndex:5,wrongWord:"my",correction:"mine",reason:"No noun follows, so use the possessive pronoun: 'This bag isn't yours, it's mine.'",correctionOptions:["mine","my","your","hers"]}},{id:"pp-error-2",topic:"possessive-pronouns",type:"error-spot",difficulty:"beginner",sentence:"Can I borrow your pen? I can't find mine pen.",grammarRule:"My vs Mine — Adjective Needs a Noun",explanation:"A noun ('pen') follows, so we need the possessive adjective 'my', not the possessive pronoun 'mine'. A possessive pronoun is never followed by a noun.",errorSpot:{errorWordIndex:8,wrongWord:"mine",correction:"my",reason:"'Pen' follows, so use the adjective: 'I can't find my pen.'",correctionOptions:["my","mine","your","her"]}},{id:"pp-error-3",topic:"possessive-pronouns",type:"error-spot",difficulty:"intermediate",sentence:"Whose jacket is this? I think it's her.",grammarRule:"Her vs Hers — No Noun After a Pronoun",explanation:"With no noun after it, we need the possessive pronoun 'hers', not the object pronoun 'her'. 'Hers' never changes and never takes an apostrophe.",errorSpot:{errorWordIndex:7,wrongWord:"her",correction:"hers",reason:"No noun follows, so use the possessive pronoun: 'I think it's hers.'",correctionOptions:["hers","her","his","theirs"]}},{id:"pp-error-4",topic:"possessive-pronouns",type:"error-spot",difficulty:"intermediate",sentence:"That car outside is ours car.",grammarRule:"Our vs Ours — Adjective Needs a Noun",explanation:"A noun ('car') follows, so we need the possessive adjective 'our', not the possessive pronoun 'ours'. A possessive pronoun is never followed by a noun.",errorSpot:{errorWordIndex:4,wrongWord:"ours",correction:"our",reason:"'Car' follows, so use the adjective: 'That car outside is our car.'",correctionOptions:["our","ours","their","my"]}},{id:"pp-error-5",topic:"possessive-pronouns",type:"error-spot",difficulty:"intermediate",sentence:"We didn't bring our umbrellas, so we used theirs umbrellas.",grammarRule:"Their vs Theirs — Adjective Needs a Noun",explanation:"A noun ('umbrellas') follows, so we need the possessive adjective 'their', not the possessive pronoun 'theirs'. A possessive pronoun is never followed by a noun.",errorSpot:{errorWordIndex:8,wrongWord:"theirs",correction:"their",reason:"'Umbrellas' follows, so use the adjective: 'We used their umbrellas.'",correctionOptions:["their","theirs","our","his"]}},{id:"pp-error-6",topic:"possessive-pronouns",type:"error-spot",difficulty:"advanced",sentence:"This isn't your seat, it's him.",grammarRule:"His vs Him — Possession, Not Object",explanation:"To show possession with no noun after it, we need the possessive pronoun 'his', not the object pronoun 'him'. 'Him' never shows ownership.",errorSpot:{errorWordIndex:5,wrongWord:"him",correction:"his",reason:"This shows possession, so use the possessive pronoun: 'This isn't your seat, it's his.'",correctionOptions:["his","him","he's","its"]}},{id:"pp-mc-1",topic:"possessive-pronouns",type:"multiple-choice",difficulty:"beginner",sentence:"Choose the sentence that correctly replaces 'my book' with a possessive pronoun.",grammarRule:"Possessive Pronoun 'Mine'",explanation:"'Mine' replaces 'my' + noun and stands completely alone.",tip:"mine on its own, never 'mine' + noun.",multipleChoice:{question:"Which sentence is correct?",correctOption:"This is mine.",options:["This is mine.","This is mine book.","This is my's.","This is me."],optionExplanations:{"This is mine.":"Correct! 'Mine' replaces 'my book' and stands alone, with no noun after it.","This is mine book.":"Wrong. A possessive pronoun is never followed by a noun — just say 'This is mine.'","This is my's.":"Wrong. 'My's' doesn't exist — the possessive pronoun form of 'my' is 'mine'.","This is me.":"Wrong. 'Me' is an object pronoun — it doesn't show ownership."}}},{id:"pp-mc-2",topic:"possessive-pronouns",type:"multiple-choice",difficulty:"beginner",sentence:"Choose the sentence that uses a possessive pronoun correctly.",grammarRule:"Possessive Pronoun 'Hers'",explanation:"'Hers' replaces 'her' + noun and stands completely alone, with no apostrophe.",tip:"hers has no apostrophe and no noun after it.",multipleChoice:{question:"Which sentence is correct?",correctOption:"That jacket is hers.",options:["That jacket is hers.","That jacket is her.","That jacket is hers jacket.","That jacket is she."],optionExplanations:{"That jacket is hers.":"Correct! 'Hers' replaces 'her jacket' and stands alone.","That jacket is her.":"Wrong. 'Her' is an object pronoun here — the possessive pronoun is 'hers'.","That jacket is hers jacket.":"Wrong. A possessive pronoun is never followed by a noun.","That jacket is she.":"Wrong. 'She' is a subject pronoun — it cannot show possession."}}},{id:"pp-mc-3",topic:"possessive-pronouns",type:"multiple-choice",difficulty:"intermediate",sentence:"Choose the best way to complete this short dialogue.",grammarRule:"Whose + Possessive Pronoun",explanation:"We answer a 'Whose...?' question with a possessive pronoun on its own — here, 'mine'.",tip:"Whose is this? → It's mine / yours / his / hers / ours / theirs.",multipleChoice:{question:"A: Whose umbrella is this? B: ___",correctOption:"It's mine.",options:["It's mine.","It's my.","It's me.","It's I."],optionExplanations:{"It's mine.":"Correct! 'Mine' answers a 'whose' question and needs no noun after it.","It's my.":"Wrong. 'My' is a possessive adjective — it always needs a noun after it.","It's me.":"Wrong. 'Me' is an object pronoun — it doesn't show ownership.","It's I.":"Wrong. 'I' is a subject pronoun — it doesn't show ownership."}}},{id:"pp-mc-4",topic:"possessive-pronouns",type:"multiple-choice",difficulty:"intermediate",sentence:"Choose the grammatically correct sentence.",grammarRule:"Our vs Ours",explanation:"'Our' is a possessive adjective and always needs a noun after it, like 'flat'. 'Ours' is a possessive pronoun and never takes a noun or an apostrophe.",tip:"our + noun (our flat). ours alone, no noun, no apostrophe.",multipleChoice:{question:"Which sentence is correct?",correctOption:"Our flat is lovely.",options:["Our flat is lovely.","Ours flat is lovely.","Our's flat is lovely.","Our flat is ours lovely."],optionExplanations:{"Our flat is lovely.":"Correct! 'Our' (possessive adjective) + noun 'flat'.","Ours flat is lovely.":"Wrong. 'Ours' is a possessive pronoun — it can never be followed by a noun like 'flat'.","Our's flat is lovely.":"Wrong. 'Our's' doesn't exist — there is no apostrophe form of 'our'.","Our flat is ours lovely.":"Wrong. 'Ours' cannot sit in front of another word like 'lovely' — remove it."}}},{id:"pp-mc-5",topic:"possessive-pronouns",type:"multiple-choice",difficulty:"intermediate",sentence:"Choose the sentence with the correct possessive form.",grammarRule:"Possessive 'Its' vs Contraction 'It's'",explanation:"'Its' (no apostrophe) shows possession. 'It's' (with an apostrophe) is short for 'it is' or 'it has' — a different word entirely.",tip:"its = possession, no apostrophe. it's = it is / it has, with an apostrophe.",multipleChoice:{question:"Which sentence is correct?",correctOption:"The company increased its profits.",options:["The company increased its profits.","The company increased it's profits.","The company increased its' profits.","The company increased theirs profits."],optionExplanations:{"The company increased its profits.":"Correct! 'Its' (no apostrophe) shows the company's own profits.","The company increased it's profits.":"Wrong. 'It's' means 'it is' — that makes no sense here. Use 'its' with no apostrophe.","The company increased its' profits.":"Wrong. There is no form 'its'' with an apostrophe after the s.","The company increased theirs profits.":"Wrong. 'Theirs' is a possessive pronoun — it can never be followed by a noun like 'profits'."}}},{id:"pp-mc-6",topic:"possessive-pronouns",type:"multiple-choice",difficulty:"intermediate",sentence:"Choose the correct reply to this question.",grammarRule:"Possessive Pronoun 'Mine'",explanation:"'Mine' stands alone after 'not' with no noun and no extra pronoun.",tip:"it's not mine — short, no noun, no extra word after mine.",multipleChoice:{question:"A: Is this bag yours? B: ___",correctOption:"No, it's not mine.",options:["No, it's not mine.","No, it's not my.","No, it isn't my bag mine.","No, it's not me."],optionExplanations:{"No, it's not mine.":"Correct! 'Mine' replaces 'my bag' and needs nothing after it.","No, it's not my.":"Wrong. 'My' is a possessive adjective — it always needs a noun after it.","No, it isn't my bag mine.":"Wrong. Using both 'my bag' and 'mine' together is incorrect — pick one.","No, it's not me.":"Wrong. 'Me' is an object pronoun — it doesn't show ownership."}}},{id:"pp-mc-7",topic:"possessive-pronouns",type:"multiple-choice",difficulty:"advanced",sentence:"Choose the grammatically correct sentence.",grammarRule:"Possessive Pronoun 'Theirs'",explanation:"'Theirs' is the possessive pronoun form of 'their'. It never takes an apostrophe and is never followed by a noun.",tip:"theirs — no apostrophe, no noun after it.",multipleChoice:{question:"Which sentence is correct?",correctOption:"This isn't our car — it's theirs.",options:["This isn't our car — it's theirs.","This isn't our car — it's their's.","This isn't our car — it's their.","This isn't our car — it's theirs car."],optionExplanations:{"This isn't our car — it's theirs.":"Correct! 'Theirs' replaces 'their car' and stands alone.","This isn't our car — it's their's.":"Wrong. 'Their's' doesn't exist — the possessive pronoun is simply 'theirs'.","This isn't our car — it's their.":"Wrong. 'Their' is a possessive adjective — it always needs a noun after it.","This isn't our car — it's theirs car.":"Wrong. A possessive pronoun is never followed by a noun."}}},{id:"pp-wt-1",topic:"possessive-pronouns",type:"word-transform",difficulty:"beginner",sentence:"This umbrella isn't yours, it's ___.",grammarRule:"Possessive Pronoun 'Mine'",explanation:"'Mine' is the possessive pronoun that matches 'I' — it replaces 'my' + noun.",tip:"I → my (adjective) → mine (pronoun, no noun after it).",wordTransform:{baseWord:"I",correctAnswer:"mine"}},{id:"pp-wt-2",topic:"possessive-pronouns",type:"word-transform",difficulty:"beginner",sentence:"That dog isn't our dog. It's ___.",grammarRule:"Possessive Pronoun 'Theirs'",explanation:"'Theirs' is the possessive pronoun that matches 'they' — it replaces 'their' + noun.",tip:"they → their (adjective) → theirs (pronoun, no noun after it).",wordTransform:{baseWord:"they",correctAnswer:"theirs"}},{id:"pp-wt-3",topic:"possessive-pronouns",type:"word-transform",difficulty:"intermediate",sentence:"I like your idea, but I prefer ___.",grammarRule:"Possessive Pronoun 'Ours'",explanation:"'Ours' is the possessive pronoun that matches 'we' — it replaces 'our' + noun.",tip:"we → our (adjective) → ours (pronoun, no noun after it).",wordTransform:{baseWord:"we",correctAnswer:"ours"}},{id:"pp-wt-4",topic:"possessive-pronouns",type:"word-transform",difficulty:"intermediate",sentence:"He found a wallet. He thinks it's ___.",grammarRule:"Possessive Pronoun 'Hers'",explanation:"'Hers' is the possessive pronoun that matches 'she' — it replaces 'her' + noun, with no apostrophe.",tip:"she → her (adjective) → hers (pronoun, no apostrophe).",wordTransform:{baseWord:"she",correctAnswer:"hers"}},{id:"pp-wt-5",topic:"possessive-pronouns",type:"word-transform",difficulty:"intermediate",sentence:"This seat is taken. I think it's ___.",grammarRule:"Possessive Pronoun 'His'",explanation:"'His' is the possessive pronoun that matches 'he' — unlike other pronouns, it has the same form as the possessive adjective.",tip:"he → his (adjective) → his (pronoun — same spelling).",wordTransform:{baseWord:"he",correctAnswer:"his"}},{id:"pp-wt-6",topic:"possessive-pronouns",type:"word-transform",difficulty:"advanced",sentence:"We don't have keys like that. Those must be ___.",grammarRule:"Possessive Pronoun 'Yours'",explanation:"'Yours' is the possessive pronoun that matches 'you' — it replaces 'your' + noun, for one person or several.",tip:"you → your (adjective) → yours (pronoun, singular or plural 'you').",wordTransform:{baseWord:"you",correctAnswer:"yours"}}],f={id:"possessive-pronouns",level:"A2+",name:"Possessive Pronouns",description:"Practise possessive pronouns — mine, yours, his, hers, ours and theirs — and the rule that they stand alone, never followed by a noun, unlike my, your, his, her, our and their.",lesson:"Lesson 5A",icon:"👜",cards:[{id:"pp-card-1",rule:"mine = my + noun (no noun after the pronoun)",example:"This isn't your coat — it's ___ (I).",answer:"mine",explanation:"'Mine' replaces 'my' + noun. A possessive pronoun stands alone — we never put a noun straight after it.",examples:["I can't find my keys. Have you seen mine?","The red bike is mine, not my brother's."],ua:"mine = «мій/моя/моє», але без іменника після: my coat → mine. Не можна сказати «mine coat» — іменник після займенника не ставимо."},{id:"pp-card-2",rule:"yours = your + noun",example:"I left my umbrella at home. Can I borrow ___ (you)?",answer:"yours",explanation:"'Yours' replaces 'your' + noun ('your umbrella'). It works the same way for one person or several people.",examples:["Is this pen yours?","Our garden is small, but yours is huge!"],ua:"yours = «твій/твоя/твоє» або «ваш/ваша/ваше», без іменника: your umbrella → yours."},{id:"pp-card-3",rule:"his — same word for adjective and pronoun",example:"That's not my phone — I think it's ___ (he).",answer:"his",explanation:"'His' is unusual: it is both the possessive adjective ('his phone') and the possessive pronoun ('it's his'). The spelling never changes.",examples:["His car is the blue one.","This jacket isn't mine — it's his."],ua:"his — єдина форма і для прикметника (his phone — «його телефон»), і для займенника (it's his — «це його»). Форма не змінюється."},{id:"pp-card-4",rule:"hers = her + noun",example:"This scarf isn't mine. I think it's ___ (she).",answer:"hers",explanation:"'Hers' replaces 'her' + noun ('her scarf'). There is never an apostrophe — 'her's' doesn't exist.",examples:["That umbrella is hers, not mine.","I like your bag more than hers."],ua:"hers = «її», без іменника: her scarf → hers. Апострофа немає: не «her's», а hers."},{id:"pp-card-5",rule:"ours = our + noun",example:"Your flat is on the second floor. ___ (we) is on the fifth.",answer:"ours",explanation:"'Ours' replaces 'our' + noun ('our flat'). It refers to something belonging to the speaker and at least one other person.",examples:["This table is ours, not theirs.","Their garden is bigger than ours."],ua:"ours = «наш/наша/наше», без іменника: our flat → ours."},{id:"pp-card-6",rule:"theirs = their + noun",example:"We brought our own chairs. They brought ___ (they) too.",answer:"theirs",explanation:"'Theirs' replaces 'their' + noun ('their chairs'). It refers to something belonging to two or more other people.",examples:["Our team lost, but theirs won.","Is that suitcase theirs?"],ua:"theirs = «їхній/їхня/їхнє», без іменника: their chairs → theirs."},{id:"pp-card-7",rule:"its vs it's — no apostrophe in the possessive",example:"The company increased ___ (it) profits this year.",answer:"its",explanation:"'Its' (no apostrophe) shows possession — the profits belonging to the company. 'It's' (with an apostrophe) is short for 'it is' or 'it has' — a completely different word.",examples:["The dog wagged its tail.","It's going to rain later."],ua:"its (без апострофа) — присвійна форма «його/її» про предмет: its tail. it's (з апострофом) = it is / it has — зовсім інше слово."}],rules:g},y=[{id:"qty-gap-1",topic:"quantifiers",type:"gap-fill",difficulty:"beginner",sentence:"Would you like ___ tea?",grammarRule:"Some in Offers and Requests",explanation:"We often use 'some' instead of 'any' in questions that are offers or polite requests: 'Would you like some tea?'",tip:"Offers and requests use 'some': Would you like some water? Could I have some help?",gapFill:{gapIndex:3,correctAnswer:"some",options:["some","any","no","many"],correctOptionIndex:0}},{id:"qty-gap-2",topic:"quantifiers",type:"gap-fill",difficulty:"beginner",sentence:"Do you have ___ brothers or sisters?",grammarRule:"Any in Ordinary Questions",explanation:"In most ordinary questions we use 'any', not 'some', to ask whether something exists.",tip:"Ordinary questions use 'any': Do you have any pets? Is there any milk?",gapFill:{gapIndex:3,correctAnswer:"any",options:["any","some","no","much"],correctOptionIndex:0}},{id:"qty-gap-3",topic:"quantifiers",type:"gap-fill",difficulty:"intermediate",sentence:"There's ___ milk left in the fridge — we need to buy more.",grammarRule:"No = Not Any (Positive Verb)",explanation:"'No' + noun means 'not any'. It goes with a positive verb, not a negative one: 'There's no milk', NOT 'There isn't no milk'.",tip:"no + positive verb = not any: There's no milk = There isn't any milk.",gapFill:{gapIndex:1,correctAnswer:"no",options:["no","not","any","some"],correctOptionIndex:0}},{id:"qty-gap-4",topic:"quantifiers",type:"gap-fill",difficulty:"intermediate",sentence:"How ___ time do we have before the train leaves?",grammarRule:"Much With Uncountable Nouns",explanation:"'Time' is uncountable, so we ask about it with 'much': 'How much time...?'",tip:"How much + uncountable: how much time, how much money, how much water.",gapFill:{gapIndex:1,correctAnswer:"much",options:["much","many","a lot","no"],correctOptionIndex:0}},{id:"qty-gap-5",topic:"quantifiers",type:"gap-fill",difficulty:"intermediate",sentence:"There aren't ___ seats left — only five or six.",grammarRule:"Many With Countable Nouns",explanation:"'Seats' is countable, so we use 'many' to talk about the amount: 'There aren't many seats left.'",tip:"many + countable plural: many seats, many people, many days.",gapFill:{gapIndex:2,correctAnswer:"many",options:["many","much","no","any"],correctOptionIndex:0}},{id:"qty-gap-6",topic:"quantifiers",type:"gap-fill",difficulty:"advanced",sentence:"I can't concentrate — there are ___ distractions in this office.",grammarRule:"Too Many With Countable Nouns",explanation:"'Distractions' is countable, and there's a problem (can't concentrate), so we use 'too many': 'too many distractions'.",tip:"too many + countable (problem): too many distractions, too many emails, too many mistakes.",gapFill:{gapIndex:6,correctAnswer:"too many",options:["too many","too much","a lot","enough"],correctOptionIndex:0}},{id:"qty-error-1",topic:"quantifiers",type:"error-spot",difficulty:"beginner",sentence:"I don't have no time to explain this now.",grammarRule:"No Double Negatives — Any After a Negative Verb",explanation:"English doesn't use double negatives. After a negative verb ('don't have'), use 'any', not 'no'.",errorSpot:{errorWordIndex:3,wrongWord:"no",correction:"any",reason:"After a negative verb, use 'any': 'I don't have any time to explain this now.'",correctionOptions:["any","no","some","much"]}},{id:"qty-error-2",topic:"quantifiers",type:"error-spot",difficulty:"beginner",sentence:"There are no information about the flight.",grammarRule:"Singular Verb With Uncountable Nouns",explanation:"'Information' is uncountable, so it always takes a singular verb, even with 'no': 'There is no information.'",errorSpot:{errorWordIndex:1,wrongWord:"are",correction:"is",reason:"Uncountable nouns take a singular verb: 'There is no information about the flight.'",correctionOptions:["is","are","was","have"]}},{id:"qty-error-3",topic:"quantifiers",type:"error-spot",difficulty:"intermediate",sentence:"I don't have much friends in this city.",grammarRule:"Many With Countable Nouns",explanation:"'Friends' is countable, so use 'many', not 'much'. 'Much' is only for uncountable nouns.",errorSpot:{errorWordIndex:3,wrongWord:"much",correction:"many",reason:"'Friends' is countable, so the correct quantifier is 'many': 'I don't have many friends in this city.'",correctionOptions:["many","much","a lot","no"]}},{id:"qty-error-4",topic:"quantifiers",type:"error-spot",difficulty:"intermediate",sentence:"I don't have lot of money saved for the trip.",grammarRule:"A Lot Of — Needs 'A' Before 'Lot'",explanation:"'Lot of' isn't a phrase on its own. It must be 'a lot of' (with 'a') or 'lots of' (without 'a').",errorSpot:{errorWordIndex:3,wrongWord:"lot",correction:"a lot",reason:"Add 'a' before 'lot': 'I don't have a lot of money saved for the trip.'",correctionOptions:["a lot","lot","many","much"]}},{id:"qty-error-5",topic:"quantifiers",type:"error-spot",difficulty:"intermediate",sentence:"There are too much people at this party.",grammarRule:"Too Many With Countable Nouns",explanation:"'People' is countable, so we use 'too many', not 'too much', to describe a problem amount.",errorSpot:{errorWordIndex:3,wrongWord:"much",correction:"many",reason:"'People' is countable, so use 'too many': 'There are too many people at this party.'",correctionOptions:["many","much","a lot","no"]}},{id:"qty-error-6",topic:"quantifiers",type:"error-spot",difficulty:"advanced",sentence:"I need a little advices before the interview.",grammarRule:"Advice Is Uncountable — No Plural Form",explanation:"'Advice' is an uncountable noun — it has no plural form. Use 'some advice' or 'a little advice', never 'advices'.",errorSpot:{errorWordIndex:4,wrongWord:"advices",correction:"advice",reason:"'Advice' has no plural form: 'I need a little advice before the interview.'",correctionOptions:["advice","advices","advice's","a advice"]}},{id:"qty-mc-1",topic:"quantifiers",type:"multiple-choice",difficulty:"beginner",sentence:"Choose the sentence that makes a polite offer using 'some'.",grammarRule:"Some in Offers and Requests",explanation:"We can use 'some' in questions that are offers, even though 'any' is usual in most other questions.",tip:"Offers use 'some': Would you like some coffee?",multipleChoice:{question:"Which sentence is a polite offer?",correctOption:"Would you like some coffee?",options:["Would you like some coffee?","Would you like any coffee?","Have you got no coffee?","Do you have many coffee?"],optionExplanations:{"Would you like some coffee?":"Correct! 'Some' is natural in offers, even though it's a question.","Would you like any coffee?":"Wrong. 'Any' sounds unnatural in a friendly offer — use 'some' instead.","Have you got no coffee?":"Wrong. This asks if coffee is missing, not an offer.","Do you have many coffee?":"Wrong. 'Coffee' is uncountable here, and 'many' needs a countable noun — plus this isn't an offer."}}},{id:"qty-mc-2",topic:"quantifiers",type:"multiple-choice",difficulty:"beginner",sentence:"Choose the sentence that correctly uses a quantifier with an uncountable noun.",grammarRule:"Much With Uncountable Nouns",explanation:"'Time' is uncountable, so we use 'much', not 'many', especially in negatives and questions.",tip:"much + uncountable: much time, much money, much water.",multipleChoice:{question:"Which sentence is correct?",correctOption:"I don't have much time today.",options:["I don't have much time today.","I don't have many time today.","I don't have a lot time today.","I don't have few time today."],optionExplanations:{"I don't have much time today.":"Correct! 'Time' is uncountable, so 'much' is right.","I don't have many time today.":"Wrong. 'Many' is only for countable nouns — 'time' is uncountable.","I don't have a lot time today.":"Wrong. It must be 'a lot OF time', with 'of'.","I don't have few time today.":"Wrong. 'Few' is used with countable nouns, not uncountable ones like 'time'."}}},{id:"qty-mc-3",topic:"quantifiers",type:"multiple-choice",difficulty:"intermediate",sentence:"Choose the sentence that correctly uses a quantifier with a countable noun.",grammarRule:"Many With Countable Nouns",explanation:"'Apples' is countable and plural, so we ask 'how many', not 'how much'.",tip:"How many + countable plural: how many apples, how many people.",multipleChoice:{question:"Which sentence is correct?",correctOption:"How many apples do we need?",options:["How many apples do we need?","How much apples do we need?","How many apple do we need?","How much of apples do we need?"],optionExplanations:{"How many apples do we need?":"Correct! 'Apples' is countable and plural, so 'many' is right.","How much apples do we need?":"Wrong. 'Much' is for uncountable nouns — 'apples' is countable.","How many apple do we need?":"Wrong. After 'many', a countable noun must be plural: 'apples', not 'apple'.","How much of apples do we need?":"Wrong. 'Much of' isn't used like this before a plural countable noun."}}},{id:"qty-mc-4",topic:"quantifiers",type:"multiple-choice",difficulty:"intermediate",sentence:"Choose the sentence that correctly describes a problem amount.",grammarRule:"Too Much With Uncountable Nouns",explanation:"'Traffic' is uncountable, so a problem amount of it is 'too much traffic'.",tip:"too much + uncountable (problem): too much traffic, too much noise, too much work.",multipleChoice:{question:"Which sentence describes a problem correctly?",correctOption:"There's too much traffic this morning.",options:["There's too much traffic this morning.","There's too many traffic this morning.","There are too much traffic this morning.","There's too much traffics this morning."],optionExplanations:{"There's too much traffic this morning.":"Correct! 'Traffic' is uncountable, so 'too much' and the singular verb 'There's' are both right.","There's too many traffic this morning.":"Wrong. 'Traffic' is uncountable, so it needs 'too much', not 'too many'.","There are too much traffic this morning.":"Wrong. 'Traffic' is uncountable and singular, so it needs 'There's', not 'There are'.","There's too much traffics this morning.":"Wrong. 'Traffic' is uncountable — it has no plural form 'traffics'."}}},{id:"qty-mc-5",topic:"quantifiers",type:"multiple-choice",difficulty:"intermediate",sentence:"Choose the sentence that correctly uses 'enough'.",grammarRule:"Enough Before a Noun",explanation:"'Enough' meaning 'the right amount' goes directly before the noun it describes: 'enough chairs'.",tip:"enough + noun = the right amount: enough chairs, enough time, enough money.",multipleChoice:{question:"Which sentence uses 'enough' correctly?",correctOption:"We don't have enough chairs for everyone.",options:["We don't have enough chairs for everyone.","We don't have chairs enough for everyone.","We don't have much enough chairs for everyone.","We don't have a enough chairs for everyone."],optionExplanations:{"We don't have enough chairs for everyone.":"Correct! 'Enough' goes directly before the noun 'chairs'.","We don't have chairs enough for everyone.":"Wrong. Before a noun, 'enough' must come before it, not after: 'enough chairs'.","We don't have much enough chairs for everyone.":"Wrong. We don't combine 'much' and 'enough' together like this.","We don't have a enough chairs for everyone.":"Wrong. 'Enough' never takes 'a' in front of it."}}},{id:"qty-mc-6",topic:"quantifiers",type:"multiple-choice",difficulty:"intermediate",sentence:"Choose the sentence that correctly uses 'a little'.",grammarRule:"A Little With Uncountable Nouns",explanation:"'A little' (a small amount) is used with uncountable nouns like 'help'. For plural countable nouns, we use 'a few' instead.",tip:"a little + uncountable: a little help, a little time. a few + countable plural: a few people.",multipleChoice:{question:"Which sentence uses 'a little' correctly?",correctOption:"I need a little help with this form.",options:["I need a little help with this form.","I need a little helps with this form.","I need a little people to help me.","I need a little forms filled in."],optionExplanations:{"I need a little help with this form.":"Correct! 'Help' is uncountable, so 'a little' is right.","I need a little helps with this form.":"Wrong. 'Help' is uncountable and has no plural form 'helps'.","I need a little people to help me.":"Wrong. 'People' is countable and plural — use 'a few people', not 'a little people'.","I need a little forms filled in.":"Wrong. 'Forms' is countable and plural — 'a little' doesn't combine with plural countable nouns."}}},{id:"qty-mc-7",topic:"quantifiers",type:"multiple-choice",difficulty:"advanced",sentence:"Choose the sentence that correctly talks about something in general.",grammarRule:"No Quantifier for General Statements",explanation:"When we speak about something in general, we use no article and no quantifier before the uncountable or plural noun.",tip:"General statements: no article, no quantifier — Fashion isn't important to me. People are interesting.",multipleChoice:{question:"Which sentence correctly talks about something in general?",correctOption:"Fashion isn't very important to me.",options:["Fashion isn't very important to me.","The fashion isn't very important to me.","Some fashion isn't very important to me.","A fashion isn't very important to me."],optionExplanations:{"Fashion isn't very important to me.":"Correct! Speaking about fashion in general needs no article and no quantifier.","The fashion isn't very important to me.":"Wrong. 'The' makes it sound like one specific, already-mentioned fashion, not fashion in general.","Some fashion isn't very important to me.":"Wrong. 'Some' suggests a specific, unspecified amount of fashion, not the general idea.","A fashion isn't very important to me.":"Wrong. 'Fashion' is uncountable here, so it can't take 'a'."}}},{id:"qty-wt-1",topic:"quantifiers",type:"word-transform",difficulty:"beginner",sentence:"Could you give me ___ advice about buying a car?",grammarRule:"Some in Polite Requests",explanation:"Even in a question, 'some' is used here because it's a polite request, not an ordinary question.",tip:"Requests use 'some': Could I have some water? Could you give me some advice?",wordTransform:{baseWord:"some/any",correctAnswer:"some"}},{id:"qty-wt-2",topic:"quantifiers",type:"word-transform",difficulty:"beginner",sentence:"There's ___ parking near the office, so we should take the bus.",grammarRule:"No = Not Any (Positive Verb)",explanation:"'No' goes with a positive verb and means the same as 'not any'. We don't combine 'no' with a negative verb.",tip:"no + positive verb = not any: There's no parking = There isn't any parking.",wordTransform:{baseWord:"no/not",correctAnswer:"no"}},{id:"qty-wt-3",topic:"quantifiers",type:"word-transform",difficulty:"intermediate",sentence:"We didn't make ___ mistakes in the test.",grammarRule:"Many With Countable Nouns",explanation:"'Mistakes' is countable (plural), so we use 'many', not 'much'.",tip:"many + countable plural: many mistakes, many friends, many days.",wordTransform:{baseWord:"much/many",correctAnswer:"many"}},{id:"qty-wt-4",topic:"quantifiers",type:"word-transform",difficulty:"intermediate",sentence:"She's stressed because she has ___ work this month.",grammarRule:"Too Much With Uncountable Nouns",explanation:"'Work' is uncountable, so we use 'too much' to mean more than is comfortable or necessary.",tip:"too much + uncountable: too much work, too much stress, too much noise.",wordTransform:{baseWord:"too much/too many",correctAnswer:"too much"}},{id:"qty-wt-5",topic:"quantifiers",type:"word-transform",difficulty:"intermediate",sentence:"Can I have ___ sugar in my coffee, please?",grammarRule:"A Little With Uncountable Nouns",explanation:"'A little' (or 'a bit of') shows a small amount of an uncountable noun like 'sugar'.",tip:"a little / a bit of + uncountable: a little sugar, a bit of time.",wordTransform:{baseWord:"a bit of/a little",correctAnswer:"a little"}},{id:"qty-wt-6",topic:"quantifiers",type:"word-transform",difficulty:"advanced",sentence:"I only had $20, so I didn't have ___ money to buy the tickets.",grammarRule:"Enough — The Right Amount Needed",explanation:"'Enough' means the amount needed for a particular purpose — here, buying the tickets.",tip:"enough + noun = the right amount for a purpose: enough money, enough time, enough space.",wordTransform:{baseWord:"enough/much",correctAnswer:"enough"}}],w={id:"quantifiers",level:"A2+",name:"Quantifiers",description:"Practise some, any, no, much, many, a lot of, too much/too many, enough and a little — the words we use to talk about amounts of countable and uncountable nouns.",lesson:"Lesson 5B",icon:"🧮",cards:[{id:"qty-card-1",rule:"some in positive sentences, offers and requests",example:"There's ___ cake left in the kitchen — help yourself!",answer:"some",explanation:"We use 'some' in positive sentences when we don't say the exact amount. It also sounds natural in offers and requests, even though they're questions.",examples:["I bought some bread and some cheese at the shop.","Could I have some water, please?"],ua:"some = «трохи, якась кількість» (не точна): There's some cake — «Є трохи торта». Також у пропозиціях: Would you like some tea? — «Хочеш чаю?»"},{id:"qty-card-2",rule:"any in questions and negatives",example:"I don't have ___ cash on me right now.",answer:"any",explanation:"We use 'any' in negative sentences to say something doesn't exist, and in most questions to ask if it exists.",examples:["Is there any sugar in the cupboard?","We didn't see any dolphins on the boat trip."],ua:"any вживаємо в питаннях і заперечних реченнях: Do you have any cash? — «У тебе є готівка?» I don't have any cash — «У мене немає готівки»."},{id:"qty-card-3",rule:"no = not any (with a positive verb)",example:"There's ___ sugar in the jar — it's completely empty.",answer:"no",explanation:"'No' + noun means the same as 'not any', but it goes with a positive verb, not a negative one.",examples:["There's no bread left — we ate it all.","He has no free time this week."],ua:"no = «ніякий, зовсім немає», але дієслово ставимо у стверджувальній формі: There's no sugar = There isn't any sugar."},{id:"qty-card-4",rule:"a lot of / lots of — a large amount",example:"She's got ___ (a lot of / lots of) experience in this job.",answer:"a lot of",explanation:"'A lot of' and 'lots of' both mean a large amount. They work with countable and uncountable nouns, in positive, negative and question sentences.",examples:["We spent a lot of money on the trip.","There are lots of good restaurants in this area."],ua:"a lot of / lots of = «багато» (велика кількість), підходять і до злічуваних, і до незлічуваних іменників: a lot of money, a lot of people."},{id:"qty-card-5",rule:"much with uncountable nouns, many with countable nouns",example:"How ___ (much / many) luggage have you got?",answer:"much",explanation:"'Much' goes with uncountable nouns (like 'luggage'), and 'many' goes with countable plural nouns (like 'bags'). Both are common in questions and negatives.",examples:["I haven't got much money left.","There aren't many buses after 10 p.m."],ua:"much — з незлічуваними (much luggage), many — зі злічуваними у множині (many bags). Частіше в питаннях і запереченнях."},{id:"qty-card-6",rule:"too much / too many — more than necessary (a problem)",example:"There was ___ (too much / too many) noise at the concert — I couldn't hear anything.",answer:"too much",explanation:"'Too much' (uncountable) and 'too many' (countable) show that an amount is a problem — more than is good or necessary.",examples:["I ate too much cake and now I feel sick.","There were too many people in the small room."],ua:"too much (незлічувані) / too many (злічувані) = «забагато», коли кількість — проблема: too much noise, too many people."},{id:"qty-card-7",rule:"enough — the right amount, before the noun",example:"We haven't got ___ chairs for all the guests.",answer:"enough",explanation:"'Enough' means the right or necessary amount. Before a noun, it goes directly in front of it: 'enough chairs'.",examples:["Have we got enough food for the party?","There isn't enough time to finish today."],ua:"enough = «достатньо», ставимо прямо перед іменником: enough chairs — «достатньо стільців»."},{id:"qty-card-8",rule:"a bit of / a little — a small amount",example:"I only need ___ (a bit of / a little) help with my homework.",answer:"a little",explanation:"'A bit of' and 'a little' both mean a small amount. They are used with uncountable nouns, like 'help', 'time' or 'money'.",examples:["Could you give me a little more time?","There's a bit of milk left in the bottle."],ua:"a bit of / a little = «трохи» (невелика кількість), тільки з незлічуваними іменниками: a little time, a bit of milk."}],rules:y},v=[{id:"mra-gap-1",topic:"modals-rules-advice",type:"gap-fill",difficulty:"beginner",sentence:"You ___ drink and drive. It's extremely dangerous and against the law.",grammarRule:"'mustn't' — Prohibition (Forbidden)",explanation:"'Mustn't' means something is forbidden — there is no choice at all. 'Don't have to' or 'needn't' would mean the opposite: it isn't necessary, but you still could.",tip:"mustn't = forbidden, no choice. don't have to / needn't = not necessary, but still allowed.",gapFill:{gapIndex:1,correctAnswer:"mustn't",options:["mustn't","don't have to","needn't","shouldn't"],correctOptionIndex:0}},{id:"mra-gap-2",topic:"modals-rules-advice",type:"gap-fill",difficulty:"beginner",sentence:"You ___ pay to enter the museum on Sundays - it's free for everyone.",grammarRule:"'don't have to' — No Obligation (Optional)",explanation:"'Don't have to' means something isn't necessary — you have a choice. 'Mustn't' would mean entering is forbidden, which changes the meaning completely.",tip:"don't have to = optional, your choice. mustn't = forbidden, no choice.",gapFill:{gapIndex:1,correctAnswer:"don't have to",options:["don't have to","mustn't","shouldn't","can't"],correctOptionIndex:0}},{id:"mra-gap-3",topic:"modals-rules-advice",type:"gap-fill",difficulty:"intermediate",sentence:"I ___ wear a uniform at work. It's the company's rule, not my choice.",grammarRule:"'have to' — External Obligation (Someone Else's Rule)",explanation:"'Have to' expresses an obligation that comes from outside — a rule made by someone else, like an employer or the law.",tip:"have to = someone else's rule. must = my own decision or feeling.",gapFill:{gapIndex:1,correctAnswer:"have to",options:["have to","don't have to","shouldn't","needn't"],correctOptionIndex:0}},{id:"mra-gap-4",topic:"modals-rules-advice",type:"gap-fill",difficulty:"intermediate",sentence:"I ___ call my mum tonight - I promised her I would.",grammarRule:"'must' — Personal Obligation (Speaker's Own Feeling)",explanation:"'Must' expresses something the speaker feels is important or necessary themselves — a personal obligation, not an outside rule.",tip:"must = I think it's necessary. have to = a rule says it's necessary.",gapFill:{gapIndex:1,correctAnswer:"must",options:["must","mustn't","needn't","shouldn't"],correctOptionIndex:0}},{id:"mra-gap-5",topic:"modals-rules-advice",type:"gap-fill",difficulty:"intermediate",sentence:"You ___ try the new Italian restaurant on Main Street - the food is amazing.",grammarRule:"'should' — Giving Advice",explanation:"'Should' gives friendly advice or a recommendation — it's a good idea, but it isn't an obligation.",tip:"should = good idea (advice). must / have to = necessary (obligation).",gapFill:{gapIndex:1,correctAnswer:"should",options:["should","shouldn't","must","mustn't"],correctOptionIndex:0}},{id:"mra-gap-6",topic:"modals-rules-advice",type:"gap-fill",difficulty:"advanced",sentence:"You ___ bring any food to the picnic - we've already bought enough for everyone.",grammarRule:"'needn't' — Not Necessary",explanation:"'Needn't' means it isn't necessary — the same meaning as 'don't have to', though a little more formal.",tip:"needn't = don't have to (not necessary). Both are the opposite of must / have to.",gapFill:{gapIndex:1,correctAnswer:"needn't",options:["needn't","mustn't","shouldn't","can't"],correctOptionIndex:0}},{id:"mra-error-1",topic:"modals-rules-advice",type:"error-spot",difficulty:"beginner",sentence:"She must leaves now because the meeting starts in five minutes.",grammarRule:"Modal 'must' + Bare Infinitive",explanation:"Modals like 'must' are always followed by the base form of the verb — never add -s, even for he/she/it.",errorSpot:{errorWordIndex:2,wrongWord:"leaves",correction:"leave",reason:"After 'must', use the base form: 'must leave', not 'must leaves'.",correctionOptions:["leave","leaves","leaving","to leave"]}},{id:"mra-error-2",topic:"modals-rules-advice",type:"error-spot",difficulty:"beginner",sentence:"He doesn't has to work on Saturdays this month.",grammarRule:"'have to' — Negative Form (doesn't have to)",explanation:"In negative sentences with 'have to', the auxiliary 'doesn't' already carries the -s, so the main verb returns to its base form.",errorSpot:{errorWordIndex:2,wrongWord:"has",correction:"have",reason:"'Doesn't' already has the -s, so use the base form: 'doesn't have to', not 'doesn't has to'.",correctionOptions:["have","has","having","had"]}},{id:"mra-error-3",topic:"modals-rules-advice",type:"error-spot",difficulty:"intermediate",sentence:"You mustn't worrying about the exam. You have prepared really well.",grammarRule:"Modal 'mustn't' + Bare Infinitive",explanation:"Modals are always followed by the base form of the verb, never the -ing form.",errorSpot:{errorWordIndex:2,wrongWord:"worrying",correction:"worry",reason:"After 'mustn't', use the base form: 'mustn't worry', not 'mustn't worrying'.",correctionOptions:["worry","worrying","worries","to worry"]}},{id:"mra-error-4",topic:"modals-rules-advice",type:"error-spot",difficulty:"intermediate",sentence:"We needn't buying tickets in advance - we can pay at the door.",grammarRule:"Modal 'needn't' + Bare Infinitive",explanation:"'Needn't' is a modal verb, so it's followed by the base form of the verb.",errorSpot:{errorWordIndex:2,wrongWord:"buying",correction:"buy",reason:"After 'needn't', use the base form: 'needn't buy', not 'needn't buying'.",correctionOptions:["buy","buying","bought","to buy"]}},{id:"mra-error-5",topic:"modals-rules-advice",type:"error-spot",difficulty:"intermediate",sentence:"She should calls her landlord about the broken heater.",grammarRule:"Modal 'should' + Bare Infinitive",explanation:"After 'should', use the base form of the verb, not the third person -s form.",errorSpot:{errorWordIndex:2,wrongWord:"calls",correction:"call",reason:"After 'should', use the base form: 'should call', not 'should calls'.",correctionOptions:["call","calls","calling","to call"]}},{id:"mra-error-6",topic:"modals-rules-advice",type:"error-spot",difficulty:"advanced",sentence:"Does she has to finish the project by Monday?",grammarRule:"'have to' — Question Form (Does ... have to)",explanation:"In questions with 'have to', the auxiliary 'does' already carries the -s, so 'have' stays in its base form.",errorSpot:{errorWordIndex:2,wrongWord:"has",correction:"have",reason:"'Does' already has the -s, so use the base form: 'Does she have to...?', not 'Does she has to...?'",correctionOptions:["have","has","having","had"]}},{id:"mra-mc-1",topic:"modals-rules-advice",type:"multiple-choice",difficulty:"beginner",sentence:"Choose the sentence that means something is forbidden:",grammarRule:"'mustn't' — Prohibition",explanation:"'Mustn't' means something is not allowed at all — there is no choice.",tip:"mustn't = forbidden. don't have to / needn't = not necessary, but still allowed.",multipleChoice:{question:"Which sentence means it is not allowed?",correctOption:"You mustn't park here - it's a fire exit.",options:["You mustn't park here - it's a fire exit.","You don't have to park here - there's space elsewhere.","You needn't park here.","You shouldn't park here, but you can if you want."],optionExplanations:{"You mustn't park here - it's a fire exit.":"Correct! 'Mustn't' means it's forbidden - there is no choice.","You don't have to park here - there's space elsewhere.":"Wrong. This means parking here isn't necessary, not that it's forbidden.","You needn't park here.":"Wrong. This means parking here isn't necessary, not that it's forbidden.","You shouldn't park here, but you can if you want.":"Wrong. This is just advice against it, not a strict prohibition."}}},{id:"mra-mc-2",topic:"modals-rules-advice",type:"multiple-choice",difficulty:"beginner",sentence:"Choose the sentence where the obligation comes from an outside rule, not the speaker's own feeling:",grammarRule:"'have to' vs 'must' — External vs Personal Obligation",explanation:"'Have to' describes rules made by someone else, like a law or an employer. 'Must' usually describes something the speaker personally feels is necessary.",tip:"have to = someone else's rule. must = my own decision or feeling.",multipleChoice:{question:"Which sentence describes an obligation set by someone else?",correctOption:"Employees have to wear safety helmets on the building site.",options:["Employees have to wear safety helmets on the building site.","I must remember to water my plants - I always forget.","You should drink more water every day.","We needn't finish the whole project today."],optionExplanations:{"Employees have to wear safety helmets on the building site.":"Correct! This is a workplace safety rule, not the speaker's own feeling - 'have to' fits.","I must remember to water my plants - I always forget.":"Wrong. This is the speaker's own personal reminder, which fits 'must', not an outside rule.","You should drink more water every day.":"Wrong. This is advice, not an obligation at all.","We needn't finish the whole project today.":"Wrong. This expresses a lack of necessity, not an obligation."}}},{id:"mra-mc-3",topic:"modals-rules-advice",type:"multiple-choice",difficulty:"intermediate",sentence:"Choose the sentence that means 'it isn't necessary, but you can if you want':",grammarRule:"'don't have to' — Lack of Obligation (not mustn't)",explanation:"'Don't have to' means something is not necessary, but it's still allowed — the choice is yours. It is NOT the same as 'mustn't', which means forbidden.",tip:"don't have to = optional. mustn't = forbidden. Never confuse them!",multipleChoice:{question:"Which sentence expresses a lack of obligation, not a prohibition?",correctOption:"You don't have to answer every question - just do your best.",options:["You don't have to answer every question - just do your best.","You mustn't answer every question.","You shouldn't answer every question.","You can't answer every question."],optionExplanations:{"You don't have to answer every question - just do your best.":"Correct! This means answering every question isn't necessary, but it's still allowed.","You mustn't answer every question.":"Wrong. This means answering every question is forbidden, which is a much stronger, different meaning.","You shouldn't answer every question.":"Wrong. This is advice against doing it, not a statement about necessity.","You can't answer every question.":"Wrong. This means it isn't possible, not that it's unnecessary."}}},{id:"mra-mc-4",topic:"modals-rules-advice",type:"multiple-choice",difficulty:"intermediate",sentence:"Which sentence has almost the same meaning as 'You don't have to pay now'?",grammarRule:"'needn't' = 'don't have to'",explanation:"'Needn't' and 'don't have to' both mean something is not necessary. 'Needn't' sounds a little more formal.",tip:"needn't ≈ don't have to (not necessary). Different from mustn't (forbidden).",multipleChoice:{question:"Choose the sentence with the same meaning.",correctOption:"You needn't pay now.",options:["You needn't pay now.","You mustn't pay now.","You shouldn't pay now.","You can't pay now."],optionExplanations:{"You needn't pay now.":"Correct! 'Needn't' means it's not necessary, just like 'don't have to'.","You mustn't pay now.":"Wrong. This means paying now is forbidden - the opposite kind of meaning.","You shouldn't pay now.":"Wrong. This is advice against paying now, not a statement about necessity.","You can't pay now.":"Wrong. This means it isn't possible to pay now."}}},{id:"mra-mc-5",topic:"modals-rules-advice",type:"multiple-choice",difficulty:"intermediate",sentence:"A friend asks what to do about a headache. Choose the sentence that gives ADVICE, not an obligation:",grammarRule:"'should' — Advice, Not Obligation",explanation:"'Should' gives a recommendation or opinion — it's a good idea, but the person is still free to ignore it. 'Must'/'have to'/'need to' suggest something much stronger or compulsory.",tip:"should = friendly advice. must / have to = obligation, no choice.",multipleChoice:{question:"Which sentence is advice, not a strict rule?",correctOption:"You should take a painkiller and rest for a while.",options:["You should take a painkiller and rest for a while.","You must take a painkiller right now.","You have to see a doctor immediately.","You need to call an ambulance."],optionExplanations:{"You should take a painkiller and rest for a while.":"Correct! 'Should' gives a gentle recommendation, not a strict rule.","You must take a painkiller right now.":"Wrong. 'Must' sounds like a strong personal obligation, far stronger than friendly advice.","You have to see a doctor immediately.":"Wrong. 'Have to' sounds like an obligation, not a suggestion.","You need to call an ambulance.":"Wrong. 'Need to' expresses necessity, which is much stronger than advice."}}},{id:"mra-mc-6",topic:"modals-rules-advice",type:"multiple-choice",difficulty:"intermediate",sentence:"Choose the sentence that gives advice against doing something, rather than a strict prohibition:",grammarRule:"'shouldn't' vs 'mustn't' — Advice Against vs Forbidden",explanation:"'Shouldn't' means it's not a good idea — advice, not a rule. 'Mustn't' means it's forbidden; there is no choice.",tip:"shouldn't = bad idea (advice). mustn't = forbidden (no choice).",multipleChoice:{question:"Which sentence is advice against something, rather than a prohibition?",correctOption:"You shouldn't eat so much junk food - it's not good for you.",options:["You shouldn't eat so much junk food - it's not good for you.","You mustn't eat in the exam room.","You can't eat in the library.","You don't have to eat if you're not hungry."],optionExplanations:{"You shouldn't eat so much junk food - it's not good for you.":"Correct! 'Shouldn't' is advice against something - it's a bad idea, but still your choice.","You mustn't eat in the exam room.":"Wrong. 'Mustn't' means eating is forbidden there - a strict rule, not advice.","You can't eat in the library.":"Wrong. 'Can't' here means it's not permitted/possible, like a rule.","You don't have to eat if you're not hungry.":"Wrong. This expresses a lack of necessity, not advice against something."}}},{id:"mra-mc-7",topic:"modals-rules-advice",type:"multiple-choice",difficulty:"advanced",sentence:"Choose the sentence that correctly says that something IS necessary:",grammarRule:"'need to' vs 'needn't' — Necessity vs No Necessity",explanation:"'Need to' expresses necessity, similar to 'have to'. 'Needn't' (with an added -n't) means the opposite — not necessary — so the two are easy to confuse.",tip:"need to = necessary. needn't = NOT necessary. One suffix apart, opposite meanings!",multipleChoice:{question:"Which sentence correctly says that something is necessary?",correctOption:"You need to renew your passport before it expires.",options:["You need to renew your passport before it expires.","You needn't renew your passport before it expires.","You mustn't renew your passport before it expires.","You shouldn't renew your passport before it expires."],optionExplanations:{"You need to renew your passport before it expires.":"Correct! 'Need to' expresses necessity - you must do this.","You needn't renew your passport before it expires.":"Wrong. 'Needn't' means the opposite - it's not necessary.","You mustn't renew your passport before it expires.":"Wrong. This would mean renewing it is forbidden, which makes no sense here.","You shouldn't renew your passport before it expires.":"Wrong. This would mean renewing it is a bad idea, which also makes no sense here."}}},{id:"mra-wt-1",topic:"modals-rules-advice",type:"word-transform",difficulty:"beginner",sentence:"She ___ to finish her homework before dinner every day.",grammarRule:"'have to' — Third Person Present",explanation:"'Have to' behaves like an ordinary verb grammatically — add -s for he/she/it in the present simple: 'has to'.",tip:"have to → has to for he/she/it. Real modals (must, should) never add -s.",wordTransform:{baseWord:"have",correctAnswer:"has"}},{id:"mra-wt-2",topic:"modals-rules-advice",type:"word-transform",difficulty:"beginner",sentence:"He ___ to see a doctor about his back.",grammarRule:"'need to' — Third Person Present",explanation:"'Need to' also behaves like an ordinary verb — add -s for he/she/it: 'needs to'.",tip:"need to → needs to for he/she/it, just like have to → has to.",wordTransform:{baseWord:"need",correctAnswer:"needs"}},{id:"mra-wt-3",topic:"modals-rules-advice",type:"word-transform",difficulty:"intermediate",sentence:"We ___ to wait two hours at the airport yesterday because of a delay.",grammarRule:"'have to' — Past Simple (had to)",explanation:"'Must' has no past form, so 'had to' is used to express obligation in the past.",tip:"must → had to in the past. There is no 'musted'!",wordTransform:{baseWord:"have",correctAnswer:"had"}},{id:"mra-wt-4",topic:"modals-rules-advice",type:"word-transform",difficulty:"intermediate",sentence:"You ___ to show your passport at the border tomorrow.",grammarRule:"'have to' — Future (will have to)",explanation:"For future obligation, use 'will have to'. You cannot combine 'will' with 'must' in this way.",tip:"Future obligation → will have to, never 'will must'.",wordTransform:{baseWord:"have",correctAnswer:"will have"}},{id:"mra-wt-5",topic:"modals-rules-advice",type:"word-transform",difficulty:"intermediate",sentence:"I ___ to work this weekend. My boss said I can take the days off.",grammarRule:"'have to' — Negative (No Obligation)",explanation:"'Don't have to' means something isn't necessary — you have a choice. It is not the same as 'mustn't', which means forbidden.",tip:"don't have to = optional, your choice. mustn't = forbidden, no choice.",wordTransform:{baseWord:"have",correctAnswer:"don't have"}},{id:"mra-wt-6",topic:"modals-rules-advice",type:"word-transform",difficulty:"advanced",sentence:"You ___ worry about the interview. You're well prepared.",grammarRule:"'need to' — Negative (No Necessity)",explanation:"'Don't need to' and 'needn't' both mean something isn't necessary. Both forms are correct, though 'needn't' is a little more formal.",tip:"don't need to = needn't = not necessary. Never confuse with mustn't (forbidden).",wordTransform:{baseWord:"need",correctAnswer:"don't need to",alternativeAnswers:["needn't"]}}],b={id:"modals-rules-advice",level:"B1",name:"Modals for Rules and Advice",description:"Learn how to use must, mustn't, have to, don't have to, need to, needn't, should and shouldn't to talk about obligation, prohibition, necessity and advice.",lesson:"Lesson 4A",icon:"🚦",cards:[{id:"mra-card-1",rule:"must — strong obligation (what I think is necessary)",example:"I ___ finish this project tonight - I promised my boss.",answer:"must",explanation:"Must expresses something the speaker feels is necessary or important themselves, not a rule made by someone else. It often sounds more personal and urgent than have to.",examples:["I must remember to call the dentist today.","You must try this cake - it's amazing!"],ua:"must — особисте відчуття обов'язку: «я мушу», не зовнішнє правило."},{id:"mra-card-2",rule:"mustn't — prohibition (not allowed)",example:"You ___ touch that wire - it's extremely dangerous.",answer:"mustn't",explanation:"Mustn't means something is forbidden or not allowed at all - there is no choice. It is very different from don't have to, which means something is simply not necessary.",examples:["Passengers mustn't open the doors while the train is moving.","You mustn't tell anyone my secret."],ua:"mustn't — заборонено: «не можна», а не просто «не обов'язково»."},{id:"mra-card-3",rule:"have to — obligation from outside (a rule, not your choice)",example:"In this office, staff ___ clock in before nine.",answer:"have to",explanation:"Have to describes an obligation that comes from somewhere else - a law, a workplace, a school. It feels less personal than must, which usually expresses the speaker's own opinion.",examples:["In Japan, you have to take your shoes off before entering a house.","Drivers have to stop at a red light."],ua:"have to — обов'язок ззовні (закон, правило), не особиста думка."},{id:"mra-card-4",rule:"don't have to — no obligation (it's your choice)",example:"You ___ wear a suit to the interview - smart casual is fine.",answer:"don't have to",explanation:"Don't have to means something isn't necessary, but you're still allowed to do it if you want. This is completely different from mustn't, which means it isn't allowed at all.",examples:["You don't have to come to the party if you're tired.","She doesn't have to work on Fridays this semester."],ua:"don't have to — не обов'язково (можна, якщо хочеш), на відміну від mustn't."},{id:"mra-card-5",rule:"need to — necessity (similar to have to)",example:"We ___ leave soon if we want to catch the train.",answer:"need to",explanation:"Need to expresses necessity, very similarly to have to. It can describe obligations from outside or things the speaker feels are important.",examples:["I need to buy some milk on the way home.","Does she need to sign the form today?"],ua:"need to ≈ have to — потрібно, необхідно."},{id:"mra-card-6",rule:"needn't / don't need to — not necessary",example:"You ___ bring an umbrella - the forecast says it won't rain.",answer:"needn't",explanation:"Needn't and don't need to both mean something isn't necessary. They have almost the same meaning as don't have to.",examples:["You needn't apologise - it wasn't your fault.","We don't need to hurry; we have plenty of time."],ua:"needn't ≈ don't need to ≈ don't have to — не обов'язково."},{id:"mra-card-7",rule:"should — giving advice (a good idea)",example:"You ___ drink more water in this hot weather.",answer:"should",explanation:"Should gives advice or a recommendation. It suggests something is a good idea, but the person is free to decide for themselves.",examples:["You should see a dentist about that tooth.","We should leave earlier next time to avoid the traffic."],ua:"should — порада, гарна ідея, але не обов'язок."},{id:"mra-card-8",rule:"shouldn't — advice against (not a good idea)",example:"You ___ stay up so late before an exam.",answer:"shouldn't",explanation:"Shouldn't means something is not a good idea - it's advice against doing it. It's much weaker than mustn't, which means something is forbidden.",examples:["You shouldn't believe everything you read online.","He shouldn't drive if he's that tired."],ua:"shouldn't — погана ідея (порада), а не заборона, як mustn't."}],rules:v},x=[{id:"art-gap-1",topic:"articles",type:"gap-fill",difficulty:"beginner",sentence:"She showed us ___ amazing invention she'd built in her garage.",grammarRule:"A/An — First Mention (New Information)",explanation:"When something is mentioned for the first time, use a/an — the listener doesn't know which one yet. 'Amazing' starts with a vowel sound, so we use 'an'.",tip:"New information = a/an. Next word starts with a vowel sound = an, consonant sound = a.",gapFill:{gapIndex:3,correctAnswer:"an",options:["an","a","the","–"],correctOptionIndex:0}},{id:"art-gap-2",topic:"articles",type:"gap-fill",difficulty:"beginner",sentence:"My cousin is ___ nurse at the city hospital.",grammarRule:"A/An — Jobs and Professions",explanation:"We use a/an before a job or profession. 'Nurse' starts with a consonant sound, so we use 'a'.",tip:"Jobs always take a/an: a teacher, an engineer, a nurse.",gapFill:{gapIndex:3,correctAnswer:"a",options:["a","an","the","–"],correctOptionIndex:0}},{id:"art-gap-3",topic:"articles",type:"gap-fill",difficulty:"intermediate",sentence:"I ordered a coffee and a sandwich, but ___ sandwich was cold when it arrived.",grammarRule:"The — Something Already Mentioned",explanation:"'Sandwich' was already mentioned, so both speaker and listener know exactly which one is meant — use 'the'.",tip:"Second mention of the same thing = the.",gapFill:{gapIndex:8,correctAnswer:"the",options:["the","a","an","–"],correctOptionIndex:0}},{id:"art-gap-4",topic:"articles",type:"gap-fill",difficulty:"intermediate",sentence:"Out of all the runners in the race, she was ___ fastest by far.",grammarRule:"The — Superlatives",explanation:"Superlative adjectives (fastest, biggest, best) are always preceded by 'the' because they describe something unique in its group.",tip:"Superlative adjective → always 'the': the best, the tallest, the most expensive.",gapFill:{gapIndex:10,correctAnswer:"the",options:["the","a","an","–"],correctOptionIndex:0}},{id:"art-gap-5",topic:"articles",type:"gap-fill",difficulty:"intermediate",sentence:"In general, ___ smartphones are far more powerful than computers were twenty years ago.",grammarRule:"No Article — General Statements (Plural Nouns)",explanation:"When we talk about things in general, not specific ones, we use no article at all with plural nouns: 'smartphones' here means smartphones in general.",tip:"Talking generally about a whole group = no article: Dogs are loyal. Computers are useful.",gapFill:{gapIndex:2,correctAnswer:"–",options:["–","the","a","some"],correctOptionIndex:0}},{id:"art-gap-6",topic:"articles",type:"gap-fill",difficulty:"advanced",sentence:"He's always been good at ___ basketball, even though he's quite short.",grammarRule:"No Article — Names of Sports",explanation:"Names of sports and games never take an article: we play basketball, football, chess — not 'the basketball'.",tip:"Sports and games = no article: play tennis, like football, enjoy chess.",gapFill:{gapIndex:5,correctAnswer:"–",options:["–","the","a","an"],correctOptionIndex:0}},{id:"art-error-1",topic:"articles",type:"error-spot",difficulty:"beginner",sentence:"I need to buy a umbrella before it starts raining.",grammarRule:"A vs An — Vowel Sounds",explanation:"Use 'an' before a word that starts with a vowel sound. 'Umbrella' starts with a vowel sound, so it needs 'an', not 'a'.",errorSpot:{errorWordIndex:4,wrongWord:"a",correction:"an",reason:"'Umbrella' starts with a vowel sound, so it needs 'an': 'I need to buy an umbrella.'",correctionOptions:["an","a","the","some"]}},{id:"art-error-2",topic:"articles",type:"error-spot",difficulty:"beginner",sentence:"I bought a new bike last month but a bike broke down yesterday.",grammarRule:"The — Something Already Mentioned",explanation:"'Bike' was already mentioned, so the speaker and listener both know which one is meant — use 'the', not 'a', for the second mention.",errorSpot:{errorWordIndex:8,wrongWord:"a",correction:"the",reason:"The bike has already been mentioned, so we use 'the': 'but the bike broke down yesterday.'",correctionOptions:["the","a","an","this"]}},{id:"art-error-3",topic:"articles",type:"error-spot",difficulty:"intermediate",sentence:"Everyone agreed that she was a best candidate for the job.",grammarRule:"The — Superlatives",explanation:"Superlatives like 'best' always take 'the', because they describe something unique in its group.",errorSpot:{errorWordIndex:5,wrongWord:"a",correction:"the",reason:"'Best' is a superlative, so it always takes 'the': 'she was the best candidate.'",correctionOptions:["the","a","some","this"]}},{id:"art-error-4",topic:"articles",type:"error-spot",difficulty:"intermediate",sentence:"They're planning a trip along a River Nile next summer.",grammarRule:"The — Rivers, Oceans and Seas",explanation:"Rivers, oceans and seas always take 'the': the River Nile, the Pacific Ocean, the Atlantic.",errorSpot:{errorWordIndex:5,wrongWord:"a",correction:"the",reason:"Rivers always take 'the': 'a trip along the River Nile.'",correctionOptions:["the","a","an","that"]}},{id:"art-error-5",topic:"articles",type:"error-spot",difficulty:"intermediate",sentence:"Her sister just qualified as the dentist after years of study.",grammarRule:"A/An — Jobs and Professions",explanation:"Jobs take 'a/an', not 'the', unless we're already talking about one specific person's job that has been mentioned before.",errorSpot:{errorWordIndex:5,wrongWord:"the",correction:"a",reason:"A job mentioned for the first time takes 'a/an': 'she qualified as a dentist.'",correctionOptions:["a","the","an","some"]}},{id:"art-error-6",topic:"articles",type:"error-spot",difficulty:"advanced",sentence:"She is a only person in the office who can speak Japanese.",grammarRule:"The — Defining Expressions (the only, the first)",explanation:"'Only' is a defining expression — like superlatives, it always takes 'the': the only, the first, the last.",errorSpot:{errorWordIndex:2,wrongWord:"a",correction:"the",reason:"'Only' always takes 'the': 'She is the only person in the office who can speak Japanese.'",correctionOptions:["the","a","an","some"]}},{id:"art-mc-1",topic:"articles",type:"multiple-choice",difficulty:"beginner",sentence:"Choose the sentence that uses the article correctly:",grammarRule:"The — Things There's Only One Of",explanation:"There's only one sun, so we always say 'the sun' — just like 'the sky', 'the internet' or 'the moon', things that are unique.",tip:"Only one in the whole world/situation = the: the sun, the sky, the internet.",multipleChoice:{question:"Which sentence is correct?",correctOption:"The sun was shining brightly all afternoon.",options:["The sun was shining brightly all afternoon.","A sun was shining brightly all afternoon.","Sun was shining brightly all afternoon.","An sun was shining brightly all afternoon."],optionExplanations:{"The sun was shining brightly all afternoon.":"Correct! There's only one sun, so it always takes 'the'.","A sun was shining brightly all afternoon.":"Wrong. 'Sun' is unique — it can't be 'a sun', as if there were several.","Sun was shining brightly all afternoon.":"Wrong. A unique thing like the sun can't appear with no article at all.","An sun was shining brightly all afternoon.":"Wrong. 'Sun' starts with a consonant sound, and in any case unique things take 'the', not 'an'."}}},{id:"art-mc-2",topic:"articles",type:"multiple-choice",difficulty:"beginner",sentence:"Choose the sentence with the correct article (or no article):",grammarRule:"No Article vs The — Country Names",explanation:"Most country names take no article (she lives in France), but names made of several words or plural forms need 'the': the United Kingdom, the United States, the Netherlands.",tip:"Most countries = no article. Names with 'Kingdom/States/Republic' or plural endings = the.",multipleChoice:{question:"Which sentence is correct?",correctOption:"She has lived in the United Kingdom for ten years.",options:["She has lived in the United Kingdom for ten years.","She has lived in United Kingdom for ten years.","She has lived in a United Kingdom for ten years.","She has lived in United the Kingdom for ten years."],optionExplanations:{"She has lived in the United Kingdom for ten years.":"Correct! Country names with extra words like 'Kingdom' take 'the'.","She has lived in United Kingdom for ten years.":"Wrong. This multi-word country name needs 'the': 'the United Kingdom'.","She has lived in a United Kingdom for ten years.":"Wrong. There's only one United Kingdom — it can't take 'a'.","She has lived in United the Kingdom for ten years.":"Wrong. 'The' goes before the whole name: 'the United Kingdom'."}}},{id:"art-mc-3",topic:"articles",type:"multiple-choice",difficulty:"intermediate",sentence:"Choose the sentence that uses the article correctly:",grammarRule:"The — Rivers, Oceans and Seas",explanation:"Oceans, seas and rivers always take 'the': the Atlantic Ocean, the Mediterranean Sea, the River Thames.",tip:"Seas, oceans, rivers = always the.",multipleChoice:{question:"Which sentence is correct?",correctOption:"Cargo ships cross the Atlantic Ocean every day.",options:["Cargo ships cross the Atlantic Ocean every day.","Cargo ships cross Atlantic Ocean every day.","Cargo ships cross a Atlantic Ocean every day.","Cargo ships cross an Atlantic Ocean every day."],optionExplanations:{"Cargo ships cross the Atlantic Ocean every day.":"Correct! Oceans always take 'the'.","Cargo ships cross Atlantic Ocean every day.":"Wrong. Oceans can't appear with no article at all.","Cargo ships cross a Atlantic Ocean every day.":"Wrong. There's only one Atlantic Ocean — it needs 'the', not 'a'.","Cargo ships cross an Atlantic Ocean every day.":"Wrong. There's only one Atlantic Ocean — it needs 'the', not 'an'."}}},{id:"art-mc-4",topic:"articles",type:"multiple-choice",difficulty:"intermediate",sentence:"Choose the sentence that uses the article correctly:",grammarRule:"The — Areas of a Country",explanation:"We use 'the' before an area or region of a country: the south of France, the north of England, the west coast of Italy.",tip:"A region/area within a place = the: the south of Spain, the north of the country.",multipleChoice:{question:"Which sentence is correct?",correctOption:"They own a small vineyard in the south of France.",options:["They own a small vineyard in the south of France.","They own a small vineyard in south of France.","They own a small vineyard in a south of France.","They own a small vineyard in south of a France."],optionExplanations:{"They own a small vineyard in the south of France.":"Correct! An area of a country takes 'the': 'the south of France'.","They own a small vineyard in south of France.":"Wrong. 'South of France' needs 'the' before it.","They own a small vineyard in a south of France.":"Wrong. Areas like this take 'the', not 'a'.","They own a small vineyard in south of a France.":"Wrong. Country names like 'France' take no article at all."}}},{id:"art-mc-5",topic:"articles",type:"multiple-choice",difficulty:"intermediate",sentence:"Choose the sentence that uses articles correctly:",grammarRule:"No Article — Prepositional Phrases",explanation:"Some fixed phrases with prepositions never take an article: for lunch, at work, on foot, at home, by car.",tip:"Fixed phrases like at work, for lunch, on foot never take an article.",multipleChoice:{question:"Which sentence is correct?",correctOption:"I usually have a sandwich for lunch and walk to work on foot.",options:["I usually have a sandwich for lunch and walk to work on foot.","I usually have a sandwich for the lunch and walk to the work on the foot.","I usually have a sandwich for a lunch and walk to a work on a foot.","I usually have a sandwich for the lunch and walk to work on a foot."],optionExplanations:{"I usually have a sandwich for lunch and walk to work on foot.":"Correct! 'For lunch', 'to work' and 'on foot' are fixed phrases with no article.","I usually have a sandwich for the lunch and walk to the work on the foot.":"Wrong. None of these fixed phrases take 'the'.","I usually have a sandwich for a lunch and walk to a work on a foot.":"Wrong. None of these fixed phrases take 'a'.","I usually have a sandwich for the lunch and walk to work on a foot.":"Wrong. 'For lunch' and 'on foot' take no article at all."}}},{id:"art-mc-6",topic:"articles",type:"multiple-choice",difficulty:"intermediate",sentence:"Choose the sentence someone would actually say out loud:",grammarRule:"The — Dates in Spoken English",explanation:"When we say dates aloud, we use 'the' before the ordinal number: the fifth of June, the first of May.",tip:"Spoken dates = the + ordinal number: the third of April.",multipleChoice:{question:"Which sentence is correct?",correctOption:"My birthday is on the fifth of June.",options:["My birthday is on the fifth of June.","My birthday is on fifth of June.","My birthday is on a fifth of June.","My birthday is on fifth of the June."],optionExplanations:{"My birthday is on the fifth of June.":"Correct! Spoken dates use 'the' before the ordinal number.","My birthday is on fifth of June.":"Wrong. Missing 'the' before 'fifth'.","My birthday is on a fifth of June.":"Wrong. There's only one fifth of June each year — it needs 'the', not 'a'.","My birthday is on fifth of the June.":"Wrong. 'The' goes before the ordinal number ('the fifth'), not before the month name."}}},{id:"art-mc-7",topic:"articles",type:"multiple-choice",difficulty:"advanced",sentence:"Choose the sentence that uses the article correctly:",grammarRule:"The — Defining Expressions (the only, the first)",explanation:"Defining expressions such as 'the first', 'the last' and 'the only' always take 'the', because they point to one specific, unique thing.",tip:"the first / the last / the only — always the, never a/an.",multipleChoice:{question:"Which sentence is correct?",correctOption:"She was the first woman to climb that mountain alone.",options:["She was the first woman to climb that mountain alone.","She was a first woman to climb that mountain alone.","She was first woman to climb that mountain alone.","She was an first woman to climb that mountain alone."],optionExplanations:{"She was the first woman to climb that mountain alone.":"Correct! 'The first' is a defining expression — it always takes 'the'.","She was a first woman to climb that mountain alone.":"Wrong. 'First' in this sense always takes 'the', not 'a'.","She was first woman to climb that mountain alone.":"Wrong. 'First' used this way can't appear with no article.","She was an first woman to climb that mountain alone.":"Wrong. 'First' always takes 'the' here, not 'an'."}}},{id:"art-wt-1",topic:"articles",type:"word-transform",difficulty:"beginner",sentence:"There was ___ strange noise coming from the car engine, and nobody knew what it was.",grammarRule:"A/An — First Mention (New Information)",explanation:"This is the first time the noise is mentioned, and nobody knows what's causing it — use 'a', not 'the'.",tip:"New, unknown thing mentioned for the first time = a/an.",wordTransform:{baseWord:"a/the",correctAnswer:"a"}},{id:"art-wt-2",topic:"articles",type:"word-transform",difficulty:"beginner",sentence:"My brother-in-law works as ___ electrician for a company in town.",grammarRule:"A/An — Jobs and Professions",explanation:"'Electrician' starts with a vowel sound, so the job needs 'an', not 'a'.",tip:"Jobs always take a/an — choose by the sound of the next word.",wordTransform:{baseWord:"a/an",correctAnswer:"an"}},{id:"art-wt-3",topic:"articles",type:"word-transform",difficulty:"intermediate",sentence:"We finally found the café we'd read about, and ___ coffee there was fantastic.",grammarRule:"The — Something Already Mentioned",explanation:"The café (and its coffee) has already been mentioned, so we know exactly which one — use 'the'.",tip:"Already mentioned/known = the.",wordTransform:{baseWord:"the/a",correctAnswer:"the"}},{id:"art-wt-4",topic:"articles",type:"word-transform",difficulty:"intermediate",sentence:"Of all her paintings, this landscape is ___ most famous.",grammarRule:"The — Superlatives",explanation:"Superlatives (most famous, best, tallest) always take 'the'.",tip:"Superlative adjective → the.",wordTransform:{baseWord:"the/a",correctAnswer:"the"}},{id:"art-wt-5",topic:"articles",type:"word-transform",difficulty:"intermediate",sentence:"Their boat finally reached ___ Pacific Ocean after three weeks at sea.",grammarRule:"The — Rivers, Oceans and Seas",explanation:"Oceans, seas and rivers always take 'the': the Pacific Ocean, the Nile.",tip:"Seas/oceans/rivers = always the.",wordTransform:{baseWord:"the/a",correctAnswer:"the"}},{id:"art-wt-6",topic:"articles",type:"word-transform",difficulty:"advanced",sentence:"Out of the whole team, Maria was ___ only person who finished the marathon.",grammarRule:"The — Defining Expressions (the only, the first)",explanation:"Defining expressions like 'the only' and 'the first' always take 'the'.",tip:"the only / the first / the last = always the.",wordTransform:{baseWord:"the/a",correctAnswer:"the"}}],k={id:"articles",level:"B1",name:"Articles",description:"Learn when to use a/an, the, or no article at all — with famous 'firsts', jobs, geography and everyday general statements.",lesson:"Lesson 4B",icon:"🔤",cards:[{id:"art-card-1",rule:"a/an — introducing something new",example:"I just adopted ___ energetic puppy from the shelter.",answer:"an",explanation:"Use a/an the first time you mention something, before the listener knows which one. 'Energetic' starts with a vowel sound, so we use 'an'.",examples:["She bought a new laptop yesterday.","He works as an architect in Kyiv."],ua:"a/an — коли щось згадуємо вперше: an перед голосним звуком, a — перед приголосним."},{id:"art-card-2",rule:"a/an — jobs and professions",example:"My father is ___ accountant for a big company.",answer:"an",explanation:"We always use a/an before a job title. 'Accountant' starts with a vowel sound, so it takes 'an'.",examples:["She's a dentist.","He wants to become an engineer."],ua:"Професії завжди з a/an: a teacher, an actor."},{id:"art-card-3",rule:"the — already mentioned",example:"We watched a documentary last night, and ___ documentary was really moving.",answer:"the",explanation:"Once something has been mentioned, both speaker and listener know exactly which one is meant — so we switch to 'the'.",examples:["I read a magazine on the train. The magazine was about space.","There's a car outside. The car is blocking our drive."],ua:"the — коли вже знаємо, про що йдеться (згадувалося раніше)."},{id:"art-card-4",rule:"the — superlatives",example:"This is ___ biggest shopping centre in the country.",answer:"the",explanation:"Superlative adjectives (biggest, best, most expensive) describe something unique in its group, so they always take 'the'.",examples:["He's the tallest player on the team.","That was the worst film I've ever seen."],ua:"Найвищий ступінь порівняння завжди з the: the biggest, the best."},{id:"art-card-5",rule:"the — seas, oceans and rivers",example:"Thousands of boats cross ___ English Channel every year.",answer:"the",explanation:"Seas, oceans and rivers always take 'the', even though most place names don't: the English Channel, the River Danube, the Pacific.",examples:["They sailed across the Atlantic Ocean.","The River Thames flows through London."],ua:"Моря, океани й річки завжди з the: the Pacific, the Danube."},{id:"art-card-6",rule:"the vs no article — specific time vs general place",example:"We spent ___ whole afternoon walking around town without any plan.",answer:"the",explanation:"Use 'the' for one specific instance, like 'the whole afternoon' (that particular afternoon). But we say 'around town' with no article when we mean the general idea of being in town, not one specific place.",examples:["I grew up in a small town.","She walked around town all day without a map."],ua:"the whole afternoon — конкретний момент; around town (без артикля) — загальне поняття."},{id:"art-card-7",rule:"the — defining expressions",example:"He was ___ last guest to leave the party.",answer:"the",explanation:"Defining expressions like 'the only', 'the first' and 'the last' always take 'the', because they point to one specific, unique thing.",examples:["This is the only café open this late.","Who was the first person to arrive?"],ua:"the only, the first, the last — завжди з the, бо вказують на щось унікальне."},{id:"art-card-8",rule:"no article — sports, meals and transport",example:"After playing tennis for ___ hour, we went home for dinner.",answer:"an",explanation:"Sports (tennis, football), meals (breakfast, dinner) and forms of transport (by car, on foot) never take an article. The normal a/an rule still applies elsewhere in the sentence — 'hour' starts with a vowel sound, so it's 'an hour'.",examples:["She plays volleyball every weekend.","We usually travel by train."],ua:"Спорт, їжа (dinner) і транспорт (by car) — без артикля: play tennis, by car."}],rules:x},I=[{id:"pps-gap-1",topic:"present-perfect-superlative",type:"gap-fill",difficulty:"beginner",sentence:"It's the ___ film I've ever seen.",grammarRule:"Irregular Superlative 'Good' → 'Best'",explanation:"'Good' has an irregular superlative form: best. We never say 'goodest' or 'most good'.",tip:"good→best, bad→worst, far→furthest — irregular, just like go→went.",gapFill:{gapIndex:2,correctAnswer:"best",options:["best","goodest","more good","most good"],correctOptionIndex:0}},{id:"pps-gap-2",topic:"present-perfect-superlative",type:"gap-fill",difficulty:"beginner",sentence:"This is the ___ hotel I've ever stayed in.",grammarRule:"Superlative of Long Adjectives — 'Most' + Adjective",explanation:"Adjectives with two or more syllables form the superlative with 'most', not '-est'.",tip:"expensive, beautiful, comfortable → most + adjective, never adjective+est.",gapFill:{gapIndex:3,correctAnswer:"most expensive",options:["most expensive","expensivest","more expensive","much expensive"],correctOptionIndex:0}},{id:"pps-gap-3",topic:"present-perfect-superlative",type:"gap-fill",difficulty:"intermediate",sentence:"That's the ___ mistake you've ever made.",grammarRule:"Irregular Superlative 'Bad' → 'Worst'",explanation:"'Bad' has an irregular superlative form: worst. It never takes '-est' or 'most'.",tip:"bad→worse→worst — the whole comparison chain is irregular.",gapFill:{gapIndex:2,correctAnswer:"worst",options:["worst","baddest","more bad","most bad"],correctOptionIndex:0}},{id:"pps-gap-4",topic:"present-perfect-superlative",type:"gap-fill",difficulty:"intermediate",sentence:"She's the kindest person I ___ met.",grammarRule:"Present Perfect + Ever — Word Order",explanation:"To add 'ever' to this structure, use have/has + ever + past participle: 'I have ever met', not 'did ever meet'.",tip:"have/has always comes before 'ever', and 'ever' always comes before the past participle.",gapFill:{gapIndex:5,correctAnswer:"have ever",options:["have ever","has ever","did ever","ever have"],correctOptionIndex:0}},{id:"pps-gap-5",topic:"present-perfect-superlative",type:"gap-fill",difficulty:"intermediate",sentence:"This is the funniest joke I've ___ heard.",grammarRule:"'Ever' — At Any Time in Your Life",explanation:"'Ever' means 'at any time in your life until now'. It fits naturally between 've and the past participle in this structure.",tip:"ever = in your whole life so far — never, already and yet don't fit this meaning here.",gapFill:{gapIndex:6,correctAnswer:"ever",options:["ever","never","already","yet"],correctOptionIndex:0}},{id:"pps-gap-6",topic:"present-perfect-superlative",type:"gap-fill",difficulty:"advanced",sentence:"This is the biggest company she ___ worked for.",grammarRule:"Subject-Verb Agreement — Has Ever + Past Participle",explanation:"With a third person singular subject (he/she/it), use 'has', not 'have': 'she has ever worked for'.",tip:"I/we/you/they → have ever. He/she/it → has ever.",gapFill:{gapIndex:6,correctAnswer:"has ever",options:["has ever","have ever","is ever","did ever"],correctOptionIndex:0}},{id:"pps-error-1",topic:"present-perfect-superlative",type:"error-spot",difficulty:"beginner",sentence:"This is the goodest film I've ever seen.",grammarRule:"Irregular Superlative 'Good' → 'Best'",explanation:"'Good' doesn't follow the regular -est pattern. Its superlative is irregular: best.",errorSpot:{errorWordIndex:3,wrongWord:"goodest",correction:"best",reason:"'Good' is irregular: good→better→best. Never 'goodest'.",correctionOptions:["best","goodest","more good","most good"]}},{id:"pps-error-2",topic:"present-perfect-superlative",type:"error-spot",difficulty:"beginner",sentence:"It's the baddest storm I've ever seen.",grammarRule:"Irregular Superlative 'Bad' → 'Worst'",explanation:"'Bad' is irregular: bad→worse→worst. It never takes '-est'.",errorSpot:{errorWordIndex:2,wrongWord:"baddest",correction:"worst",reason:"'Bad' is irregular: the superlative is 'worst', not 'baddest'.",correctionOptions:["worst","baddest","more bad","most bad"]}},{id:"pps-error-3",topic:"present-perfect-superlative",type:"error-spot",difficulty:"intermediate",sentence:"This is the biggest car I've ever drove.",grammarRule:"Past Participle after Present Perfect",explanation:"After 've (have) in the present perfect, use the past participle 'driven', not the past simple 'drove'.",errorSpot:{errorWordIndex:7,wrongWord:"drove",correction:"driven",reason:"Present perfect needs the past participle: drive→drove→driven. Use 'driven' after 've.",correctionOptions:["driven","drove","drives","driving"]}},{id:"pps-error-4",topic:"present-perfect-superlative",type:"error-spot",difficulty:"intermediate",sentence:"He's the more intelligent person I've ever met.",grammarRule:"Superlative, Not Comparative",explanation:"Comparing one person to everyone else you've ever met needs the superlative ('most intelligent'), not the comparative ('more intelligent').",errorSpot:{errorWordIndex:2,wrongWord:"more",correction:"most",reason:"This compares against everyone, so it needs the superlative 'most intelligent', not the comparative 'more intelligent'.",correctionOptions:["most","more","much","many"]}},{id:"pps-error-5",topic:"present-perfect-superlative",type:"error-spot",difficulty:"intermediate",sentence:"That's the worst mistake you've ever make.",grammarRule:"Past Participle after Present Perfect",explanation:"After 've (have) in the present perfect, use the past participle 'made', not the base form 'make'.",errorSpot:{errorWordIndex:6,wrongWord:"make",correction:"made",reason:"Present perfect needs the past participle: make→made. Use 'made' after 've.",correctionOptions:["made","make","making","makes"]}},{id:"pps-error-6",topic:"present-perfect-superlative",type:"error-spot",difficulty:"advanced",sentence:"It's a most boring film I've ever seen.",grammarRule:"'The' before the Superlative Adjective",explanation:"Superlative adjectives always need 'the' in front of them, not 'a' or 'an' — even though 'a' is normal with other adjectives.",errorSpot:{errorWordIndex:1,wrongWord:"a",correction:"the",reason:"Superlatives always take 'the': 'the most boring', never 'a most boring'.",correctionOptions:["the","a","an","one"]}},{id:"pps-mc-1",topic:"present-perfect-superlative",type:"multiple-choice",difficulty:"beginner",sentence:"Choose the sentence that correctly uses present perfect + superlative:",grammarRule:"Present Perfect + Superlative — Basic Structure",explanation:"We use the present perfect (have/has + past participle) with a superlative adjective to talk about the best or worst experience of our life so far.",tip:"the + superlative + noun + subject + have/has + past participle — no past simple needed.",multipleChoice:{question:"Which sentence is grammatically correct?",correctOption:"It's the best holiday I've ever had.",options:["It's the best holiday I've ever had.","It's the best holiday I ever had.","It's the best holiday I have had ever.","It's the best holiday I did ever have."],optionExplanations:{"It's the best holiday I've ever had.":"Correct! Present perfect ('ve had) + superlative ('best') + 'ever' in the right position.","It's the best holiday I ever had.":"Wrong. 'Ever' in this structure needs the present perfect auxiliary 'have', not the past simple 'had' on its own.","It's the best holiday I have had ever.":"Wrong. 'Ever' goes between 'have' and the past participle, not at the end of the sentence.","It's the best holiday I did ever have.":"Wrong. This structure needs present perfect (have + past participle), not 'did'."}}},{id:"pps-mc-2",topic:"present-perfect-superlative",type:"multiple-choice",difficulty:"beginner",sentence:"Choose the correct superlative form of 'far':",grammarRule:"Irregular Superlative 'Far' → 'Furthest'",explanation:"'Far' has an irregular superlative form: furthest (or farthest) — never 'farest' or 'most far'.",tip:"good→best, bad→worst, far→furthest/farthest — learn these by heart; they don't follow the normal rules.",multipleChoice:{question:"Which is the correct superlative of 'far'?",correctOption:"furthest",options:["furthest","farest","most far","farrest"],optionExplanations:{furthest:"Correct! 'Far' is irregular: far → furthest (or farthest).",farest:"Wrong. 'Far' doesn't take the regular -est ending.","most far":"Wrong. 'Far' is irregular — it doesn't use 'most + adjective' either.",farrest:"Wrong. This isn't a real word — the irregular form is 'furthest' or 'farthest'."}}},{id:"pps-mc-3",topic:"present-perfect-superlative",type:"multiple-choice",difficulty:"intermediate",sentence:"Choose the sentence with 'ever' in the correct position:",grammarRule:"Position of 'Ever' — Between Have and Past Participle",explanation:"'Ever' goes between 'have/has' and the past participle: I've ever worked, she's ever met.",tip:"have + ever + past participle — never split 've' and 'ever', and never put 'ever' at the end.",multipleChoice:{question:"Which sentence places 'ever' correctly?",correctOption:"She's the kindest manager I've ever worked for.",options:["She's the kindest manager I've ever worked for.","She's the kindest manager I ever've worked for.","She's the kindest manager I've worked ever for.","She's the kindest manager ever I've worked for."],optionExplanations:{"She's the kindest manager I've ever worked for.":"Correct! 'Ever' sits right after 've (have) and before the past participle 'worked'.","She's the kindest manager I ever've worked for.":"Wrong. 'Ever' can't come before the contracted 've — it must follow have/has.","She's the kindest manager I've worked ever for.":"Wrong. 'Ever' must come before the past participle 'worked', not after it.","She's the kindest manager ever I've worked for.":"Wrong. 'Ever' belongs inside the present perfect verb phrase, not at the start of the clause."}}},{id:"pps-mc-4",topic:"present-perfect-superlative",type:"multiple-choice",difficulty:"intermediate",sentence:"Choose the correct sentence:",grammarRule:"Present Perfect (not Past Simple) for Life Experience",explanation:"To talk about an experience up to now (your whole life so far), use the present perfect — not the past simple, present continuous or future.",tip:"'Ever' + a superlative always needs the present perfect: have/has + past participle.",multipleChoice:{question:"Which sentence correctly talks about a whole-life experience?",correctOption:"It's the most beautiful city I've ever visited.",options:["It's the most beautiful city I've ever visited.","It's the most beautiful city I ever visited.","It's the most beautiful city I'm ever visiting.","It's the most beautiful city I will ever visit."],optionExplanations:{"It's the most beautiful city I've ever visited.":"Correct! Present perfect + 'ever' + past participle talks about your whole life up to now.","It's the most beautiful city I ever visited.":"Wrong. Missing 'have' — 'ever' with a superlative needs the present perfect auxiliary.","It's the most beautiful city I'm ever visiting.":"Wrong. Present continuous describes something happening now or arranged for later, not a life experience.","It's the most beautiful city I will ever visit.":"Wrong. The future tense talks about what hasn't happened yet, not a past experience."}}},{id:"pps-mc-5",topic:"present-perfect-superlative",type:"multiple-choice",difficulty:"intermediate",sentence:"Choose the correctly formed superlative:",grammarRule:"Superlative of Long Adjectives — 'Most' + Adjective",explanation:"Adjectives with two or more syllables (not ending in -y) form the superlative with 'most', not with '-est'.",tip:"exhausted, expensive, beautiful, interesting → most + adjective, never adjective+est.",multipleChoice:{question:"Which sentence uses the correct superlative form?",correctOption:"This is the most exhausted I've ever been.",options:["This is the most exhausted I've ever been.","This is the exhaustedest I've ever been.","This is the more exhausted I've ever been.","This is the much exhausted I've ever been."],optionExplanations:{"This is the most exhausted I've ever been.":"Correct! 'Exhausted' is a long adjective — use 'most' to form the superlative.","This is the exhaustedest I've ever been.":"Wrong. Long adjectives don't take '-est'.","This is the more exhausted I've ever been.":"Wrong. 'More' is comparative, not superlative — this needs 'most'.","This is the much exhausted I've ever been.":"Wrong. 'Much' isn't used to form superlatives — the correct word is 'most'."}}},{id:"pps-mc-6",topic:"present-perfect-superlative",type:"multiple-choice",difficulty:"intermediate",sentence:"Choose the sentence with the correct past participle:",grammarRule:"Past Participle after Present Perfect",explanation:"After have/has in the present perfect, irregular verbs use their past participle form, not the past simple or the base form.",tip:"hear→heard, see→seen, eat→eaten — always the past participle after have/has.",multipleChoice:{question:"Which sentence is correct?",correctOption:"This is the silliest thing I've ever heard you say.",options:["This is the silliest thing I've ever heard you say.","This is the silliest thing I've ever hear you say.","This is the silliest thing I've ever heared you say.","This is the silliest thing I've ever hearing you say."],optionExplanations:{"This is the silliest thing I've ever heard you say.":"Correct! 'Hear' is irregular: hear→heard. 'Heard' is the past participle needed after 've.","This is the silliest thing I've ever hear you say.":"Wrong. The base form 'hear' can't follow 've — it needs the past participle 'heard'.","This is the silliest thing I've ever heared you say.":"Wrong. 'Hear' is irregular — there's no regular '-ed' form 'heared'.","This is the silliest thing I've ever hearing you say.":"Wrong. The -ing form never follows 've in the present perfect."}}},{id:"pps-mc-7",topic:"present-perfect-superlative",type:"multiple-choice",difficulty:"advanced",sentence:"Choose the sentence with the correct word order:",grammarRule:"Word Order — The + Superlative + Noun + Subject + Have + Ever + Past Participle",explanation:"The full structure is: the + superlative adjective (+ noun) + subject + have/has + (ever) + past participle. Nothing comes between the superlative and its noun.",tip:"Build it in order: the → superlative → noun → subject → have/has → ever → past participle.",multipleChoice:{question:"Which sentence has the correct word order?",correctOption:"This is the biggest company I've ever worked for.",options:["This is the biggest company I've ever worked for.","This is the company biggest I've ever worked for.","This is the biggest I've ever worked for company.","This ever is the biggest company I've worked for."],optionExplanations:{"This is the biggest company I've ever worked for.":"Correct! the + superlative + noun + subject + have + ever + past participle, in the right order.","This is the company biggest I've ever worked for.":"Wrong. The superlative adjective must come before its noun: 'the biggest company', not 'the company biggest'.","This is the biggest I've ever worked for company.":"Wrong. The noun 'company' has been moved to the end — it must stay right after the superlative.","This ever is the biggest company I've worked for.":"Wrong. 'Ever' belongs inside the verb phrase (I've ever worked), not at the start of the sentence."}}},{id:"pps-wt-1",topic:"present-perfect-superlative",type:"word-transform",difficulty:"beginner",sentence:"That's the ___ (funny) joke I've ever heard.",grammarRule:"Adjectives Ending in -y — '-y' → '-iest'",explanation:"Adjectives ending in a consonant + y change y to i and add -est: funny→funniest.",tip:"funny→funniest, easy→easiest, happy→happiest — change y to i before adding -est.",wordTransform:{baseWord:"funny",correctAnswer:"funniest"}},{id:"pps-wt-2",topic:"present-perfect-superlative",type:"word-transform",difficulty:"beginner",sentence:"This is the ___ (bad) storm I've ever seen.",grammarRule:"Irregular Superlative 'Bad' → 'Worst'",explanation:"'Bad' is irregular: bad→worse→worst. It never takes '-est'.",tip:"bad→worst — the same irregular pattern as good→best and far→furthest.",wordTransform:{baseWord:"bad",correctAnswer:"worst"}},{id:"pps-wt-3",topic:"present-perfect-superlative",type:"word-transform",difficulty:"intermediate",sentence:"Jake is the ___ (patient) manager I've ever had.",grammarRule:"Superlative of Long Adjectives — 'Most' + Adjective",explanation:"'Patient' has two syllables and doesn't end in -y, so its superlative uses 'most', not '-est'.",tip:"Two or more syllables, no -y ending → most + adjective.",wordTransform:{baseWord:"patient",correctAnswer:"most patient"}},{id:"pps-wt-4",topic:"present-perfect-superlative",type:"word-transform",difficulty:"intermediate",sentence:"I think this is the ___ (exhausted) I've ever been.",grammarRule:"Superlative of Long Adjectives — 'Most' + Adjective",explanation:"'Exhausted' is a long adjective (a past participle used as an adjective), so its superlative uses 'most'.",tip:"Past-participle adjectives (exhausted, bored, surprised) always use 'most', never '-est'.",wordTransform:{baseWord:"exhausted",correctAnswer:"most exhausted"}},{id:"pps-wt-5",topic:"present-perfect-superlative",type:"word-transform",difficulty:"intermediate",sentence:"It's probably the ___ (brilliant) film we've ever seen.",grammarRule:"Superlative of Long Adjectives — 'Most' + Adjective",explanation:"'Brilliant' has three syllables, so its superlative is formed with 'most', not '-est'.",tip:"The longer the adjective, the more likely it needs 'most' instead of '-est'.",wordTransform:{baseWord:"brilliant",correctAnswer:"most brilliant"}},{id:"pps-wt-6",topic:"present-perfect-superlative",type:"word-transform",difficulty:"advanced",sentence:"This is the ___ (far) I've ever travelled alone.",grammarRule:"Irregular Superlative 'Far' → 'Furthest'",explanation:"'Far' is irregular: far→further/farther→furthest/farthest. Both 'furthest' and 'farthest' are correct.",tip:"far→furthest (distance, figurative) or farthest (physical distance) — both are accepted.",wordTransform:{baseWord:"far",correctAnswer:"furthest",alternativeAnswers:["farthest"]}}],_={id:"present-perfect-superlative",level:"B1",name:"Present Perfect + Superlative",description:"Use the present perfect with a superlative adjective to talk about the best, worst or most amazing experience of your whole life — and learn exactly where 'ever' goes.",lesson:"Lesson 4D",icon:"🏆",cards:[{id:"pps-card-1",rule:"the + superlative + present perfect",example:"This is the ___ (good) coffee I've had this week.",answer:"best",explanation:"We use the present perfect with a superlative adjective to talk about the best, worst or most amazing experience of our life so far.",examples:["It's the biggest house I've seen.","That's the worst film I've watched."],ua:"«the + найвищий ступінь + Present Perfect» — найкращий/найгірший досвід «дотепер»."},{id:"pps-card-2",rule:"ever between have and the past participle",example:"It's the nicest café I've ___ (be) to.",answer:"ever been",explanation:"'Ever' means 'at any time in your life'. It always goes between have/has and the past participle, never at the end of the sentence.",examples:["That's the funniest joke I've ever heard.","She's the kindest teacher I've ever had."],ua:"ever стоїть між have і дієприкметником: I've ever been, не I ever've been."},{id:"pps-card-3",rule:"irregular superlatives: good→best, bad→worst, far→furthest",example:"This is the ___ (bad) storm I've seen this year.",answer:"worst",explanation:"Good, bad and far have irregular superlative forms: best, worst, furthest/farthest — never goodest or baddest.",examples:["This is the best meal I've ever eaten.","It's the furthest I've ever been from home."],ua:"good→best, bad→worst, far→furthest/farthest — не додавай -est."},{id:"pps-card-4",rule:"short adjectives: add -est",example:"This is the ___ (long) book I've ever read.",answer:"longest",explanation:"Short, one-syllable adjectives take -est in the superlative: long→longest, old→oldest, fast→fastest.",examples:["It's the slowest car I've ever driven.","That's the coldest winter I've ever had."],ua:"короткі прикметники (1 склад): +est → longest, oldest, fastest."},{id:"pps-card-5",rule:"adjectives ending in -y: -y → -iest",example:"She's the ___ (happy) person I've ever met.",answer:"happiest",explanation:"Adjectives ending in a consonant + y change y to i and add -est: happy→happiest, easy→easiest, funny→funniest.",examples:["This is the easiest exam I've ever taken.","That's the funniest show I've ever watched."],ua:"прикметники на -y: y→i +est → happiest, easiest, funniest."},{id:"pps-card-6",rule:"long adjectives: most + adjective",example:"This is the ___ (beautiful) place I've ever visited.",answer:"most beautiful",explanation:"Adjectives with two or more syllables (and not ending in -y) use 'most' + adjective: most expensive, most interesting, most beautiful.",examples:["This is the most comfortable sofa I've ever sat on.","It's the most interesting question you've asked me."],ua:"довгі прикметники: most + прикметник → most beautiful, most expensive."},{id:"pps-card-7",rule:"past participle after have/has — not past simple",example:"That's the most expensive bike I've ever ___ (buy).",answer:"bought",explanation:"After have/has in the present perfect, use the past participle, not the past simple or base form: buy→bought, not buyed or buy.",examples:["It's the best meal I've ever eaten.","This is the biggest mistake I've ever made at work."],ua:"після have/has — дієприкметник (bought), не Past Simple чи базова форма."},{id:"pps-card-8",rule:"'the' before the superlative adjective",example:"That's ___ nicest present I've ever received.",answer:"the",explanation:"Superlative adjectives always need 'the' in front of them — never 'a' or no article at all.",examples:["She's the funniest comedian I've ever seen live.","It's the tallest building I've ever been inside."],ua:"перед найвищим ступенем завжди 'the': the best, не a best."}],rules:I},W=[{id:"rc-gap-1",topic:"relative-clauses",type:"gap-fill",difficulty:"beginner",sentence:"Christopher Blair is the writer ___ invents fake news stories online.",grammarRule:"Relative Pronoun 'Who' — People",explanation:"'Who' introduces a relative clause that gives essential information about a person — here, the writer.",tip:"who = people. He's the man who took my bag.",gapFill:{gapIndex:5,correctAnswer:"who",options:["who","which","where","whose"],correctOptionIndex:0}},{id:"rc-gap-2",topic:"relative-clauses",type:"gap-fill",difficulty:"beginner",sentence:"This is the website ___ I read the news every morning.",grammarRule:"Relative Pronoun 'Where' — Places",explanation:"'Where' introduces a relative clause that gives essential information about a place — here, the website.",tip:"where = places. This is the building where we got married.",gapFill:{gapIndex:4,correctAnswer:"where",options:["where","which","who","when"],correctOptionIndex:0}},{id:"rc-gap-3",topic:"relative-clauses",type:"gap-fill",difficulty:"intermediate",sentence:"He writes news stories ___ are completely invented.",grammarRule:"Relative Pronoun 'Which' — Things",explanation:"'Which' introduces a relative clause that gives essential information about a thing — here, the news stories.",tip:"which = things. This is the bank card which she was looking for.",gapFill:{gapIndex:4,correctAnswer:"which",options:["which","who","when","whose"],correctOptionIndex:0}},{id:"rc-gap-4",topic:"relative-clauses",type:"gap-fill",difficulty:"intermediate",sentence:"She remembers the exact moment ___ she realised the story was fake.",grammarRule:"Relative Pronoun 'When' — Times",explanation:"'When' introduces a relative clause that gives essential information about a time — here, the exact moment.",tip:"when = times. That was the day when I graduated.",gapFill:{gapIndex:5,correctAnswer:"when",options:["when","where","which","who"],correctOptionIndex:0}},{id:"rc-gap-5",topic:"relative-clauses",type:"gap-fill",difficulty:"intermediate",sentence:"That's the journalist ___ article got millions of views overnight.",grammarRule:"Relative Pronoun 'Whose' — Possession",explanation:"'Whose' introduces a relative clause that shows possession — here, the journalist's article.",tip:"whose = possession. Is that the man whose phone you picked up?",gapFill:{gapIndex:3,correctAnswer:"whose",options:["whose","who","which","where"],correctOptionIndex:0}},{id:"rc-gap-6",topic:"relative-clauses",type:"gap-fill",difficulty:"advanced",sentence:"This is the headline ___ convinced thousands of people to share a fake story.",grammarRule:"Relative Pronoun 'Which' — Things as the Subject",explanation:"'Which' can be the subject of its own clause — here, the headline is what convinced people to share.",tip:"which can be the subject of the relative clause too: the thing which did something.",gapFill:{gapIndex:4,correctAnswer:"which",options:["which","who","whose","where"],correctOptionIndex:0}},{id:"rc-error-1",topic:"relative-clauses",type:"error-spot",difficulty:"beginner",sentence:"She's the woman which lives in the flat upstairs.",grammarRule:"Who vs Which — People, Not Things",explanation:"'Which' is used for things, not people. For a person, use 'who'.",errorSpot:{errorWordIndex:3,wrongWord:"which",correction:"who",reason:"'Woman' is a person, so use 'who', not 'which': 'She's the woman who lives in the flat upstairs.'",correctionOptions:["who","which","where","whose"]}},{id:"rc-error-2",topic:"relative-clauses",type:"error-spot",difficulty:"beginner",sentence:"This is the book who I borrowed from the library.",grammarRule:"Which vs Who — Things, Not People",explanation:"'Who' is used for people, not things. For a thing like a book, use 'which' (or 'that').",errorSpot:{errorWordIndex:4,wrongWord:"who",correction:"which",reason:"'Book' is a thing, so use 'which', not 'who': 'This is the book which I borrowed from the library.'",correctionOptions:["which","who","where","when"]}},{id:"rc-error-3",topic:"relative-clauses",type:"error-spot",difficulty:"intermediate",sentence:"That's the café who serves the best coffee in town.",grammarRule:"Which vs Who — Places Used as the Subject",explanation:"A café is a place, but here it's the subject of the clause (the café serves coffee), so we treat it like a thing and use 'which', not 'who'.",errorSpot:{errorWordIndex:3,wrongWord:"who",correction:"which",reason:"The café is the subject doing the action, so use 'which': 'That's the café which serves the best coffee in town.'",correctionOptions:["which","who","where","when"]}},{id:"rc-error-4",topic:"relative-clauses",type:"error-spot",difficulty:"intermediate",sentence:"He's the man whose took my wallet yesterday.",grammarRule:"Who vs Whose — Subject, Not Possession",explanation:"'Whose' shows possession and must be followed by a noun. Here the man himself took the wallet, so we need the subject pronoun 'who'.",errorSpot:{errorWordIndex:3,wrongWord:"whose",correction:"who",reason:"No possession is shown here — the man is the subject who took the wallet: 'He's the man who took my wallet yesterday.'",correctionOptions:["who","whose","which","where"]}},{id:"rc-error-5",topic:"relative-clauses",type:"error-spot",difficulty:"intermediate",sentence:"Is that the student who's phone keeps ringing in class?",grammarRule:"Whose vs Who's — Possession, Not a Contraction",explanation:"'Who's' is short for 'who is' or 'who has' — it never shows possession. For possession, use 'whose'.",errorSpot:{errorWordIndex:4,wrongWord:"who's",correction:"whose",reason:"This shows possession (the student's phone), so use 'whose': 'Is that the student whose phone keeps ringing in class?'",correctionOptions:["whose","who's","who","which"]}},{id:"rc-error-6",topic:"relative-clauses",type:"error-spot",difficulty:"advanced",sentence:"That was the year which I graduated from university.",grammarRule:"When vs Which — Times, Not Things",explanation:"'Which' is used for things, not times. For a time expression like 'year', use 'when'.",errorSpot:{errorWordIndex:4,wrongWord:"which",correction:"when",reason:"'Year' is a time, so use 'when', not 'which': 'That was the year when I graduated from university.'",correctionOptions:["when","which","where","who"]}},{id:"rc-mc-1",topic:"relative-clauses",type:"multiple-choice",difficulty:"beginner",sentence:"Choose the sentence that correctly uses a relative pronoun for a person:",grammarRule:"Relative Pronoun 'Who' — People",explanation:"'Who' is the relative pronoun used for people.",tip:"who = people, always.",multipleChoice:{question:"Which sentence is correct?",correctOption:"He's the journalist who writes for the newspaper.",options:["He's the journalist who writes for the newspaper.","He's the journalist which writes for the newspaper.","He's the journalist where writes for the newspaper.","He's the journalist whose writes for the newspaper."],optionExplanations:{"He's the journalist who writes for the newspaper.":"Correct! 'Who' introduces a relative clause about a person.","He's the journalist which writes for the newspaper.":"Wrong. 'Which' is for things, not people.","He's the journalist where writes for the newspaper.":"Wrong. 'Where' is for places, not people.","He's the journalist whose writes for the newspaper.":"Wrong. 'Whose' needs a noun right after it to show possession — there's no noun here."}}},{id:"rc-mc-2",topic:"relative-clauses",type:"multiple-choice",difficulty:"beginner",sentence:"Choose the sentence that correctly uses a relative pronoun for a thing:",grammarRule:"Relative Pronoun 'Which' — Things",explanation:"'Which' is the relative pronoun used for things.",tip:"which = things, always.",multipleChoice:{question:"Which sentence is correct?",correctOption:"This is the bank card which she was looking for.",options:["This is the bank card which she was looking for.","This is the bank card who she was looking for.","This is the bank card where she was looking for.","This is the bank card whose she was looking for."],optionExplanations:{"This is the bank card which she was looking for.":"Correct! 'Which' introduces a relative clause about a thing.","This is the bank card who she was looking for.":"Wrong. 'Who' is for people, not things.","This is the bank card where she was looking for.":"Wrong. 'Where' is for places, not things.","This is the bank card whose she was looking for.":"Wrong. 'Whose' needs a noun right after it to show possession — there's no noun here."}}},{id:"rc-mc-3",topic:"relative-clauses",type:"multiple-choice",difficulty:"intermediate",sentence:"Choose the sentence that correctly uses a relative pronoun for a place:",grammarRule:"Relative Pronoun 'Where' — Places",explanation:"'Where' is the relative pronoun used for places.",tip:"where = places. Think: 'in that place'.",multipleChoice:{question:"Which sentence is correct?",correctOption:"This is the building where we got married.",options:["This is the building where we got married.","This is the building which we got married.","This is the building who we got married.","This is the building when we got married."],optionExplanations:{"This is the building where we got married.":"Correct! 'Where' introduces a relative clause about a place.","This is the building which we got married.":"Wrong. 'Which' doesn't work with a place used this way — 'where' is needed.","This is the building who we got married.":"Wrong. 'Who' is for people, not places.","This is the building when we got married.":"Wrong. 'When' is for times, not places."}}},{id:"rc-mc-4",topic:"relative-clauses",type:"multiple-choice",difficulty:"intermediate",sentence:"Choose the sentence that correctly uses a relative pronoun for a time:",grammarRule:"Relative Pronoun 'When' — Times",explanation:"'When' is the relative pronoun used for times.",tip:"when = times. Think: 'at that time'.",multipleChoice:{question:"Which sentence is correct?",correctOption:"That was the day when I graduated from university.",options:["That was the day when I graduated from university.","That was the day where I graduated from university.","That was the day which I graduated from university.","That was the day whose I graduated from university."],optionExplanations:{"That was the day when I graduated from university.":"Correct! 'When' introduces a relative clause about a time.","That was the day where I graduated from university.":"Wrong. 'Where' is for places, not times.","That was the day which I graduated from university.":"Wrong. 'Which' is for things, not times.","That was the day whose I graduated from university.":"Wrong. 'Whose' needs a noun right after it to show possession — there's no noun here."}}},{id:"rc-mc-5",topic:"relative-clauses",type:"multiple-choice",difficulty:"intermediate",sentence:"Choose the sentence that correctly shows possession with a relative pronoun:",grammarRule:"Relative Pronoun 'Whose' — Possession",explanation:"'Whose' shows possession and is always followed directly by a noun.",tip:"whose + noun = possession. who's = who is / who has.",multipleChoice:{question:"Which sentence is correct?",correctOption:"Is that the man whose phone you picked up?",options:["Is that the man whose phone you picked up?","Is that the man who's phone you picked up?","Is that the man which phone you picked up?","Is that the man who phone you picked up?"],optionExplanations:{"Is that the man whose phone you picked up?":"Correct! 'Whose' shows that the phone belongs to the man.","Is that the man who's phone you picked up?":"Wrong. 'Who's' is short for 'who is' or 'who has' — it never shows possession.","Is that the man which phone you picked up?":"Wrong. 'Which' is for things, not people, and doesn't show possession here.","Is that the man who phone you picked up?":"Wrong. 'Who' needs no noun after it — possession needs 'whose'."}}},{id:"rc-mc-6",topic:"relative-clauses",type:"multiple-choice",difficulty:"intermediate",sentence:"Look at these four sentences about relative clauses.",grammarRule:"That — Replaces Who/Which, Never Whose",explanation:"'That' can replace 'who' or 'which' in defining relative clauses, but it can never replace 'whose'.",tip:"that = who/which substitute. that ≠ whose, ever.",multipleChoice:{question:"In which sentence can the relative pronoun NOT be replaced by 'that'?",correctOption:"Is that the man whose phone you picked up?",options:["Is that the man whose phone you picked up?","He's the man who took my bag.","This is the bank card which she was looking for.","He writes news stories which are completely fake."],optionExplanations:{"Is that the man whose phone you picked up?":"Correct! 'Whose' shows possession and can never be replaced by 'that'.","He's the man who took my bag.":"Wrong. 'Who' (for a person) can be replaced by 'that': 'He's the man that took my bag.'","This is the bank card which she was looking for.":"Wrong. 'Which' (for a thing) can be replaced by 'that': 'This is the bank card that she was looking for.'","He writes news stories which are completely fake.":"Wrong. 'Which' (for a thing) can be replaced by 'that': 'He writes news stories that are completely fake.'"}}},{id:"rc-mc-7",topic:"relative-clauses",type:"multiple-choice",difficulty:"advanced",sentence:"Look at these four sentences about relative clauses.",grammarRule:"Leaving Out the Relative Pronoun — Object Clauses Only",explanation:"We can leave out who, which or that when it is the OBJECT of the relative clause — but never when it is the subject, and never with 'whose'.",tip:"Object of the clause → pronoun optional. Subject of the clause → pronoun required.",multipleChoice:{question:"In which sentence can the relative pronoun safely be left out?",correctOption:"She's the woman I was telling you about.",options:["She's the woman I was telling you about.","She's the woman lives next door.","This is the man phone you picked up.","That's the café serves the best coffee in town."],optionExplanations:{"She's the woman I was telling you about.":"Correct! The woman is the OBJECT of the relative clause ('I was telling you about her'), so 'who'/'that' can be left out.","She's the woman lives next door.":"Wrong. The woman is the SUBJECT of the relative clause (she lives next door) — 'who' cannot be left out here.","This is the man phone you picked up.":"Wrong. 'Whose' shows possession and can never be left out.","That's the café serves the best coffee in town.":"Wrong. The café is the SUBJECT of the relative clause (it serves coffee) — 'which' cannot be left out here."}}},{id:"rc-wt-1",topic:"relative-clauses",type:"word-transform",difficulty:"beginner",sentence:"She's the reporter ___ exposed the scandal.",grammarRule:"Relative Pronoun 'Who' — People",explanation:"'Who' (or 'that') introduces a relative clause about a person — here, the subject who exposed the scandal.",tip:"person → who (or that).",wordTransform:{baseWord:"person",correctAnswer:"who",alternativeAnswers:["that"]}},{id:"rc-wt-2",topic:"relative-clauses",type:"word-transform",difficulty:"beginner",sentence:"This is the newspaper ___ published the story first.",grammarRule:"Relative Pronoun 'Which' — Things",explanation:"'Which' (or 'that') introduces a relative clause about a thing — here, the subject that published the story.",tip:"thing → which (or that).",wordTransform:{baseWord:"thing",correctAnswer:"which",alternativeAnswers:["that"]}},{id:"rc-wt-3",topic:"relative-clauses",type:"word-transform",difficulty:"intermediate",sentence:"That's the café ___ we always meet for coffee.",grammarRule:"Relative Pronoun 'Where' — Places",explanation:"'Where' introduces a relative clause about a place.",tip:"place → where.",wordTransform:{baseWord:"place",correctAnswer:"where"}},{id:"rc-wt-4",topic:"relative-clauses",type:"word-transform",difficulty:"intermediate",sentence:"I'll never forget the moment ___ I saw my name in print.",grammarRule:"Relative Pronoun 'When' — Times",explanation:"'When' (or sometimes 'that') introduces a relative clause about a time.",tip:"time → when (or sometimes that).",wordTransform:{baseWord:"time",correctAnswer:"when",alternativeAnswers:["that"]}},{id:"rc-wt-5",topic:"relative-clauses",type:"word-transform",difficulty:"intermediate",sentence:"He's the author ___ new book became a bestseller.",grammarRule:"Relative Pronoun 'Whose' — Possession",explanation:"'Whose' introduces a relative clause showing possession — here, the author's book.",tip:"possession → whose, always followed by a noun.",wordTransform:{baseWord:"possession",correctAnswer:"whose"}},{id:"rc-wt-6",topic:"relative-clauses",type:"word-transform",difficulty:"advanced",sentence:"She's the journalist ___ everyone in the newsroom respects.",grammarRule:"Who/That as the Object of the Clause",explanation:"'Who' or 'that' can introduce a relative clause even when the person is the OBJECT, not the subject, of that clause ('everyone respects her'). Native speakers often drop it altogether, but you must fill the gap here.",tip:"Object relative clause: who/that fills the gap, or it can be dropped entirely in natural speech.",wordTransform:{baseWord:"person — object of the clause",correctAnswer:"who",alternativeAnswers:["that"]}}],T={id:"relative-clauses",level:"B1",name:"Relative Clauses",description:"Practise who, which, where, when and whose for giving essential information about people, places, things, times and possessions — plus when you can use that instead, or leave the pronoun out altogether.",lesson:"Lesson 5A",icon:"🔗",cards:[{id:"rc-card-1",rule:"who — for people",example:"She's the woman ___ called the ambulance.",answer:"who",explanation:"We use 'who' for people in a relative clause. It can be the subject, like here (she called the ambulance).",examples:["He's the man who works at the bakery on the corner.","They're the tourists who got lost downtown yesterday."],ua:"who = «який/яка» про людей: she's the woman who called — вона подзвонила."},{id:"rc-card-2",rule:"which — for things",example:"That's the article ___ caused so much debate online.",answer:"which",explanation:"We use 'which' for things and animals in a relative clause, never for people.",examples:["This is the laptop which stopped working last week.","He deleted the post which upset so many readers."],ua:"which = «який/яка/яке» про речі, не про людей: the article which caused debate."},{id:"rc-card-3",rule:"where — for places",example:"This is the café ___ we always meet after work.",answer:"where",explanation:"We use 'where' for places in a relative clause — it means 'in that place'.",examples:["That's the park where we had our picnic.","This is the office where I had my first job interview."],ua:"where = «де»: café where we meet — кафе, де ми зустрічаємось."},{id:"rc-card-4",rule:"when — for times",example:"I'll never forget the day ___ I got my first job.",answer:"when",explanation:"We use 'when' for times in a relative clause — it means 'at that time'.",examples:["That was the summer when we travelled around Europe.","Do you remember the moment when the power went out?"],ua:"when = «коли»: the day when I got the job — день, коли я отримав роботу."},{id:"rc-card-5",rule:"whose — for possession",example:"He's the man ___ car was stolen last night.",answer:"whose",explanation:"We use 'whose' to show that something belongs to the person or thing just mentioned. It is always followed by a noun.",examples:["She's the woman whose dog barks every morning.","That's the company whose app crashed yesterday."],ua:"whose = «чий/чия/чиє»: the man whose car — чоловік, чия машина."},{id:"rc-card-6",rule:"that instead of who or which",example:"He's the man ___ (who/that) stole my bike.",answer:"who",explanation:"In defining relative clauses, 'that' can replace 'who' or 'which' with no change in meaning. Both forms are correct.",examples:["This is the bank card that she'd been looking for all day.","She's the journalist that wrote the article."],ua:"that часто замінює who/which у визначальних реченнях: who/that — без різниці."},{id:"rc-card-7",rule:"leaving out the pronoun (object clauses)",example:"He's the man ___ (who/that) I told you about.",answer:"who",explanation:"When the person or thing is the OBJECT of the relative clause (not the subject), we can leave out who, which or that completely: 'He's the man I told you about.'",examples:["She's the woman I was telling you about.","This is the book I borrowed from the library."],ua:"Коли іменник — об'єкт речення, who/which/that можна взагалі пропустити."}],rules:W},P=[{id:"rs-gap-1",topic:"reported-speech",type:"gap-fill",difficulty:"beginner",sentence:"He said that he ___ in Madrid.",grammarRule:"Present Simple → Past Simple in Reported Speech",explanation:"'Live' is present simple in direct speech ('I live in Madrid'). After a past reporting verb, it moves one tense back to past simple: lived.",tip:"Reporting verb in the past (said/told) → shift the original verb one tense back.",gapFill:{gapIndex:4,correctAnswer:"lived",options:["lived","lives","live","living"],correctOptionIndex:0}},{id:"rs-gap-2",topic:"reported-speech",type:"gap-fill",difficulty:"beginner",sentence:"They said that they ___ a documentary.",grammarRule:"Present Continuous → Past Continuous in Reported Speech",explanation:"'Are watching' is present continuous in direct speech ('We are watching a documentary'). In reported speech it backshifts to past continuous: were watching.",tip:"Present continuous (is/am/are + -ing) → past continuous (was/were + -ing) in reported speech.",gapFill:{gapIndex:4,correctAnswer:"were watching",options:["were watching","are watching","watched","watching"],correctOptionIndex:0}},{id:"rs-gap-3",topic:"reported-speech",type:"gap-fill",difficulty:"intermediate",sentence:"She told me that she ___ the report.",grammarRule:"Present Perfect → Past Perfect in Reported Speech",explanation:"'I've finished the report' uses present perfect. In reported speech, present perfect backshifts to past perfect: had finished.",tip:"Present perfect (have/has + past participle) → past perfect (had + past participle) in reported speech.",gapFill:{gapIndex:5,correctAnswer:"had finished",options:["had finished","has finished","finished","was finishing"],correctOptionIndex:0}},{id:"rs-gap-4",topic:"reported-speech",type:"gap-fill",difficulty:"intermediate",sentence:"They said that they ___ that film the week before.",grammarRule:"Past Simple → Past Perfect in Reported Speech",explanation:"'We saw that film last week' uses past simple. In reported speech, past simple often moves one step further back to past perfect: had seen.",tip:"Past simple can backshift to past perfect in reported speech, especially when it happened before something else.",gapFill:{gapIndex:4,correctAnswer:"had seen",options:["had seen","saw","have seen","see"],correctOptionIndex:0}},{id:"rs-gap-5",topic:"reported-speech",type:"gap-fill",difficulty:"intermediate",sentence:"He told us that he ___ three languages.",grammarRule:"Can → Could in Reported Speech",explanation:"'I can speak three languages' uses 'can'. In reported speech, 'can' always backshifts to 'could'.",tip:"can → could in reported speech, just like will → would.",gapFill:{gapIndex:5,correctAnswer:"could speak",options:["could speak","can speak","speaks","spoke"],correctOptionIndex:0}},{id:"rs-gap-6",topic:"reported-speech",type:"gap-fill",difficulty:"advanced",sentence:"She said that she ___ me back later.",grammarRule:"Will → Would in Reported Speech",explanation:"'I'll call you back later' uses 'will'. In reported speech, 'will' always backshifts to 'would'.",tip:"will → would in reported speech. The pronoun also changes: 'you' (the listener) becomes 'me'.",gapFill:{gapIndex:4,correctAnswer:"would call",options:["would call","will call","called","calls"],correctOptionIndex:0}},{id:"rs-error-1",topic:"reported-speech",type:"error-spot",difficulty:"beginner",sentence:"She told to me that she needed help.",grammarRule:"Say vs Tell in Reported Speech",explanation:"'Tell' already includes the person and is never followed by 'to': tell someone. 'Said to' does take 'to' + person.",errorSpot:{errorWordIndex:1,wrongWord:"told",correction:"said",reason:"'Told' is never followed by 'to'. Either say 'told me' or 'said to me' — changing 'told' to 'said' fixes the sentence.",correctionOptions:["said","told","say","tell"]}},{id:"rs-error-2",topic:"reported-speech",type:"error-spot",difficulty:"beginner",sentence:"He said me that he would be late.",grammarRule:"Say vs Tell in Reported Speech",explanation:"'Say' is never followed directly by a person: 'said me' is wrong. Use 'told' + person, or 'said to' + person.",errorSpot:{errorWordIndex:1,wrongWord:"said",correction:"told",reason:"'Say' cannot take a person directly after it — change 'said' to 'told': 'He told me...'.",correctionOptions:["told","said","tells","says"]}},{id:"rs-error-3",topic:"reported-speech",type:"error-spot",difficulty:"intermediate",sentence:"She said that she lives in Berlin.",grammarRule:"Present Simple → Past Simple in Reported Speech",explanation:"After a past reporting verb, present simple backshifts to past simple: lives → lived.",errorSpot:{errorWordIndex:4,wrongWord:"lives",correction:"lived",reason:"The original statement ('I live in Berlin') is present simple, so it must backshift to past simple: lived.",correctionOptions:["lived","lives","living","live"]}},{id:"rs-error-4",topic:"reported-speech",type:"error-spot",difficulty:"intermediate",sentence:"He told us that he will help us.",grammarRule:"Will → Would in Reported Speech",explanation:"'Will' in direct speech always becomes 'would' in reported speech.",errorSpot:{errorWordIndex:5,wrongWord:"will",correction:"would",reason:"'Will' backshifts to 'would' in reported speech: 'He told us that he would help us.'",correctionOptions:["would","will","can","could"]}},{id:"rs-error-5",topic:"reported-speech",type:"error-spot",difficulty:"intermediate",sentence:"She said that she can drive a truck.",grammarRule:"Can → Could in Reported Speech",explanation:"'Can' in direct speech always becomes 'could' in reported speech.",errorSpot:{errorWordIndex:4,wrongWord:"can",correction:"could",reason:"'Can' backshifts to 'could' in reported speech: 'She said that she could drive a truck.'",correctionOptions:["could","can","will","would"]}},{id:"rs-error-6",topic:"reported-speech",type:"error-spot",difficulty:"advanced",sentence:"He said that my flight was delayed.",grammarRule:"Pronouns in Reported Speech",explanation:"Pronouns and possessives change to match the reported speaker, not the person repeating the words. A colleague talking about his own flight needs 'his', not 'my'.",errorSpot:{errorWordIndex:3,wrongWord:"my",correction:"his",reason:"He was talking about his own flight, so the possessive must match him: 'his flight', not 'my flight'.",correctionOptions:["his","my","her","their"]}},{id:"rs-mc-1",topic:"reported-speech",type:"multiple-choice",difficulty:"beginner",sentence:"Anna said, 'I'm tired.'",grammarRule:"Present Simple → Past Simple in Reported Speech",explanation:"'Am' is present simple (the verb 'be'). In reported speech it backshifts to 'was', and the reporting verb 'said' doesn't need 'to' here.",tip:"be (am/is/are) → was/were in reported speech, just like any other present simple verb.",multipleChoice:{question:"Which sentence correctly reports what Anna said?",correctOption:"Anna said that she was tired.",options:["Anna said that she was tired.","Anna said that she is tired.","Anna told that she was tired.","Anna said she tired."],optionExplanations:{"Anna said that she was tired.":"Correct! 'Am' backshifts to 'was', and 'said that' needs no object.","Anna said that she is tired.":"Wrong. 'Is' must backshift to 'was' after the past reporting verb 'said'.","Anna told that she was tired.":"Wrong. 'Tell' always needs a person: 'told me', not 'told that'.","Anna said she tired.":"Wrong. The verb 'be' is missing — it needs 'was': 'she was tired'."}}},{id:"rs-mc-2",topic:"reported-speech",type:"multiple-choice",difficulty:"beginner",sentence:"Tom said, 'I have to leave early.'",grammarRule:"Have To / Has To → Had To in Reported Speech",explanation:"'Have to' in direct speech backshifts to 'had to' in reported speech, following the same pattern as other present forms.",tip:"have to / has to → had to in reported speech, no matter who is speaking.",multipleChoice:{question:"Which sentence correctly reports what Tom said?",correctOption:"Tom said that he had to leave early.",options:["Tom said that he had to leave early.","Tom said that he has to leave early.","Tom told that he had to leave early.","Tom said that he have to leave early."],optionExplanations:{"Tom said that he had to leave early.":"Correct! 'Have to' backshifts to 'had to'.","Tom said that he has to leave early.":"Wrong. 'Has to' must backshift to 'had to' in reported speech.","Tom told that he had to leave early.":"Wrong. 'Tell' needs a person: 'told me', not 'told that'.","Tom said that he have to leave early.":"Wrong. This is neither the original form ('have to') nor the correct backshifted form ('had to')."}}},{id:"rs-mc-3",topic:"reported-speech",type:"multiple-choice",difficulty:"intermediate",sentence:"Our neighbours said, 'We're going to paint the fence this weekend.'",grammarRule:"Am/Is/Are Going To → Was/Were Going To in Reported Speech",explanation:"'Are going to' in direct speech backshifts to 'were going to' in reported speech — only the 'be' part changes.",tip:"am/is/are going to → was/were going to. The rest of the phrase ('going to paint') stays the same.",multipleChoice:{question:"Which sentence correctly reports what the neighbours said?",correctOption:"Our neighbours said that they were going to paint the fence this weekend.",options:["Our neighbours said that they were going to paint the fence this weekend.","Our neighbours said that they are going to paint the fence this weekend.","Our neighbours said that they would paint the fence this weekend.","Our neighbours said that they going to paint the fence this weekend."],optionExplanations:{"Our neighbours said that they were going to paint the fence this weekend.":"Correct! 'Are going to' backshifts to 'were going to'.","Our neighbours said that they are going to paint the fence this weekend.":"Wrong. 'Are' must backshift to 'were' after the past reporting verb.","Our neighbours said that they would paint the fence this weekend.":"Wrong. 'Going to' backshifts to 'was/were going to', not 'would'.","Our neighbours said that they going to paint the fence this weekend.":"Wrong. The auxiliary 'were' is missing — it can't be dropped."}}},{id:"rs-mc-4",topic:"reported-speech",type:"multiple-choice",difficulty:"intermediate",sentence:"David said, 'I'm busy.'",grammarRule:"Say vs Tell in Reported Speech",explanation:"'Tell' always needs a person straight after it (told me) and never takes 'to'. 'Say' doesn't take a person directly — it needs 'to' first (said to me) or no person at all.",tip:"tell + person (told me) vs say (to) + person (said to me) — never 'told to' or 'said me'.",multipleChoice:{question:"Which sentence uses the reporting verb correctly?",correctOption:"David told me that he was busy.",options:["David told me that he was busy.","David told that he was busy.","David told to me that he was busy.","David said me that he was busy."],optionExplanations:{"David told me that he was busy.":"Correct! 'Tell' takes a person directly: told me.","David told that he was busy.":"Wrong. 'Tell' needs a person: 'told me', not just 'told that'.","David told to me that he was busy.":"Wrong. 'Tell' never takes 'to': it's 'told me', not 'told to me'.","David said me that he was busy.":"Wrong. 'Say' never takes a person directly: it needs 'said to me' or just 'said'."}}},{id:"rs-mc-5",topic:"reported-speech",type:"multiple-choice",difficulty:"intermediate",sentence:"Laura said, 'I've lost my keys.'",grammarRule:"Present Perfect → Past Perfect in Reported Speech",explanation:"'I've lost' is present perfect. In reported speech it backshifts to past perfect: had lost. The possessive 'my' also changes to match Laura: 'her keys'.",tip:"present perfect → past perfect, and don't forget the possessive change: my → her.",multipleChoice:{question:"Which sentence correctly reports what Laura said?",correctOption:"Laura said that she had lost her keys.",options:["Laura said that she had lost her keys.","Laura said that she has lost her keys.","Laura said that she lost her keys.","Laura said that she was losing her keys."],optionExplanations:{"Laura said that she had lost her keys.":"Correct! Present perfect 'has lost' backshifts to past perfect 'had lost'.","Laura said that she has lost her keys.":"Wrong. 'Has lost' must backshift to 'had lost' in reported speech.","Laura said that she lost her keys.":"Wrong. This drops the perfect aspect entirely — it should be 'had lost', not just 'lost'.","Laura said that she was losing her keys.":"Wrong. This changes the meaning to an ongoing action, not a completed one."}}},{id:"rs-mc-6",topic:"reported-speech",type:"multiple-choice",difficulty:"intermediate",sentence:"They told us, 'We missed the bus.'",grammarRule:"Past Simple → Past Perfect in Reported Speech",explanation:"'We missed the bus' is past simple. In reported speech, a past simple action that happened before the reporting often backshifts further to past perfect.",tip:"past simple → past perfect in reported speech, especially for something that happened earlier.",multipleChoice:{question:"Which sentence correctly reports what they told you?",correctOption:"They told us that they had missed the bus.",options:["They told us that they had missed the bus.","They told us that they missed the bus.","They told us that they have missed the bus.","They told us that they were missing the bus."],optionExplanations:{"They told us that they had missed the bus.":"Correct! Past simple 'missed' backshifts to past perfect 'had missed'.","They told us that they missed the bus.":"Wrong. The verb should backshift further to past perfect: 'had missed'.","They told us that they have missed the bus.":"Wrong. Present perfect 'have missed' is not the correct backshift here.","They told us that they were missing the bus.":"Wrong. This changes the meaning to an action in progress, not a completed one."}}},{id:"rs-mc-7",topic:"reported-speech",type:"multiple-choice",difficulty:"advanced",sentence:"Tom said to you, 'I can't finish my project without your help.'",grammarRule:"Reported Speech — Combining Tense, Modal and Pronoun Changes",explanation:"Reporting this sentence needs three changes together: 'can't' → 'couldn't', 'my' → 'his' (it's Tom's project), and 'your' → 'my' (you are the one he asked for help).",tip:"Check every word that depends on who is speaking: the modal verb AND every pronoun and possessive.",multipleChoice:{question:"Which sentence correctly reports what Tom said to you?",correctOption:"Tom said that he couldn't finish his project without my help.",options:["Tom said that he couldn't finish his project without my help.","Tom said that he couldn't finish his project without your help.","Tom said that he can't finish his project without my help.","Tom told that he couldn't finish his project without my help."],optionExplanations:{"Tom said that he couldn't finish his project without my help.":"Correct! 'Can't' → 'couldn't', 'my' → 'his' (Tom's project), 'your' → 'my' (you were the one asked for help).","Tom said that he couldn't finish his project without your help.":"Wrong. 'Your' should change to 'my', because you are the person reporting this, and it was your help he needed.","Tom said that he can't finish his project without my help.":"Wrong. 'Can't' must backshift to 'couldn't' after the past reporting verb.","Tom told that he couldn't finish his project without my help.":"Wrong. 'Tell' needs a person: 'told me', not 'told that'."}}},{id:"rs-wt-1",topic:"reported-speech",type:"word-transform",difficulty:"beginner",sentence:"She said that she ___ (feel) great.",grammarRule:"Present Simple → Past Simple in Reported Speech",explanation:"'I feel great' is present simple. In reported speech it backshifts to past simple: felt.",tip:"Present simple always backshifts to past simple after said/told.",wordTransform:{baseWord:"feel",correctAnswer:"felt"}},{id:"rs-wt-2",topic:"reported-speech",type:"word-transform",difficulty:"beginner",sentence:"They told us that they ___ (enjoy) the trip.",grammarRule:"Present Continuous → Past Continuous in Reported Speech",explanation:"'We are enjoying the trip' is present continuous. In reported speech it backshifts to past continuous: were enjoying.",tip:"Present continuous (is/am/are + -ing) → past continuous (was/were + -ing).",wordTransform:{baseWord:"enjoy",correctAnswer:"were enjoying"}},{id:"rs-wt-3",topic:"reported-speech",type:"word-transform",difficulty:"intermediate",sentence:"He said that he ___ (finish) his homework.",grammarRule:"Present Perfect → Past Perfect in Reported Speech",explanation:"'I've finished my homework' is present perfect. In reported speech it backshifts to past perfect: had finished.",tip:"Present perfect → past perfect in reported speech.",wordTransform:{baseWord:"finish",correctAnswer:"had finished"}},{id:"rs-wt-4",topic:"reported-speech",type:"word-transform",difficulty:"intermediate",sentence:"She told me that she ___ (see) Anna at the station.",grammarRule:"Past Simple → Past Perfect in Reported Speech",explanation:"'I saw Anna at the station' is past simple. In reported speech it often backshifts further to past perfect: had seen.",tip:"Past simple can backshift to past perfect in reported speech.",wordTransform:{baseWord:"see",correctAnswer:"had seen"}},{id:"rs-wt-5",topic:"reported-speech",type:"word-transform",difficulty:"intermediate",sentence:"He said that he ___ (have to) work this weekend.",grammarRule:"Have To / Has To → Had To in Reported Speech",explanation:"'I have to work this weekend' uses 'have to'. In reported speech it always backshifts to 'had to'.",tip:"have to / has to → had to, whoever is speaking.",wordTransform:{baseWord:"have to",correctAnswer:"had to"}},{id:"rs-wt-6",topic:"reported-speech",type:"word-transform",difficulty:"advanced",sentence:"He told his manager that he ___ (be) going to resign.",grammarRule:"Am/Is/Are Going To → Was/Were Going To in Reported Speech",explanation:"'I'm going to resign' uses 'am going to'. In reported speech, only the 'be' part changes: was going to.",tip:"am/is/are going to → was/were going to — 'going to' itself never changes.",wordTransform:{baseWord:"be",correctAnswer:"was"}}],S={id:"reported-speech",level:"B1",name:"Reported Speech",description:"Learn how to report what someone said: shifting tenses one step into the past, changing pronouns and possessives, and choosing between say and tell.",lesson:"Lesson 5B",icon:"🗣️",cards:[{id:"rs-card-1",rule:"say vs tell",example:"Mark ___ (tell) his boss that he was running late.",answer:"told",explanation:"'Tell' always needs a person straight after it: tell someone. 'Say' doesn't take a person directly — it uses 'say to someone', or no person at all.",examples:["She told her teacher that she had finished the test.","She said to her teacher that she had finished the test."],ua:"tell + особа (told him); say (to) + особа (said to him) — не «told to»."},{id:"rs-card-2",rule:"present simple → past simple",example:"Maria said that she ___ (enjoy) long walks in the park.",answer:"enjoyed",explanation:"After a past reporting verb like said or told, a present simple verb in direct speech moves back one tense to past simple.",examples:["He said that he worked in a bank.","They said that they lived near the station."],ua:"Present Simple → Past Simple: enjoys → enjoyed."},{id:"rs-card-3",rule:"present continuous → past continuous",example:"He told us that he ___ (wait) for the bus.",answer:"was waiting",explanation:"Present continuous (is/am/are + -ing) in direct speech backshifts to past continuous (was/were + -ing) in reported speech.",examples:["She said that she was cooking dinner.","They told me that they were planning a trip."],ua:"Present Continuous → Past Continuous: is waiting → was waiting."},{id:"rs-card-4",rule:"present perfect → past perfect",example:"She said that she ___ (visit) Paris twice.",answer:"had visited",explanation:"Present perfect (have/has + past participle) in direct speech backshifts to past perfect (had + past participle) in reported speech.",examples:["He told me that he had paid the bill.","They said that they had already left."],ua:"Present Perfect → Past Perfect: has visited → had visited."},{id:"rs-card-5",rule:"past simple → past perfect",example:"He said that he ___ (meet) her the day before.",answer:"had met",explanation:"A past simple verb in direct speech often backshifts one step further to past perfect, to show it happened before the reporting.",examples:["She said that she had called earlier.","They told us that they had arrived before the storm."],ua:"Past Simple → Past Perfect: met → had met."},{id:"rs-card-6",rule:"will → would",example:"She said that she ___ (help) us later.",answer:"would help",explanation:"'Will' in direct speech becomes 'would' in reported speech — the same backshift pattern as other modal verbs.",examples:["He said that he would call back.","They told us that they would arrive soon."],ua:"will → would: 'I will help' → he said he would help."},{id:"rs-card-7",rule:"can → could",example:"He told me that he ___ (swim) very well.",answer:"could swim",explanation:"'Can' in direct speech becomes 'could' in reported speech.",examples:["She said that she could cook well.","They told us that they could finish on time."],ua:"can → could: 'I can swim' → he said he could swim."},{id:"rs-card-8",rule:"have to / has to → had to",example:"She said that she ___ (have to) work late.",answer:"had to",explanation:"'Have to' or 'has to' in direct speech becomes 'had to' in reported speech, just like other present forms moving into the past.",examples:["He told us that he had to leave early.","They said that they had to change their plans."],ua:"have to / has to → had to: завжди одна форма в минулому."},{id:"rs-card-9",rule:"am/is/are going to → was/were going to",example:"She told me that she ___ (be) going to start a new job.",answer:"was",explanation:"'Am/is/are going to' in direct speech becomes 'was/were going to' in reported speech — only the 'be' part changes.",examples:["He said that he was going to call back.","They told us that they were going to move house."],ua:"am/is/are going to → was/were going to: змінюється лише be."},{id:"rs-card-10",rule:"pronouns and possessives change too",example:"Maria said that ___ (my/her) phone was out of battery.",answer:"her",explanation:"Pronouns and possessives change to match who is speaking now, not who originally spoke. Maria said 'my phone' — but when we report her words, it becomes 'her phone'.",examples:["Tom said that his brother had called him.","They said that their flight had been delayed."],ua:"Займенники теж змінюються: «my phone» (Марія) → her phone, коли переказуємо."}],rules:P},A={id:"personal-news",level:"B1",name:"Giving & Responding to News",description:"Practise the phrases for giving good and bad personal news, and responding to other people's news in English.",lesson:"Unit 5C",icon:"📢",cards:[{id:"news-card-1",rule:"Guess what! (giving good news)",example:"___ what! I've just been offered a new job!",answer:"Guess",explanation:"Guess what! is a fixed phrase used to get someone's attention before sharing exciting news. It always introduces good news, never bad.",examples:["Guess what! My sister just had a baby boy.","Guess what! We won the quiz last night."],ua:"«Вгадай що!» — фраза, щоб почати гарну новину: Guess what!"},{id:"news-card-2",rule:"Bad news, I'm afraid (giving bad news)",example:"Bad news, I'm ___ — the match was cancelled.",answer:"afraid",explanation:"We use I'm afraid to softly introduce our own bad news. I'm sorry is for responding to someone else's bad news, not for announcing your own.",examples:["Bad news, I'm afraid - the shop is closed today.","I'm afraid the meeting has been moved."],ua:"Повідомляємо погану новину — I'm afraid, не I'm sorry (те для відповіді)."},{id:"news-card-3",rule:"You won't believe this, but... (good or bad news)",example:"You won't believe ___, but Tom's getting married!",answer:"this",explanation:"This fixed phrase can introduce either good or bad news. It builds a little suspense before the main point.",examples:["You won't believe this, but I lost my phone again.","You won't believe this, but we won the lottery!"],ua:"«Ти не повіриш, але...» підходить і для гарних, і для поганих новин."},{id:"news-card-4",rule:"pleased to tell you (giving good news formally)",example:"We're really ___ (please) to tell you that you got the scholarship.",answer:"pleased",explanation:"Pleased to tell you... introduces good news warmly or formally. Pleased is an adjective here, describing how the speaker feels.",examples:["I'm pleased to tell you the results were excellent.","We're pleased to tell you your order has arrived."],ua:"«Радий повідомити» — I'm pleased to tell you... (pleased — прикметник)."},{id:"news-card-5",rule:"Congratulations! (celebrating good news)",example:"She just got engaged - ___!",answer:"Congratulations",explanation:"Congratulations celebrates any happy event, such as an engagement, a baby or a birthday. Well done! is specifically for something a person worked hard to achieve, like passing a test.",examples:["Congratulations on your new house!","Well done on finishing the marathon!"],ua:"Congratulations — для будь-якої приємної події; Well done — за досягнення."},{id:"news-card-6",rule:"pleased for you (preposition for)",example:"I just heard your good news. I'm so pleased ___ you.",answer:"for",explanation:"Pleased for someone means happy because of their good fortune. The preposition is always for, never with or about.",examples:["I'm so pleased for you - you deserve it!","We're really pleased for Anna and her new job."],ua:"«Я радий за тебе» — pleased for you (завжди for)."},{id:"news-card-7",rule:"What a shame (responding to bad news)",example:"What a ___! I'm sorry you didn't get the part in the play.",answer:"shame",explanation:"What a shame and I'm sorry to hear that both respond sympathetically to bad news. Shame here means disappointment, not embarrassment.",examples:["What a shame you missed the party!","I'm sorry to hear that your flight was cancelled."],ua:"«Як шкода» — What a shame (shame тут = прикрість, не сором)."},{id:"news-card-8",rule:"get married (adjective, not the noun marriage)",example:"My uncle is getting ___ (marry) in the autumn.",answer:"married",explanation:"Married is the adjective used after get and be. Marriage is a noun and cannot follow getting directly.",examples:["My cousin got engaged last weekend.","They got married in a small church."],ua:"Після get — married (прикметник), не marriage (іменник)."},{id:"news-card-9",rule:"pass an exam/test (not win)",example:"It took him three tries, but he finally ___ (pass) his theory exam.",answer:"passed",explanation:"We pass or fail exams and tests. Win is only used for competitions, matches or prizes - never for exams.",examples:["She passed all her university exams.","He failed the test twice before passing."],ua:"Іспити/тести — pass або fail, а не win (win лише для змагань)."},{id:"news-card-10",rule:"have a baby (fixed collocation)",example:"My best friend ___ (have) twins in March, and I can't wait to meet them!",answer:"had",explanation:"Have a baby is the fixed phrase for giving birth. We don't say make or get a baby.",examples:["They had a baby girl in the spring.","My neighbours just had twins!"],ua:"«Народити дитину» — have a baby (не make чи get)."}],rules:[{id:"news-gap-1",topic:"personal-news",type:"gap-fill",difficulty:"beginner",sentence:"___ what! I passed my driving test first time!",grammarRule:"Giving good news — Guess what!",explanation:"'Guess what!' is a fixed phrase used to grab someone's attention before sharing exciting news.",tip:"Guess what! always comes before good news, never bad news.",gapFill:{gapIndex:0,correctAnswer:"Guess",options:["Guess","Know","See","Hear"],correctOptionIndex:0}},{id:"news-gap-2",topic:"personal-news",type:"gap-fill",difficulty:"beginner",sentence:"Bad news, I'm ___. The flight's been delayed.",grammarRule:"Giving bad news — I'm afraid",explanation:"'I'm afraid' softens bad news you are telling someone. 'I'm sorry' is used to respond to someone else's bad news, not to introduce your own.",tip:"Giving bad news: I'm afraid. Responding to bad news: I'm sorry.",gapFill:{gapIndex:3,correctAnswer:"afraid",options:["afraid","sorry","shame","worried"],correctOptionIndex:0}},{id:"news-gap-3",topic:"personal-news",type:"gap-fill",difficulty:"intermediate",sentence:"You won't believe ___, but Maria got engaged yesterday!",grammarRule:"Giving good or bad news — You won't believe this",explanation:"'You won't believe this, but...' can introduce either good or bad news. It builds suspense before the main point.",tip:"This phrase works for both good and bad news — the 'but' leads into either.",gapFill:{gapIndex:3,correctAnswer:"this",options:["this","that","it","so"],correctOptionIndex:0}},{id:"news-gap-4",topic:"personal-news",type:"gap-fill",difficulty:"intermediate",sentence:"My brother ___ a new job, so he's moving to London next month.",grammarRule:"Events and occasions — get a new job",explanation:"'Get a new job' is the fixed collocation for starting work somewhere new. 'Got' is the past simple of 'get'.",tip:"Get a new job, get promoted, get engaged — all use 'get', not 'make' or 'do'.",gapFill:{gapIndex:2,correctAnswer:"got",options:["got","made","did","had"],correctOptionIndex:0}},{id:"news-gap-5",topic:"personal-news",type:"gap-fill",difficulty:"intermediate",sentence:"Wow, congratulations! I'm so pleased ___ you.",grammarRule:"Responding to good news — pleased for you",explanation:"'Pleased for you' always uses the preposition 'for', showing you are happy because of someone else's good fortune.",tip:"I'm pleased/happy for you — always 'for', never 'with' or 'about'.",gapFill:{gapIndex:5,correctAnswer:"for",options:["for","with","to","about"],correctOptionIndex:0}},{id:"news-gap-6",topic:"personal-news",type:"gap-fill",difficulty:"intermediate",sentence:"What a ___! I'm really sorry you lost the match.",grammarRule:"Responding to bad news — What a shame",explanation:"'What a shame' is a fixed sympathetic response to disappointing news. 'Shame' here means a pity, not embarrassment.",tip:"What a shame! = That's a pity! Use it to show sympathy.",gapFill:{gapIndex:2,correctAnswer:"shame",options:["shame","pity","sad","sorry"],correctOptionIndex:0}},{id:"news-error-1",topic:"personal-news",type:"error-spot",difficulty:"beginner",sentence:"Guess that! I finally passed my driving test.",grammarRule:"Giving good news — Guess what!",explanation:"'Guess what!' is the fixed phrase used to introduce exciting news. 'Guess that' is not a real expression.",tip:"Always 'Guess what!', never 'Guess that' or 'Guess this'.",errorSpot:{errorWordIndex:1,wrongWord:"that",correction:"what",reason:"'Guess what!' is the fixed phrase. 'Guess that' is not a real expression.",correctionOptions:["this","what","so","it"]}},{id:"news-error-2",topic:"personal-news",type:"error-spot",difficulty:"beginner",sentence:"I've got some good news for tell you: I'm moving to Spain.",grammarRule:"Giving good news — news to tell you",explanation:"'Good news to tell you' needs the infinitive 'to', not 'for'. The fixed phrase is 'I've got some news to tell you'.",tip:"News to tell you — infinitive 'to', not 'for'.",errorSpot:{errorWordIndex:5,wrongWord:"for",correction:"to",reason:"The fixed phrase uses the infinitive 'to tell you', not 'for tell you'.",correctionOptions:["for","to","at","with"]}},{id:"news-error-3",topic:"personal-news",type:"error-spot",difficulty:"intermediate",sentence:"Bad news, I'm sorry. I lost my phone again.",grammarRule:"Giving bad news — I'm afraid",explanation:"When you are the one giving bad news, say 'I'm afraid'. 'I'm sorry' is for responding to someone else's bad news.",tip:"Giving your own bad news: I'm afraid. Not I'm sorry.",errorSpot:{errorWordIndex:3,wrongWord:"sorry",correction:"afraid",reason:"To introduce your own bad news, use 'I'm afraid', not 'I'm sorry'.",correctionOptions:["sorry","afraid","sad","worried"]}},{id:"news-error-4",topic:"personal-news",type:"error-spot",difficulty:"intermediate",sentence:"I'm so relieved - I finally won my driving test this time!",grammarRule:"Events and occasions — pass a test (not win)",explanation:"We pass or fail exams and tests. 'Win' is only used for competitions, matches or prizes.",tip:"Pass/fail a test; win a competition or match — don't mix them up.",errorSpot:{errorWordIndex:6,wrongWord:"won",correction:"passed",reason:"We pass or fail tests and exams. 'Win' is only for competitions and matches.",correctionOptions:["won","passed","beat","took"]}},{id:"news-error-5",topic:"personal-news",type:"error-spot",difficulty:"intermediate",sentence:"My sister made a baby last month, so now I'm an uncle.",grammarRule:"Events and occasions — have a baby",explanation:"'Have a baby' is the fixed phrase for giving birth. We don't say 'make a baby' in this context.",tip:"Have a baby, not make a baby.",errorSpot:{errorWordIndex:2,wrongWord:"made",correction:"had",reason:"The fixed phrase for giving birth is 'have a baby', not 'make a baby'.",correctionOptions:["made","had","did","got"]}},{id:"news-error-6",topic:"personal-news",type:"error-spot",difficulty:"advanced",sentence:"My cousin's getting marriage next summer - she's so excited!",grammarRule:"Events and occasions — get married",explanation:"'Married' is the adjective used after 'get' and 'be'. 'Marriage' is a noun and cannot follow 'getting' directly.",tip:"Get married (adjective), not get marriage (noun).",errorSpot:{errorWordIndex:3,wrongWord:"marriage",correction:"married",reason:"'Married' is the adjective needed after 'getting'. 'Marriage' is a noun.",correctionOptions:["marriage","married","marry","marrying"]}},{id:"news-mc-1",topic:"personal-news",type:"multiple-choice",difficulty:"beginner",sentence:"A friend just told you: 'I passed my driving test!' Which is the best response?",grammarRule:"Responding to good news",explanation:"'Congratulations! Well done!' celebrates good news and the effort behind it — the natural response to someone's achievement.",tip:"Congratulations! / Well done! — the classic pair of responses to good news.",multipleChoice:{question:"Which response is best?",correctOption:"Congratulations! Well done!",options:["Congratulations! Well done!","What a shame, I'm sorry.","Never mind, it's fine.","I'm really sorry to hear that."],optionExplanations:{"Congratulations! Well done!":"Correct — this celebrates good news and the effort behind it.","What a shame, I'm sorry.":"Wrong — this responds to bad news, not good news.","Never mind, it's fine.":"Wrong — this accepts an apology, it doesn't celebrate news.","I'm really sorry to hear that.":"Wrong — this is a sympathetic response to bad news."}}},{id:"news-mc-2",topic:"personal-news",type:"multiple-choice",difficulty:"beginner",sentence:"You want to introduce some exciting news to a friend. Which phrase fits best?",grammarRule:"Giving good news — Guess what!",explanation:"'Guess what!' followed by 'I've got some amazing news' is the natural way to introduce exciting news to a friend.",tip:"Guess what! + news statement = classic opener for good news.",multipleChoice:{question:"Which phrase is correct?",correctOption:"Guess what! I've got some amazing news.",options:["Guess what! I've got some amazing news.","That's terrible news.","I'm so sorry to hear that.","Never mind, it's fine."],optionExplanations:{"Guess what! I've got some amazing news.":"Correct — this is a natural opener for exciting news.","That's terrible news.":"Wrong — this responds to bad news, it doesn't introduce news.","I'm so sorry to hear that.":"Wrong — this is a sympathetic response, not an opener.","Never mind, it's fine.":"Wrong — this accepts an apology, not an opener for news."}}},{id:"news-mc-3",topic:"personal-news",type:"multiple-choice",difficulty:"intermediate",sentence:"You need to tell a colleague something disappointing. Which phrase introduces it best?",grammarRule:"Giving bad news — I'm afraid",explanation:"'Bad news, I'm afraid' warns the listener that disappointing news is coming, in a gentle way.",tip:"Bad news, I'm afraid — a soft way to introduce bad news.",multipleChoice:{question:"Which phrase is correct?",correctOption:"Bad news, I'm afraid.",options:["Bad news, I'm afraid.","Guess what!","I'm so pleased for you.","Well done!"],optionExplanations:{"Bad news, I'm afraid.":"Correct — this gently introduces disappointing news.","Guess what!":"Wrong — this introduces good news, not bad news.","I'm so pleased for you.":"Wrong — this responds to someone else's good news.","Well done!":"Wrong — this celebrates an achievement, not bad news."}}},{id:"news-mc-4",topic:"personal-news",type:"multiple-choice",difficulty:"intermediate",sentence:"A colleague says: 'I'm so sorry, I failed my exam again.' Which response fits best?",grammarRule:"Responding to bad news",explanation:"'What a shame. I'm really sorry to hear that' shows sympathy for someone else's disappointing news.",tip:"What a shame / I'm sorry to hear that — sympathetic responses to bad news.",multipleChoice:{question:"Which response is best?",correctOption:"What a shame. I'm really sorry to hear that.",options:["What a shame. I'm really sorry to hear that.","That's amazing! Congratulations!","I'm so pleased for you.","Well done!"],optionExplanations:{"What a shame. I'm really sorry to hear that.":"Correct — this shows sympathy for disappointing news.","That's amazing! Congratulations!":"Wrong — this celebrates good news, not bad news.","I'm so pleased for you.":"Wrong — this responds to good news, not failure.","Well done!":"Wrong — this celebrates an achievement, not a failure."}}},{id:"news-mc-5",topic:"personal-news",type:"multiple-choice",difficulty:"intermediate",sentence:"Tom asked for more responsibility, and his boss gave him a higher position at the same company. Which sentence describes this correctly?",grammarRule:"Events and occasions — get promoted vs get a new job",explanation:"'Get promoted' means moving to a higher position at the same company. 'Get a new job' usually means starting work somewhere different.",tip:"Promoted = higher role, same company. New job = different job.",multipleChoice:{question:"Which option is correct?",correctOption:"He got promoted.",options:["He got promoted.","He got a new job.","He won a competition.","He graduated."],optionExplanations:{"He got promoted.":"Correct — a higher position at the same company is a promotion.","He got a new job.":"Wrong — he stayed at the same company, so it isn't a new job.","He won a competition.":"Wrong — nothing here is a competition.","He graduated.":"Wrong — graduation is for finishing a course of study."}}},{id:"news-mc-6",topic:"personal-news",type:"multiple-choice",difficulty:"intermediate",sentence:"You're not sure if your friend will think your news is good or bad. Which opener fits best?",grammarRule:"Giving good or bad news — You won't believe this",explanation:"'You won't believe this, but...' works for news that could be surprising in either direction, good or bad.",tip:"Use this opener when you're not sure how the news will be received.",multipleChoice:{question:"Which phrase is correct?",correctOption:"You won't believe this, but...",options:["You won't believe this, but...","I'm really pleased to tell you...","Well done!","What a shame."],optionExplanations:{"You won't believe this, but...":"Correct — this opener suits news that could go either way.","I'm really pleased to tell you...":"Wrong — this only introduces good news.","Well done!":"Wrong — this is a response to good news, not an opener.","What a shame.":"Wrong — this is a response to bad news, not an opener."}}},{id:"news-mc-7",topic:"personal-news",type:"multiple-choice",difficulty:"advanced",sentence:"A friend tells you their grandmother is in hospital. Which is the correct sympathetic response?",grammarRule:"Responding to bad news vs apologising",explanation:"'I'm sorry to hear that' shows sympathy for someone else's bad news. 'I'm sorry I'm late' and 'I apologise for...' are apologies for your own mistakes, not sympathy for someone else's news.",tip:"Sympathy for their news: I'm sorry to hear that. Apology for your own fault: I'm sorry I...",multipleChoice:{question:"Which option is correct?",correctOption:"I'm so sorry to hear that.",options:["I'm so sorry to hear that.","I'm sorry I'm late.","Sorry to bother you.","I apologise for the mistake."],optionExplanations:{"I'm so sorry to hear that.":"Correct — this shows sympathy for someone else's bad news.","I'm sorry I'm late.":"Wrong — this apologises for your own lateness, not sympathy for their news.","Sorry to bother you.":"Wrong — this apologises for interrupting someone, not sympathy.","I apologise for the mistake.":"Wrong — this apologises for your own error, not sympathy for their news."}}},{id:"news-wt-1",topic:"personal-news",type:"word-transform",difficulty:"beginner",sentence:"He felt so proud when he finally ___ (pass) his driving test last week.",grammarRule:"Past Simple — pass a test",explanation:"'Passed' is the regular past simple form of 'pass'. We pass or fail exams and tests.",tip:"Pass → passed (regular -ed past simple).",wordTransform:{baseWord:"pass",correctAnswer:"passed"}},{id:"news-wt-2",topic:"personal-news",type:"word-transform",difficulty:"beginner",sentence:"I'm so excited - I've just ___ (win) two tickets to the festival!",grammarRule:"Present Perfect — win (irregular past participle)",explanation:"'Won' is the irregular past participle of 'win', used after 'have/has' in the present perfect.",tip:"Win → won (irregular past participle), not 'winned'.",wordTransform:{baseWord:"win",correctAnswer:"won"}},{id:"news-wt-3",topic:"personal-news",type:"word-transform",difficulty:"intermediate",sentence:"My sister ___ (have) a baby next spring - she's due in April.",grammarRule:"Present Continuous for future arrangements — have a baby",explanation:"To talk about a planned future event like an expected birth, use the present continuous: is/are + having.",tip:"Present continuous for fixed future plans: She is having a baby in April.",wordTransform:{baseWord:"have",correctAnswer:"is having"}},{id:"news-wt-4",topic:"personal-news",type:"word-transform",difficulty:"intermediate",sentence:"My neighbours got ___ (engage) last weekend after years together.",grammarRule:"Past participle as adjective — get engaged",explanation:"'Engaged' is the past participle used as an adjective after 'get'. It describes the state of having agreed to marry.",tip:"Get engaged, get married — 'get' + past participle adjective.",wordTransform:{baseWord:"engage",correctAnswer:"engaged"}},{id:"news-wt-5",topic:"personal-news",type:"word-transform",difficulty:"intermediate",sentence:"I've just ___ (lose) my job, so I'm updating my CV tonight.",grammarRule:"Present Perfect — lose (irregular past participle)",explanation:"'Lost' is the irregular past participle of 'lose', used after 'have/has' for a recent event with present relevance.",tip:"Lose → lost (irregular). I've lost my job.",wordTransform:{baseWord:"lose",correctAnswer:"lost"}},{id:"news-wt-6",topic:"personal-news",type:"word-transform",difficulty:"advanced",sentence:"We're all really ___ (excite) about Maria's new baby.",grammarRule:"Adjective -ed form — excited",explanation:"'Excited' is the -ed adjective describing how people feel. Use it after 'be/feel', not the -ing form, which describes the thing causing the feeling.",tip:"Excited (how you feel) vs exciting (what causes the feeling).",wordTransform:{baseWord:"excite",correctAnswer:"excited"}},{id:"news-match-1",topic:"personal-news",type:"sentence-match",difficulty:"beginner",sentence:"Match each way of giving news to its correct ending.",grammarRule:"Giving good and bad news — fixed phrases",explanation:"These are fixed phrases used to introduce good or bad news. Each beginning has only one natural, correct ending.",tip:"Learn these openers as whole chunks, not word by word.",sentenceMatch:{pairs:[{beginning:"Guess",ending:"what!"},{beginning:"I've got some good news",ending:"to tell you."},{beginning:"Bad news,",ending:"I'm afraid."},{beginning:"You won't believe",ending:"this, but..."}]}},{id:"news-match-2",topic:"personal-news",type:"sentence-match",difficulty:"beginner",sentence:"Match each response to news to its correct ending.",grammarRule:"Responding to good and bad news — fixed phrases",explanation:"These are fixed phrases used to respond to someone else's news. Each beginning has only one standard, correct ending.",tip:"'I'm so pleased for you', 'That's wonderful news!', 'What a shame' and 'I'm really sorry to hear that' are all fixed phrases.",sentenceMatch:{pairs:[{beginning:"I'm so pleased",ending:"for you."},{beginning:"That's wonderful",ending:"news!"},{beginning:"What a",ending:"shame."},{beginning:"I'm really sorry",ending:"to hear that."}]}}]},R=[{id:"pred-gap-1",topic:"future-predictions",type:"gap-fill",difficulty:"beginner",sentence:"I'm sure we ___ enjoy the concert tonight.",grammarRule:"will — confident prediction",explanation:"'I'm sure' shows the speaker feels certain about the future, so we use 'will'.",tip:"I'm sure + will = a confident prediction.",gapFill:{gapIndex:3,correctAnswer:"will",options:["will","might","won't","are going to"],correctOptionIndex:0}},{id:"pred-gap-2",topic:"future-predictions",type:"gap-fill",difficulty:"beginner",sentence:"He's very reliable, so I'm sure he ___ let us down.",grammarRule:"won't — confident negative prediction",explanation:"'Won't' (will not) makes a confident negative prediction — we are sure something will not happen.",tip:"Reliable + sure = won't let you down.",gapFill:{gapIndex:7,correctAnswer:"won't",options:["won't","might not","doesn't","isn't"],correctOptionIndex:0}},{id:"pred-gap-3",topic:"future-predictions",type:"gap-fill",difficulty:"intermediate",sentence:"I haven't checked the schedule, so we ___ be free on Friday.",grammarRule:"might — uncertain prediction",explanation:"'Might' shows we are not sure about the future — it's a possibility, not a certainty.",tip:"Haven't decided/checked yet = might, not will.",gapFill:{gapIndex:7,correctAnswer:"might",options:["might","will","won't","are"],correctOptionIndex:0}},{id:"pred-gap-4",topic:"future-predictions",type:"gap-fill",difficulty:"intermediate",sentence:"I'm not sure about my plans, so I ___ come to the party.",grammarRule:"might not — uncertain negative prediction",explanation:"'Might not' shows it's possible something won't happen, but we can't be certain either way.",tip:"Not sure = might not, a softer, less certain negative than won't.",gapFill:{gapIndex:8,correctAnswer:"might not",options:["might not","won't","don't","am not"],correctOptionIndex:0}},{id:"pred-gap-5",topic:"future-predictions",type:"gap-fill",difficulty:"intermediate",sentence:"Look at those grey clouds — it ___ rain any minute.",grammarRule:"be going to — evidence-based prediction",explanation:"We use 'be going to' when we can see evidence right now that something will happen — here, the grey clouds.",tip:"Evidence you can see now (clouds, a queue, a mess) = going to, not will.",gapFill:{gapIndex:7,correctAnswer:"is going to",options:["is going to","will","might","was going to"],correctOptionIndex:0}},{id:"pred-gap-6",topic:"future-predictions",type:"gap-fill",difficulty:"advanced",sentence:"Experts say screens ___ become much thinner in the next few years.",grammarRule:"will — general prediction based on opinion",explanation:"A general prediction about the distant future, based on someone's opinion or expertise rather than visible evidence, uses 'will'.",tip:"Experts say/believe/think + will — an opinion-based prediction, not something you can see happening now.",gapFill:{gapIndex:3,correctAnswer:"will",options:["will","is going to","might","was"],correctOptionIndex:0}},{id:"pred-error-1",topic:"future-predictions",type:"error-spot",difficulty:"beginner",sentence:"She will probably passes the exam next week.",grammarRule:"will + base verb",explanation:"After 'will', the verb always stays in its base form — never add -s, even for 'she/he/it'.",errorSpot:{errorWordIndex:3,wrongWord:"passes",correction:"pass",reason:"After 'will', use the base verb with no -s: 'She will probably pass the exam.'",correctionOptions:["pass","passes","passed","passing"]}},{id:"pred-error-2",topic:"future-predictions",type:"error-spot",difficulty:"beginner",sentence:"It's going to raining later.",grammarRule:"be going to + base verb",explanation:"After 'going to', the verb always stays in its base form, never -ing: 'It's going to rain.'",errorSpot:{errorWordIndex:3,wrongWord:"raining",correction:"rain",reason:"'Going to' is followed by the base verb, not the -ing form: 'It's going to rain later.'",correctionOptions:["rain","raining","rains","rained"]}},{id:"pred-error-3",topic:"future-predictions",type:"error-spot",difficulty:"intermediate",sentence:"She never forgets anything, so I'm sure she will forget your birthday.",grammarRule:"won't — confident negative prediction",explanation:"Since she never forgets anything, the confident prediction should be negative: 'won't', not 'will'.",errorSpot:{errorWordIndex:8,wrongWord:"will",correction:"won't",reason:"The context (she never forgets) needs a confident NEGATIVE prediction: 'I'm sure she won't forget.'",correctionOptions:["won't","can't","doesn't","isn't"]}},{id:"pred-error-4",topic:"future-predictions",type:"error-spot",difficulty:"intermediate",sentence:"I haven't decided about the trip, so I will go next week.",grammarRule:"might — uncertain prediction",explanation:"'Haven't decided' shows uncertainty, so the prediction should use 'might', not the confident 'will'.",errorSpot:{errorWordIndex:8,wrongWord:"will",correction:"might",reason:"Uncertainty ('haven't decided') needs 'might': 'so I might go next week.'",correctionOptions:["might","will","can","must"]}},{id:"pred-error-5",topic:"future-predictions",type:"error-spot",difficulty:"intermediate",sentence:"They is going to visit us next weekend.",grammarRule:"be going to — subject-verb agreement",explanation:"'Be' must agree with the subject: 'they' takes 'are', not 'is'.",errorSpot:{errorWordIndex:1,wrongWord:"is",correction:"are",reason:"The plural subject 'they' needs 'are going to', not 'is going to'.",correctionOptions:["are","is","be","were"]}},{id:"pred-error-6",topic:"future-predictions",type:"error-spot",difficulty:"advanced",sentence:"I don't think it might rain later.",grammarRule:"don't think + will — negative belief",explanation:"To say you don't believe something will happen, use 'don't think ... will', not 'might' — 'might' is already uncertain, so combining it with 'don't think' doesn't work naturally.",errorSpot:{errorWordIndex:4,wrongWord:"might",correction:"will",reason:"'I don't think it will rain' is the natural way to express a negative prediction — not 'I don't think it might rain'.",correctionOptions:["will","might","would","could"]}},{id:"pred-mc-1",topic:"future-predictions",type:"multiple-choice",difficulty:"beginner",sentence:"Choose the sentence that shows the speaker feels certain about the future:",grammarRule:"will — confident prediction",explanation:"'Will' is used when the speaker feels certain about a prediction, often signalled by 'I'm sure'.",tip:"I'm sure + will = certainty.",multipleChoice:{question:"Which sentence is correct?",correctOption:"I'm sure the train will arrive on time.",options:["I'm sure the train will arrive on time.","The train might arrive on time.","The train could arrive on time.","Perhaps the train will arrive on time."],optionExplanations:{"I'm sure the train will arrive on time.":"Correct! 'I'm sure' + 'will' expresses a confident prediction.","The train might arrive on time.":"Wrong. 'Might' expresses uncertainty, not confidence.","The train could arrive on time.":"Wrong. 'Could' here suggests possibility, not certainty.","Perhaps the train will arrive on time.":"Wrong. 'Perhaps' signals doubt, which contradicts feeling certain."}}},{id:"pred-mc-2",topic:"future-predictions",type:"multiple-choice",difficulty:"beginner",sentence:"Choose the sentence that correctly uses 'be going to' for a prediction based on evidence you can see right now:",grammarRule:"be going to — evidence-based prediction",explanation:"'Be going to' is used when there is visible evidence right now that something will happen.",tip:"Look at the sky — it's going to snow! Evidence you can see now = going to.",multipleChoice:{question:"Which sentence is correct?",correctOption:"Look at the sky – it's going to snow!",options:["Look at the sky – it's going to snow!","Look at the sky – it will snow probably!","Look at the sky – it might going to snow!","Look at the sky – it's will snow!"],optionExplanations:{"Look at the sky – it's going to snow!":"Correct! Visible evidence (the sky) + 'be going to' is the natural combination.","Look at the sky – it will snow probably!":"Wrong. 'Probably' must come before 'will', not after: 'it will probably snow'.","Look at the sky – it might going to snow!":"Wrong. 'Might' and 'going to' cannot be combined like this.","Look at the sky – it's will snow!":"Wrong. 'Is' and 'will' cannot be used together."}}},{id:"pred-mc-3",topic:"future-predictions",type:"multiple-choice",difficulty:"intermediate",sentence:"A: 'Why do you have your umbrella?' You can see dark clouds outside. Choose the best reply:",grammarRule:"be going to vs will — evidence vs opinion",explanation:"Since the dark clouds are visible evidence right now, 'be going to' is the natural choice for this prediction.",tip:"Visible evidence right now (dark clouds) = going to, not will.",multipleChoice:{question:"Which reply fits best, given she can see dark clouds right now?",correctOption:"Because I think it's going to rain.",options:["Because I think it's going to rain.","Because it might have rained.","Because it has rained.","Because it was going to rain."],optionExplanations:{"Because I think it's going to rain.":"Correct! Evidence visible now (dark clouds) + 'be going to' makes a natural prediction.","Because it might have rained.":"Wrong. This is about the past, not a prediction about the future.","Because it has rained.":"Wrong. Present perfect describes something that already happened.","Because it was going to rain.":"Wrong. Past tense doesn't fit a prediction made right now."}}},{id:"pred-mc-4",topic:"future-predictions",type:"multiple-choice",difficulty:"intermediate",sentence:"Your friend asks if you're coming to the party, but you haven't decided yet. Choose the best reply:",grammarRule:"might — uncertain prediction",explanation:"'Might' is the correct choice when you genuinely haven't decided — it expresses a real possibility, not a certainty.",tip:"Haven't decided yet = might, never will or won't.",multipleChoice:{question:"Which reply fits best?",correctOption:"I might come – I haven't decided yet.",options:["I might come – I haven't decided yet.","I will come – I haven't decided yet.","I won't come – I haven't decided yet.","I'm going to come – I haven't decided yet."],optionExplanations:{"I might come – I haven't decided yet.":"Correct! 'Might' matches the genuine uncertainty of not having decided.","I will come – I haven't decided yet.":"Wrong. 'Will' expresses certainty, which contradicts 'haven't decided'.","I won't come – I haven't decided yet.":"Wrong. 'Won't' is also a confident prediction, which contradicts the uncertainty.","I'm going to come – I haven't decided yet.":"Wrong. 'Going to' suggests a firm plan, which contradicts not having decided."}}},{id:"pred-mc-5",topic:"future-predictions",type:"multiple-choice",difficulty:"intermediate",sentence:"Choose the grammatically correct sentence:",grammarRule:"definitely/probably + won't — word order before won't",explanation:"'Definitely' and 'probably' come immediately before 'won't', never after it.",tip:"Probably/definitely + won't — the adverb always comes right before 'won't'.",multipleChoice:{question:"Which sentence is correct?",correctOption:"She definitely won't be late – she's never late.",options:["She definitely won't be late – she's never late.","She won't definitely be late – she's never late.","She don't definitely won't be late.","She definitely not will be late."],optionExplanations:{"She definitely won't be late – she's never late.":"Correct! 'Definitely' comes right before 'won't'.","She won't definitely be late – she's never late.":"Wrong. The adverb must come before 'won't', not after it.","She don't definitely won't be late.":"Wrong. This has a double negative and incorrect auxiliary 'don't'.","She definitely not will be late.":"Wrong. 'Not' must attach to 'will' as 'won't', not stand alone before it."}}},{id:"pred-mc-6",topic:"future-predictions",type:"multiple-choice",difficulty:"intermediate",sentence:"Choose the sentence that makes a general prediction based on opinion, not something you can see happening right now:",grammarRule:"will vs be going to — opinion vs visible evidence",explanation:"'Will' is used for general predictions based on opinion or belief about the future, without visible evidence right now.",tip:"An opinion about the distant future = will. Visible evidence right now = going to.",multipleChoice:{question:"Which sentence is correct?",correctOption:"I think robots will do more jobs in the future.",options:["I think robots will do more jobs in the future.","Look, the robot is going to fall over!","The machine is going to break any second.","Watch out, it's going to explode!"],optionExplanations:{"I think robots will do more jobs in the future.":"Correct! A general opinion about the future, with no visible evidence right now, uses 'will'.","Look, the robot is going to fall over!":"Wrong. 'Look' signals visible evidence right now, which needs 'going to'.","The machine is going to break any second.":"Wrong. This describes something you can see happening right now.","Watch out, it's going to explode!":"Wrong. 'Watch out' signals immediate visible danger, which needs 'going to'."}}},{id:"pred-mc-7",topic:"future-predictions",type:"multiple-choice",difficulty:"advanced",sentence:"Choose the grammatically correct sentence:",grammarRule:"probably/definitely + be going to — word order",explanation:"With 'be going to', 'probably' and 'definitely' go between 'be' and 'going to', not inside or after the phrase.",tip:"He's probably going to be late — the adverb sits between 'be' and 'going to'.",multipleChoice:{question:"Which sentence is correct?",correctOption:"He's probably going to be late again.",options:["He's probably going to be late again.","He's going probably to be late again.","He's going to probably be late again.","He probably's going to be late again."],optionExplanations:{"He's probably going to be late again.":"Correct! 'Probably' sits between 'be' and 'going to'.","He's going probably to be late again.":"Wrong. This breaks up 'going to' in the wrong place.","He's going to probably be late again.":"Wrong. 'Probably' belongs before 'going to', not after it.","He probably's going to be late again.":"Wrong. 'Probably's' is not a valid contraction."}}},{id:"pred-wt-1",topic:"future-predictions",type:"word-transform",difficulty:"beginner",sentence:"I ___ (call) you as soon as I arrive.",grammarRule:"will — promise / confident prediction",explanation:"A confident promise about the future uses 'will' + base verb.",tip:"Promises and confident predictions: will + base verb.",wordTransform:{baseWord:"call",correctAnswer:"will call"}},{id:"pred-wt-2",topic:"future-predictions",type:"word-transform",difficulty:"beginner",sentence:"They've lost their three best players, so they ___ (win) the match tonight.",grammarRule:"won't — confident negative prediction",explanation:"Strong evidence of a bad outcome leads to a confident negative prediction with 'won't'.",tip:"Confident 'no' about the future: won't + base verb.",wordTransform:{baseWord:"win",correctAnswer:"won't win"}},{id:"pred-wt-3",topic:"future-predictions",type:"word-transform",difficulty:"intermediate",sentence:"I haven't decided yet, but I ___ (go) to the gym later.",grammarRule:"might — uncertain prediction",explanation:"'Might' + base verb expresses a real possibility when the speaker hasn't decided yet.",tip:"Haven't decided = might + base verb.",wordTransform:{baseWord:"go",correctAnswer:"might go"}},{id:"pred-wt-4",topic:"future-predictions",type:"word-transform",difficulty:"intermediate",sentence:"Look at those clouds – it ___ (rain) soon.",grammarRule:"be going to — evidence-based prediction",explanation:"Visible evidence (the clouds) right now calls for 'be going to' + base verb.",tip:"Evidence you can see now: is/are going to + base verb.",wordTransform:{baseWord:"rain",correctAnswer:"is going to rain"}},{id:"pred-wt-5",topic:"future-predictions",type:"word-transform",difficulty:"intermediate",sentence:"I'm not sure about dinner yet – I ___ (cook) tonight.",grammarRule:"might not — uncertain negative prediction",explanation:"'Might not' + base verb expresses genuine uncertainty about a negative outcome.",tip:"Not sure + negative idea = might not + base verb.",wordTransform:{baseWord:"cook",correctAnswer:"might not cook"}},{id:"pred-wt-6",topic:"future-predictions",type:"word-transform",difficulty:"advanced",sentence:"She's worked so hard all year, so she ___ (pass) her final exams.",grammarRule:"definitely + going to / will — strong confident prediction",explanation:"'Definitely' with 'be going to' or 'will' expresses the strongest level of confidence in a prediction.",tip:"Strongest confidence: definitely + going to, or definitely + will.",wordTransform:{baseWord:"pass",correctAnswer:"is definitely going to pass",alternativeAnswers:["will definitely pass"]}}],q={id:"future-predictions",level:"B1",name:"Predictions: will, might & be going to",description:"Practise making predictions about the future with will, might and be going to, and learn where probably and definitely go in the sentence.",lesson:"Unit 5D",icon:"🔮",cards:[{id:"pred-card-1",rule:"will — confident prediction",example:"I'm sure the team ___ (win) tonight.",answer:"will win",explanation:"We use will when we feel certain about a prediction, often after phrases like I'm sure or I think.",examples:["I'm sure she will get the job.","I think ticket prices will go up next year."],ua:"will — впевнений прогноз: I'm sure she will win («я впевнений, що...»)."},{id:"pred-card-2",rule:"won't — confident negative prediction",example:"He's very organised, so he ___ (forget) the meeting.",answer:"won't forget",explanation:"Won't (will not) makes a confident negative prediction — we are sure something will not happen.",examples:["Don't worry, we won't be late.","I'm sure she won't mind waiting a few minutes."],ua:"won't — впевнений прогноз «не»: I'm sure he won't be late."},{id:"pred-card-3",rule:"might — uncertain prediction",example:"We haven't decided yet, so we ___ (go) camping this summer.",answer:"might go",explanation:"Might shows we are not sure about a prediction — it's a possibility, not a certainty.",examples:["They might win the game, but they might not.","I might take the early train tomorrow."],ua:"might — можливість, коли не впевнені: We might go («можливо, підемо»)."},{id:"pred-card-4",rule:"might not — uncertain negative prediction",example:"I'm feeling ill, so I ___ (come) to work tomorrow.",answer:"might not come",explanation:"Might not shows it's possible something won't happen, but we can't be certain either way.",examples:["She might not finish the report today.","We might not have time to visit everyone."],ua:"might not — можливо, що ні: I might not come («можливо, я не прийду»)."},{id:"pred-card-5",rule:"be going to — evidence-based prediction",example:"Look at those dark clouds — it ___ (will / going to) rain soon.",answer:"is going to",explanation:"We use be going to when we can see evidence right now that something will happen.",examples:["Look out, that glass is going to fall off the table!","She's exhausted — she's going to sleep all weekend."],ua:"be going to — прогноз на основі доказів зараз: it's going to rain!"},{id:"pred-card-6",rule:"will + probably/definitely — adverb after will",example:"She's a great student, so she ___ (pass) all her exams.",answer:"will probably pass",explanation:"Probably and definitely usually come straight after will, not before it: she'll probably pass, not she probably will pass.",examples:["He'll definitely be late — he always is.","They'll probably arrive before lunch."],ua:"probably/definitely стоять одразу після will: she'll probably pass."},{id:"pred-card-7",rule:"definitely/probably + won't — before won't",example:"He's missed the bus three times this week, so he ___ (be) on time today.",answer:"definitely won't be",explanation:"With won't, probably and definitely come before it, not after: she probably won't call, not she won't probably call.",examples:["I definitely won't be able to make the meeting.","She probably won't call again tonight."],ua:"З won't ці слова йдуть ПЕРЕД ним: she probably won't call."},{id:"pred-card-8",rule:"probably/definitely with be going to",example:"She's running really late, so she ___ (miss) the bus.",answer:"is probably going to miss",explanation:"We can also use probably and definitely with be going to, placed between be and going to.",examples:["He's definitely not going to meet us there.","We're probably going to be late for the film."],ua:"З be going to ці слова стоять між be і going to: she's probably going to miss it."}],rules:R},C=[{id:"ut-gap-1",topic:"used-to",type:"gap-fill",difficulty:"beginner",sentence:"As a child, I ___ collect toy cars.",grammarRule:"used to — Past Habit, Affirmative",explanation:"'Used to' + infinitive describes a past habit that is no longer true. The form is the same for every subject: I/you/he/she/we/they used to.",tip:"used to + base verb = a habit in the past that has stopped.",gapFill:{gapIndex:4,correctAnswer:"used to",options:["used to","use to","was used to","using"],correctOptionIndex:0}},{id:"ut-gap-2",topic:"used-to",type:"gap-fill",difficulty:"beginner",sentence:"She ___ live in a small village before she moved to the city.",grammarRule:"used to — Past State",explanation:"'Used to' also describes a past state (where someone lived, what they owned, how they felt) that is no longer the case.",tip:"used to can describe a past state too, not just a repeated action: used to live, used to have, used to be.",gapFill:{gapIndex:1,correctAnswer:"used to",options:["used to","uses to","use to","was used"],correctOptionIndex:0}},{id:"ut-gap-3",topic:"used-to",type:"gap-fill",difficulty:"intermediate",sentence:"I ___ to like vegetables when I was young, but now I love them.",grammarRule:"used to — Negative Form",explanation:"The negative of 'used to' is 'didn't use to' — note there is no 'd' in 'use' once 'didn't' carries the past tense.",tip:"Negative: didn't use to (not didn't used to) — the 'd' moves to 'did'.",gapFill:{gapIndex:1,correctAnswer:"didn't use",options:["didn't use","didn't used","don't used","not used"],correctOptionIndex:0}},{id:"ut-gap-4",topic:"used-to",type:"gap-fill",difficulty:"intermediate",sentence:"___ you use to play an instrument when you were at school?",grammarRule:"used to — Question Form",explanation:"Questions with 'used to' are formed with 'did' + subject + 'use to' + infinitive — again, no 'd' on 'use' after 'did'.",tip:"Question: Did you use to...? The 'd' belongs to 'did', never to 'use'.",gapFill:{gapIndex:0,correctAnswer:"Did",options:["Did","Used","Do","Were"],correctOptionIndex:0}},{id:"ut-gap-5",topic:"used-to",type:"gap-fill",difficulty:"intermediate",sentence:"Last year, our class ___ to a museum for a school trip.",grammarRule:"used to vs Past Simple — One-off Events",explanation:"'Used to' is wrong for something that happened only once, a specific number of times, or for a specific length of time — the past simple is correct there instead.",tip:"A single event or a stated number of times/years → past simple, never used to.",gapFill:{gapIndex:4,correctAnswer:"went",options:["went","used to go","use to go","was going"],correctOptionIndex:0}},{id:"ut-gap-6",topic:"used-to",type:"gap-fill",difficulty:"advanced",sentence:"A: Do you still play tennis every day? B: No, I ___, but I don't anymore.",grammarRule:"used to — Short Answer (Verb Omitted)",explanation:"In spoken English, the verb after 'used to' is often left out, especially in short answers: 'I used to' on its own means 'I used to do that'.",tip:"Short answers can stop at 'used to' — the activity is understood from the question.",gapFill:{gapIndex:11,correctAnswer:"used to",options:["used to","used","use to","did use to"],correctOptionIndex:0}},{id:"ut-error-1",topic:"used-to",type:"error-spot",difficulty:"beginner",sentence:"He use to draw every day at school.",grammarRule:"used to — Spelling of the Affirmative",explanation:"The affirmative form is always 'used to', with a 'd' — 'use to' on its own is never correct in an affirmative sentence.",errorSpot:{errorWordIndex:1,wrongWord:"use",correction:"used",reason:"Affirmative 'used to' always has the 'd': 'He used to draw every day at school.'",correctionOptions:["used","use","uses","using"]}},{id:"ut-error-2",topic:"used-to",type:"error-spot",difficulty:"beginner",sentence:"She didn't used to eat meat.",grammarRule:"used to — No 'd' After didn't",explanation:"Once 'didn't' carries the past tense, 'use' stays in its base form — 'didn't used to' is a common mistake.",errorSpot:{errorWordIndex:2,wrongWord:"used",correction:"use",reason:"After 'didn't', drop the 'd': 'She didn't use to eat meat.'",correctionOptions:["use","used","uses","using"]}},{id:"ut-error-3",topic:"used-to",type:"error-spot",difficulty:"intermediate",sentence:"Did you used to live in Paris?",grammarRule:"used to — No 'd' After did",explanation:"The same rule applies to questions: once 'did' carries the past tense, 'use' loses its 'd'.",errorSpot:{errorWordIndex:2,wrongWord:"used",correction:"use",reason:"After 'did', drop the 'd': 'Did you use to live in Paris?'",correctionOptions:["use","used","uses","using"]}},{id:"ut-error-4",topic:"used-to",type:"error-spot",difficulty:"intermediate",sentence:"She used to goes to the gym every day.",grammarRule:"used to + Base Verb Form",explanation:"'Used to' is always followed by the base form of the verb — never a form with -s, -ing or the past tense.",errorSpot:{errorWordIndex:3,wrongWord:"goes",correction:"go",reason:"After 'used to', use the base verb: 'She used to go to the gym every day.'",correctionOptions:["go","goes","going","went"]}},{id:"ut-error-5",topic:"used-to",type:"error-spot",difficulty:"intermediate",sentence:"He used to playing football every weekend.",grammarRule:"used to + Base Verb Form — Not -ing",explanation:"'Used to' is never followed by an -ing form, even though it looks a little like a continuous structure — the base verb is required.",errorSpot:{errorWordIndex:3,wrongWord:"playing",correction:"play",reason:"After 'used to', use the base verb, not -ing: 'He used to play football every weekend.'",correctionOptions:["play","playing","plays","played"]}},{id:"ut-error-6",topic:"used-to",type:"error-spot",difficulty:"advanced",sentence:"They used to lived in Berlin when they were young.",grammarRule:"used to + Base Verb Form — Not Past Tense",explanation:"'Used to' already carries the past meaning, so the verb after it must stay in the base form — it is never also put into the past tense.",errorSpot:{errorWordIndex:3,wrongWord:"lived",correction:"live",reason:"After 'used to', use the base verb, not the past tense: 'They used to live in Berlin when they were young.'",correctionOptions:["live","lived","living","lives"]}},{id:"ut-mc-1",topic:"used-to",type:"multiple-choice",difficulty:"beginner",sentence:"Choose the correct sentence about a past habit that has stopped:",grammarRule:"used to — Basic Meaning",explanation:"'Used to' describes a habit or state in the past that is usually no longer true now.",tip:"used to + infinitive = true in the past, not true now.",multipleChoice:{question:"Which sentence is correct?",correctOption:"He used to play the guitar, but he gave it up years ago.",options:["He used to play the guitar, but he gave it up years ago.","He use to playing the guitar, but he gave it up years ago.","He is used to play the guitar, but he gave it up years ago.","He used to played the guitar, but he gave it up years ago."],optionExplanations:{"He used to play the guitar, but he gave it up years ago.":"Correct! 'used to' + base verb describes a past habit that has stopped.","He use to playing the guitar, but he gave it up years ago.":"Wrong. Affirmative needs 'used', and 'to' is followed by the base verb, not '-ing'.","He is used to play the guitar, but he gave it up years ago.":"Wrong. 'Is used to' (+ -ing) means 'is accustomed to', a different structure entirely.","He used to played the guitar, but he gave it up years ago.":"Wrong. 'used to' is always followed by the base verb, not the past form 'played'."}}},{id:"ut-mc-2",topic:"used-to",type:"multiple-choice",difficulty:"beginner",sentence:"Choose the sentence with the correct negative form:",grammarRule:"used to — Negative Form",explanation:"The negative of 'used to' is 'didn't use to' (no 'd' on 'use'). In spoken English, 'never used to' is also common.",tip:"didn't use to — remember the missing 'd'.",multipleChoice:{question:"Which sentence is correct?",correctOption:"I didn't use to enjoy reading, but now I read every night.",options:["I didn't use to enjoy reading, but now I read every night.","I didn't used to enjoy reading, but now I read every night.","I don't used to enjoy reading, but now I read every night.","I not used to enjoy reading, but now I read every night."],optionExplanations:{"I didn't use to enjoy reading, but now I read every night.":"Correct! After 'didn't', 'use' loses its 'd'.","I didn't used to enjoy reading, but now I read every night.":"Wrong. 'didn't' already carries the past tense, so 'use' should not have a 'd'.","I don't used to enjoy reading, but now I read every night.":"Wrong. 'used to' is only a past form — the auxiliary must be 'did', not 'do'.","I not used to enjoy reading, but now I read every night.":"Wrong. The negative needs the auxiliary 'didn't', not just 'not'."}}},{id:"ut-mc-3",topic:"used-to",type:"multiple-choice",difficulty:"intermediate",sentence:"Choose the sentence that correctly uses 'used to' for a past state:",grammarRule:"used to — Past State",explanation:"'Used to' can describe not just repeated actions but also a lasting state in the past — where someone lived, what they had, how they felt.",tip:"used to + be/have/live = a state that is no longer true.",multipleChoice:{question:"Which sentence describes a past state correctly?",correctOption:"She used to be very shy, but she's much more confident now.",options:["She used to be very shy, but she's much more confident now.","She used to being very shy, but she's much more confident now.","She was used to shy, but she's much more confident now.","She uses to be very shy, but she's much more confident now."],optionExplanations:{"She used to be very shy, but she's much more confident now.":"Correct! 'used to be' describes a state that was true in the past.","She used to being very shy, but she's much more confident now.":"Wrong. 'used to' is followed by the base verb 'be', not '-ing'.","She was used to shy, but she's much more confident now.":"Wrong. 'was used to' needs a noun or -ing form, and this isn't that structure at all.","She uses to be very shy, but she's much more confident now.":"Wrong. 'used to' never changes form — there is no 'uses to'."}}},{id:"ut-mc-4",topic:"used-to",type:"multiple-choice",difficulty:"intermediate",sentence:"Find the sentence where 'used to' is used INCORRECTLY:",grammarRule:"used to vs Past Simple — One-off Events",explanation:"'Used to' cannot describe something that happened only once, a stated number of times, or for a stated length of time — the past simple is required there.",tip:"A single event, a number, or a length of time → never 'used to'.",multipleChoice:{question:"Which sentence has an error?",correctOption:"Last March I used to visit some friends in Mexico City.",options:["Last March I used to visit some friends in Mexico City.","Last March I visited some friends in Mexico City.","I used to visit my grandparents every summer when I was a child.","He used to spend hours drawing cartoon characters."],optionExplanations:{"Last March I used to visit some friends in Mexico City.":"WRONG! 'Last March' names one specific, dated event — the past simple is needed, not 'used to'.","Last March I visited some friends in Mexico City.":"Correct. A single dated event uses the past simple.","I used to visit my grandparents every summer when I was a child.":"Correct. 'Every summer' describes a repeated past habit — 'used to' is right here.","He used to spend hours drawing cartoon characters.":"Correct. A repeated past habit, with no specific date — 'used to' is right here."}}},{id:"ut-mc-5",topic:"used-to",type:"multiple-choice",difficulty:"intermediate",sentence:"Choose the best question to ask about someone's past hobbies:",grammarRule:"used to — Question Form",explanation:"Questions with 'used to' use 'did' + subject + 'use to' + infinitive.",tip:"Did + subject + use to + base verb — never 'Did ... used to'.",multipleChoice:{question:"Which question is grammatically correct?",correctOption:"Did you use to collect anything when you were a child?",options:["Did you use to collect anything when you were a child?","Did you used to collect anything when you were a child?","Used you to collect anything when you were a child?","Do you used to collect anything when you were a child?"],optionExplanations:{"Did you use to collect anything when you were a child?":"Correct! 'Did' + subject + 'use to' (no 'd') + base verb.","Did you used to collect anything when you were a child?":"Wrong. Once 'did' carries the past tense, 'use' must lose its 'd'.","Used you to collect anything when you were a child?":"Wrong. Modern English always uses 'did ... use to', not 'used you to'.","Do you used to collect anything when you were a child?":"Wrong. 'used to' only exists in the past — 'do' is the wrong auxiliary, and 'used' still needs to drop the 'd' anyway."}}},{id:"ut-mc-6",topic:"used-to",type:"multiple-choice",difficulty:"intermediate",sentence:"Choose the sentence with the most natural short answer:",grammarRule:"used to — Short Answer",explanation:"In spoken English, the verb after 'used to' is often dropped in short answers because it's understood from the question.",tip:"A: Do you still skateboard? B: No, I used to. — the activity doesn't need repeating.",multipleChoice:{question:"A: Do you still play tennis? B: ...",correctOption:"No, I used to, but I don't anymore.",options:["No, I used to, but I don't anymore.","No, I used to play, but I don't anymore.","No, I use to, but I don't anymore.","No, I am used to, but I don't anymore."],optionExplanations:{"No, I used to, but I don't anymore.":"Correct! Dropping the verb after 'used to' in a short answer is natural and common.","No, I used to play, but I don't anymore.":"Also grammatically fine, but less natural here than the short form with 'used to' alone — the activity is already clear from the question.","No, I use to, but I don't anymore.":"Wrong. In an affirmative statement, 'used to' always keeps its 'd'.","No, I am used to, but I don't anymore.":"Wrong. 'Am used to' needs a noun or -ing form and means 'accustomed to' — a different meaning entirely."}}},{id:"ut-mc-7",topic:"used-to",type:"multiple-choice",difficulty:"advanced",sentence:"Choose the sentence that correctly uses the negative form 'never used to':",grammarRule:"used to — never used to (Spoken Alternative)",explanation:"In spoken English, 'never used to' is often preferred to 'didn't use to' — it keeps the 'd' on 'used' because 'never' doesn't act as an auxiliary.",tip:"never used to (with 'd') is a common spoken alternative to didn't use to (without 'd').",multipleChoice:{question:"Which sentence is correct?",correctOption:"I never used to see my cousins, except in the summer holidays.",options:["I never used to see my cousins, except in the summer holidays.","I never use to see my cousins, except in the summer holidays.","I didn't never used to see my cousins, except in the summer holidays.","I never did use to see my cousins, except in the summer holidays."],optionExplanations:{"I never used to see my cousins, except in the summer holidays.":"Correct! With 'never' (not 'didn't'), 'used' keeps its 'd'.","I never use to see my cousins, except in the summer holidays.":"Wrong. 'Never' is not an auxiliary like 'didn't' — 'used' should keep the 'd'.","I didn't never used to see my cousins, except in the summer holidays.":"Wrong. This is a double negative — 'didn't' and 'never' cannot both be used together.","I never did use to see my cousins, except in the summer holidays.":"Wrong. 'Never' replaces 'didn't' entirely — adding 'did' as well is unnecessary and unnatural."}}},{id:"ut-wt-1",topic:"used-to",type:"word-transform",difficulty:"beginner",sentence:"We ___ (live) close to the train station, but we moved away last year.",grammarRule:"used to — Affirmative with a State Verb",explanation:"'Used to' + base verb describes a past state. 'Live' here describes where someone lived in the past, no longer true now.",tip:"used to + base verb, always the same form for every subject.",wordTransform:{baseWord:"live",correctAnswer:"used to live"}},{id:"ut-wt-2",topic:"used-to",type:"word-transform",difficulty:"beginner",sentence:"Elena ___ (drink) a lot of coffee, but she doesn't anymore.",grammarRule:"used to — Affirmative with a Habit",explanation:"'Used to' describes a repeated past habit — drinking a lot of coffee regularly, which has now stopped.",tip:"used to + base verb works the same for he/she/it as for I/you/we/they.",wordTransform:{baseWord:"drink",correctAnswer:"used to drink"}},{id:"ut-wt-3",topic:"used-to",type:"word-transform",difficulty:"intermediate",sentence:"I ___ (like) my job, but I love it now.",grammarRule:"used to — Negative Form",explanation:"The negative of 'used to' is 'didn't use to' — no 'd' on 'use' once 'didn't' carries the past tense. The contrast with 'now' shows the feeling has changed.",tip:"Negative: didn't use to + base verb.",wordTransform:{baseWord:"like",correctAnswer:"didn't use to like"}},{id:"ut-wt-4",topic:"used-to",type:"word-transform",difficulty:"intermediate",sentence:"Did you ___ (have) art lessons when you were young?",grammarRule:"used to — Question Form",explanation:"Questions with 'used to' are built with 'did' + subject + 'use to' + base verb — note that 'use' has no 'd' once 'did' is already there.",tip:"Question: Did + subject + use to + base verb (no 'd' on 'use').",wordTransform:{baseWord:"have",correctAnswer:"use to have"}},{id:"ut-wt-5",topic:"used-to",type:"word-transform",difficulty:"intermediate",sentence:"My parents ___ (watch) a lot of television, but they don't now.",grammarRule:"used to — Affirmative with a Habit",explanation:"A repeated habit in the past that has stopped (watching a lot of television) is exactly what 'used to' describes.",tip:"used to + base verb for a habit that no longer continues.",wordTransform:{baseWord:"watch",correctAnswer:"used to watch"}},{id:"ut-wt-6",topic:"used-to",type:"word-transform",difficulty:"advanced",sentence:"It never ___ (be) so hot in the summers here, but things have changed.",grammarRule:"used to — never used to (Past State)",explanation:"'Never used to' (with the 'd' kept, since 'never' is not an auxiliary) describes a past state that was never true before, but things are different now.",tip:"never used to + base verb — 'used' keeps its 'd' after 'never'.",wordTransform:{baseWord:"be",correctAnswer:"used to be"}}],j={id:"used-to",level:"B1",name:"used to",description:"Learn how to talk about past habits and states that are no longer true with 'used to' — the affirmative, negative and question forms, and when the past simple is needed instead.",lesson:"Unit 6A",icon:"🕰️",cards:[{id:"ut-card-1",rule:"used to + base verb — past habit",example:"As a child, Marco ___ (collect) stamps every weekend.",answer:"used to collect",explanation:"'Used to' + the base form of the verb describes something that happened regularly in the past but doesn't happen now. The form never changes, whoever is doing it.",examples:["We used to walk to school together every morning.","My grandmother used to tell us stories before bed."],ua:"used to + дієслово — звичка в минулому, якої вже немає: used to collect («колись збирав»)."},{id:"ut-card-2",rule:"used to + base verb — past state",example:"Before she moved abroad, Anna ___ (live) in a tiny flat.",answer:"used to live",explanation:"'Used to' also describes a state that lasted for a time in the past — where someone lived, what they owned, how they felt — and is no longer true.",examples:["He used to be very quiet at school.","They used to have a dog, but it died two years ago."],ua:"used to описує і стан у минулому, не лише дію: used to live, used to be."},{id:"ut-card-3",rule:"negative: didn't use to (no 'd')",example:"I ___ (not / enjoy) spicy food, but now it's my favourite.",answer:"didn't use to enjoy",explanation:"The negative is 'didn't use to' + base verb. Because 'didn't' already carries the past tense, 'use' drops its 'd'.",examples:["She didn't use to go out much, but she's much more social now.","We didn't use to travel abroad very often."],ua:"заперечення: didn't use to (без «d» на use!) — didn't used to є помилкою."},{id:"ut-card-4",rule:"question: Did ... use to? (no 'd')",example:"Did you ___ (play) a musical instrument as a child?",answer:"use to play",explanation:"Questions are formed with 'did' + subject + 'use to' + base verb. Again, 'use' has no 'd' once 'did' is carrying the past tense.",examples:["Did you use to live near the sea?","Did they use to visit you every summer?"],ua:"питання: Did + підмет + use to (без «d»): Did you use to play...?"},{id:"ut-card-5",rule:"used to or past simple?",example:"She ___ (be) a photographer before she became a teacher.",answer:"used to be",explanation:"'Used to' and the past simple can both describe a repeated past habit or lasting state — both are correct and mean almost the same thing.",examples:["I used to play tennis every weekend.","I played tennis every weekend."],ua:"used to і Past Simple часто взаємозамінні для звички/стану в минулому: обидва варіанти правильні."},{id:"ut-card-6",rule:"one-off events: past simple only",example:"Last summer, my family ___ (move) to a new city.",answer:"moved",explanation:"'Used to' cannot describe something that happened only once, a stated number of times, or for a stated length of time — only the past simple works for those.",examples:["We went to Portugal twice last year.","I studied French for two years at school."],ua:"used to не можна для разової події, точної кількості разів чи періоду — лише Past Simple: moved, went, studied."},{id:"ut-card-7",rule:"never used to (spoken alternative)",example:"My brother ___ (not / like) classical music, but he does now.",answer:"never used to like",explanation:"In spoken English, 'never used to' is often preferred to 'didn't use to'. With 'never' instead of 'didn't', 'used' keeps its 'd'.",examples:["I never used to eat breakfast, but I do every day now.","She never used to drive, but she passed her test last year."],ua:"в розмовній мові часто never used to (з «d», бо never — не допоміжне дієслово) замість didn't use to."},{id:"ut-card-8",rule:"short answers: verb often dropped",example:"A: Do you still skateboard? B: No, I ___, but I don't anymore.",answer:"used to",explanation:"In short answers, the verb after 'used to' is often left out completely, because it's already clear from the question.",examples:["A: Do you still play the piano? B: I used to, but I stopped years ago.","A: Did you use to collect anything? B: Yes, I used to."],ua:"у коротких відповідях дієслово після used to часто опускають: I used to (без повторення дії)."}],rules:C},O=[{id:"cs-gap-1",topic:"comparatives-and-superlatives",type:"gap-fill",difficulty:"beginner",sentence:"My brother is ___ than me.",grammarRule:"Comparative of Short Adjectives (+er)",explanation:"Tall is a one-syllable adjective, so we add -er to form the comparative: tall → taller.",tip:"One-syllable adjectives: add -er for the comparative, -est for the superlative.",gapFill:{gapIndex:3,correctAnswer:"taller",options:["taller","more tall","tallest","more taller"],correctOptionIndex:0}},{id:"cs-gap-2",topic:"comparatives-and-superlatives",type:"gap-fill",difficulty:"beginner",sentence:"This is ___ restaurant in the city.",grammarRule:"Superlative of Long Adjectives (the most)",explanation:"Expensive has three syllables, so its superlative uses 'the most', not '-est': the most expensive.",tip:"Long adjectives (2+ syllables, not ending in -y): the most/the least + adjective.",gapFill:{gapIndex:2,correctAnswer:"the most expensive",options:["the most expensive","the expensivest","more expensive","most expensivest"],correctOptionIndex:0}},{id:"cs-gap-3",topic:"comparatives-and-superlatives",type:"gap-fill",difficulty:"intermediate",sentence:"The soup tastes ___ than yesterday.",grammarRule:"Irregular Comparative — good → better",explanation:"Good is irregular: good → better → the best. It never takes -er or more.",tip:"good→better→the best — memorise this one, it has no regular pattern.",gapFill:{gapIndex:3,correctAnswer:"better",options:["better","gooder","more good","best"],correctOptionIndex:0}},{id:"cs-gap-4",topic:"comparatives-and-superlatives",type:"gap-fill",difficulty:"intermediate",sentence:"My new job isn't ___ my last one.",grammarRule:"Comparisons with (not) as...as",explanation:"(Not) as + adjective + as compares two things as equal, or not equal: isn't as stressful as = less stressful than.",tip:"as + adjective + as = equal. not as + adjective + as = less.",gapFill:{gapIndex:4,correctAnswer:"as stressful as",options:["as stressful as","more stressful than","stressfuler than","the most stressful"],correctOptionIndex:0}},{id:"cs-gap-5",topic:"comparatives-and-superlatives",type:"gap-fill",difficulty:"intermediate",sentence:"She can run ___ than her brother.",grammarRule:"Comparative Adverbs — Regular (+er)",explanation:"Fast is a short adverb (the same form as the adjective), so we add -er: fast → faster.",tip:"Short adverbs (fast, hard, late, early) take -er/-est, just like short adjectives.",gapFill:{gapIndex:3,correctAnswer:"faster",options:["faster","more fast","fastest","more faster"],correctOptionIndex:0}},{id:"cs-gap-6",topic:"comparatives-and-superlatives",type:"gap-fill",difficulty:"advanced",sentence:"He did ___ in the test than he expected.",grammarRule:"Irregular Comparative Adverb — badly → worse",explanation:"Badly is irregular as an adverb too: badly → worse → the worst.",tip:"well→better, badly→worse — both adjectives and adverbs share these irregular forms.",gapFill:{gapIndex:2,correctAnswer:"worse",options:["worse","more badly","badder","the worst"],correctOptionIndex:0}},{id:"cs-error-1",topic:"comparatives-and-superlatives",type:"error-spot",difficulty:"beginner",sentence:"My new office is biger than my old one.",grammarRule:"Comparative of CVC Adjectives — Double Consonant",explanation:"Big ends in one vowel + one consonant, so we double the final letter before -er: big → bigger.",errorSpot:{errorWordIndex:4,wrongWord:"biger",correction:"bigger",reason:"Big ends in a single vowel + consonant, so the final letter doubles before -er: bigger, not biger.",correctionOptions:["bigger","biger","more big","biggest"]}},{id:"cs-error-2",topic:"comparatives-and-superlatives",type:"error-spot",difficulty:"beginner",sentence:"This app is importanter than the last version.",grammarRule:"Comparative of Long Adjectives — 'More' + Adjective",explanation:"Important has three syllables, so it forms the comparative with 'more', not '-er': more important.",errorSpot:{errorWordIndex:3,wrongWord:"importanter",correction:"more important",reason:"Long adjectives never take -er — use 'more important', never importanter.",correctionOptions:["more important","importanter","importantest","most important"]}},{id:"cs-error-3",topic:"comparatives-and-superlatives",type:"error-spot",difficulty:"intermediate",sentence:"The new office is farer from the station than the old one.",grammarRule:"Irregular Comparative — far → further/farther",explanation:"Far has an irregular comparative: further (or farther). It never takes -er.",errorSpot:{errorWordIndex:4,wrongWord:"farer",correction:"further",reason:"Far is irregular: far → further/farther, never farer.",correctionOptions:["further","farer","more far","farthest"]}},{id:"cs-error-4",topic:"comparatives-and-superlatives",type:"error-spot",difficulty:"intermediate",sentence:"This laptop isn't as fast than my old one.",grammarRule:"Comparisons with (not) as...as",explanation:"The structure is (not) as + adjective + as, not as + adjective + than. Use 'as' on both sides.",errorSpot:{errorWordIndex:5,wrongWord:"than",correction:"as",reason:"'As...as' needs 'as' on both sides: isn't as fast as, not isn't as fast than.",correctionOptions:["as","than","that","so"]}},{id:"cs-error-5",topic:"comparatives-and-superlatives",type:"error-spot",difficulty:"intermediate",sentence:"He drives more carefuller than his brother.",grammarRule:"Comparative Adverbs — 'More' + -ly Adverb",explanation:"Adverbs ending in -ly use 'more', not -er: more carefully, never carefuller.",errorSpot:{errorWordIndex:3,wrongWord:"carefuller",correction:"carefully",reason:"-ly adverbs never take -er — 'more' already does that job: more carefully.",correctionOptions:["carefully","carefuller","more careful","careful"]}},{id:"cs-error-6",topic:"comparatives-and-superlatives",type:"error-spot",difficulty:"advanced",sentence:"She can speak French weller than I can.",grammarRule:"Irregular Comparative Adverb — well → better",explanation:"Well is irregular as an adverb too: well → better → best. It never takes -er.",errorSpot:{errorWordIndex:4,wrongWord:"weller",correction:"better",reason:"Well is irregular: well → better, never weller.",correctionOptions:["better","weller","more well","gooder"]}},{id:"cs-mc-1",topic:"comparatives-and-superlatives",type:"multiple-choice",difficulty:"beginner",sentence:"Choose the sentence with the correct comparative form:",grammarRule:"Comparative of Adjectives Ending in -y",explanation:"Heavy is a two-syllable adjective ending in -y, so y changes to i before adding -er: heavy → heavier.",tip:"happy→happier, easy→easier, heavy→heavier — y becomes i before -er/-est.",multipleChoice:{question:"Which sentence is correct?",correctOption:"This bag is heavier than that one.",options:["This bag is heavier than that one.","This bag is more heavy than that one.","This bag is heavyer than that one.","This bag is most heavy than that one."],optionExplanations:{"This bag is heavier than that one.":"Correct! Heavy ends in a consonant + y, so y changes to i before -er: heavy → heavier.","This bag is more heavy than that one.":"Wrong. Heavy is a short, common adjective — it takes -er, not more.","This bag is heavyer than that one.":"Wrong. The y must change to i before adding -er: heavier, not heavyer.","This bag is most heavy than that one.":"Wrong. 'Most' is for superlatives, and it's never followed by 'than'."}}},{id:"cs-mc-2",topic:"comparatives-and-superlatives",type:"multiple-choice",difficulty:"beginner",sentence:"Choose the sentence with the correct superlative form:",grammarRule:"Superlative of Long Adjectives (the most)",explanation:"Comfortable has more than two syllables, so its superlative uses 'the most', not '-est'.",tip:"Long adjectives (2+ syllables, not ending in -y): the most/the least + adjective.",multipleChoice:{question:"Which sentence is correct?",correctOption:"It's the most comfortable sofa in the shop.",options:["It's the most comfortable sofa in the shop.","It's the comfortablest sofa in the shop.","It's the more comfortable sofa in the shop.","It's the most comfortablest sofa in the shop."],optionExplanations:{"It's the most comfortable sofa in the shop.":"Correct! Comfortable has more than two syllables, so the superlative uses 'the most'.","It's the comfortablest sofa in the shop.":"Wrong. Long adjectives never take -est — use 'the most' instead.","It's the more comfortable sofa in the shop.":"Wrong. 'More' is for comparatives, comparing two things. This compares one sofa to all the others — use the superlative 'the most'.","It's the most comfortablest sofa in the shop.":"Wrong. You can't combine 'most' and '-est' — 'the most comfortable' is correct on its own."}}},{id:"cs-mc-3",topic:"comparatives-and-superlatives",type:"multiple-choice",difficulty:"intermediate",sentence:"Choose the sentence with the correct superlative form:",grammarRule:"Irregular Superlative — bad → worst",explanation:"Bad is irregular: bad → worse → the worst. It never takes -est or most.",tip:"good→best, bad→worst, far→furthest — learn these three irregular superlatives together.",multipleChoice:{question:"Which sentence is correct?",correctOption:"That was the worst meal I've ever had.",options:["That was the worst meal I've ever had.","That was the baddest meal I've ever had.","That was the most bad meal I've ever had.","That was the more bad meal I've ever had."],optionExplanations:{"That was the worst meal I've ever had.":"Correct! Bad is irregular: bad → worse → the worst.","That was the baddest meal I've ever had.":"Wrong. Bad never takes -est — its superlative is irregular: the worst.","That was the most bad meal I've ever had.":"Wrong. Bad doesn't use 'most' either — it's irregular: the worst.","That was the more bad meal I've ever had.":"Wrong. This mixes the comparative 'more' with a superlative meaning — and 'bad' is irregular anyway: the worst."}}},{id:"cs-mc-4",topic:"comparatives-and-superlatives",type:"multiple-choice",difficulty:"intermediate",sentence:"This coat isn't as expensive as the other one.",grammarRule:"Meaning of 'not as...as'",explanation:"'Not as + adjective + as' means the first thing has less of that quality than the second.",tip:"not as expensive as = cheaper. not as good as = worse. as...as (no 'not') = equal.",multipleChoice:{question:"What does this sentence mean?",correctOption:"The coat costs less than the other one.",options:["The coat costs less than the other one.","The coat costs more than the other one.","The two coats cost exactly the same.","We don't know the price of either coat."],optionExplanations:{"The coat costs less than the other one.":"Correct! 'Not as + adjective + as' shows the first thing has less of that quality — here, it's cheaper.","The coat costs more than the other one.":"Wrong. 'Not as expensive as' means less expensive, not more.","The two coats cost exactly the same.":"Wrong. 'As...as' without 'not' would mean equal — 'not as...as' means unequal.","We don't know the price of either coat.":"Wrong. The sentence does compare the prices — it tells us this coat is cheaper."}}},{id:"cs-mc-5",topic:"comparatives-and-superlatives",type:"multiple-choice",difficulty:"intermediate",sentence:"Choose the sentence with the correct comparative adverb:",grammarRule:"Comparative Adverbs — 'More' + -ly Adverb",explanation:"Adverbs ending in -ly form the comparative with 'more', not -er: fluently → more fluently.",tip:"Most -ly adverbs use more/most. Only a few short adverbs (fast, hard) add -er/-est.",multipleChoice:{question:"Which sentence is correct?",correctOption:"He speaks more fluently than his sister.",options:["He speaks more fluently than his sister.","He speaks fluentlier than his sister.","He speaks more fluent than his sister.","He speaks fluently more than his sister."],optionExplanations:{"He speaks more fluently than his sister.":"Correct! Fluently ends in -ly, so the comparative uses 'more': more fluently.","He speaks fluentlier than his sister.":"Wrong. -ly adverbs never take -er — use 'more' instead.","He speaks more fluent than his sister.":"Wrong. 'Fluent' is the adjective; to compare how he speaks (an action), you need the adverb 'fluently'.","He speaks fluently more than his sister.":"Wrong. 'More' must come directly before the adverb: more fluently, not fluently more."}}},{id:"cs-mc-6",topic:"comparatives-and-superlatives",type:"multiple-choice",difficulty:"intermediate",sentence:"Choose the sentence where the superlative is used correctly:",grammarRule:"Superlatives with Possessive Adjectives",explanation:"We usually use 'the' before a superlative, but a possessive adjective (my, her, his, their) can take its place.",tip:"the best friend OR her best friend — never 'the her best friend'.",multipleChoice:{question:"Which sentence is correct?",correctOption:"That's her best painting.",options:["That's her best painting.","That's the her best painting.","That's she best painting.","That's her the best painting."],optionExplanations:{"That's her best painting.":"Correct! A possessive adjective (her) can replace 'the' before a superlative.","That's the her best painting.":"Wrong. You can't use 'the' and a possessive adjective together — choose one: her best painting.","That's she best painting.":"Wrong. 'She' is a subject pronoun; you need the possessive adjective 'her' before the noun phrase.","That's her the best painting.":"Wrong. The possessive adjective replaces 'the' — it doesn't come after it."}}},{id:"cs-mc-7",topic:"comparatives-and-superlatives",type:"multiple-choice",difficulty:"advanced",sentence:"Choose the sentence with the correct comparative form:",grammarRule:"Irregular Comparative Adverb — far → further/farther",explanation:"Far has an irregular comparative and superlative: far → further/farther → the furthest/farthest.",tip:"Further and farther are both correct — British English often prefers 'further'.",multipleChoice:{question:"Which sentence is correct?",correctOption:"She ran further than anyone else in the race.",options:["She ran further than anyone else in the race.","She ran farer than anyone else in the race.","She ran more far than anyone else in the race.","She ran the farer of anyone else in the race."],optionExplanations:{"She ran further than anyone else in the race.":"Correct! Far is irregular: far → further/farther → the furthest/farthest.","She ran farer than anyone else in the race.":"Wrong. Far never takes -er — its comparative is irregular: further or farther.","She ran more far than anyone else in the race.":"Wrong. Far doesn't use 'more' either — it's irregular: further/farther.","She ran the farer of anyone else in the race.":"Wrong. This isn't a real word, and the comparative (not superlative) is needed here: further than anyone else."}}},{id:"cs-wt-1",topic:"comparatives-and-superlatives",type:"word-transform",difficulty:"beginner",sentence:"This laptop is ___ (light) than my old one.",grammarRule:"Comparative of Short Adjectives (+er)",explanation:"Light is a one-syllable adjective, so we add -er to form the comparative: light → lighter.",tip:"One-syllable adjectives: add -er. light→lighter, fast→faster, small→smaller.",wordTransform:{baseWord:"light",correctAnswer:"lighter"}},{id:"cs-wt-2",topic:"comparatives-and-superlatives",type:"word-transform",difficulty:"beginner",sentence:"She is the ___ (talented) person I've ever met.",grammarRule:"Superlative of Long Adjectives (the most)",explanation:"Talented has three syllables, so its superlative uses 'most', not '-est': the most talented.",tip:"Three-syllable (or longer) adjectives always use most/the most, never -est.",wordTransform:{baseWord:"talented",correctAnswer:"most talented"}},{id:"cs-wt-3",topic:"comparatives-and-superlatives",type:"word-transform",difficulty:"intermediate",sentence:"The traffic today is ___ (bad) than yesterday.",grammarRule:"Irregular Comparative — bad → worse",explanation:"Bad is irregular: bad → worse → the worst. It never takes -er or more.",tip:"bad→worse→the worst — just like good→better→the best.",wordTransform:{baseWord:"bad",correctAnswer:"worse"}},{id:"cs-wt-4",topic:"comparatives-and-superlatives",type:"word-transform",difficulty:"intermediate",sentence:"My brother isn't as ___ (confident) as me.",grammarRule:"Comparisons with (not) as...as — Base Form",explanation:"In the structure (not) as + adjective + as, the adjective keeps its base form — it is never comparative.",tip:"as...as and not as...as always use the plain adjective: as tall as, not as taller as.",wordTransform:{baseWord:"confident",correctAnswer:"confident"}},{id:"cs-wt-5",topic:"comparatives-and-superlatives",type:"word-transform",difficulty:"intermediate",sentence:"He checked the contract ___ (careful) than before.",grammarRule:"Comparative Adverbs — 'More' + -ly Adverb",explanation:"To compare actions, we use the adverb carefully, and since it ends in -ly, the comparative is formed with more: more carefully.",tip:"Turn the adjective into the -ly adverb first, then add more: careful → carefully → more carefully.",wordTransform:{baseWord:"careful",correctAnswer:"more carefully"}},{id:"cs-wt-6",topic:"comparatives-and-superlatives",type:"word-transform",difficulty:"advanced",sentence:"Of all my colleagues, she works ___ (hard).",grammarRule:"Superlative Adverbs — Short Adverbs (+ the -est)",explanation:"Hard is a short adverb (the same form as the adjective), so its superlative adds -est: the hardest.",tip:"Short adverbs like hard, fast and late form the superlative the same way as short adjectives: + the -est.",wordTransform:{baseWord:"hard",correctAnswer:"the hardest"}}],H={id:"comparatives-and-superlatives",level:"B1",name:"Comparatives and Superlatives",description:"Compare people, places, things and actions using comparative and superlative adjectives and adverbs — regular endings, irregular forms like good/bad/far, and (not) as...as.",lesson:"Lesson 6B",icon:"⚖️",cards:[{id:"cs-card-1",rule:"short adjectives: -er / -est",example:"My new phone is ___ (fast) than my old one.",answer:"faster",explanation:"For one-syllable adjectives, add -er for the comparative and -est for the superlative: fast → faster → the fastest.",examples:["This is the fastest way to get to the airport.","Her car is cheaper than mine, but mine is more reliable."],ua:"короткі прикметники: +er / the ...est: fast → faster → the fastest."},{id:"cs-card-2",rule:"-y adjectives: y → i + -er/-est",example:"The exam was ___ (easy) than I expected.",answer:"easier",explanation:"Two-syllable adjectives ending in -y change y to i before adding -er or -est: easy → easier → the easiest.",examples:["She's the happiest person I know.","This recipe is easier than the one we tried last week."],ua:"прикметники на -y: y→i: easy → easier → the easiest."},{id:"cs-card-3",rule:"CVC adjectives: double the final consonant",example:"This flat is ___ (big) than our last one.",answer:"bigger",explanation:"Short adjectives ending in one vowel + one consonant double the final consonant before -er/-est: big → bigger → the biggest.",examples:["Today is hotter than yesterday.","That's the biggest mistake I've ever made at work."],ua:"один голосний + один приголосний: подвоюємо приголосну: big → bigger → the biggest."},{id:"cs-card-4",rule:"longer adjectives: more / most + adjective",example:"I think working from home is ___ (convenient) than commuting every day.",answer:"more convenient",explanation:"Adjectives with two or more syllables (except those ending in -y) use more/the most instead of -er/-est: convenient → more convenient → the most convenient.",examples:["This is the most expensive restaurant in town.","Her new job is more stressful than her last one."],ua:"довгі прикметники: more / the most + adjective: expensive → more expensive."},{id:"cs-card-5",rule:"irregular adjectives: good, bad, far",example:"The weather today is much ___ (bad) than it was yesterday.",answer:"worse",explanation:"Good, bad and far have irregular comparative and superlative forms: good → better → the best; bad → worse → the worst; far → further/farther → the furthest/farthest.",examples:["This is the best coffee I've ever had.","We had to walk further than we planned."],ua:"неправильні форми: good→better→best, bad→worse→worst, far→further→furthest."},{id:"cs-card-6",rule:"(not) as + adjective + as",example:"This hotel isn't as ___ (expensive) as the one we stayed in last year.",answer:"expensive",explanation:"We use (not) as + adjective + as to say two things are equal, or not equal, in some quality. 'Not as...as' usually means less: not as expensive as = cheaper than.",examples:["He isn't as tall as his brother.","This test was just as difficult as the last one."],ua:"(not) as + прикметник + as — порівняння: not as expensive as = дешевше."},{id:"cs-card-7",rule:"comparative and superlative adverbs",example:"She speaks English ___ (fluent) than she did a year ago.",answer:"more fluently",explanation:"Adverbs form comparatives and superlatives the same way as adjectives: short adverbs add -er/-est (fast→faster), most adverbs (especially -ly ones) use more/most (fluently→more fluently). Well and badly are irregular: well→better, badly→worse.",examples:["He explained it more clearly than before.","Of all the students, she works the hardest."],ua:"прислівники: fast→faster; fluently→more fluently; well→better, badly→worse (виняток)."},{id:"cs-card-8",rule:"superlatives: the + -est/most, often with present perfect + ever",example:"This is the ___ (interesting) book I've ever read.",answer:"most interesting",explanation:"We normally use 'the' before a superlative, though a possessive adjective is also possible ('her best friend'). Superlatives are often followed by the present perfect + ever to talk about someone's whole experience so far.",examples:["That's the funniest film I've ever seen.","He's the most talented musician in the band."],ua:"найвищий ступінь часто з Present Perfect + ever: the most interesting book I've ever read."}],rules:O},E=[t,o,n,i,a,r,s,l,h,d,p,m,f,w,b,k,_,T,S,A,q,j,H];export{E as default};
